INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79fe90b5-f11d-4fc8-95c6-521fea490809', '武三思席上詠綺娘（題擬）', '武三思席上詠綺娘（題擬）', '63812777-256d-4133-a33b-e849347d32ea', '唐', '["紫府開樽召衆賓，更令妖艷舞紅裀。","曲終獨向筵前立，滿眼春光射主人。","（《新編分門古今類事》卷二引《甘）（澤謠》）。"]', '["紫府开樽召衆賓，更令妖艷舞紅裀。","曲終独向筵前立，满眼春光射主人。","（《新編分门古今類事》卷二引《甘）（澤謠》）。"]', '诗', 'shi', '', NULL, '武三思席上詠綺娘（題擬） 蘇焜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227ebcf8-7f52-41e4-a594-6b2788d8a233', '聽《華嚴》詩（幷序）', '听《华嚴》诗（幷序）', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["法席開廣方，緇徒滿勝筵。","聖衆隨雲集，天華照日鮮。","座分千葉華，香引六銖烟。","鐘聲聞有頂，梵響韻無邊。","一音宣妙義，七處重弘宣。","唯心明八會，滌慮體三禪。","既悟無生滅，常欣佛現前。","（《卐續藏經》本唐釋法藏《華嚴經傳記》卷三《智儼傳》爲永昌元年作。","）。"]', '["法席开廣方，緇徒满勝筵。","聖衆隨云集，天华照日鲜。","座分千葉华，香引六銖烟。","鐘声闻有頂，梵响韻無邊。","一音宣妙義，七处重弘宣。","唯心明八會，滌慮體三禪。","既悟無生滅，常欣佛現前。","（《卐續藏經》本唐釋法藏《华嚴經傳記》卷三《智儼傳》爲永昌元年作。","）。"]', '诗', 'shi', '', NULL, '聽《華嚴》詩（幷序） 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0320a64e-8aee-40c1-a9d8-636226b23fe2', '賜姚崇', '賜姚崇', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["依依柳色變，處處春風起。","借問向鹽池，何如遊滻水？","（見胡聘之《山右石刻叢編》卷五高宗《過樓巖寺》詩附韋元晨《六絕紀文》引。","作於長安二年。","時姚崇按察蒲州鹽池事返，賜以此詩。","題據韋文擬。","）。"]', '["依依柳色变，处处春风起。","借问向鹽池，何如游滻水？","（见胡聘之《山右石刻叢編》卷五高宗《過楼巖寺》诗附韋元晨《六絕紀文》引。","作於长安二年。","时姚崇按察蒲州鹽池事返，賜以此诗。","題據韋文擬。","）。"]', '诗', 'shi', '', NULL, '賜姚崇 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f7576f-faa9-442c-8f12-7869949190f3', '五言和波崙師登佛授記閣一首', '五言和波崙師登佛授記閣一首', '95f3551b-f3fa-44b4-9131-6b08434fddfd', '唐', '["帝宅開金地，神州列寶坊。","龍宮橫霧術，鴈塔亘霞莊。","窈窕分千仞，參差聳百常。","繡櫺懸疊檻，畫拱映雕梁。","寶座開千葉，金繩下八行。","青龍浮剎柱，白馬對祠場。","樹踊金銀色，蓮開日月光。","東西分閈廡，左右控池隍。","瑞葉擎朝露，祥花送晚香。","天衣隨劫拂，仙梵逐風揚。","忽有三空士，來宣七覺芳。","銀函承寶帙，玉札下琱章。","闢牖青雲外，披軒紫□傍。","山川橫地軸，辰象麗天[□。","□□□□□，□]繩待慈航。","（日本藏唐抄本《唐詩卷》，日本大阪市立美術館編《唐抄本》影印本）。"]', '["帝宅开金地，神州列寶坊。","龙宮橫霧術，鴈塔亘霞莊。","窈窕分千仞，參差聳百常。","繡櫺懸叠檻，畫拱映雕梁。","寶座开千葉，金繩下八行。","青龙浮剎柱，白马对祠場。","樹踊金銀色，蓮开日月光。","东西分閈廡，左右控池隍。","瑞葉擎朝露，祥花送晚香。","天衣隨劫拂，仙梵逐风揚。","忽有三空士，来宣七覺芳。","銀函承寶帙，玉札下琱章。","闢牖青云外，披軒紫□傍。","山川橫地軸，辰象丽天[□。","□□□□□，□]繩待慈航。","（日本藏唐抄本《唐诗卷》，日本大阪市立美術館編《唐抄本》影印本）。"]', '诗', 'shi', '', NULL, '五言和波崙師登佛授記閣一首 武三思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe60c72-e54d-4ca2-8345-a8f3dd05d3d9', '九成宮山', '九成宮山', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["有水魚爭樂，無人鳥共歌。","（見《吟窗雜錄》卷三七）。"]', '["有水鱼爭乐，無人鸟共歌。","（见《吟窗杂錄》卷三七）。"]', '诗', 'shi', '', NULL, '九成宮山 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1dcf01-5cea-47ab-9f8c-649f69279925', '神龍中自容山追入上詩', '神龙中自容山追入上诗', '5b0eafc8-25ed-4b95-8420-2a64e02a2c24', '唐', '["無事向容山，今日向東都。","陛下敕進來，令作右金吾。","（錄自汪紹楹校本《太平廣記》卷二五八引唐張鷟《朝野僉載》、趙守儼校本《朝野僉載》卷四。","）（按：《全唐詩》卷八六九據《唐詩紀事》卷八十錄權龍褒詩五首，其中嶺南歸後獻詩云：「龍褒有何罪，天恩放嶺南。","敕知無罪過，追來與將軍。","」而以此詩作別本注出。","然《朝野僉載》爲記載權詩最早之著作，《廣記》亦早於《紀事》，當以其所錄詩爲正。","其名亦當以「龍襄」爲是。","又《紀事》所錄，疑出後人補擬之作。","今重錄之以訂前失。","）。"]', '["無事向容山，今日向东都。","陛下敕進来，令作右金吾。","（錄自汪紹楹校本《太平廣記》卷二五八引唐張鷟《朝野僉載》、趙守儼校本《朝野僉載》卷四。","）（按：《全唐诗》卷八六九據《唐诗紀事》卷八十錄權龙褒诗五首，其中嶺南归後獻诗云：「龙褒有何罪，天恩放嶺南。","敕知無罪過，追来與將軍。","」而以此诗作別本注出。","然《朝野僉載》爲記載權诗最早之著作，《廣記》亦早於《紀事》，當以其所錄诗爲正。","其名亦當以「龙襄」爲是。","又《紀事》所錄，疑出後人補擬之作。","今重錄之以訂前失。","）。"]', '诗', 'shi', '', NULL, '神龍中自容山追入上詩 權龍襄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5140f8-40a7-4ebe-a501-fb44113ebde2', '麗色賦附歌', '丽色賦附歌', '54825d81-3b81-4dd0-9124-edb860e627d7', '唐', '["涉綠水兮採紅蓮，水漫漫兮花田田。","舟容與兮白日暮，桂水浮兮不可度。","（見《文苑英華》卷九六）。"]', '["涉綠水兮採紅蓮，水漫漫兮花田田。","舟容與兮白日暮，桂水浮兮不可度。","（见《文苑英华》卷九六）。"]', '诗', 'shi', '', NULL, '麗色賦附歌 富嘉謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ee52b6-39b1-4bed-a7a4-a4311e6f9c46', '應制 一', '應制 一', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["敬舉天杯飲。","（宋葉廷珪《海錄碎事》卷十引李宗楚詩）。"]', '["敬舉天杯饮。","（宋葉廷珪《海錄碎事》卷十引李宗楚诗）。"]', '诗', 'shi', '', NULL, '應制 一 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d845e80f-94e7-4764-ae6f-ad7692bea03e', '應制 二', '應制 二', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["儀乾開寶曆，御極轉金輪。","（同前書同卷引宗楚詩）（按：《海錄碎事》卷十錄初唐人應制詩句，中署宗楚客作者四聯，《全唐詩》卷四六收入三聯，其中「七萃鑾輿動，千年瑞檢開」二句，爲李嶠《奉和拜洛應制》之首二句，葉氏誤署。","《全唐詩》未收之「殷薦三神享，明祠萬玉陪」，爲李嶠同詩中句，文字略異。","同卷另錄李宗楚詩一句，當爲宗楚客之訛，今錄入。","）。"]', '["儀乾开寶曆，御極轉金輪。","（同前书同卷引宗楚诗）（按：《海錄碎事》卷十錄初唐人應制诗句，中署宗楚客作者四聯，《全唐诗》卷四六收入三聯，其中「七萃鑾輿动，千年瑞檢开」二句，爲李嶠《奉和拜洛應制》之首二句，葉氏誤署。","《全唐诗》未收之「殷薦三神享，明祠万玉陪」，爲李嶠同诗中句，文字略異。","同卷另錄李宗楚诗一句，當爲宗楚客之訛，今錄入。","）。"]', '诗', 'shi', '', NULL, '應制 二 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc4ca5d-29a2-4397-9799-3df23d6f8bd8', '五言詩二首 一', '五言诗二首 一', 'e278a260-2eec-4868-b9ed-ef3de55f7e03', '唐', '["寫書今日了，先生莫[嫌遲]（鹹池）。","明朝（此字僅存左邊上半截）是[假]（賈）日，早放學生歸。","。"]', '["寫书今日了，先生莫[嫌遲]（鹹池）。","明朝（此字僅存左邊上半截）是[假]（賈）日，早放学生归。","。"]', '诗', 'shi', '', NULL, '五言詩二首 一 卜天壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('789a68fe-1af1-44c5-8f64-b153e3b58c45', '五言詩二首 二', '五言诗二首 二', 'e278a260-2eec-4868-b9ed-ef3de55f7e03', '唐', '["他道側書易，我道側書[難]。","側書還側讀，還須側眼[看]。","（二詩均錄自郭沫若著《出土文物二三事》附一九六九年吐魯番阿塔那唐墓出土卜天壽抄本《論語鄭氏注》卷末詩詞業片。","原詩有訛缺，從郭沫若、龍晦二人說增改。","）（按：卜天壽《論語》抄本後寫有《十二月三臺詞》一首又一句半、五絕六首。","前者顯然爲抄錄時曲。","後六首，郭沫若以爲僅第一首爲卜天壽自作，另五首皆係抄錄民間流傳的舊詩。","龍晦則以爲第五首亦爲卜天壽自作。","今從二人說繫二詩於卜天壽名下，餘皆錄入本書卷五十六無名氏詩內。","）。"]', '["他道側书易，我道側书[难]。","側书還側读，還須側眼[看]。","（二诗均錄自郭沫若著《出土文物二三事》附一九六九年吐魯番阿塔那唐墓出土卜天壽抄本《論語鄭氏注》卷末诗词業片。","原诗有訛缺，從郭沫若、龙晦二人说增改。","）（按：卜天壽《論語》抄本後寫有《十二月三台词》一首又一句半、五絕六首。","前者显然爲抄錄时曲。","後六首，郭沫若以爲僅第一首爲卜天壽自作，另五首皆係抄錄民间流傳的旧诗。","龙晦則以爲第五首亦爲卜天壽自作。","今從二人说繫二诗於卜天壽名下，餘皆錄入本书卷五十六無名氏诗內。","）。"]', '诗', 'shi', '', NULL, '五言詩二首 二 卜天壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3fc1bbc-0509-4888-a0a8-57d735f0571f', '五言奉和姚元崇相公過樓巖寺詩（題擬）', '五言奉和姚元崇相公過楼巖寺诗（題擬）', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["巖突金銀臺，登攀信美哉！白林叢萬壑，珠綴結三台。","應物盡標勝，冥心無去來。","{汞夆/金}明巾鐵柱，長欲助鹽梅。","（錄自清胡聘之《山右石刻叢編》卷五）（按：此詩刻於姚崇五言《過樓巖寺》後，題僅作「五言奉和」，下署：「前朝議郎行左臺監察御史攝宮尹司直韋元旦。","」）。"]', '["巖突金銀台，登攀信美哉！白林叢万壑，珠綴結三台。","應物尽標勝，冥心無去来。","{汞夆/金}明巾鐵柱，长欲助鹽梅。","（錄自清胡聘之《山右石刻叢編》卷五）（按：此诗刻於姚崇五言《過楼巖寺》後，題僅作「五言奉和」，下署：「前朝議郎行左台監察御史攝宮尹司直韋元旦。","」）。"]', '诗', 'shi', '', NULL, '五言奉和姚元崇相公過樓巖寺詩（題擬） 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17af009-ffd0-44e2-af05-255f41beb385', '題龍湖', '題龙湖', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["環堤森霧伏，璧水湛天樞。","帶雨金龍甲，朝天錦鯉魚。","樓船搖月鑑，閣鼓肅冰壺。","扣枻歌三疊，飛觴瀉百枯。","犀燃神鬼泣，劍射斗牛虛。","懷古標遐軌，龍湖第一途。"]', '["环堤森霧伏，璧水湛天樞。","带雨金龙甲，朝天錦鯉鱼。","楼船搖月鑑，閣鼓肅冰壺。","扣枻歌三叠，飞觴瀉百枯。","犀燃神鬼泣，劍射斗牛虛。","懷古標遐軌，龙湖第一途。"]', '诗', 'shi', '', NULL, '題龍湖 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd6c791-db51-4acb-a158-2dccd8f2920b', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["一戈探虎穴，萬里到龍湖。","原上千花雨，湖邊百草埔。","分曹驅鹿豕，犄角困獐狐。","野女妍堆髻，山獠醉倒壺。","氣清消霧冷，路險迫雲衢。","虎帳風霆肅，龍旂日月舒。","芟除盡荆棘，雨交鑑湖娛。"]', '["一戈探虎穴，万里到龙湖。","原上千花雨，湖邊百草埔。","分曹驱鹿豕，犄角困獐狐。","野女妍堆髻，山獠醉倒壺。","氣清消霧冷，路險迫云衢。","虎帳风霆肅，龙旂日月舒。","芟除尽荆棘，雨交鑑湖娛。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cef02011-72f0-431f-9a2d-99052c6bcca5', '其三', '其三', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["地極綏安鎮，天隨使節存。","民風移醜陋，土俗轉醖醇。","野服迎旌佩，獠草避陣雲。","宣威雄劍鼓，導化動琴樽。","石裂磨刀處，溪留飲馬痕。","龍湖魚鳥眼，認此第三巡。"]', '["地極綏安鎮，天隨使節存。","民风移醜陋，土俗轉醖醇。","野服迎旌佩，獠草避陣云。","宣威雄劍鼓，導化动琴樽。","石裂磨刀处，溪留饮马痕。","龙湖鱼鸟眼，認此第三巡。"]', '诗', 'shi', '', NULL, '其三 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc17ddf-60c4-405a-8ea5-9184e787c3cd', '其四', '其四', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["望望龍湖上，魚龍薄漢雲。","鴻濛開半月，蛇穢破孤軍。","一鑑生風翰，千章渙浪紋。","法慈敷教化，清靜加彌綸。","法慈剪凶醜，凜冽迴春溫。","龍湖三五夜，棨戟四迴輪。","。"]', '["望望龙湖上，鱼龙薄漢云。","鴻濛开半月，蛇穢破孤軍。","一鑑生风翰，千章渙浪紋。","法慈敷教化，清静加彌綸。","法慈剪凶醜，凜冽迴春溫。","龙湖三五夜，棨戟四迴輪。","。"]', '诗', 'shi', '', NULL, '其四 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c4494f-680f-45d9-a52c-419b52252933', '其五', '其五', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["隻騎登南服，五龍開洞門。","未有登臨者，天留好使君。","湖心涵萬象，湖口合千春。","久翫天機動，昭迴漢表文。","迢遙天侶上，磊落野人羣。","促命茅君起，雄揮記五巡。"]', '["隻騎登南服，五龙开洞门。","未有登臨者，天留好使君。","湖心涵万象，湖口合千春。","久翫天機动，昭迴漢表文。","迢遙天侶上，磊落野人羣。","促命茅君起，雄揮記五巡。"]', '诗', 'shi', '', NULL, '其五 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a82a28-5247-4fa6-be7e-36c343391aff', '南獠納欵', '南獠納欵', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["南薰阜物華，南獠儼庭寔。","野味散芳芬，海殽參茂密。","胸篆飛瑞煙，蠙珠媚炎日。","掩嫮籠白鷴，鹽章悶鸂鶒。","歸化服維新，皇朝重玄[質]（盾）。","筮辰貢龍顏，表子躬逢地吉。"]', '["南薰阜物华，南獠儼庭寔。","野味散芳芬，海殽參茂密。","胸篆飞瑞煙，蠙珠媚炎日。","掩嫮籠白鷴，鹽章悶鸂鶒。","归化服維新，皇朝重玄[質]（盾）。","筮辰貢龙顏，表子躬逢地吉。"]', '诗', 'shi', '', NULL, '南獠納欵 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29993900-8dac-4f8a-8f9b-c8a039ea4355', '觀雪篇', '观雪篇', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["不敢希釀泉，忻然覩香雪。","圭璧充庭輝，山林變瑤闕。","農郊卜歲豐，帥閫和民悅。","觸簷鳴瑀珩，拂衙凜鐵鉞。","藻臺淨冰鑑，茶壺團素月。","聖恩宏海陬，邊臣効芹說。"]', '["不敢希釀泉，忻然覩香雪。","圭璧充庭輝，山林变瑤闕。","農郊卜歲豐，帥閫和民悅。","觸簷鳴瑀珩，拂衙凜鐵鉞。","藻台淨冰鑑，茶壺團素月。","聖恩宏海陬，邊臣効芹说。"]', '诗', 'shi', '', NULL, '觀雪篇 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da95fee3-ad04-4d93-8233-23775f3f72bc', '平獠宴喜', '平獠宴喜', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["玉鈐森萬騎，金鼓肅羣雄。","掃穴三苗竄，旋車百粤空。","風生雲無帳，雪壓碧油[幢]（憧）。","火烈消窮北，呈祥應歲東。","朝端張孝友，炮鱉待元戎。"]', '["玉鈐森万騎，金鼓肅羣雄。","掃穴三苗竄，旋车百粤空。","风生云無帳，雪壓碧油[幢]（憧）。","火烈消窮北，呈祥應歲东。","朝端張孝友，炮鱉待元戎。"]', '诗', 'shi', '', NULL, '平獠宴喜 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dbb8599-e210-450d-8421-8bc7e8a206f6', '山遊懷古', '山游懷古', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["迅烈驅黎瘴，委蛇陡翠微。","漢宮塵漠漠，隨社黍離離。","聖遠津稀問，蟾升樹亦輝。","晨昏童冠浴，夜靜士民嬉。","邊檄興師旅，秋深近阻饑。","仲由剛協力，曾點志同時。","倚曲酬歌去，宣尼正哂而。"]', '["迅烈驱黎瘴，委蛇陡翠微。","漢宮塵漠漠，隨社黍離離。","聖远津稀问，蟾升樹亦輝。","晨昏童冠浴，夜静士民嬉。","邊檄兴師旅，秋深近阻饑。","仲由剛協力，曾点志同时。","倚曲酬歌去，宣尼正哂而。"]', '诗', 'shi', '', NULL, '山遊懷古 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f76fee-0484-467a-a8e0-f2bae00973a4', '旋師之什', '旋師之什', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["雪盡青山昏，師旋赤眉至。","皇天監有光，邊帥却非義。","六月張貔貅，萬弓發羊豕。","海嶽皆效靈，苗民悉循紀。","卷舒如祥雲，進止若時雨。","薄暮天爲陰，銜枚肅我旅。","一火空巢窩，羣兇相籍死。","《采芑》歌言旋，記此非黷武。"]', '["雪尽青山昏，師旋赤眉至。","皇天監有光，邊帥却非義。","六月張貔貅，万弓發羊豕。","海嶽皆效靈，苗民悉循紀。","卷舒如祥云，進止若时雨。","薄暮天爲陰，銜枚肅我旅。","一火空巢窩，羣兇相籍死。","《采芑》歌言旋，記此非黷武。"]', '诗', 'shi', '', NULL, '旋師之什 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c06748-75e6-439e-8442-2b48d77bd8b5', '喜雨次曹泉州', '喜雨次曹泉州', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["上帝將垂譴，邊臣驚不寧。","徬徨勞野馬，乾曝俯龍亭。","精意馨穹昊，陽和正鬱蒸。","絪緼雲作瑞，黮𪒘雨成聲。","原濕枯隨發，生靈死復甦。","刑牲崇禮報，作頌慶昇平。"]', '["上帝將垂譴，邊臣驚不寧。","徬徨勞野马，乾曝俯龙亭。","精意馨穹昊，陽和正鬱蒸。","絪緼云作瑞，黮𪒘雨成声。","原濕枯隨發，生靈死复甦。","刑牲崇禮報，作頌慶昇平。"]', '诗', 'shi', '', NULL, '喜雨次曹泉州 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde9ceda-c0e7-4da0-aa8a-603a36426917', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["羲和停火輪，霡霂深民福。","年康收篚文，庭寔陳秋穫。","土產若未腴，勤綏功則博。","九五垂衣裳，千萬監忠樸。","銅虎謹深懸，木鐸今始作。","誥勅常佩吟，酒色難湎惑。","願皇欽福多，錫民無災瘼。","載答聖皇恩，轉輪赴河洛。"]', '["羲和停火輪，霡霂深民福。","年康收篚文，庭寔陳秋穫。","土產若未腴，勤綏功則博。","九五垂衣裳，千万監忠樸。","銅虎謹深懸，木鐸今始作。","誥勅常佩吟，酒色难湎惑。","願皇欽福多，錫民無災瘼。","載答聖皇恩，轉輪赴河洛。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb93adb-c980-48b3-8abf-c9c81e0afa44', '望闕謝恩', '望闕謝恩', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["御扆褒忠勇，官符再佩箴。","遐陬蒙一體，服馬赫遙臨。","海嶺知天瑞，懽忻荷聖心。","排衙香御胸，應郭撒妖祲。","講武勤西狩，呼嵩拜北欽。","天顏嚴咫尺，夙夜敢荒淫。"]', '["御扆褒忠勇，官符再佩箴。","遐陬蒙一體，服马赫遙臨。","海嶺知天瑞，懽忻荷聖心。","排衙香御胸，應郭撒妖祲。","講武勤西狩，呼嵩拜北欽。","天顏嚴咫尺，夙夜敢荒淫。"]', '诗', 'shi', '', NULL, '望闕謝恩 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7345602b-4dfc-48df-9dd1-03efa6f59a4b', '教民祭蜡', '教民祭蜡', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["玉壘陳釅酪，金盌薦芳饎。","父老吹龍笛，官僚仗虎墀。","山川出雲雨，神祇迴耀輝。","舞蹈幽明洽，趨蹌禮度微。","祈禳稱世世，民社兩無違。","。"]', '["玉壘陳釅酪，金盌薦芳饎。","父老吹龙笛，官僚仗虎墀。","山川出云雨，神祇迴耀輝。","舞蹈幽明洽，趨蹌禮度微。","祈禳稱世世，民社兩無違。","。"]', '诗', 'shi', '', NULL, '教民祭蜡 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a043d398-4fc5-4ef9-96cb-69a5f7b3cb29', '祀后土', '祀后土', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["天啓鑑湖清，靈源浸天碧。","不爲潛龍盤，上翊飛龍續。","花氣噴龍香，河光溥龍德。","福以龍德鍾，壽以龍仁益。","百禮祀龍神，九歌感龍格。","龍湖配天長，萬葉復千億。"]', '["天啓鑑湖清，靈源浸天碧。","不爲潛龙盤，上翊飞龙續。","花氣噴龙香，河光溥龙德。","福以龙德鍾，壽以龙仁益。","百禮祀龙神，九歌感龙格。","龙湖配天长，万葉复千億。"]', '诗', 'shi', '', NULL, '祀后土 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca282c71-ed6c-4cde-a5ae-8b76328de253', '修文語土民', '修文語土民', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["廟算符天象，干旄格有苗。","三軍歌按堵，萬騎弛鳴鏢。","虔嶺頑民遠，朝陽寇逆招。","偃文休衆士，錫命自皇朝。","莫篆天然石，惟吹洛下簫。","聲聞神起舞，氣感海無妖。","方叔猷元壯，相如賦未饒。","成周放牛馬，林野任逍遙。"]', '["廟算符天象，干旄格有苗。","三軍歌按堵，万騎弛鳴鏢。","虔嶺頑民远，朝陽寇逆招。","偃文休衆士，錫命自皇朝。","莫篆天然石，惟吹洛下簫。","声闻神起舞，氣感海無妖。","方叔猷元壯，相如賦未饒。","成周放牛马，林野任逍遙。"]', '诗', 'shi', '', NULL, '修文語土民 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b766c6c-0358-4d51-8739-899205485b5d', '半徑廬居語父老', '半徑廬居語父老', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["寒猿號嶺表，添我哭聲哀。","萬浦驅潮至，愁連撥不開。","二州諸父老，百里載牲來。","竅竁成堆玉，坊戎未砌階。","菜蕪間半徑，金石耀雙臺。","感愴千秋恨，期消四境埃。","陰扶祈大母，顯相賴殊才。","獸舞梁山下，龍眠潮海涯。","三杯酬地傑，一杖陟山迴。","環拜諸公罷，拈香奠晚罍。"]', '["寒猿號嶺表，添我哭声哀。","万浦驱潮至，愁連撥不开。","二州諸父老，百里載牲来。","竅竁成堆玉，坊戎未砌階。","菜蕪间半徑，金石耀雙台。","感愴千秋恨，期消四境埃。","陰扶祈大母，显相賴殊才。","獸舞梁山下，龙眠潮海涯。","三杯酬地傑，一杖陟山迴。","环拜諸公罷，拈香奠晚罍。"]', '诗', 'shi', '', NULL, '半徑廬居語父老 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ac0e48-fa98-474c-ad99-0dd02edd6227', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["丹心忠老母，白首媚萱堂。","萬里提兵路，三苗葬子方。","桑田多變海，萱草獨凌霜。","華潔凝秋色，葳蕤燦晚芳。","山靈驅毒蛀，神女靚明粧。","剝落千花後，舒遲百歲康。","如何齡九五，霞佩陟雲房。","語罷成追暮，羣然淚雨茫。","（原按：《誌銘》：總章己巳，閩廣之交，獠蠻嘯聚。","高宗命陳政公出撫之。","至界，以兵少請援，朝命二兄敏、敷領兵南下。","）（太母魏氏見三子之閩，乃與俱往。","至浙之江山縣，敏、敷病疽。","至浦城，孫子亦疽。","魏母提兵至鎮，政得進屯雲霄營。","政卒，孫元光將軍，代領其衆，奉建州治。","垂拱四年，魏氏卒，將軍以支孫承重，付州事于許天正，葬祖母于半徑山，結廬守制。","漳人稱半徑將軍。","故有《廬居語父老》之作。","）。"]', '["丹心忠老母，白首媚萱堂。","万里提兵路，三苗葬子方。","桑田多变海，萱草独凌霜。","华潔凝秋色，葳蕤燦晚芳。","山靈驱毒蛀，神女靚明粧。","剝落千花後，舒遲百歲康。","如何齡九五，霞佩陟云房。","語罷成追暮，羣然泪雨茫。","（原按：《誌銘》：總章己巳，閩廣之交，獠蠻嘯聚。","高宗命陳政公出撫之。","至界，以兵少請援，朝命二兄敏、敷領兵南下。","）（太母魏氏见三子之閩，乃與俱往。","至浙之江山縣，敏、敷病疽。","至浦城，孫子亦疽。","魏母提兵至鎮，政得進屯云霄營。","政卒，孫元光將軍，代領其衆，奉建州治。","垂拱四年，魏氏卒，將軍以支孫承重，付州事于許天正，葬祖母于半徑山，結廬守制。","漳人稱半徑將軍。","故有《廬居語父老》之作。","）。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fee188-929e-416c-9d84-4344f992cb74', '語州縣諸公敏續', '語州縣諸公敏續', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["總角趨朝對，雄飛出禁城。","人才當翊國，世賞可辭榮。","憐厥神童子，尋爲壯友生。","南方承父鎮，北闕列儒名。","移孝爲忠吉，由奢入儉寧。","長安瞻日月，嶺海肅風霆。","敗事誠因酒，增高必自陵。","尊老須養老，使士要推誠。","寅協無他式，清勤慎不矜。"]', '["總角趨朝对，雄飞出禁城。","人才當翊国，世賞可辞榮。","怜厥神童子，尋爲壯友生。","南方承父鎮，北闕列儒名。","移孝爲忠吉，由奢入儉寧。","长安瞻日月，嶺海肅风霆。","敗事誠因酒，增高必自陵。","尊老須養老，使士要推誠。","寅協無他式，清勤慎不矜。"]', '诗', 'shi', '', NULL, '語州縣諸公敏續 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd0f9e48-5d13-4189-a81b-f78b0bc2f016', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["敦倫開野叟，勤學勸生儒。","刊爵雖殊分，同仁本一途。","雲泥如有隔，水火豈相資。","飲露知蟬潔，觀顏覺鑑虛。","潛光同隱豹，出宰必懸魚。","適國無先後，梯雲有卷舒。","天文迴北極，水勢赴東都。","定策參耆宿，輪忠奉簡書。","彌重勳業懋，開國負稱孤。"]', '["敦倫开野叟，勤学勸生儒。","刊爵雖殊分，同仁本一途。","云泥如有隔，水火豈相資。","饮露知蟬潔，观顏覺鑑虛。","潛光同隐豹，出宰必懸鱼。","適国無先後，梯云有卷舒。","天文迴北極，水勢赴东都。","定策參耆宿，輪忠奉簡书。","彌重勳業懋，开国負稱孤。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ac31d7-9fd7-485c-b234-4dd4bb2f8f95', '和王採訪重九見訪', '和王採訪重九见訪', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["河北推儒雅，嵩高降嶽神。","明徑通桂掖，飛幰渡荆津。","明快宜朝美，疏通亦我憐。","怒同雷電厲，喜沛雨霖恩。","喬木家聲舊，嚴軺帝命新。","心交今管[鮑]（飽），籌運訪張陳。","是日登高節，伊誰送酒頻。","江州華胄使，携榼再慇懃。","。"]', '["河北推儒雅，嵩高降嶽神。","明徑通桂掖，飞幰渡荆津。","明快宜朝美，疏通亦我怜。","怒同雷電厲，喜沛雨霖恩。","喬木家声旧，嚴軺帝命新。","心交今管[鲍]（飽），籌運訪張陳。","是日登高節，伊誰送酒頻。","江州华胄使，携榼再慇懃。","。"]', '诗', 'shi', '', NULL, '和王採訪重九見訪 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0529a02c-1329-4ad2-8c01-861648901498', '公庭春宴', '公庭春宴', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["東風驅凍去，萬品破陽輝。","紅紫粧春媚，罍樽試酒奇。","公庭開月榭，農榼薦時犧。","興逐芳芬發，盃同蜂蝶飛。","誰云佳節會，獨與賞心違。","信手撚紅[瓣]（辨），粘衣盡紫蕤。","陰移來日者，各贈滿須歸。"]', '["东风驱凍去，万品破陽輝。","紅紫粧春媚，罍樽試酒奇。","公庭开月榭，農榼薦时犧。","兴逐芳芬發，盃同蜂蝶飞。","誰云佳節會，独與賞心違。","信手撚紅[瓣]（辨），粘衣尽紫蕤。","陰移来日者，各贈满須归。"]', '诗', 'shi', '', NULL, '公庭春宴 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea760c98-3002-44b8-8f6d-ada7f0dacd89', '酬裴使君王探公', '酬裴使君王探公', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["百粤臨南海，儒冠任使軺。","饋我兼金佩，和之美玉簫。","清風生四座，麗日正良霄。","意氣宜令契，公忠豈古饒。","簡書頻誦讀，玉燭要均調。","冰鑑秋霄察，君門萬里遙。","驪騑歌四牡，諤諤答清朝。"]', '["百粤臨南海，儒冠任使軺。","饋我兼金佩，和之美玉簫。","清风生四座，丽日正良霄。","意氣宜令契，公忠豈古饒。","簡书頻誦读，玉燭要均調。","冰鑑秋霄察，君门万里遙。","驪騑歌四牡，諤諤答清朝。"]', '诗', 'shi', '', NULL, '酬裴使君王探公 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be44055-3322-451c-839f-d7f57d478499', '晚春旋漳會酌', '晚春旋漳會酌', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["帝德符三極，皇風振四夷。","將軺春暮飲，士卒嶺南馳。","馬嘯腥風遠，兵歌暖日怡。","妖雲驅屏跡，芳卉媚迎詩。","拍掌橫弓槊，徘徊索酒巵。","陰處竄蛇豕，暗笑使君迷。"]', '["帝德符三極，皇风振四夷。","將軺春暮饮，士卒嶺南驰。","马嘯腥风远，兵歌暖日怡。","妖云驱屏跡，芳卉媚迎诗。","拍掌橫弓槊，徘徊索酒巵。","陰处竄蛇豕，暗笑使君迷。"]', '诗', 'shi', '', NULL, '晚春旋漳會酌 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab3c5b4-60fa-421d-8125-803cdfd47d19', '故國山川寫景', '故国山川寫景', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["浮光昂岳望，固始秀民鄉。","第宅參文武，姻㜕半帝王。","珠樓簾結綺，花苑水流香。","禮節傳家範，簪纓奕世芳。","飛鞭馳道坦，聚蓋艷陽光。","簫鼓迎懽會，桐麻遣唁喪。","勳臣扶景運，風樹配天長。"]', '["浮光昂岳望，固始秀民乡。","第宅參文武，姻㜕半帝王。","珠楼簾結綺，花苑水流香。","禮節傳家範，簪纓奕世芳。","飞鞭驰道坦，聚蓋艷陽光。","簫鼓迎懽會，桐麻遣唁喪。","勳臣扶景運，风樹配天长。"]', '诗', 'shi', '', NULL, '故國山川寫景 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358aa3dd-e1fc-4e88-9d1c-5a015b47ff64', '神湖州三山神題壁', '神湖州三山神題壁', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["孤隨不尊士，幽谷多豪傑。","三山亦隱者，韜晦忘其名。","勝蹟美山水，妙思神甲兵。","精誠諒斯在，對越儼如生。","木石森騶伏，雲烟拂旆旌。","雨暘祈響應，龍鳳勅碑銘。","清泚符神潔，香芹契德馨。","三山耀神德，萬歲翊唐靈。","。"]', '["孤隨不尊士，幽谷多豪傑。","三山亦隐者，韜晦忘其名。","勝蹟美山水，妙思神甲兵。","精誠諒斯在，对越儼如生。","木石森騶伏，云烟拂旆旌。","雨暘祈响應，龙鳳勅碑銘。","清泚符神潔，香芹契德馨。","三山耀神德，万歲翊唐靈。","。"]', '诗', 'shi', '', NULL, '神湖州三山神題壁 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32dfe0b6-c0ae-423d-afaa-371504961f9a', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["孤雲悅我心，一點通神意。","流泉濯巨靈，深谷豁神智。","魈魅神之兵，黎庶神所庇。","精氣燭彼天，名山妥靈地。","嶺表開崇祠，遼東建神幟。","六字動天威，九重頒歲祭。","相期翊國忠，我輿三神契。"]', '["孤云悅我心，一点通神意。","流泉濯巨靈，深谷豁神智。","魈魅神之兵，黎庶神所庇。","精氣燭彼天，名山妥靈地。","嶺表开崇祠，遼东建神幟。","六字动天威，九重頒歲祭。","相期翊国忠，我輿三神契。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6c7f41-e9e1-46cf-89ab-21f463991a8d', '其三', '其三', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["孤征東嶺表，[冒]（胃）雨一登臨。","再拜煙霧霽，羣峰奎璧森。","獨山峰聳閣，中谷水鳴琴。","明山卉木翳，遙林雲霧深。","瞻廟開明貺，平遼斷穢祲。","神颫號萬籟，列宿獻千禽。","樹尾揚旌帛，山頭鏇革金。","葵陽烘固介，華露潤華簪。","鼎立崢嶸勢，鐘聞杳靄陰。","綰荷據口勾，掬水洗懷襟。","瀑石流觴詠，豐碑駐馬吟。","三山香火地，萬古帝王欽。"]', '["孤征东嶺表，[冒]（胃）雨一登臨。","再拜煙霧霽，羣峰奎璧森。","独山峰聳閣，中谷水鳴琴。","明山卉木翳，遙林云霧深。","瞻廟开明貺，平遼斷穢祲。","神颫號万籟，列宿獻千禽。","樹尾揚旌帛，山头鏇革金。","葵陽烘固介，华露潤华簪。","鼎立崢嶸勢，鐘闻杳靄陰。","綰荷據口勾，掬水洗懷襟。","瀑石流觴詠，豐碑駐马吟。","三山香火地，万古帝王欽。"]', '诗', 'shi', '', NULL, '其三 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ba9f62-8588-4509-8ff3-dae05f9b7ba7', '至人行', '至人行', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["至人平念慮，好惡歸其衷。","試劍三苗罪，同車蓋世雄。","斷蛟驅猛虎，附鳳翊飛龍。","際會風雲上，清平嶺海中。","窮民加保惠，勳士祿功庸。","姝子干旌紕，妖淫桎[梏]（桔）凶。","熱籌消{氵灾}氣，精蓋啓宸聰。","卓爾三才立，巋哉一道同。"]', '["至人平念慮，好惡归其衷。","試劍三苗罪，同车蓋世雄。","斷蛟驱猛虎，附鳳翊飞龙。","際會风云上，清平嶺海中。","窮民加保惠，勳士祿功庸。","姝子干旌紕，妖淫桎[梏]（桔）凶。","熱籌消{氵灾}氣，精蓋啓宸聰。","卓爾三才立，巋哉一道同。"]', '诗', 'shi', '', NULL, '至人行 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb6f4a0-a546-4318-b9a4-b3f3ac16228c', '雲龍', '云龙', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["乾坤成列神流通，純陽附陰生神龍。","伸屈妙運參帝功，一鼓絪緼油雲從。","飛翔四海雨域[中]（十），萬彙焦枯仰化融。","苦時潛德來奮蹤，羣生渴想心忡忡。","雷鳴雲起德斯普，變化循環自今古。","。"]', '["乾坤成列神流通，純陽附陰生神龙。","伸屈妙運參帝功，一鼓絪緼油云從。","飞翔四海雨域[中]（十），万彙焦枯仰化融。","苦时潛德来奮蹤，羣生渴想心忡忡。","雷鳴云起德斯普，变化循环自今古。","。"]', '诗', 'shi', '', NULL, '雲龍 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a5d97d-263f-4eb6-b4c8-879fca9c7ec7', '風虎', '风虎', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["乾坤義氣爲虎神，咆哮尚闞誰相親。","浮雲滿谷隨相震，嘯地生風鼓氣新。","日入山林膳百獸，時清效數宗麒麟。","忍饑渡河知仁人，威彰揮爪雄武臣。","戴王秉義無忘噬，作政行苛何誅夷。"]', '["乾坤義氣爲虎神，咆哮尚闞誰相親。","浮云满谷隨相震，嘯地生风鼓氣新。","日入山林膳百獸，时清效數宗麒麟。","忍饑渡河知仁人，威彰揮爪雄武臣。","戴王秉義無忘噬，作政行苛何誅夷。"]', '诗', 'shi', '', NULL, '風虎 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96280614-a33c-424a-9fb5-cb239188867c', '聖作物覩', '聖作物覩', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["乾坤正氣鍾聖物，聰明天縱臨生民。","四靈百端皆符身，九夷八蠻咸來賓。","制作百爲開彝倫，明禋千載秋又春。","物覩之聖爲何人，[羲]（義）農堯舜禹湯文。","萬古帝王咸準則，祗令萬物覩者德。"]', '["乾坤正氣鍾聖物，聰明天縱臨生民。","四靈百端皆符身，九夷八蠻咸来賓。","制作百爲开彝倫，明禋千載秋又春。","物覩之聖爲何人，[羲]（義）農堯舜禹湯文。","万古帝王咸準則，祗令万物覩者德。"]', '诗', 'shi', '', NULL, '聖作物覩 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b78f631-394f-475c-833f-63412c81caa8', '真人操', '真人操', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["陰陽妙教生真人，名山勝地隱其身。","吹噓瀨氣完元神，陞降雪外離煙塵。","軒轅乘龍萬歲春，穆觀王母存崑崙。","青牛出關避世紛，招呼鸞鶴引霞樽。","秦王漢武心塵土，欲求真仙惡得覩。"]', '["陰陽妙教生真人，名山勝地隐其身。","吹噓瀨氣完元神，陞降雪外離煙塵。","軒轅乘龙万歲春，穆观王母存崑崙。","青牛出关避世紛，招呼鸾鹤引霞樽。","秦王漢武心塵土，欲求真仙惡得覩。"]', '诗', 'shi', '', NULL, '真人操 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dadcaf5-be61-48d2-af02-a9e9d701d9e8', '恩義操', '恩義操', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["天尊地卑分君臣，乾男坤女生男孫。","懷恩抱義成人倫，入有雙親出有君。","行義顯親親以尊，隆恩敦君君以仁。","君仁親尊恩義純，雙全忠孝參乾坤。","春秋亂賊紛然起，仲尼一筆扶人紀。"]', '["天尊地卑分君臣，乾男坤女生男孫。","懷恩抱義成人倫，入有雙親出有君。","行義显親親以尊，隆恩敦君君以仁。","君仁親尊恩義純，雙全忠孝參乾坤。","春秋亂賊紛然起，仲尼一笔扶人紀。"]', '诗', 'shi', '', NULL, '恩義操 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd93765-59eb-4e94-8dae-05ca2dd9685e', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["嶺海物產知君臣，黑鯉朝北葵向曛。","嶺海物產知慈仁，寒獺祭魚烏哺親。","吳起學曾斯學[荀]（筍），欺君害民喪不奔。","祿養生成忘義恩，不如鷄犬司門晨。"]', '["嶺海物產知君臣，黑鯉朝北葵向曛。","嶺海物產知慈仁，寒獺祭鱼烏哺親。","吳起学曾斯学[荀]（筍），欺君害民喪不奔。","祿養生成忘義恩，不如鷄犬司门晨。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc003798-c335-4aee-b9a9-08b4bd619321', '忠烈操', '忠烈操', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["乾生男子坤生姝，國有君王家有夫。","委[質]（盾）結褵託其軀，三綱五常與命俱。","一朝凶變違常途，匡扶弗得將何如？","英英烈烈[他]（地）慮無。","捨生取義終不[渝]（瑜）。","《柏舟》之詩王蠋語，千古芳名耀青史。"]', '["乾生男子坤生姝，国有君王家有夫。","委[質]（盾）結褵託其軀，三綱五常與命俱。","一朝凶变違常途，匡扶弗得將何如？","英英烈烈[他]（地）慮無。","捨生取義終不[渝]（瑜）。","《柏舟》之诗王蠋語，千古芳名耀青史。"]', '诗', 'shi', '', NULL, '忠烈操 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae12ed3-a69b-46ad-b498-4e7dbb6ae738', '候夜行師七唱', '候夜行師七唱', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["一從長髮離京城，侍父寒暄經萬程。","上籲玄天低籲地，朝瞻紅日夜瞻星。","諸君喜抵王師所，四顧傷爲荆莽坰。","羣落妻拏凄泣聲，俄然戎醜萬交橫。","司空淑人頻勸諭，英雄死義無求生。","馬皮遠裹伏波骨，銅柱高標交趾驚。","振旅龍江修戰具，移文鳳闕請增兵。"]', '["一從长髮離京城，侍父寒暄經万程。","上籲玄天低籲地，朝瞻紅日夜瞻星。","諸君喜抵王師所，四顧傷爲荆莽坰。","羣落妻拏凄泣声，俄然戎醜万交橫。","司空淑人頻勸諭，英雄死義無求生。","马皮远裹伏波骨，銅柱高標交趾驚。","振旅龙江修戰具，移文鳳闕請增兵。"]', '诗', 'shi', '', NULL, '候夜行師七唱 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2b9bcc-d661-4ecb-b3b2-9dbd7f05e64b', '其二', '其二', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["魏母咸亨奉勅文，府兵雲衆成營屯。","屹然一鎮雲霄末，漸爾羣言花柳春。","男生女長通蕃息，五十八氏交爲婚。","火田黃稻俱甘旨，綱水金魚洽醉。","寇戎不測紛如雪，甲胄何時不出門。","夜祀天皇弘德澤，日將山獠化縞民。","一聲譙鼓月初出，戍樓西北望皇閽。"]', '["魏母咸亨奉勅文，府兵云衆成營屯。","屹然一鎮云霄末，漸爾羣言花柳春。","男生女长通蕃息，五十八氏交爲婚。","火田黄稻俱甘旨，綱水金鱼洽醉。","寇戎不測紛如雪，甲胄何时不出门。","夜祀天皇弘德澤，日將山獠化縞民。","一声譙鼓月初出，戍楼西北望皇閽。"]', '诗', 'shi', '', NULL, '其二 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3037e51-1d32-49b0-b8ef-eb47756beb59', '其三', '其三', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["戍樓西北望皇閽，日暖桃緋京國春。","公子踏青陪御輦，官民結彩慶姻門。","上林花木胭脂媚，邊境桑蔴戟劍屯。","乳燕東風相對語，老親上塚孰溫存。","採茶喜鑽新榆火，修[禊]（楔）爭驅舊虜氛。","盡醉韶華三月暮，誰聞更鼓二更巡。"]', '["戍楼西北望皇閽，日暖桃緋京国春。","公子踏青陪御輦，官民結彩慶姻门。","上林花木胭脂媚，邊境桑蔴戟劍屯。","乳燕东风相对語，老親上塚孰溫存。","採茶喜鑽新榆火，修[禊]（楔）爭驱旧虜氛。","尽醉韶华三月暮，誰闻更鼓二更巡。"]', '诗', 'shi', '', NULL, '其三 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fcbd670-473d-4c72-8b8a-3f686d99a04e', '其四', '其四', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["戍樓西北望皇家，夏永南征嶺海賒。","殿閣涼生梅浦雨，葵柳紅映錦江霞。","侮凌烽火心如水，變幻風雲眼未花。","犀照湖花消魍{鬼象}，龍呈劍氣射虛邪。","赤鳥黑馬流紅汗，綠柳金鶯冒翠華。","淬礪戈矛尋石上，沉浮瓜李戲江涯。","蕙蘭紉佩生香滿，荷芰縫衫御暑嘉。","較斧開林驅虎豹，施罟截港捕魚蝦。","火田畬種無耕犢，陰隙戎潛起宿鴉。","夜析重門防暴客，三更三點尚排衙。"]', '["戍楼西北望皇家，夏永南征嶺海賒。","殿閣涼生梅浦雨，葵柳紅映錦江霞。","侮凌烽火心如水，变幻风云眼未花。","犀照湖花消魍{鬼象}，龙呈劍氣射虛邪。","赤鸟黑马流紅汗，綠柳金鶯冒翠华。","淬礪戈矛尋石上，沉浮瓜李戲江涯。","蕙蘭紉佩生香满，荷芰縫衫御暑嘉。","較斧开林驱虎豹，施罟截港捕鱼蝦。","火田畬種無耕犢，陰隙戎潛起宿鴉。","夜析重门防暴客，三更三点尚排衙。"]', '诗', 'shi', '', NULL, '其四 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f1bc7c-f73f-44be-b695-dffc7fd3e73e', '其五', '其五', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["戍樓西北望皇州，宿衙曾隨上苑遊。","明月蘆花迷曲岸，西風梧葉報清秋。","鳳凰臺上幾聲笛，鸚鵡洲邊一葦舟。","對菊淵明懷刺史，拋梭織女弄牽牛。","娟娟萬里江河爛，耽耽孤星大火流。","白雁遠傳蘇武札，銀鱸細切[季]（李）鷹[羞]（差）。","露悽霜肅吳砧搗，馬壯兵強楚戍愁。","報道四更笳鼓響，銜枚襲虜獻俘囚。"]', '["戍楼西北望皇州，宿衙曾隨上苑游。","明月蘆花迷曲岸，西风梧葉報清秋。","鳳凰台上幾声笛，鸚鵡洲邊一葦舟。","对菊淵明懷刺史，拋梭织女弄牽牛。","娟娟万里江河爛，耽耽孤星大火流。","白雁远傳蘇武札，銀鱸細切[季]（李）鷹[羞]（差）。","露悽霜肅吳砧捣，马壯兵強楚戍愁。","報道四更笳鼓响，銜枚襲虜獻俘囚。"]', '诗', 'shi', '', NULL, '其五 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0582b86a-6a4c-4d87-abdd-a99917be0a86', '其六', '其六', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["戍樓西北請泉山，十載干戈暑又寒。","紅錦飄來楓樹醉，黃金廢盡菊花殘。","故園橙橘小春鬧，聖席圓湯冬至閑。","劍戟百磨巖石裂，驊騮羣飲澤泉乾。","雪花散雜梅花媚，白水前爲墨水餐。","河腹冰堅防虜騎，邊陲雨涷弊征鞍。","水窗向北因風寒，密壘開東得月看。","迭起寒雞猶未唱，銅壺先滴五更闌。"]', '["戍楼西北請泉山，十載干戈暑又寒。","紅錦飄来楓樹醉，黄金廢尽菊花殘。","故园橙橘小春鬧，聖席圓湯冬至闲。","劍戟百磨巖石裂，驊騮羣饮澤泉乾。","雪花散杂梅花媚，白水前爲墨水餐。","河腹冰堅防虜騎，邊陲雨涷弊征鞍。","水窗向北因风寒，密壘开东得月看。","迭起寒雞猶未唱，銅壺先滴五更闌。"]', '诗', 'shi', '', NULL, '其六 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c11a41-aaff-48fb-96b4-1d8a41453d1b', '其七', '其七', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["黃昏候夜到更闌，爆竺驚聞把劍看。","士友同仇裘共敝，丈夫努力飯加餐。","星移物換鬢花白，月落參橫燭淚乾。","怨女鸞孤來遶枕，征夫馬健不離鞍。","量弘宇宙無遺壤，令肅風霆欲裂山。","義重同胞堪搏虎，身輕戰甲不號寒。","灰飛葭管陽初復，拍落梅花歌示殘。","歌嘯未殘胡虜却，東南取道夕長安。","（以上均錄自廈門圖書館古籍部藏《潁川陳氏開漳族譜》，原注出《龍月公集》。","此譜爲陳禎祥撰，民國五年印。","陳元光詩皆承廈門大學中文系吳在慶同志錄示。","）（按：《文獻》一九八七年第三輯刊何池《新見唐陳元光佚詩》，云龍海縣東園鄉潭頭村藏《陳氏族譜》，亦收有陳元光詩，文字稍異。","惜未獲見參校。","）。"]', '["黄昏候夜到更闌，爆竺驚闻把劍看。","士友同仇裘共敝，丈夫努力飯加餐。","星移物換鬢花白，月落參橫燭泪乾。","怨女鸾孤来遶枕，征夫马健不離鞍。","量弘宇宙無遺壤，令肅风霆欲裂山。","義重同胞堪搏虎，身轻戰甲不號寒。","灰飞葭管陽初复，拍落梅花歌示殘。","歌嘯未殘胡虜却，东南取道夕长安。","（以上均錄自廈门圖书館古籍部藏《潁川陳氏开漳族譜》，原注出《龙月公集》。","此譜爲陳禎祥撰，民国五年印。","陳元光诗皆承廈门大学中文系吳在慶同志錄示。","）（按：《文獻》一九八七年第三輯刊何池《新见唐陳元光佚诗》，云龙海縣东园乡潭头村藏《陳氏族譜》，亦收有陳元光诗，文字稍異。","惜未獲见參校。","）。"]', '诗', 'shi', '', NULL, '其七 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e782dbc0-59f6-4287-97e3-7048eeebf63d', '真妄偈', '真妄偈', '08343759-eab7-4bdd-8d34-78d2276baa16', '唐', '["真法性本淨，妄念何由起？從真有妄生，此妄何所止？無初即無末，有終應有始。","無始而無終，長懷懵茲理。","願爲開玄妙，析之出生死。","（《林間錄》卷上）。"]', '["真法性本淨，妄念何由起？從真有妄生，此妄何所止？無初即無末，有終應有始。","無始而無終，长懷懵茲理。","願爲开玄妙，析之出生死。","（《林间錄》卷上）。"]', '诗', 'shi', '', NULL, '真妄偈 復禮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f913c22-25b3-4182-8e3c-d368fdcc6659', '憶雲門', '憶云门', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["樹閑煙不破，溪靜鷺忘飛。","更愛幽奇處，斜陽艷翠微。","（見《會稽掇英總集》卷六）。"]', '["樹闲煙不破，溪静鷺忘飞。","更愛幽奇处，斜陽艷翠微。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '憶雲門 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63da25d1-37cb-4b6d-ab9a-0839d932a3aa', '西施浣紗篇', '西施浣紗篇', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["西施舊石在，苔蘚日於滋。","幾處沾粧汙，何年滅履綦？","岸花羞慢臉，波月斅嚬眉。","君將花月好，來比浣紗時。","（影印本《詩淵》第一冊第六三頁）。"]', '["西施旧石在，苔蘚日於滋。","幾处沾粧汙，何年滅履綦？","岸花羞慢臉，波月斅嚬眉。","君將花月好，来比浣紗时。","（影印本《诗淵》第一冊第六三頁）。"]', '诗', 'shi', '', NULL, '西施浣紗篇 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a575fd51-ac53-4871-94d4-bfb0901601ff', '潛珠篇', '潛珠篇', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["夜光四寸今所無，聞有入海求大珠。","大珠自愛潛不發，希世一見比明月。","靈物變化詎可尋？幾人皓首死閩越。","泥蟠沙臥海底沉，何知結愛美人心。","可憐曜乘十二乘，誰惜黃金七百金。","越鄉祈寶誠非易，涉險捐軀名與義。","天生至寶自無倫，如何真僞人莫分。","古來貴耳而賤目，恐君既見不及聞。","世有南山採薇子，從來道氣凌白雲。","今乃千里作一尉，無媒爲獻明聖君。","（同前七一頁）。"]', '["夜光四寸今所無，闻有入海求大珠。","大珠自愛潛不發，希世一见比明月。","靈物变化詎可尋？幾人皓首死閩越。","泥蟠沙臥海底沉，何知結愛美人心。","可怜曜乘十二乘，誰惜黄金七百金。","越乡祈寶誠非易，涉險捐軀名與義。","天生至寶自無倫，如何真僞人莫分。","古来貴耳而賤目，恐君既见不及闻。","世有南山採薇子，從来道氣凌白云。","今乃千里作一尉，無媒爲獻明聖君。","（同前七一頁）。"]', '诗', 'shi', '', NULL, '潛珠篇 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('904fb654-ea4c-4d35-8c89-8ca23155985a', '遊嵩岳待寄詩誚之', '游嵩岳待寄诗誚之', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["嵩峯高不極，上有玉瑯玕。","佳遊竟不至，何以慰長薚？","（同前七四四頁）。"]', '["嵩峯高不極，上有玉瑯玕。","佳游竟不至，何以慰长薚？","（同前七四四頁）。"]', '诗', 'shi', '', NULL, '遊嵩岳待寄詩誚之 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4b5c72-8bea-406a-86a7-151dd2fdb26b', '錢江曉寄十三弟', '錢江晓寄十三弟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["曉泊錢塘渚，開簾遠望通。","海雲張野暗，山火徹江紅。","客淚常思北，邊愁欲盡東。","從來夢兄弟，未似昨宵中。","（同前七五八頁）。"]', '["晓泊錢塘渚，开簾远望通。","海云張野暗，山火徹江紅。","客泪常思北，邊愁欲尽东。","從来梦兄弟，未似昨宵中。","（同前七五八頁）。"]', '诗', 'shi', '', NULL, '錢江曉寄十三弟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31f4127-f9a3-46f2-9326-2f3d805fe3fc', '緱山詩', '緱山诗', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["緱山連嵩岑，近帶洛陽陌。","洛京遊宦子，不知虛直宅。","北入養龍谿，勢如夏雲積。","褰涉窮水府，躋攀倚霞壁。","檉栝穿虹𡸣，蘿蔦曳金碧。","崟嶔天蓋小，路轉石門窄。","還顧杳虧蔽，前瞻浩攢𤤐。","態繁賞屢移，形變魂方惕。","洞隱息心士，源潛度世客。","漁樵或迷途，誌刻述往迹。","安仁寔載誕，子晉曾所歷。","王元拜隱侯，吾祖挹仙伯。","永興白華感，久列丹臺籍。","弊廬對石堂，虛坐留玉舄。","洎余愛羽化，洗心向禪寂。","志結顏始紅，歲闌髮已白。","愧無兼濟美，獨營弱喪魄。","歸來緝衰暮，敦本事膏液。","始願期儻從，揮手弄煙策。","（同前第三冊第二○八五頁）。"]', '["緱山連嵩岑，近带洛陽陌。","洛京游宦子，不知虛直宅。","北入養龙谿，勢如夏云積。","褰涉窮水府，躋攀倚霞壁。","檉栝穿虹𡸣，蘿蔦曳金碧。","崟嶔天蓋小，路轉石门窄。","還顧杳虧蔽，前瞻浩攢𤤐。","態繁賞屢移，形变魂方惕。","洞隐息心士，源潛度世客。","漁樵或迷途，誌刻述往迹。","安仁寔載誕，子晉曾所歷。","王元拜隐侯，吾祖挹仙伯。","永兴白华感，久列丹台籍。","弊廬对石堂，虛坐留玉舄。","洎余愛羽化，洗心向禪寂。","志結顏始紅，歲闌髮已白。","愧無兼濟美，独營弱喪魄。","归来緝衰暮，敦本事膏液。","始願期儻從，揮手弄煙策。","（同前第三冊第二○八五頁）。"]', '诗', 'shi', '', NULL, '緱山詩 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dbfca05-5622-4e0d-bfb6-67b1898bf537', '北邙古墓', '北邙古墓', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["君不見邙山苑外上宮墳，相接纍纍縈蔓草。","宮亭遠識南宮樹，逶迤輾作南宮道。","一朝形影化窮塵，昔時玉貌與朱唇。","錦衾香覆青樓月，羅衣嬌弄紫臺雲。","越娃楚艷君不見，趙舞燕歌愁殺人。","遊鼙倐掩寂無晤，蛾眉何事須相妬。","九重見日閉鴛鴦，三泉今夕開狐兔。","駐馬倚車望洛陽，御橋天闕遙相當。","佳人死別無歸日，可憐行路盡沾衣。","（同前第二一八八頁）。"]', '["君不见邙山苑外上宮墳，相接纍纍縈蔓草。","宮亭远識南宮樹，逶迤輾作南宮道。","一朝形影化窮塵，昔时玉貌與朱唇。","錦衾香覆青楼月，羅衣嬌弄紫台云。","越娃楚艷君不见，趙舞燕歌愁殺人。","游鼙倐掩寂無晤，蛾眉何事須相妬。","九重见日閉鴛鴦，三泉今夕开狐兔。","駐马倚车望洛陽，御橋天闕遙相當。","佳人死別無归日，可怜行路尽沾衣。","（同前第二一八八頁）。"]', '诗', 'shi', '', NULL, '北邙古墓 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a1d099-9055-4a0c-9f6e-712817d831f1', '陸渾南桃花湯', '陸渾南桃花湯', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["氛氳桃花湯，去都三百里。","遠峯益稠沓，具物盡奇詭。","借問採藥人，冥奧從此始。","汨吾尚清淨，葷血久誓止。","覽彼□□鮮，自謂形骸滓。","重敦永劫願，無負神泉水。","坐馳意屢愜，身踐心益死。","長妹梵筵衆，拙妻道門子。","提攜遊二山，歲暮此已矣。","（同前第二一八八頁）。"]', '["氛氳桃花湯，去都三百里。","远峯益稠沓，具物尽奇詭。","借问採藥人，冥奧從此始。","汨吾尚清淨，葷血久誓止。","覽彼□□鲜，自謂形骸滓。","重敦永劫願，無負神泉水。","坐驰意屢愜，身踐心益死。","长妹梵筵衆，拙妻道门子。","提携游二山，歲暮此已矣。","（同前第二一八八頁）。"]', '诗', 'shi', '', NULL, '陸渾南桃花湯 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af32419-c44f-4f90-9964-2bd19a2a3a16', '花燭行', '花燭行', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["帝城九門乘夜開，仙車百兩自天來。","列火東歸暗行月，浮橋西渡響奔雷。","龍樓錦障連連出，遙望梁臺如晝日。","梁臺花燭見天人，平陽賓從綺羅春。","共迎織女歸春幄，俱送常娥下月輪。","常娥月中君未見，紅粉盈盈隔團扇。","玉樽交引合歡盃，珠履共蹋鴛鴦薦。","漏盡更深斗欲斜，可憐金翠滿庭花。","庭花灼灼歌穠李，此夕天孫嫁王子。","結褵初出望園中，和鳴已入秦筲裏。","同心合帶兩相依，明日雙朝入此微。","共待洛城分曙色，更看天下鳳凰飛。","（同前第二冊第一三九二頁）。"]', '["帝城九门乘夜开，仙车百兩自天来。","列火东归暗行月，浮橋西渡响奔雷。","龙楼錦障連連出，遙望梁台如晝日。","梁台花燭见天人，平陽賓從綺羅春。","共迎织女归春幄，俱送常娥下月輪。","常娥月中君未见，紅粉盈盈隔團扇。","玉樽交引合歡盃，珠履共蹋鴛鴦薦。","漏尽更深斗欲斜，可怜金翠满庭花。","庭花灼灼歌穠李，此夕天孫嫁王子。","結褵初出望园中，和鳴已入秦筲裏。","同心合带兩相依，明日雙朝入此微。","共待洛城分曙色，更看天下鳳凰飞。","（同前第二冊第一三九二頁）。"]', '诗', 'shi', '', NULL, '花燭行 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddfbf2b-3f21-4685-a44c-0fa2e4122866', '臥聞嵩山鐘', '臥闻嵩山鐘', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["臥聞嵩山鐘，振衣步蹊樾。","槁葉零宿雨，新鴻叫晴月。","物改興心換，夜涼清機發。","昔事潘鎮人，北岑採[薇]（微）蕨。","倚巖顧我笑，謂我有仙骨。","銘德在青春，徇祿去玄髮。","悔往自昭洗，練形歸洞窟。","（同前第一四三五頁）。"]', '["臥闻嵩山鐘，振衣步蹊樾。","槁葉零宿雨，新鴻叫晴月。","物改兴心換，夜涼清機發。","昔事潘鎮人，北岑採[薇]（微）蕨。","倚巖顧我笑，謂我有仙骨。","銘德在青春，徇祿去玄髮。","悔往自昭洗，練形归洞窟。","（同前第一四三五頁）。"]', '诗', 'shi', '', NULL, '臥聞嵩山鐘 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('647a5e3c-96df-493c-8b82-b111b62b84f8', '初承恩旨言放歸舟', '初承恩旨言放归舟', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["一朝承凱澤，萬里別荒陬。","去國雲南滯，還鄉水北流。","淚迎今日喜，夢換昨宵愁。","自向歸魂說，炎方不可留。","（同前第一四九八頁）。"]', '["一朝承凱澤，万里別荒陬。","去国云南滯，還乡水北流。","泪迎今日喜，梦換昨宵愁。","自向归魂说，炎方不可留。","（同前第一四九八頁）。"]', '诗', 'shi', '', NULL, '初承恩旨言放歸舟 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de08a218-4d1f-4f47-bc38-7f2b8948b73c', '題九州院雙鶴', '題九州院雙鹤', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["君門九重閉，中有天泉池。","可憐雙白鶴，飛下碧松枝。","吹樓多清管，鳴舞共差池。","常欲萬里去，懷恩終在斯。","（同前第四冊第二八○一頁）。"]', '["君门九重閉，中有天泉池。","可怜雙白鹤，飞下碧松枝。","吹楼多清管，鳴舞共差池。","常欲万里去，懷恩終在斯。","（同前第四冊第二八○一頁）。"]', '诗', 'shi', '', NULL, '題九州院雙鶴 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d283bb51-0c9e-4875-ba6b-37750089c31b', '江行見鸕鷀', '江行见鸕鷀', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["江畔鸕鷀鳥，迎霜處處飛。","北看疑是雁，南客更思歸。","嶺上行人絕，關中音信稀。","故園今夜裏，應爲擣寒衣。","（同前第二八二七頁）。"]', '["江畔鸕鷀鸟，迎霜处处飞。","北看疑是雁，南客更思归。","嶺上行人絕，关中音信稀。","故园今夜裏，應爲擣寒衣。","（同前第二八二七頁）。"]', '诗', 'shi', '', NULL, '江行見鸕鷀 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ed027d-16eb-4ef6-9307-15fb2bbdd507', '陸渾水亭', '陸渾水亭', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["昔予登茲樓，感愛川岳奇。","別來雖云遠，夜夢常在斯。","更以沈痼日，歸臥南山陲。","弊廬不可見，雲林相蔽虧。","（同前第五冊第三一二八頁）。"]', '["昔予登茲楼，感愛川岳奇。","別来雖云远，夜梦常在斯。","更以沈痼日，归臥南山陲。","弊廬不可见，云林相蔽虧。","（同前第五冊第三一二八頁）。"]', '诗', 'shi', '', NULL, '陸渾水亭 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9598e58a-aa65-46d1-b7f3-65230e26d30b', '宴鄭協律山亭', '宴鄭協律山亭', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["朝英退食迴，追興洛城隈。","山瞻二室近，水自陸渾來。","小徑藤間入，高窗竹上開。","砌花連菡萏，溪柳覆莓苔。","舞席歸雲斷，歌筵薄景催。","可憐郊野際，長有故人杯。","（同前第三四八五頁）。"]', '["朝英退食迴，追兴洛城隈。","山瞻二室近，水自陸渾来。","小徑藤间入，高窗竹上开。","砌花連菡萏，溪柳覆莓苔。","舞席归云斷，歌筵薄景催。","可怜郊野際，长有故人杯。","（同前第三四八五頁）。"]', '诗', 'shi', '', NULL, '宴鄭協律山亭 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eac19cb-e70f-4431-8617-bd1dbed319d6', '憶嵩山陸渾舊宅', '憶嵩山陸渾旧宅', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["世德辭貴仕，天爵光道門。","好仙宅二室，受藥居陸渾。","清白立家訓，偃息爲國藩。","喬樹南勿翦，弊廬北尚存。","自惟實蒙陋，何顏稱子孫。","少秉陽許意，遭逢明聖恩。","揮翰雲龍署，參光天馬轅。","一身事扃闥，十載隔涼暄。","陳力試叨進，祗寵固幽源。","況以沈疾久，睽辭金馬垣。","天子猶未識，詎敢棲丘樊。","晝懷秘書谷，夕夢子平村。","擷芳歲云晏，投紼意彌敦。","皇私儻以報，無負青春言。","（同前第三五二九頁）。"]', '["世德辞貴仕，天爵光道门。","好仙宅二室，受藥居陸渾。","清白立家訓，偃息爲国藩。","喬樹南勿翦，弊廬北尚存。","自惟實蒙陋，何顏稱子孫。","少秉陽許意，遭逢明聖恩。","揮翰云龙署，參光天马轅。","一身事扃闥，十載隔涼暄。","陳力試叨進，祗寵固幽源。","況以沈疾久，睽辞金马垣。","天子猶未識，詎敢棲丘樊。","晝懷秘书谷，夕梦子平村。","擷芳歲云晏，投紼意彌敦。","皇私儻以報，無負青春言。","（同前第三五二九頁）。"]', '诗', 'shi', '', NULL, '憶嵩山陸渾舊宅 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca738202-62e6-467c-b83b-9f37c4359815', '茅齋讀書', '茅斋读书', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["清軒臨夕池，微逕入寒樹。","暝還探舊史，頗知古人趣。","明一誘道心，吹萬成世務。","獵精自補闕，安能守章句？","（同前第六冊第四一四九頁）。"]', '["清軒臨夕池，微逕入寒樹。","暝還探旧史，頗知古人趣。","明一誘道心，吹万成世務。","獵精自補闕，安能守章句？","（同前第六冊第四一四九頁）。"]', '诗', 'shi', '', NULL, '茅齋讀書 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78aaf1f1-f67a-4460-bae6-af377292772a', '題會福塔院詩', '題會福塔院诗', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["如湧浮圖近紫霄，芙蓉仙苑禮羣僚。","海天遙奉金輪日，盡遣禎祥歸聖朝。","（見清修《日下舊聞考》卷一二五引《宋延清集》）（按：此塔院清時稱三塔寺，在永清縣，其上有唐聖曆元年石刻。","）。"]', '["如湧浮圖近紫霄，芙蓉仙苑禮羣僚。","海天遙奉金輪日，尽遣禎祥归聖朝。","（见清修《日下旧闻考》卷一二五引《宋延清集》）（按：此塔院清时稱三塔寺，在永清縣，其上有唐聖曆元年石刻。","）。"]', '诗', 'shi', '', NULL, '題會福塔院詩 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c10a21-bd99-4946-bcfa-93e86f283d07', '陪王都督登樓詩', '陪王都督登楼诗', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["晦日登樓望，江山一半天。","（見宋樂史《太平寰宇記》卷一六二、王象之《輿地紀勝》卷一○三《靜江府》）（按：《全唐詩》卷五三《桂州陪王都督晦日宴逍遙樓》首二句云：「晦節高樓望，山川一半春。","」此錄二句當即其異文。","因其出處甚早，有五字不同，韻脚亦異，故另錄出。","）。"]', '["晦日登楼望，江山一半天。","（见宋乐史《太平寰宇記》卷一六二、王象之《輿地紀勝》卷一○三《静江府》）（按：《全唐诗》卷五三《桂州陪王都督晦日宴逍遙楼》首二句云：「晦節高楼望，山川一半春。","」此錄二句當即其異文。","因其出处甚早，有五字不同，韻脚亦異，故另錄出。","）。"]', '诗', 'shi', '', NULL, '陪王都督登樓詩 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cfe6c0d-c75e-4c93-ad70-63bc1c9f8682', '則天挽歌', '則天挽歌', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["還應鼎湖劍，千載忽同歸。","（見《十萬卷樓叢書》本皎然《詩式》卷四）。"]', '["還應鼎湖劍，千載忽同归。","（见《十万卷楼叢书》本皎然《诗式》卷四）。"]', '诗', 'shi', '', NULL, '則天挽歌 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1aff94e-78d8-4f2d-8783-f69c2286dcb7', '夔州（題擬）', '夔州（題擬）', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["路入巴渝通兩蜀，江連荆楚接三川。","（見佚名《錦繡花谷續集》卷十二「夔州」）。"]', '["路入巴渝通兩蜀，江連荆楚接三川。","（见佚名《錦繡花谷續集》卷十二「夔州」）。"]', '诗', 'shi', '', NULL, '夔州（題擬） 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f11c20e-0df2-45f6-96e1-ce21f0e1f6ed', '句', '句', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["高樹陰疎鳥不留。","（見宋李壁《王荆文公詩箋注》卷二三《宜春苑》注引）。"]', '["高樹陰疎鸟不留。","（见宋李壁《王荆文公诗箋注》卷二三《宜春苑》注引）。"]', '诗', 'shi', '', NULL, '句 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('333d38f2-a343-48e3-89b6-14f52d88f315', '偈', '偈', '845d4ec8-20cd-4f78-9fa7-2ae78c565547', '唐', '["經誦三千部，曹溪一句亡。","未明出世旨，寧歇累生狂。","羊鹿牛權設，初中後善揚。","誰知火宅內，元是法中王。","（見《景德傳燈錄》卷五、《六祖大師法寶壇經》）。"]', '["經誦三千部，曹溪一句亡。","未明出世旨，寧歇累生狂。","羊鹿牛權設，初中後善揚。","誰知火宅內，元是法中王。","（见《景德傳灯錄》卷五、《六祖大師法寶壇經》）。"]', '诗', 'shi', '', NULL, '偈 法達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3d74dd-3681-44cf-8879-e344bb72c679', '歌', '歌', '5b49cd8e-08e6-4522-ad2b-b35906477e9f', '唐', '["黑白兩迴開佛眼，不繫一法出蓮叢。","真空不壞靈智性，妙用恒常無作功。","聖智本來成佛道，寂光非照自圓通。","（見《大正新修大藏經》第四十八冊吳越釋延壽《宗鏡錄》卷十八）。"]', '["黑白兩迴开佛眼，不繫一法出蓮叢。","真空不壞靈智性，妙用恒常無作功。","聖智本来成佛道，寂光非照自圓通。","（见《大正新修大藏經》第四十八冊吳越釋延壽《宗镜錄》卷十八）。"]', '诗', 'shi', '', NULL, '歌 萬迴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d8588e-4ec1-48cf-a8b4-444f1b33e55e', '五言翫花鶯一首', '五言翫花鶯一首', '0ae8374c-76f3-438f-ac0d-540335494c35', '唐', '["桑門寡言晤，策杖事迎逢。","以此芳春節，忽值竹林風。","求友鶯嫣（一作「嬌」）樹，含香花笑叢。","雖喜遨遊志，還媿乏雕蟲。","。"]', '["桑门寡言晤，策杖事迎逢。","以此芳春節，忽值竹林风。","求友鶯嫣（一作「嬌」）樹，含香花笑叢。","雖喜遨游志，還媿乏雕蟲。","。"]', '诗', 'shi', '', NULL, '五言翫花鶯一首 智藏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9873221-5b23-4b63-928d-405d05e0b415', '五言秋日言志一首', '五言秋日言志一首', '0ae8374c-76f3-438f-ac0d-540335494c35', '唐', '["欲知得性所，來尋仁智情。","氣爽山川麗，風高物候芳。","燕巢辭夏色，鴈渚聽秋聲。","因茲竹林友，榮辱莫相驚。","（均見《日本古典文學大系》六九冊《懷風藻》）（按：《懷風藻》目錄稱「僧正吳學生智藏師」智藏在唐居住時間甚久，至暮年始返國。","二詩作年不可考，疑即在唐日作。","）。"]', '["欲知得性所，来尋仁智情。","氣爽山川丽，风高物候芳。","燕巢辞夏色，鴈渚听秋声。","因茲竹林友，榮辱莫相驚。","（均见《日本古典文学大系》六九冊《懷风藻》）（按：《懷风藻》目錄稱「僧正吳学生智藏師」智藏在唐居住时间甚久，至暮年始返国。","二诗作年不可考，疑即在唐日作。","）。"]', '诗', 'shi', '', NULL, '五言秋日言志一首 智藏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b127fd8-4d6f-41ef-8b33-3bf2214de7fa', '七夕感逝', '七夕感逝', '78c443b1-2182-4cef-953b-a7f93a37e2dd', '唐', '["生代日何短，徂遷歲欲期。","始聞春鳥思，溘見涼雲滋。","皎皎河漢匹，三秋會有期。","嗟嗟瑟琹偶，一去無還時。","晴壁看遺掛，虛簷想步綦。","流芳行處歇，空色夢中疑。","昔有秦嘉贈，今爲潘岳詩。","百憂人自老，玄髮新成絲。"]', '["生代日何短，徂遷歲欲期。","始闻春鸟思，溘见涼云滋。","皎皎河漢匹，三秋會有期。","嗟嗟瑟琹偶，一去無還时。","晴壁看遺掛，虛簷想步綦。","流芳行处歇，空色梦中疑。","昔有秦嘉贈，今爲潘岳诗。","百憂人自老，玄髮新成絲。"]', '诗', 'shi', '', NULL, '七夕感逝 宋務光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fceabf2-852c-4660-a368-84ac23ba12f1', '七夕', '七夕', '78c443b1-2182-4cef-953b-a7f93a37e2dd', '唐', '["牽牛遙映水，織女正當車。","星橋通漢使，機石逐望近，經秋離別賒。","秋將今夕恨，復看明年花。","（見宋蒲積中《古今歲時雜詠》卷二五）（按：《古今歲時雜詠》誤將務收入六朝。","）。"]', '["牽牛遙映水，织女正當车。","星橋通漢使，機石逐望近，經秋離別賒。","秋將今夕恨，复看明年花。","（见宋蒲積中《古今歲时杂詠》卷二五）（按：《古今歲时杂詠》誤將務收入六朝。","）。"]', '诗', 'shi', '', NULL, '七夕 宋務光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b5860e-6895-4be6-b824-0259b3d484a6', '三五七言體詩', '三五七言體诗', '33185f78-cb28-4cc0-add5-c014f28df850', '唐', '["秋風清，秋月明。","落葉聚還散，寒烏棲復驚。","相思相晃知何日，此時此夜難爲情。","（見《吟窗雜錄》卷十五《炙轂子詩格》引）（按：《全唐詩》卷一八四收此詩爲李白詩，然《才調集》卷十收作無名氏詩，嚴羽《滄浪詩話》則以爲鄭世翼作，楊齊賢、王琦定爲李白作，未舉證。","今人詹鍈《李詩辨僞》以爲非李白作，論證甚詳瞻。","《炙轂子詩格》晚唐王叡作。","時去高邁、李白時代甚近，其說當可信。","）。"]', '["秋风清，秋月明。","落葉聚還散，寒烏棲复驚。","相思相晃知何日，此时此夜难爲情。","（见《吟窗杂錄》卷十五《炙轂子诗格》引）（按：《全唐诗》卷一八四收此诗爲李白诗，然《才調集》卷十收作無名氏诗，嚴羽《滄浪诗話》則以爲鄭世翼作，楊齊賢、王琦定爲李白作，未舉證。","今人詹鍈《李诗辨僞》以爲非李白作，論證甚詳瞻。","《炙轂子诗格》晚唐王叡作。","时去高邁、李白时代甚近，其说當可信。","）。"]', '诗', 'shi', '', NULL, '三五七言體詩 高邁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232671db-64fd-48d9-b083-10b0617bd7e1', '下山逢故人', '下山逢故人', '12fcd1ce-a8fe-40e0-98b0-32ec0e844f08', '唐', '["妾身本薄命，輕棄城南隅。","庭前厭芍藥，山上採蘼蕪。","春風罥落濕羅襦。","羞將顦顇日，提籠逢故夫。","（見《永樂大典》卷三○○五引唐李康成《玉臺後詠》）（按：《吟窗雜錄》卷三七收劉處約《亡奴詩》二句：「丹籍生年淺，黃泉舊路深。","」《初學記》卷十九收劉夷道《傷死奴》）（詩前二句僅二字不同，《全唐詩》卷七六九已收入。","頗疑夷道與處約爲一人。","然《郎官石柱題名考》卷四「吏部員外郎」據石刻分錄二人事跡，亦難以遽斷。","處約孫長卿以天寶後期第進士，據以推之，處約當爲高宗、武后時人，今姑列初唐之末。","）。"]', '["妾身本薄命，轻棄城南隅。","庭前厭芍藥，山上採蘼蕪。","春风罥落濕羅襦。","羞將顦顇日，提籠逢故夫。","（见《永乐大典》卷三○○五引唐李康成《玉台後詠》）（按：《吟窗杂錄》卷三七收劉处約《亡奴诗》二句：「丹籍生年淺，黄泉旧路深。","」《初学記》卷十九收劉夷道《傷死奴》）（诗前二句僅二字不同，《全唐诗》卷七六九已收入。","頗疑夷道與处約爲一人。","然《郎官石柱題名考》卷四「吏部員外郎」據石刻分錄二人事跡，亦难以遽斷。","处約孫长卿以天寶後期第進士，據以推之，处約當爲高宗、武后时人，今姑列初唐之末。","）。"]', '诗', 'shi', '', NULL, '下山逢故人 劉處約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e065cfd8-665b-4057-93d5-6f8f6da9e3f0', '池', '池', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["日落天泉暮，煙虛習池靜。","鏡潭明月輝，錦幘流霞景。","花搖仙鳳色，雲浮濯龍影。","欲識江湖心，秋來賦潘省。"]', '["日落天泉暮，煙虛習池静。","镜潭明月輝，錦幘流霞景。","花搖仙鳳色，云浮濯龙影。","欲識江湖心，秋来賦潘省。"]', '诗', 'shi', '', NULL, '池 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53fc40bb-fe9f-4716-b32c-68c814d336e6', '箏', '箏', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["蒙恬芳軌設，遊楚清音列。","形通天地規，絃寫陰陽節。","鄭音既寥亮，秦聲復凄切。","君聽陌上桑，爲辨羅敷潔。","（以上見《佚存叢書》本《李嶠雜詠百二十首》卷下）（按：《佚存叢書》本《李嶠詠百二十首》，所錄諸詩文字與《全唐詩》所載者差異較大。","以上二詩完全不同，故另錄出。","有一句或數句不同者，錄如次。","僅個別文字不同者從略。","〖1〗《風》首二句作「落日正沈沈，微風生北林」。","〖2〗《霧》三四兩句作「別有丹山霧，玲瓏素月明」。","〖3〗《梨》五六兩句作「春暮條應紫，秋來葉正紅」。","〖4〗《樓》三四兩句作「落星臨畫閣，井幹起高臺」。","〖5〗《橋》後四句作「巧作七星影，能圖半月輝。","即今滄海宴，無復白雲威」。","）（〖6〗《簾》首二句作「曉風清竹殿，初日映秦樓」。","第三句作「曖曖籠珠網」。","第五句作「窗中月影入」。","〖7〗《扇》第二句作「蒲葵實曉清」。","第五句作「逐暑含風轉」。","第七句作「還取同心契」。","〖8〗《墨》第六句作「皂疊映逾沈」。","〖9〗《刀》第五句作「割錦紅鮮裏」。","〖10〗《彈》首句作「俠客遙相望」。","三四兩句作「共持蘇合彈，來此傍垂楊」。","末二句作「莫欣黃雀至，須憚微軀傷」。","〖11〗《琵琶》首句作「裁規勢漸團」。","〖12〗《珠》末二句作「誰憐被褐者，懷寶自多才」。","〖13〗《綾》第二句作「爲衾值漢君」。","五六兩句作「色帶冰綾影，光含霜雪文」。","〖14〗《素》五六兩句作「碪杵調風響，綾紈寫月輝」。","〖15〗《錦》第七句作「若逢朱太守」。","〖16〗《布》三四兩句作「瀑泉飛掛鶴，浣火有炎光」。","末句作「來穆採花芳」。","另伯三七三八卷存李嶠雜詠二首又四句，斯五五五卷存六首又三句，其文字與《全唐詩》有較多不同，錄其要者如次。","伯三七三卷載《鳳》第六句作「頻過潁水湯」。","《兔》五、六、七三句作「漢殿跧容伏，梁園隱迹微，方知感純孝」。","）。"]', '["蒙恬芳軌設，游楚清音列。","形通天地規，絃寫陰陽節。","鄭音既寥亮，秦声复凄切。","君听陌上桑，爲辨羅敷潔。","（以上见《佚存叢书》本《李嶠杂詠百二十首》卷下）（按：《佚存叢书》本《李嶠詠百二十首》，所錄諸诗文字與《全唐诗》所載者差異較大。","以上二诗完全不同，故另錄出。","有一句或數句不同者，錄如次。","僅個別文字不同者從略。","〖1〗《风》首二句作「落日正沈沈，微风生北林」。","〖2〗《霧》三四兩句作「別有丹山霧，玲瓏素月明」。","〖3〗《梨》五六兩句作「春暮條應紫，秋来葉正紅」。","〖4〗《楼》三四兩句作「落星臨畫閣，井幹起高台」。","〖5〗《橋》後四句作「巧作七星影，能圖半月輝。","即今滄海宴，無复白云威」。","）（〖6〗《簾》首二句作「晓风清竹殿，初日映秦楼」。","第三句作「曖曖籠珠網」。","第五句作「窗中月影入」。","〖7〗《扇》第二句作「蒲葵實晓清」。","第五句作「逐暑含风轉」。","第七句作「還取同心契」。","〖8〗《墨》第六句作「皂叠映逾沈」。","〖9〗《刀》第五句作「割錦紅鲜裏」。","〖10〗《彈》首句作「俠客遙相望」。","三四兩句作「共持蘇合彈，来此傍垂楊」。","末二句作「莫欣黄雀至，須憚微軀傷」。","〖11〗《琵琶》首句作「裁規勢漸團」。","〖12〗《珠》末二句作「誰怜被褐者，懷寶自多才」。","〖13〗《綾》第二句作「爲衾值漢君」。","五六兩句作「色带冰綾影，光含霜雪文」。","〖14〗《素》五六兩句作「碪杵調风响，綾紈寫月輝」。","〖15〗《錦》第七句作「若逢朱太守」。","〖16〗《布》三四兩句作「瀑泉飞掛鹤，浣火有炎光」。","末句作「来穆採花芳」。","另伯三七三八卷存李嶠杂詠二首又四句，斯五五五卷存六首又三句，其文字與《全唐诗》有較多不同，錄其要者如次。","伯三七三卷載《鳳》第六句作「頻過潁水湯」。","《兔》五、六、七三句作「漢殿跧容伏，梁园隐迹微，方知感純孝」。","）。"]', '诗', 'shi', '', NULL, '箏 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9daa42b8-52c9-40ae-aeee-11e1f87c6c99', '五言登禪定閣一首', '五言登禪定閣一首', '60f964a5-cb25-4a11-8a05-24d7ad7e6e77', '唐', '["鹿苑傳金地，龍宮出鐵圍。","閣裏山河近，樓上落星稀。","獨園登彼岸，雙樹遂忘歸。","具（疑應作「貝」）葉含峯入，蘆花逐鴈飛。","雲{扌臥}擬留蓋，蘿懸似拂衣。","言倍列棘賞，同赴握蘭期。","禪林當月路，更似偶仙扉。","（日本藏唐抄本《唐詩卷》。","）。"]', '["鹿苑傳金地，龙宮出鐵圍。","閣裏山河近，楼上落星稀。","独园登彼岸，雙樹遂忘归。","具（疑應作「貝」）葉含峯入，蘆花逐鴈飞。","云{扌臥}擬留蓋，蘿懸似拂衣。","言倍列棘賞，同赴握蘭期。","禪林當月路，更似偶仙扉。","（日本藏唐抄本《唐诗卷》。","）。"]', '诗', 'shi', '', NULL, '五言登禪定閣一首 張栖貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce2b41b-f826-432b-9e4f-0a1191979f51', '發館陶', '發館陶', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["促轡數殘更，似聞鷄一鳴。","春風馬上夢，沙路月中行。","笳鼓遠多思，衣裘寒始輕。","稍知田父稔，燈火聞柴荆。","（錄自光緒十一年刊劉家善纂《館陶縣志》卷十一）（按：《青瑣高議》、《皇朝文鑑》、《錦繡萬花谷後集》、《輿地紀勝》另錄郭震詩多首，爲宋太宗時成都隱士郭震作，不錄。","）。"]', '["促轡數殘更，似闻鷄一鳴。","春风马上梦，沙路月中行。","笳鼓远多思，衣裘寒始轻。","稍知田父稔，灯火闻柴荆。","（錄自光緒十一年刊劉家善纂《館陶縣志》卷十一）（按：《青瑣高議》、《皇朝文鑑》、《錦繡万花谷後集》、《輿地紀勝》另錄郭震诗多首，爲宋太宗时成都隐士郭震作，不錄。","）。"]', '诗', 'shi', '', NULL, '發館陶 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5064a2a2-7f3e-4e86-aefd-274d44e8a00a', '永嘉證道歌', '永嘉證道歌', '024328af-c704-446a-9a7d-1b4e4a22b646', '唐', '["君不見，絕學無爲閒道人，不除妄想不求真。","無明實性即佛性，幻化空身即法身。","法身覺了無一物，本源自性天真佛。","五陰浮雲空去來，三毒水泡空出沒。","證實相，無人法，剎那滅却阿鼻業。","若將妄語誑衆生，自招拔舌塵沙劫。","頓覺了，如來禪，六度萬行體中圓。","夢裏明明有六趣，覺後空空無大千。","無罪福，無損益，寂滅性中莫問覓。","比來塵鏡未曾磨，今日分明須剖析。","誰無念？誰無生？若實無生無不生。","喚取機關木人問，求佛施功早晚成。","放四大，莫把提，寂滅性中隨飲啄。","諸行無常一切空，即是如來大圓覺。","決定說，表真僧，有人不許任情徵。","直（一作「真」）截根源佛所叩，摘葉尋枝我不能。","摩尼珠，人不識，如來藏裏親收得。","六般神用空不空，一顆圓光色非色。","淨五眼，得五力，唯證乃知難可測。","鏡裏看形見不片，水中捉月爭拈得。","常獨行，常獨步，達者同遊湼槃路。","調古神清風自高，貌悴骨剛人不顧。","窮釋子，口稱貧，實是身貧道不貧。","貧則身常披縷褐，道則心藏無價珍。","無價珍，用無盡，利物應機終不吝。","三身四智體中圓，八解六通心地印。","上士一決一切了，中下多聞多不信，但自懷中解垢衣，誰能向外誇精進。","從他謗，任他非，把火燒天徒自疲。","我聞恰似飲甘露，銷融頓入不思議。","觀惡言，是功德，此即成吾善知識。","不因訕謗成冤親，何表無生慈忍力。","宗亦通，說亦通，定慧圓明不滯空。","非但我今獨達了，恆沙諸佛體皆同。","師子吼，無畏說，百獸聞之皆腦裂。","香象奔波失却威，天龍寂聽生欣悅。","遊江海，涉山川，尋師訪道爲參禪。","自從認得曹谿路，了知生死不相關。","行亦禪，坐亦禪，語默動靜體安然。","縱遇鋒刀常坦坦，假饒毒藥也閒閒。","我師得見然燈佛，多劫曾爲忍辱仙。","幾迴生，幾迴死，生死悠悠無定止。","自從頓悟了無生，於諸榮辱何憂喜。","入深山，住蘭若，岑崟幽邃長松下。","優遊靜坐野僧家，闃寂安居實蕭灑。","覺即了，不施功，一切有爲法不同。","住相布施生天福，猶如仰箭射虛空。","勢力盡，箭還墜，招得來生不如意。","爭似無爲實相門，一超直入如來地。","但得本，莫愁末，如淨瑠璃含寶月。","既能解此如意珠，自利利他終不竭。","江月照，松風吹，永夜清宵何所爲？","佛印戒珠心地印，霧露雲霞體上衣。","降龍鉢，解虎錫，兩股金環鳴歷歷。","不是標形虛事持，如來寶杖親踪跡。","不求真，不斷妄，了知二法空無相。","無相無空無不空，即是如來真實相。","心鏡明，鑒無礙，廓然瑩徹周沙界。","萬象森羅影現中，一顆圓光非內外。","豁達空，撥因果，漭漭蕩蕩招殃禍。","棄有著空病亦然，還如避溺而投火。","捨妄心，取真理，取捨之心成巧僞。","學人不了用修行，深成認賊將爲子。","損法財，滅功德，莫不由斯心意識。","是以禪門了却心，頓入無生知見力。","大丈夫，秉慧劍，般若鋒兮金剛燄。","非但能摧外道心，早曾落却天魔膽。","震法靁，擊法鼓，布慈雲兮灑甘露。","龍象蹴蹋潤無邊，三乘五戒皆惺悟。","雪山肥膩更無雜，純出醍醐我常納。","一性圓通一切性，一法徧含一切法，一月普現一切水，一切水月一月攝。","諸佛法身入我性，我性還共如來合。","一地俱足一切地，非色非心非行業。","彈指圓成八萬門，剎那滅却阿鼻業。","一切數句非數句，與吾靈覺何交涉。","不可毀，不可讚，體若虛空勿涯岸。","不離當處常湛然，覓則知君不可見。","取不得，捨不得，不可得中只麽得。","默時說，說時默，大施門開無壅塞。","有人問我解何宗，報道摩訶般若力。","或是或非人不識，逆行順行天莫測。","吾早曾經多劫修，不是等閒相誑惑。","建法幢，立宗旨，明明佛敕曹溪是。","第一迦葉首傳燈，二十八代西天記。","法東流，入此土，菩提達摩爲初祖。","六代傳衣天下聞，後人得道何窮數。","真不立，妄本空，有無俱遣不空空。","二十空門元不著，一性如來體自同。","心是根，法是塵，兩種猶如鏡上痕。","痕垢盡除光始現，心法雙忘性即真。","嗟末法，惡時世，衆生福薄難調制。","去聖遠兮邪見深，魔強法弱多怨害。","問說如來頓教門，恨不滅除令瓦碎。","作在心，殃在身，不須冤訴更尤人。","欲得不招無閒業，莫謗如來正法輪。","旃檀林，無雜樹，鬱密深沈師子住。","境靜林間獨自遊，走獸飛禽皆遠去。","師子兒，衆隨後，三歲便能大哮吼。","若是野干逐（一作「隨」）法王，百年妖怪虛開口。","圓頓教，勿人情，有疑不決直須爭。","不是山僧逞人我，修行恐落斷常坑。","非不非，是不是，差之毫釐失千里。","是即龍女頓成佛，非即善星生陷墜。","吾早年來積學問，亦曾討疏尋經論。","分別名相不知休，入海算沙徒自困。","却被如來苦訶責，數他珍寶有何益。","從來蹭蹬覺虛行，多年枉作風塵客。","種性邪，錯知解，不達如來圓頓制。","二乘精進勿道心，外道聰明無智慧。","亦愚癡，亦小騃，空拳指上生實解。","執指爲月枉施功，根境法中虛揑怪。","不見一法即如來，方得名爲觀自在。","了即業障本來空，未了應須償夙債。","饑逢玉膳不飡，病遇醫王爭得差。","在欲行禪知見力，火中生蓮終不壞。","勇施犯重悟無生，早時成佛於今在。","師子吼，無畏說，深嗟懵懂頑皮靼（音折）。","祇知犯重障菩提，不見如來開秘訣。","有二比丘犯婬殺，波離螢光增罪結。","維摩大士頓除疑，猶如赫日銷霜雪。","不思議，解脫力，妙用恆沙也無極。","四事供養敢辭勞，萬兩黃金亦銷得。","粉骨碎身未足酬，一句了然超百億。","法中王，最高勝，河沙如來同共證。","我今解此如意珠，信受之者皆相應。","了了見，無一物，亦無人，亦無佛。","大千沙界海中漚，一切聖賢如電拂。","假使鐵輪頂上旋，定慧圓明終不失。","日可冷，月可熱，衆魔不能壞真說。","象駕崢嶸謾進途，誰見螗螂能拒轍。","大象不遊於兔徑，大悟不拘於小節。","莫將管見誑蒼蒼，未了吾今爲君決。","（見《四部叢刊三編》影宋本《景德傳燈錄》卷三十、冒廣生刊《永嘉詩人祠堂叢刻》第一冊釋玄覺《永嘉集》附錄）（按：《永嘉集》附錄楊億《無相大師行狀》云：「著《禪宗悟修圓旨》，自淺之深，慶州刺史魏靜緝而序之成十篇，目爲《永嘉集》，及《證道歌》一首，並盛行於世云爾。","」）。"]', '["君不见，絕学無爲閒道人，不除妄想不求真。","無明實性即佛性，幻化空身即法身。","法身覺了無一物，本源自性天真佛。","五陰浮云空去来，三毒水泡空出沒。","證實相，無人法，剎那滅却阿鼻業。","若將妄語誑衆生，自招拔舌塵沙劫。","頓覺了，如来禪，六度万行體中圓。","梦裏明明有六趣，覺後空空無大千。","無罪福，無損益，寂滅性中莫问覓。","比来塵镜未曾磨，今日分明須剖析。","誰無念？誰無生？若實無生無不生。","喚取機关木人问，求佛施功早晚成。","放四大，莫把提，寂滅性中隨饮啄。","諸行無常一切空，即是如来大圓覺。","決定说，表真僧，有人不許任情徵。","直（一作「真」）截根源佛所叩，摘葉尋枝我不能。","摩尼珠，人不識，如来藏裏親收得。","六般神用空不空，一顆圓光色非色。","淨五眼，得五力，唯證乃知难可測。","镜裏看形见不片，水中捉月爭拈得。","常独行，常独步，達者同游湼槃路。","調古神清风自高，貌悴骨剛人不顧。","窮釋子，口稱貧，實是身貧道不貧。","貧則身常披縷褐，道則心藏無價珍。","無價珍，用無尽，利物應機終不吝。","三身四智體中圓，八解六通心地印。","上士一決一切了，中下多闻多不信，但自懷中解垢衣，誰能向外誇精進。","從他謗，任他非，把火燒天徒自疲。","我闻恰似饮甘露，銷融頓入不思議。","观惡言，是功德，此即成吾善知識。","不因訕謗成冤親，何表無生慈忍力。","宗亦通，说亦通，定慧圓明不滯空。","非但我今独達了，恆沙諸佛體皆同。","師子吼，無畏说，百獸闻之皆腦裂。","香象奔波失却威，天龙寂听生欣悅。","游江海，涉山川，尋師訪道爲參禪。","自從認得曹谿路，了知生死不相关。","行亦禪，坐亦禪，語默动静體安然。","縱遇鋒刀常坦坦，假饒毒藥也閒閒。","我師得见然灯佛，多劫曾爲忍辱仙。","幾迴生，幾迴死，生死悠悠無定止。","自從頓悟了無生，於諸榮辱何憂喜。","入深山，住蘭若，岑崟幽邃长松下。","優游静坐野僧家，闃寂安居實蕭灑。","覺即了，不施功，一切有爲法不同。","住相布施生天福，猶如仰箭射虛空。","勢力尽，箭還墜，招得来生不如意。","爭似無爲實相门，一超直入如来地。","但得本，莫愁末，如淨瑠璃含寶月。","既能解此如意珠，自利利他終不竭。","江月照，松风吹，永夜清宵何所爲？","佛印戒珠心地印，霧露云霞體上衣。","降龙鉢，解虎錫，兩股金环鳴歷歷。","不是標形虛事持，如来寶杖親踪跡。","不求真，不斷妄，了知二法空無相。","無相無空無不空，即是如来真實相。","心镜明，鑒無礙，廓然瑩徹周沙界。","万象森羅影現中，一顆圓光非內外。","豁達空，撥因果，漭漭蕩蕩招殃禍。","棄有著空病亦然，還如避溺而投火。","捨妄心，取真理，取捨之心成巧僞。","学人不了用修行，深成認賊將爲子。","損法財，滅功德，莫不由斯心意識。","是以禪门了却心，頓入無生知见力。","大丈夫，秉慧劍，般若鋒兮金剛燄。","非但能摧外道心，早曾落却天魔膽。","震法靁，擊法鼓，布慈云兮灑甘露。","龙象蹴蹋潤無邊，三乘五戒皆惺悟。","雪山肥膩更無杂，純出醍醐我常納。","一性圓通一切性，一法徧含一切法，一月普現一切水，一切水月一月攝。","諸佛法身入我性，我性還共如来合。","一地俱足一切地，非色非心非行業。","彈指圓成八万门，剎那滅却阿鼻業。","一切數句非數句，與吾靈覺何交涉。","不可毀，不可讚，體若虛空勿涯岸。","不離當处常湛然，覓則知君不可见。","取不得，捨不得，不可得中只麽得。","默时说，说时默，大施门开無壅塞。","有人问我解何宗，報道摩訶般若力。","或是或非人不識，逆行順行天莫測。","吾早曾經多劫修，不是等閒相誑惑。","建法幢，立宗旨，明明佛敕曹溪是。","第一迦葉首傳灯，二十八代西天記。","法东流，入此土，菩提達摩爲初祖。","六代傳衣天下闻，後人得道何窮數。","真不立，妄本空，有無俱遣不空空。","二十空门元不著，一性如来體自同。","心是根，法是塵，兩種猶如镜上痕。","痕垢尽除光始現，心法雙忘性即真。","嗟末法，惡时世，衆生福薄难調制。","去聖远兮邪见深，魔強法弱多怨害。","问说如来頓教门，恨不滅除令瓦碎。","作在心，殃在身，不須冤訴更尤人。","欲得不招無閒業，莫謗如来正法輪。","旃檀林，無杂樹，鬱密深沈師子住。","境静林间独自游，走獸飞禽皆远去。","師子兒，衆隨後，三歲便能大哮吼。","若是野干逐（一作「隨」）法王，百年妖怪虛开口。","圓頓教，勿人情，有疑不決直須爭。","不是山僧逞人我，修行恐落斷常坑。","非不非，是不是，差之毫釐失千里。","是即龙女頓成佛，非即善星生陷墜。","吾早年来積学问，亦曾討疏尋經論。","分別名相不知休，入海算沙徒自困。","却被如来苦訶責，數他珍寶有何益。","從来蹭蹬覺虛行，多年枉作风塵客。","種性邪，錯知解，不達如来圓頓制。","二乘精進勿道心，外道聰明無智慧。","亦愚癡，亦小騃，空拳指上生實解。","執指爲月枉施功，根境法中虛揑怪。","不见一法即如来，方得名爲观自在。","了即業障本来空，未了應須償夙債。","饑逢玉膳不飡，病遇醫王爭得差。","在欲行禪知见力，火中生蓮終不壞。","勇施犯重悟無生，早时成佛於今在。","師子吼，無畏说，深嗟懵懂頑皮靼（音折）。","祇知犯重障菩提，不见如来开秘訣。","有二比丘犯婬殺，波離螢光增罪結。","維摩大士頓除疑，猶如赫日銷霜雪。","不思議，解脫力，妙用恆沙也無極。","四事供養敢辞勞，万兩黄金亦銷得。","粉骨碎身未足酬，一句了然超百億。","法中王，最高勝，河沙如来同共證。","我今解此如意珠，信受之者皆相應。","了了见，無一物，亦無人，亦無佛。","大千沙界海中漚，一切聖賢如電拂。","假使鐵輪頂上旋，定慧圓明終不失。","日可冷，月可熱，衆魔不能壞真说。","象駕崢嶸謾進途，誰见螗螂能拒轍。","大象不游於兔徑，大悟不拘於小節。","莫將管见誑蒼蒼，未了吾今爲君決。","（见《四部叢刊三編》影宋本《景德傳灯錄》卷三十、冒廣生刊《永嘉诗人祠堂叢刻》第一冊釋玄覺《永嘉集》附錄）（按：《永嘉集》附錄楊億《無相大師行狀》云：「著《禪宗悟修圓旨》，自淺之深，慶州刺史魏静緝而序之成十篇，目爲《永嘉集》，及《證道歌》一首，並盛行於世云爾。","」）。"]', '诗', 'shi', '', NULL, '永嘉證道歌 玄覺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b472d4-d48a-431f-a8c2-5e822e58b348', '偈 一', '偈 一', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["菩提本無樹，明鏡亦無臺。"]', '["菩提本無樹，明镜亦無台。"]', '诗', 'shi', '', NULL, '偈 一 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f8e5a2-71f0-4f61-ac6d-5602ae8d2fcc', '偈 二', '偈 二', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心是菩提樹，身爲明鏡臺。","明鏡本清淨，何處染塵埃？","（見敦煌本《南宗頓教最上大乘摩訶般若波羅蜜經六祖慧能大師於韶州大梵寺施法壇經》）（按：《全唐詩續補遺》卷二收惠能偈一首，原出於法海本《壇經》，與敦煌本異，今重錄。","）。"]', '["心是菩提樹，身爲明镜台。","明镜本清淨，何处染塵埃？","（见敦煌本《南宗頓教最上大乘摩訶般若波羅蜜經六祖慧能大師於韶州大梵寺施法壇經》）（按：《全唐诗續補遺》卷二收惠能偈一首，原出於法海本《壇經》，與敦煌本異，今重錄。","）。"]', '诗', 'shi', '', NULL, '偈 二 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7477bd57-7970-4f43-bff7-710a21425288', '無相頌（亦名《滅罪頌》）', '無相頌（亦名《滅罪頌》）', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["愚人修福不修道，謂言修福而是道。","布施供養福無邊，心中三惡元來造。","若將修福欲滅罪，後世得福罪元在。","若解向除罪緣，各自性中真懺悔。","若悟大乘真懺悔，除邪行正即無罪。","學道之人能自觀，即與悟人同一類。","大師令傳此頓教，願學之人同一體。","若欲當來覓本身，三毒惡緣心中洗。","努力修道莫悠悠，忽然虛度一世休。","若遇大乘頓教法，虔誠合掌至心求。","（同前）。"]', '["愚人修福不修道，謂言修福而是道。","布施供養福無邊，心中三惡元来造。","若將修福欲滅罪，後世得福罪元在。","若解向除罪緣，各自性中真懺悔。","若悟大乘真懺悔，除邪行正即無罪。","学道之人能自观，即與悟人同一類。","大師令傳此頓教，願学之人同一體。","若欲當来覓本身，三毒惡緣心中洗。","努力修道莫悠悠，忽然虛度一世休。","若遇大乘頓教法，虔誠合掌至心求。","（同前）。"]', '诗', 'shi', '', NULL, '無相頌（亦名《滅罪頌》） 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8472ce52-acaf-481e-b0e5-06ebd0b23699', '修行頌', '修行頌', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["說通及心通，如日處虛空。","惟傳頓教法，出世破邪宗。","教即無頓漸，迷悟有遲疾。","若學頓教法，愚人不可悉。","說即須萬般，合離還歸一。","煩惱暗宅中，常須生惠日。","邪來因煩惱，正來煩惱除。","邪正悉不用，清淨至無餘。","菩提本清淨，起心即是妄。","淨性在妄中，但正除三障。","世間若修道，一切盡不妨。","常見自己過，與道即相當。","色類自有道，離道別覓道。","覓道不見道，到頭還自惱。","若欲見真道，行正即是道。","自若無正心，暗行不見道。","若真修道人，不見世間過。","若見世間非，自非却是左。","他非我無罪，我非自有罪。","但自去非心，打破煩惱碎。","若欲化愚人，是須有方便。","勿令彼有疑，即有菩提現。","法元在世間，於世出世間。","勿離世間上，外求出世間。","邪見是世間，正見出世間。","邪正悉打却，菩提性宛然。","此但是頓教，亦名爲大乘。","迷來經累劫，悟則剎那間。","（同前）。"]', '["说通及心通，如日处虛空。","惟傳頓教法，出世破邪宗。","教即無頓漸，迷悟有遲疾。","若学頓教法，愚人不可悉。","说即須万般，合離還归一。","煩惱暗宅中，常須生惠日。","邪来因煩惱，正来煩惱除。","邪正悉不用，清淨至無餘。","菩提本清淨，起心即是妄。","淨性在妄中，但正除三障。","世间若修道，一切尽不妨。","常见自己過，與道即相當。","色類自有道，離道別覓道。","覓道不见道，到头還自惱。","若欲见真道，行正即是道。","自若無正心，暗行不见道。","若真修道人，不见世间過。","若见世间非，自非却是左。","他非我無罪，我非自有罪。","但自去非心，打破煩惱碎。","若欲化愚人，是須有方便。","勿令彼有疑，即有菩提現。","法元在世间，於世出世间。","勿離世间上，外求出世间。","邪见是世间，正见出世间。","邪正悉打却，菩提性宛然。","此但是頓教，亦名爲大乘。","迷来經累劫，悟則剎那间。","（同前）。"]', '诗', 'shi', '', NULL, '修行頌 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68b3283b-6fad-4f5b-9259-53ae66bab59a', '付法頌', '付法頌', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心地含情（契嵩本作「諸」）種，法雨即花生（契嵩本作「普雨悉皆萌」）。","自悟花情種（契嵩本作「頓悟華情已」），菩提菓自成。","（同前）。"]', '["心地含情（契嵩本作「諸」）種，法雨即花生（契嵩本作「普雨悉皆萌」）。","自悟花情種（契嵩本作「頓悟华情已」），菩提菓自成。","（同前）。"]', '诗', 'shi', '', NULL, '付法頌 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a761c6-d77d-4e86-8cc5-97b6ed5754c0', '擬達摩和尚頌二首（題擬） 一', '擬達摩和尚頌二首（題擬） 一', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心地邪花放，五葉逐根隨。","共造無明業，見被業風吹。"]', '["心地邪花放，五葉逐根隨。","共造無明業，见被業风吹。"]', '诗', 'shi', '', NULL, '擬達摩和尚頌二首（題擬） 一 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a0d9411-568b-4e00-9011-480c42b208d4', '擬達摩和尚頌二首（題擬） 二', '擬達摩和尚頌二首（題擬） 二', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心地正花放，五葉逐根隨。","共修般若惠，當來佛菩提。","（同前）。"]', '["心地正花放，五葉逐根隨。","共修般若惠，當来佛菩提。","（同前）。"]', '诗', 'shi', '', NULL, '擬達摩和尚頌二首（題擬） 二 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c58b28-8b4f-4554-9e7f-a35a3eb5807b', '自性真佛解脫頌', '自性真佛解脫頌', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["真如淨性是真佛，邪見三毒是真魔。","邪見之人魔在舍，正見知人魔則過。","性中邪見三毒生，即是魔王來住舍。","正見忽除三毒心，魔變成佛真無假。","化身報身及法身，三身元本是一身。","若向身中覓自見，即是成佛菩提因。","本從化身生淨性，淨性常在化身中。","性使化身行正道，當來圓滿真無窮。","婬性本是清淨因，除婬即無淨性身。","性中但自離五欲，見性剎那即是真。","今生若悟頓教門，悟即眼前見世尊。","若欲修行云覓佛，不知何處欲求真。","若能心中自見真，有真即是成佛因。","自不求真外覓佛，去覓總是大癡人。","頓教法者是西流，救度世人須自修。","今報世間學道者，不於此見大悠悠。","（同前）。"]', '["真如淨性是真佛，邪见三毒是真魔。","邪见之人魔在舍，正见知人魔則過。","性中邪见三毒生，即是魔王来住舍。","正见忽除三毒心，魔变成佛真無假。","化身報身及法身，三身元本是一身。","若向身中覓自见，即是成佛菩提因。","本從化身生淨性，淨性常在化身中。","性使化身行正道，當来圓满真無窮。","婬性本是清淨因，除婬即無淨性身。","性中但自離五欲，见性剎那即是真。","今生若悟頓教门，悟即眼前见世尊。","若欲修行云覓佛，不知何处欲求真。","若能心中自见真，有真即是成佛因。","自不求真外覓佛，去覓總是大癡人。","頓教法者是西流，救度世人須自修。","今報世间学道者，不於此见大悠悠。","（同前）。"]', '诗', 'shi', '', NULL, '自性真佛解脫頌 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf5fea3-f6b3-40b1-84a4-b41b4fa8ab05', '示志誠偈二首 一', '示志誠偈二首 一', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["生來坐不臥，死去臥不坐。","一具（《燈錄》作「元是」）臭骨頭，何爲立功課（《燈錄》作「過」）。"]', '["生来坐不臥，死去臥不坐。","一具（《灯錄》作「元是」）臭骨头，何爲立功課（《灯錄》作「過」）。"]', '诗', 'shi', '', NULL, '示志誠偈二首 一 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb700f7-81c8-4763-aadc-a4e85c1d6f57', '示志誠偈二首 二', '示志誠偈二首 二', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心地無非（《燈錄》作「一切無心」）自性戒，心地（《燈錄》作「一切」）無癡自性慧。","心地無亂自性定（《燈錄》無此句），不增不減（《燈錄》作「退」）自金剛，身去身來本三昧。","（見契嵩本《六祖大師法寶壇經》、《景德傳燈錄》卷五）。"]', '["心地無非（《灯錄》作「一切無心」）自性戒，心地（《灯錄》作「一切」）無癡自性慧。","心地無亂自性定（《灯錄》無此句），不增不減（《灯錄》作「退」）自金剛，身去身来本三昧。","（见契嵩本《六祖大師法寶壇經》、《景德傳灯錄》卷五）。"]', '诗', 'shi', '', NULL, '示志誠偈二首 二 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56deb408-deda-44a0-ae63-f6bd0262cbb3', '示智通偈', '示智通偈', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["自性具三身，發明成四智。","不離見聞緣，超然登佛地。","吾今爲汝說，諦信永無迷。","莫學馳求者，終日說菩提。","（同前）。"]', '["自性具三身，發明成四智。","不離见闻緣，超然登佛地。","吾今爲汝说，諦信永無迷。","莫学驰求者，終日说菩提。","（同前）。"]', '诗', 'shi', '', NULL, '示智通偈 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a6a113-db9b-4b42-af9c-07c74724ee0c', '示智常偈', '示智常偈', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["不見一法存無見，不似浮雲遮日面。","不知一法守空知，還如太虛生閃電。","此之知見瞥然興，錯認何曾解方便。","汝當一念自知非，自己靈光常顯現。","（同前）。"]', '["不见一法存無见，不似浮云遮日面。","不知一法守空知，還如太虛生閃電。","此之知见瞥然兴，錯認何曾解方便。","汝當一念自知非，自己靈光常显現。","（同前）。"]', '诗', 'shi', '', NULL, '示智常偈 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad8ce23-d903-44f5-9887-04f0ee6e77fc', '示法達偈三首 一', '示法達偈三首 一', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["禮本折慢幢，頭奚不至地？","有我罪即生，亡功福無比。","。"]', '["禮本折慢幢，头奚不至地？","有我罪即生，亡功福無比。","。"]', '诗', 'shi', '', NULL, '示法達偈三首 一 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09dd2021-506b-49f9-af8d-7e19ed913f2d', '示法達偈三首 二', '示法達偈三首 二', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["汝今名法達，勤誦未休歇。","空誦但循聲，明心號菩薩。","汝今有緣故，吾今爲汝說。","但信佛無言，蓮華從口發。"]', '["汝今名法達，勤誦未休歇。","空誦但循声，明心號菩薩。","汝今有緣故，吾今爲汝说。","但信佛無言，蓮华從口發。"]', '诗', 'shi', '', NULL, '示法達偈三首 二 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2dc1281-2461-461a-97d8-a6418aaec429', '示法達偈三首 三', '示法達偈三首 三', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心迷法華轉，心悟轉法華。","誦經久不明（《燈錄》作「誦久不明已」），與義作讎家。","無念念即正，有念念成邪。","有無俱不計，長御白牛車。","（同前）。"]', '["心迷法华轉，心悟轉法华。","誦經久不明（《灯錄》作「誦久不明已」），與義作讎家。","無念念即正，有念念成邪。","有無俱不計，长御白牛车。","（同前）。"]', '诗', 'shi', '', NULL, '示法達偈三首 三 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7287179-deb6-47e6-a09f-8752a8df0629', '示智通偈', '示智通偈', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["大圓鏡智性清淨，平等性智心無病，妙觀察智見非功，成所作智同圓鏡。","五八六七果因轉，但用名言無實性。","若於轉處不留情，繁興永處那伽定。","（契嵩本《六祖大師法寶壇經》）。"]', '["大圓镜智性清淨，平等性智心無病，妙观察智见非功，成所作智同圓镜。","五八六七果因轉，但用名言無實性。","若於轉处不留情，繁兴永处那伽定。","（契嵩本《六祖大師法寶壇經》）。"]', '诗', 'shi', '', NULL, '示智通偈 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('349538ac-9fa9-47ce-b7c9-91d9b9b25a63', '僧舉臥輪禪師偈作此相示（題擬）', '僧舉臥輪禪師偈作此相示（題擬）', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["惠能沒伎倆，不斷百思想。","對鏡心數起，菩提作麽長。","（同前）。"]', '["惠能沒伎倆，不斷百思想。","对镜心數起，菩提作麽长。","（同前）。"]', '诗', 'shi', '', NULL, '僧舉臥輪禪師偈作此相示（題擬） 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9493963-c0c9-4e56-9cf9-eeb7d150839c', '臨滅偈（題擬）', '臨滅偈（題擬）', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["兀兀不修善，騰騰不造惡。","寂寂斷見聞，蕩蕩心無著。","（同前）。"]', '["兀兀不修善，腾腾不造惡。","寂寂斷见闻，蕩蕩心無著。","（同前）。"]', '诗', 'shi', '', NULL, '臨滅偈（題擬） 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e20292f0-bf74-4bcd-bb59-c33479354358', '無相頌', '無相頌', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["心平何勞持戒，行直何用修禪？","恩則孝養父母，義則上下相憐。","讓則尊卑和睦，忍則衆惡無喧。","若能鑽木取火，淤泥定生紅蓮。","苦口的是良藥，逆耳必是忠言。","改過必生智慧，護短心內非賢。","日用常行饒益，成道非由施錢。","菩提祇向心覓，何勞向外求玄。","聽說依此修行，天堂祇在目前。","（同前）。"]', '["心平何勞持戒，行直何用修禪？","恩則孝養父母，義則上下相怜。","讓則尊卑和睦，忍則衆惡無喧。","若能鑽木取火，淤泥定生紅蓮。","苦口的是良藥，逆耳必是忠言。","改過必生智慧，護短心內非賢。","日用常行饒益，成道非由施錢。","菩提祇向心覓，何勞向外求玄。","听说依此修行，天堂祇在目前。","（同前）。"]', '诗', 'shi', '', NULL, '無相頌 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad50847-cfbf-4a5c-8e88-d6d3a45dc88d', '偈', '偈', 'bb404361-3a82-42bc-b8c0-683b84b489eb', '唐', '["臥輪有伎倆，能斷百思想。","對境心不起，菩提日日長。","（見契嵩本《六祖大師法寶壇經》）。"]', '["臥輪有伎倆，能斷百思想。","对境心不起，菩提日日长。","（见契嵩本《六祖大師法寶壇經》）。"]', '诗', 'shi', '', NULL, '偈 曇倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17d1b8b-a9f3-409f-9f2a-bf26a2a14cf0', '偈', '偈', 'f71d3860-33b0-479f-babe-7f61e6fd3a2d', '唐', '["即心元是佛，不悟而自屈。","我知定慧因，雙修離諸物。","（見《景德傳燈錄》卷五、契嵩本《六祖大師法寶壇經》）。"]', '["即心元是佛，不悟而自屈。","我知定慧因，雙修離諸物。","（见《景德傳灯錄》卷五、契嵩本《六祖大師法寶壇經》）。"]', '诗', 'shi', '', NULL, '偈 法海 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('613d7b7e-5113-4687-8634-b0e1eb75bf50', '偈', '偈', 'c25426a3-50db-42d5-865d-e444a4f659bf', '唐', '["三身元我體，四智本心明。","身智融無礙，應物任隨形。","起修皆妄動，守住匪真精。","妙旨因師曉，終亡染污名。","（同前）。"]', '["三身元我體，四智本心明。","身智融無礙，應物任隨形。","起修皆妄动，守住匪真精。","妙旨因師晓，終亡染污名。","（同前）。"]', '诗', 'shi', '', NULL, '偈 智通 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46749516-009e-4d8c-9b75-df4288c13760', '偈', '偈', '864e6bfb-4c22-4ba6-bee5-832cd65ab5d6', '唐', '["無端起知見，著相求菩提。","情存一念悟，寧越昔時迷。","自性覺源體，隨照枉遷流。","不入祖師室，茫然趣兩頭。","（同前）。"]', '["無端起知见，著相求菩提。","情存一念悟，寧越昔时迷。","自性覺源體，隨照枉遷流。","不入祖師室，茫然趣兩头。","（同前）。"]', '诗', 'shi', '', NULL, '偈 智常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('160b2c84-68ca-4197-9736-4856263ada37', '題取經詩', '題取經诗', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["晉宋齊梁唐代間，高僧求法離長安。","去人成百歸無十，後者安知前者難。","路遠碧天唯冷結，沙河遮日力疲殫。","後賢如未諳斯旨，往往將經容易看。","（《四部叢刊》本宋法雲撰《翻譯名義集》卷七「續補譯師」條引唐義淨三藏詩。","《禪門諸祖師偈頌》卷下之下錄此爲「義淨三藏《誡看經》」。","）（按：《全唐詩》卷七八六收此詩於無名氏卷，注云：「載《翻譯名義集》，云唐義淨三藏作。","」岑仲勉先生《讀全唐詩札記》云：「按義淨詩今收十二函一冊，何不類附而別出於無名氏之下，豈編者未知義淨三藏即義淨歟。","然此詩祇據《翻譯名義集》錄，集又署名義淨三藏，終不得謂曰無名氏也。","」今承斯旨而重錄歸義淨名下。","）。"]', '["晉宋齊梁唐代间，高僧求法離长安。","去人成百归無十，後者安知前者难。","路远碧天唯冷結，沙河遮日力疲殫。","後賢如未諳斯旨，往往將經容易看。","（《四部叢刊》本宋法云撰《翻譯名義集》卷七「續補譯師」條引唐義淨三藏诗。","《禪门諸祖師偈頌》卷下之下錄此爲「義淨三藏《誡看經》」。","）（按：《全唐诗》卷七八六收此诗於無名氏卷，注云：「載《翻譯名義集》，云唐義淨三藏作。","」岑仲勉先生《读全唐诗札記》云：「按義淨诗今收十二函一冊，何不類附而別出於無名氏之下，豈編者未知義淨三藏即義淨歟。","然此诗祇據《翻譯名義集》錄，集又署名義淨三藏，終不得謂曰無名氏也。","」今承斯旨而重錄归義淨名下。","）。"]', '诗', 'shi', '', NULL, '題取經詩 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db8e564c-1367-4f18-96bf-f5515958edc5', '古鏡', '古镜', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["鑿井遘古墳，古墳襯淪沒。","誰家青銅鏡，送此長波月。","長河何冥冥，千歲光不徹。","玉匣歷窮泉，金龍潛幽窟。","鞶組已銷散，錦衣亦虧闕。","莓苔翳清池，蝦蟆蝕明月。","埋落今如此，照心未當歇。","願垂拂拭恩，爲君鑑雲髮。","（見斯二七一七《珠英學士集》殘卷，據吳企明先生錄本〖未刊〗。","《全唐詩》卷九五僅存末六句，今補全重錄。","殘卷原缺題，今從《全唐詩》補。","）。"]', '["鑿井遘古墳，古墳襯淪沒。","誰家青銅镜，送此长波月。","长河何冥冥，千歲光不徹。","玉匣歷窮泉，金龙潛幽窟。","鞶組已銷散，錦衣亦虧闕。","莓苔翳清池，蝦蟆蝕明月。","埋落今如此，照心未當歇。","願垂拂拭恩，爲君鑑云髮。","（见斯二七一七《珠英学士集》殘卷，據吳企明先生錄本〖未刊〗。","《全唐诗》卷九五僅存末六句，今補全重錄。","殘卷原缺題，今從《全唐诗》補。","）。"]', '诗', 'shi', '', NULL, '古鏡 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c85457-725e-4ddd-be13-082b153f5f27', '瓊州（題擬）', '瓊州（題擬）', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["異哉寸波中，露此橫海脊。","舉首玉簪插，忽去銀釘擲。","身大何時見，夭矯翔霹靂。","銅柱威丹徼，朱崖鎮火陬。","（見《輿地紀勝》卷一二四《瓊州》）。"]', '["異哉寸波中，露此橫海脊。","舉首玉簪插，忽去銀釘擲。","身大何时见，夭矯翔霹靂。","銅柱威丹徼，朱崖鎮火陬。","（见《輿地紀勝》卷一二四《瓊州》）。"]', '诗', 'shi', '', NULL, '瓊州（題擬） 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df68022b-5807-4bcb-8cbd-72287c53fbb1', '句', '句', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["先朝六駕日，遠虞附已深。","（見《海錄碎事》卷十）。"]', '["先朝六駕日，远虞附已深。","（见《海錄碎事》卷十）。"]', '诗', 'shi', '', NULL, '句 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e27e2cf-ec61-463f-a8e4-7499760fb868', '詩（附存）', '诗（附存）', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["萬里赴戎機，關山度若飛。","朔氣傳金柝，寒光照鐵衣。","（見明刻本宋佚名編《錦繡萬花谷後集》卷十四「將帥」類）（按：此四句即《木蘭詩》中後人以爲極似唐人所作之句。","《萬花谷》收佺期《塞北二首》摘句後，又收此四句，署「前人」。","未祥編者另有所據抑疏忽致誤。","今人或主《木蘭詩》爲唐初人所作。","今姑錄出附存佺期名下，以供研究者）（採擇。","又按：同治《泉州府志》卷七有沈佺期大小潘山七律二首。","佺期未入閩，二詩亦不類初唐詩，疑爲後代同名者作，今不錄，附識於此。","）。"]', '["万里赴戎機，关山度若飞。","朔氣傳金柝，寒光照鐵衣。","（见明刻本宋佚名編《錦繡万花谷後集》卷十四「將帥」類）（按：此四句即《木蘭诗》中後人以爲極似唐人所作之句。","《万花谷》收佺期《塞北二首》摘句後，又收此四句，署「前人」。","未祥編者另有所據抑疏忽致誤。","今人或主《木蘭诗》爲唐初人所作。","今姑錄出附存佺期名下，以供研究者）（採擇。","又按：同治《泉州府志》卷七有沈佺期大小潘山七律二首。","佺期未入閩，二诗亦不類初唐诗，疑爲後代同名者作，今不錄，附識於此。","）。"]', '诗', 'shi', '', NULL, '詩（附存） 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e13d7c8-ef65-45b9-a39c-a052c8664059', '應制和蔡孚偃松篇', '應制和蔡孚偃松篇', 'cd176a6d-50dd-4a32-890e-f1ca97b66a70', '唐', '["大廈已成無所用，唯將獻壽答堯心。","（《唐文拾補》卷十八韋璞玉撰《大唐故朝議郎京兆府功曹上柱國韋君墓誌銘》引）。"]', '["大廈已成無所用，唯將獻壽答堯心。","（《唐文拾補》卷十八韋璞玉撰《大唐故朝議郎京兆府功曹上柱国韋君墓誌銘》引）。"]', '诗', 'shi', '', NULL, '應制和蔡孚偃松篇 韋希損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fdd919-7932-41a1-b5c3-030679ac6e4a', '奉酬龍門北溪作（存目）（按：《文苑英華》卷一六六以此詩爲知古作。《唐詩紀事》卷十四則以爲魏奉古詩，《全唐詩》卷九一據以收入。《全唐詩》同卷知古小傳稱「存詩五首」，實收僅四首，或即因臨時抽出此詩而未及改傳。龍門北溪唱酬爲先天元年事，韋嗣立首倡，繼和者有張說、崔日知、崔泰之等。張說序僅稱崔、韋，未言魏。時知古已入推崇，奉古則位尚卑。以情理揆之，以作奉古詩爲近是。因《英華》成書較早，姑存目以備考。）', '奉酬龙门北溪作（存目）（按：《文苑英华》卷一六六以此诗爲知古作。《唐诗紀事》卷十四則以爲魏奉古诗，《全唐诗》卷九一據以收入。《全唐诗》同卷知古小傳稱「存诗五首」，實收僅四首，或即因臨时抽出此诗而未及改傳。龙门北溪唱酬爲先天元年事，韋嗣立首倡，繼和者有張说、崔日知、崔泰之等。張说序僅稱崔、韋，未言魏。时知古已入推崇，奉古則位尚卑。以情理揆之，以作奉古诗爲近是。因《英华》成书較早，姑存目以備考。）', '8b82646e-3034-4796-b02e-db89010d2b39', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '奉酬龍門北溪作（存目）（按：《文苑英華》卷一六六以此詩爲知古作。《唐詩紀事》卷十四則以爲魏奉古詩，《全唐詩》卷九一據以收入。《全唐詩》同卷知古小傳稱「存詩五首」，實收僅四首，或即因臨時抽出此詩而未及改傳。龍門北溪唱酬爲先天元年事，韋嗣立首倡，繼和者有張說、崔日知、崔泰之等。張說序僅稱崔、韋，未言魏。時知古已入推崇，奉古則位尚卑。以情理揆之，以作奉古詩爲近是。因《英華》成書較早，姑存目以備考。） 魏知古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0529787-cf40-4f73-ad93-998a0692f166', '訓崔長史公石橋[詠]', '訓崔长史公石橋[詠]', '0a576775-5d01-4595-bb7c-087b926ab78d', '唐', '["□壯雄規□，□□在□□。","□空歇滅（下缺）。","（見《文物參考資料》一九五七年第三期刊俞同奎《安濟橋補充文獻附石刻拓片》）（按：劉義詩附崔恂詩後，惜漫漶太甚，僅餘十數字。","崔恂詩已收入《全唐詩補逸》卷五。","俞文又謂同時所出有另一石，前半已漫漶，後數行尚可辨，可確定二詩作年，錄如次：□元八年九月□□□□□□李于時□□□□□崔恂任深州□史□□□還此橋過喜其壯麗命舊詩云□志並七年春。","俞同奎考定「□元八年」爲開元八年，幷謂崔恂七年春另有一詩刻石，迄未發現。","）。"]', '["□壯雄規□，□□在□□。","□空歇滅（下缺）。","（见《文物參考資料》一九五七年第三期刊俞同奎《安濟橋補充文獻附石刻拓片》）（按：劉義诗附崔恂诗後，惜漫漶太甚，僅餘十數字。","崔恂诗已收入《全唐诗補逸》卷五。","俞文又謂同时所出有另一石，前半已漫漶，後數行尚可辨，可確定二诗作年，錄如次：□元八年九月□□□□□□李于时□□□□□崔恂任深州□史□□□還此橋過喜其壯丽命旧诗云□志並七年春。","俞同奎考定「□元八年」爲开元八年，幷謂崔恂七年春另有一诗刻石，迄未發現。","）。"]', '诗', 'shi', '', NULL, '訓崔長史公石橋[詠] 劉義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adaec69c-38d4-4ee2-877e-9bdd94110cf6', '五言過棲巖寺', '五言過棲巖寺', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["鷲嶺高不極，延睇俯何宮？","城郭千年在，煙雲萬里通。","坐忘榮與利，行悟□將□（當爲「空」字）。","願假慈悲力，微資燮理功。","（見清胡聘之《山右石刻叢編》卷五）（按：此詩原刻高宗詩後。","題下署：「鳳閣侍郎同鳳閣鸞臺平章事姚元崇。","」）。"]', '["鷲嶺高不極，延睇俯何宮？","城郭千年在，煙云万里通。","坐忘榮與利，行悟□將□（當爲「空」字）。","願假慈悲力，微資燮理功。","（见清胡聘之《山右石刻叢編》卷五）（按：此诗原刻高宗诗後。","題下署：「鳳閣侍郎同鳳閣鸾台平章事姚元崇。","」）。"]', '诗', 'shi', '', NULL, '五言過棲巖寺 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d58cb5-95af-4fb2-89bb-18c98d237f85', '奉使蒲州返轡奉答聖制（題擬）', '奉使蒲州返轡奉答聖制（題擬）', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["歸來朝帝□，忽□（疑爲「逢」字）鈞天響。","懸知滻水遊，絕勝汾川賞。","（見前書同卷高宗《過棲巖寺》附刻韋元晨《六絕紀文》引）（按：此詩爲「大周長安二年」作，詩題據韋文擬。","）。"]', '["归来朝帝□，忽□（疑爲「逢」字）鈞天响。","懸知滻水游，絕勝汾川賞。","（见前书同卷高宗《過棲巖寺》附刻韋元晨《六絕紀文》引）（按：此诗爲「大周长安二年」作，诗題據韋文擬。","）。"]', '诗', 'shi', '', NULL, '奉使蒲州返轡奉答聖制（題擬） 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b0382e-6c4e-4bd2-a8c1-f1bd5e6633aa', '古石之歌', '古石之歌', '37aacf96-4d0e-431f-be5c-50f23fd2cdbe', '唐', '["江東藏瑞簡，濟北蘊兵書。","若非平固湖中鴈，定是昆明池裏魚。","（見《文苑英華》卷三一《古石賦》附）。"]', '["江东藏瑞簡，濟北蘊兵书。","若非平固湖中鴈，定是昆明池裏鱼。","（见《文苑英华》卷三一《古石賦》附）。"]', '诗', 'shi', '', NULL, '古石之歌 鄭惟忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75296a7c-585f-4be9-9e6a-e7c01b4e2dc7', '贈崔沔（題擬）', '贈崔沔（題擬）', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["棣華襲韡萼，桂樹連芳根。"]', '["棣华襲韡萼，桂樹連芳根。"]', '诗', 'shi', '', NULL, '贈崔沔（題擬） 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d3cf7cd-c01d-4907-af83-f199b6a104ea', '贈崔沔', '贈崔沔', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["接閈共懷鉛，齊生俎賁玉。","（見《文苑英華》卷七○二崔祐甫《齊昭公崔府君集序》引）（按：崔祐甫文稱爲「贈祐甫先君左僕射」詩，係以祐甫身份而言，非日用詩題。","今另擬題。","）。"]', '["接閈共懷鉛，齊生俎賁玉。","（见《文苑英华》卷七○二崔祐甫《齊昭公崔府君集序》引）（按：崔祐甫文稱爲「贈祐甫先君左僕射」诗，係以祐甫身份而言，非日用诗題。","今另擬題。","）。"]', '诗', 'shi', '', NULL, '贈崔沔 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6980d441-0cab-4901-ac5c-48c0b243cac5', '桃源行', '桃源行', 'c763e618-2c3a-47b7-a22a-2af2f7a12f1a', '唐', '["武陵川徑入幽遐，中有雞犬秦人家，家傍流水多桃花。","桃花兩邊種來久，流水一道何時有？","垂條落蕋暗春風，夾岸芳菲至山口。","歲歲年年能寂寥，林下青苔日爲厚。","時有仙鳥來啣花，曾無世人此携手。","可憐不知若爲名，君任（一作「往」）從之多所更。","古驛荒橋平路盡，崩湍怪石小溪行，相見維舟登覽處，紅堤綠岸宛然成。","多君此去從仙隱，令人晚節悔營營。","（見《文苑英華》卷三三二）（按：明刻本《文苑英華》收此詩失署名，《全唐詩》卷七八六遂收歸無名氏。","按《吟窗雜錄》卷四六收包融《武陵桃源送人》一首，前二句與此詩二句同，後二句作「先時見者爲誰耶，源水今流桃復花」。","《全唐詩》卷一一四已收入。","《吟窗雜錄》爲北宋末蔡傳編，保存唐詩甚豐，惟多爲節錄。","其錄爲包融詩，當可信。","《英華》所錄前三句，疑脫去一句。","）。"]', '["武陵川徑入幽遐，中有雞犬秦人家，家傍流水多桃花。","桃花兩邊種来久，流水一道何时有？","垂條落蕋暗春风，夾岸芳菲至山口。","歲歲年年能寂寥，林下青苔日爲厚。","时有仙鸟来啣花，曾無世人此携手。","可怜不知若爲名，君任（一作「往」）從之多所更。","古驛荒橋平路尽，崩湍怪石小溪行，相见維舟登覽处，紅堤綠岸宛然成。","多君此去從仙隐，令人晚節悔營營。","（见《文苑英华》卷三三二）（按：明刻本《文苑英华》收此诗失署名，《全唐诗》卷七八六遂收归無名氏。","按《吟窗杂錄》卷四六收包融《武陵桃源送人》一首，前二句與此诗二句同，後二句作「先时见者爲誰耶，源水今流桃复花」。","《全唐诗》卷一一四已收入。","《吟窗杂錄》爲北宋末蔡傳編，保存唐诗甚豐，惟多爲節錄。","其錄爲包融诗，當可信。","《英华》所錄前三句，疑脫去一句。","）。"]', '诗', 'shi', '', NULL, '桃源行 包融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3639ab6a-bb7a-4093-8a21-6a77738c1a64', '詠江上溺死女子（題擬）', '詠江上溺死女子（題擬）', '9a60ccae-e577-48a2-94bc-73e2cfaf061e', '唐', '["二八誰家女，漂來倚岸蘆。","鳥窺眉上翠，魚弄口傍珠。","。"]', '["二八誰家女，漂来倚岸蘆。","鸟窺眉上翠，鱼弄口傍珠。","。"]', '诗', 'shi', '', NULL, '詠江上溺死女子（題擬） 江油令 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aebbe40-8bda-4df4-bd37-e80ab8555e67', '賦山火詩', '賦山火诗', '9a60ccae-e577-48a2-94bc-73e2cfaf061e', '唐', '["野火燒山去，人歸火不歸。","（均見《唐詩紀事》卷十八引《彰明逸事》）。"]', '["野火燒山去，人归火不归。","（均见《唐诗紀事》卷十八引《彰明逸事》）。"]', '诗', 'shi', '', NULL, '賦山火詩 江油令 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4135088-9b9b-4ae1-8f4a-222d7f75eedf', '在唐奉本國皇太子', '在唐奉本国皇太子', 'f4526e3c-4ec5-465f-a894-dcbe531981db', '唐', '["三寶持聖德，百靈扶仙壽。","壽共日月長，德與天地久。","（日本淡海三船《懷風藻》）。"]', '["三寶持聖德，百靈扶仙壽。","壽共日月长，德與天地久。","（日本淡海三船《懷风藻》）。"]', '诗', 'shi', '', NULL, '在唐奉本國皇太子 道慈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40a87f4-1385-49f8-892c-6872b51a9d38', '在唐憶本鄉', '在唐憶本乡', '04bcc3ef-fe5d-4ab3-a538-deb014f02aae', '唐', '["日邊瞻日本，雲裏望雲端。","遠遊勞遠國，長恨苦長安。","（《懷風藻》）。"]', '["日邊瞻日本，云裏望云端。","远游勞远国，长恨苦长安。","（《懷风藻》）。"]', '诗', 'shi', '', NULL, '在唐憶本鄉 辨正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d63b41d-d28d-4135-b3a2-9d3c1e8f71df', '與朝主人', '與朝主人', '04bcc3ef-fe5d-4ab3-a538-deb014f02aae', '唐', '["鐘鼓沸城闉，戎蕃預國親。","神明今漢主，柔遠靜胡塵。","琴歌馬上怨，楊柳曲中春。","唯有關山月，偏迎北塞人。","（同前）（按：道慈、辨正詩，張步雲《唐代逸詩輯存》已收入。","）。"]', '["鐘鼓沸城闉，戎蕃預国親。","神明今漢主，柔远静胡塵。","琴歌马上怨，楊柳曲中春。","唯有关山月，偏迎北塞人。","（同前）（按：道慈、辨正诗，張步云《唐代逸诗輯存》已收入。","）。"]', '诗', 'shi', '', NULL, '與朝主人 辨正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f2de14-cd18-4c17-afa6-fb2977b8d686', '雲中古城賦附歌 一', '云中古城賦附歌 一', '25ff532f-e023-446c-adc4-49bdcfc1b4f3', '唐', '["魏家美人聞姓元，新聲巧妙今古傳。","昔日流音遍華夏，可憐埋骨委山樊。","城闕摧殘猶可惜，荒郊處處生荆棘。","寒飈動地胡馬嘶，若個征夫不沾臆。","人生榮耀當及時，白髮須臾亂如絲。","君不見魏都行樂處，祇今空有野風吹。"]', '["魏家美人闻姓元，新声巧妙今古傳。","昔日流音遍华夏，可怜埋骨委山樊。","城闕摧殘猶可惜，荒郊处处生荆棘。","寒飈动地胡马嘶，若個征夫不沾臆。","人生榮耀當及时，白髮須臾亂如絲。","君不见魏都行乐处，祇今空有野风吹。"]', '诗', 'shi', '', NULL, '雲中古城賦附歌 一 張嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d07682-e76c-444d-90ce-964a97595954', '雲中古城賦附歌 二', '云中古城賦附歌 二', '25ff532f-e023-446c-adc4-49bdcfc1b4f3', '唐', '["雲中古城鬱嵯峨，塞上行吟麥秀歌。","感時傷古今如此，報主懷恩奈老何！（見《文苑英華》卷四五）。"]', '["云中古城鬱嵯峨，塞上行吟麦秀歌。","感时傷古今如此，報主懷恩奈老何！（见《文苑英华》卷四五）。"]', '诗', 'shi', '', NULL, '雲中古城賦附歌 二 張嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5763efa2-4a9d-4c06-bc5e-e74535e5c930', '大唐封東嶽朝覲頌附詩', '大唐封东嶽朝覲頌附诗', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["天子聖兮天孫崇，登以封兮報以功。","受命再惟皇代，天之賚人所載。","士馬山嶫，戈矛山沓，禎符山雜，靈響山答，天與人合。","我鋪衍兮長粹清，太元冊兮太一精，休光光我之慶成，舜四朝而禹萬國，莫之我京。","（見《唐文粹》卷十九）。"]', '["天子聖兮天孫崇，登以封兮報以功。","受命再惟皇代，天之賚人所載。","士马山嶫，戈矛山沓，禎符山杂，靈响山答，天與人合。","我鋪衍兮长粹清，太元冊兮太一精，休光光我之慶成，舜四朝而禹万国，莫之我京。","（见《唐文粹》卷十九）。"]', '诗', 'shi', '', NULL, '大唐封東嶽朝覲頌附詩 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7eccfd-f8e0-411d-8fd9-d97e2e016a73', '示慧忠偈（題擬） 一', '示慧忠偈（題擬） 一', 'b6f4afff-f68f-4c2c-80fc-27597e706048', '唐', '["莫繫念，念成生死河。","輪迴六趣海，無見出長波。","（見《景德傳燈錄》卷四、《五燈會元》卷二）。"]', '["莫繫念，念成生死河。","輪迴六趣海，無见出长波。","（见《景德傳灯錄》卷四、《五灯會元》卷二）。"]', '诗', 'shi', '', NULL, '示慧忠偈（題擬） 一 智威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e76a9e6-4099-4fdc-948e-18518474c303', '示慧忠偈（題擬） 二', '示慧忠偈（題擬） 二', 'b6f4afff-f68f-4c2c-80fc-27597e706048', '唐', '["余本性虛無，緣妄生人我。","如何息妄情，還歸空處坐。","（見《五燈會元》卷二）。"]', '["余本性虛無，緣妄生人我。","如何息妄情，還归空处坐。","（见《五灯會元》卷二）。"]', '诗', 'shi', '', NULL, '示慧忠偈（題擬） 二 智威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b3f39f-4de8-41fb-9ed2-9c6e519b0163', '摩訶羅國娑般檀寺述志（題擬）', '摩訶羅国娑般檀寺述志（題擬）', '4e0b30ca-e528-46f0-b131-b9049ba8db31', '唐', '["不慮菩提遠，焉將鹿苑遙。","祇愁懸路險，非意業風飄。","八塔難誠見，參著經劫燒。","何其人願滿，目覩在今朝。"]', '["不慮菩提远，焉將鹿苑遙。","祇愁懸路險，非意業风飄。","八塔难誠见，參著經劫燒。","何其人願满，目覩在今朝。"]', '诗', 'shi', '', NULL, '摩訶羅國娑般檀寺述志（題擬） 慧超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('789f1c46-8610-47aa-a185-fec135442ad6', '南天路言懷（題擬）', '南天路言懷（題擬）', '4e0b30ca-e528-46f0-b131-b9049ba8db31', '唐', '["月夜瞻氜路，浮雲颯颯歸。","減書參去便，風急不聽迴。","我國天岸北，他邦地角西。","日南無有雁，誰爲向林飛。","。"]', '["月夜瞻氜路，浮云颯颯归。","減书參去便，风急不听迴。","我国天岸北，他邦地角西。","日南無有雁，誰爲向林飞。","。"]', '诗', 'shi', '', NULL, '南天路言懷（題擬） 慧超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9898ed8-dd7b-4e6c-b2a1-2ad9a225daa7', '哀求法漢僧（幷序○題擬）', '哀求法漢僧（幷序○題擬）', '4e0b30ca-e528-46f0-b131-b9049ba8db31', '唐', '["故里燈無主，他方寶樹摧。","神靈去何處，玉貌已成灰。","憶想哀情切，悲君願不隨。","孰知鄉國路，空見白雲歸。","（以上三詩均出《大正新修大藏經》第五十一冊慧超撰《往五天竺國傳》。","參伯三五三二卷。","）。"]', '["故里灯無主，他方寶樹摧。","神靈去何处，玉貌已成灰。","憶想哀情切，悲君願不隨。","孰知乡国路，空见白云归。","（以上三诗均出《大正新修大藏經》第五十一冊慧超撰《往五天竺国傳》。","參伯三五三二卷。","）。"]', '诗', 'shi', '', NULL, '哀求法漢僧（幷序○題擬） 慧超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6891ff5c-f5ed-48a4-b886-0d9dd362fb0a', '五言□□觀□明府携（下缺）', '五言□□观□明府携（下缺）', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["春山桂實奇，露□莅江垂。","（下缺）□疎□□識，幽□□人知。","賴□□□□，□□□□□。","（《文博》一九九○年第一期刊張沛《唐黃土磨崖刻石試析》錄陝西旬陽城東禹穴側磨崖石刻）（按：據張文介紹，此石刻爲楷書，凡五十四行，行約三十字，漫漶甚嚴重。","自十一行以後，錄唱和諸人詩什。","首十行似敍唱和緣起，錄殘文如次：「〖上缺三行〗土牛〖下缺〗幽桂一□□□□里〖下缺〗焉覩其仙〖下缺〗衣繡之〖下缺〗石□泉□□雉〖下缺〗而□人花西摘以清一〖下缺〗元十七年春正月庶〖下缺〗」張文據黃土縣之置改，考定此組詩作於開元十七年，可爲定論。","第一首詩作者姓名、官職不詳。","從第二首詩題看，似即□州〖疑即金州〗別駕。","）。"]', '["春山桂實奇，露□莅江垂。","（下缺）□疎□□識，幽□□人知。","賴□□□□，□□□□□。","（《文博》一九九○年第一期刊張沛《唐黄土磨崖刻石試析》錄陝西旬陽城东禹穴側磨崖石刻）（按：據張文介紹，此石刻爲楷书，凡五十四行，行約三十字，漫漶甚嚴重。","自十一行以後，錄唱和諸人诗什。","首十行似敍唱和緣起，錄殘文如次：「〖上缺三行〗土牛〖下缺〗幽桂一□□□□里〖下缺〗焉覩其仙〖下缺〗衣繡之〖下缺〗石□泉□□雉〖下缺〗而□人花西摘以清一〖下缺〗元十七年春正月庶〖下缺〗」張文據黄土縣之置改，考定此組诗作於开元十七年，可爲定論。","第一首诗作者姓名、官職不詳。","從第二首诗題看，似即□州〖疑即金州〗別駕。","）。"]', '诗', 'shi', '', NULL, '五言□□觀□明府携（下缺） 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dca76a3-fc19-4559-b49f-1bdce4b4f50f', '', '', '05a034b7-275f-4c33-8639-1683a6457194', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' □州司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('827de3a3-5296-42fe-943b-5ec668993167', '□□州別駕□皇□從□□□聞下（下缺）', '□□州別駕□皇□從□□□闻下（下缺）', '05a034b7-275f-4c33-8639-1683a6457194', '唐', '["聞□□□才，□春復賞梅。","詠□幽山桂，傳聲□□□。","□□□□□，□□□□□。","□□□君酒，花□妓女杯。","淮南有便使，□摘一枝來。","□□史（下缺。","同前）。"]', '["闻□□□才，□春复賞梅。","詠□幽山桂，傳声□□□。","□□□□□，□□□□□。","□□□君酒，花□妓女杯。","淮南有便使，□摘一枝来。","□□史（下缺。","同前）。"]', '诗', 'shi', '', NULL, '□□州別駕□皇□從□□□聞下（下缺） □州司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c860c6e4-21e6-496c-ae3f-419535d3a65f', '□和', '□和', '6c830ab4-8fed-4015-ab0d-13df4f3ade26', '唐', '["（上缺）影□□□□□□□□□□丹。","□軾□黃土，□琴□武城。","醴泉飛漢曲，芳桂□山□。","□丹□彾□，羣英□雁聲。","□□□□德，{蠜虫=糸}□遂留情。","□□□靡□，□□□□□。","□□香可□，□□□□□。","（同前）（按：此詩題僅存「和」字，知爲和前詩之作。","）。"]', '["（上缺）影□□□□□□□□□□丹。","□軾□黄土，□琴□武城。","醴泉飞漢曲，芳桂□山□。","□丹□彾□，羣英□雁声。","□□□□德，{蠜虫=糸}□遂留情。","□□□靡□，□□□□□。","□□香可□，□□□□□。","（同前）（按：此诗題僅存「和」字，知爲和前诗之作。","）。"]', '诗', 'shi', '', NULL, '□和 □同 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1558c970-bd78-454a-8987-a8e59bef6485', '同[前]', '同[前]', '7360b562-dbe3-45bf-af7c-257b63b69efd', '唐', '["（上缺）如。","淮南桂□林，幽□武城隅。","□白無人識，□□□楊殊。","影□巖□□，□□□□□。","𠭴公子至，香拂舞童□。","不被王孫□，何由得鑒歟？","□轉□□□，□□□□□。","（同前）（按：以下諸詩，皆署〖同前〗，知爲同時唱和之作。","）。"]', '["（上缺）如。","淮南桂□林，幽□武城隅。","□白無人識，□□□楊殊。","影□巖□□，□□□□□。","𠭴公子至，香拂舞童□。","不被王孫□，何由得鑒歟？","□轉□□□，□□□□□。","（同前）（按：以下諸诗，皆署〖同前〗，知爲同时唱和之作。","）。"]', '诗', 'shi', '', NULL, '同[前] 馮□原 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79847820-4d53-45f7-8957-e58fe3de0248', '同前', '同前', '263e821c-b857-4dc6-9f45-cf4592e6b6fe', '唐', '["（上缺）芳（下缺）□□游□浦，弄鳥戲蘭陔。","石□吟□□，山□奏落梅。","壽□半□□，□□□□□。","□□臨江酌，舞席倚泉開。","□留□□□，□醉□巖□。","（同前）（按：馮□原、□馮，皆署爲黃土縣令，疑爲前後任。","）。"]', '["（上缺）芳（下缺）□□游□浦，弄鸟戲蘭陔。","石□吟□□，山□奏落梅。","壽□半□□，□□□□□。","□□臨江酌，舞席倚泉开。","□留□□□，□醉□巖□。","（同前）（按：馮□原、□馮，皆署爲黄土縣令，疑爲前後任。","）。"]', '诗', 'shi', '', NULL, '同前 □馮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ce9d58-ce55-47fa-991a-6d4095a420f8', '同前', '同前', '14f9fcf6-35ff-416d-a424-f71569a15095', '唐', '["（上缺）□□□□撫，幽巖有□香。","□□□□□，□□舞□莊。","□□□□□，□□□□□。","□□□□化，叨毗製錦□。","□□□□□，□□□□陽。","（同前）。"]', '["（上缺）□□□□撫，幽巖有□香。","□□□□□，□□舞□莊。","□□□□□，□□□□□。","□□□□化，叨毗製錦□。","□□□□□，□□□□陽。","（同前）。"]', '诗', 'shi', '', NULL, '同前 楊潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9741bb85-8025-4bb1-ba1b-a4a2f68afc6f', '同前', '同前', '6e0a76e4-899c-4e91-ba6a-e3386a365c42', '唐', '["王□重幽賞，携樽對□□。","□□□□□，□□□□□。","□□□□□，□□□□□。","鳥鳴欺□度，人嬌舞實□。","獨□□□□，□□□□□。","（同前）。"]', '["王□重幽賞，携樽对□□。","□□□□□，□□□□□。","□□□□□，□□□□□。","鸟鳴欺□度，人嬌舞實□。","独□□□□，□□□□□。","（同前）。"]', '诗', 'shi', '', NULL, '同前 楊□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8676d277-f37d-40fc-bb9b-4da6b53072bd', '同前', '同前', 'ae032125-f731-49d5-8488-e8f4c7b6e83d', '唐', '["□□□幽□，携樽玩桂□。","□□□□□，□□□□□。","□□□□□，□□□□□。","□□□月□，欺曲彩雲中。","□□□□□，合□□□□。","（同前）。"]', '["□□□幽□，携樽玩桂□。","□□□□□，□□□□□。","□□□□□，□□□□□。","□□□月□，欺曲彩云中。","□□□□□，合□□□□。","（同前）。"]', '诗', 'shi', '', NULL, '同前 黃土縣尉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812a5691-1f8c-4652-8815-4bd3265e7d4b', '', '', '6e0a76e4-899c-4e91-ba6a-e3386a365c42', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 楊□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd001311-ad2c-42f6-b1a7-41f988b4ba3e', '同前', '同前', '6e0a76e4-899c-4e91-ba6a-e3386a365c42', '唐', '["（上缺）□□丹桂□，旖旎綠巖垂。","□□露（下缺）人□花飄□袖宜□□□□□□雖（下缺。","同前）。"]', '["（上缺）□□丹桂□，旖旎綠巖垂。","□□露（下缺）人□花飄□袖宜□□□□□□雖（下缺。","同前）。"]', '诗', 'shi', '', NULL, '同前 楊□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f92f0d-b597-44f6-bed0-6ad18f28f223', '同前', '同前', '460cfb22-48f7-42be-8aa9-c48c4268ec82', '唐', '["（上缺）在□□□□巖前□華歷畿（下缺）人眄王孫寔□甄得因（下缺。","同前）。"]', '["（上缺）在□□□□巖前□华歷畿（下缺）人眄王孫寔□甄得因（下缺。","同前）。"]', '诗', 'shi', '', NULL, '同前 雍州率□□□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b05643f-3cb9-48f4-8b1a-ae4453113b4f', '同前', '同前', 'd1069f4f-d51c-43e6-83bc-80e958f3bdb5', '唐', '["（上缺）□□火□修□上罩天□孫（下缺）□□承□妓，香風韻管絃。","（下缺。","同前）（按：此下尚有□陽隱士、前西城縣尉二人之殘詩，□陽隱士詩存：「□□□勝□□履〖下缺〗雲□草□空不期□□□□得□□聖〖下缺〗」前西城縣尉詩存：「□□地零落□□□□□□□□□殊香〖下缺〗醉□□□□仙□□□曲□□能〖下缺〗」皆已不可讀，不另立目，姑附於此。","）。"]', '["（上缺）□□火□修□上罩天□孫（下缺）□□承□妓，香风韻管絃。","（下缺。","同前）（按：此下尚有□陽隐士、前西城縣尉二人之殘诗，□陽隐士诗存：「□□□勝□□履〖下缺〗云□草□空不期□□□□得□□聖〖下缺〗」前西城縣尉诗存：「□□地零落□□□□□□□□□殊香〖下缺〗醉□□□□仙□□□曲□□能〖下缺〗」皆已不可读，不另立目，姑附於此。","）。"]', '诗', 'shi', '', NULL, '同前 孫□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d482b982-a2fe-45d5-9c3c-002f23a373ac', '', '', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386eeede-d3ae-4be3-94ea-d7ce30c93a81', '戚夫人楚舞歌', '戚夫人楚舞歌', '4835e3a8-cb3e-406b-bd92-c7fe981bca5b', '唐', '["定陶城中是妾家，妾年二八顏如花。","閨中歌舞未終曲，天下死人如亂麻。","漢王此地因征戰，未出簾櫳人已薦。","風花菡萏落轅門，雲雨徘徊入行殿。","日夕悠悠非舊鄉，飄颻處處逐君王。","玉閨門裏通歸夢，銀燭迎來在戰場。","從來顧恩不顧己，何異浮萍寄深水。","逐戰曾迷隻輪下，隨君幾陷重圍裏。","此時平楚復平齊，咸陽宮闕到關西。","珠簾夕殿聞鐘漏，白日秋天憶鼓鼙。","且矜容色長自持，且遇乘輿恩幸時。","香羅侍寢雙龍殿，玉輦看花百子池。","君王縱恣翻成誤，呂后由來有深妒。","不奈君王容髮衰，相存相顧能幾時。","黃泉白骨不可報，雀釵翠羽從此辭。","君楚歌兮妾楚舞，脉脉相看兩心苦。","曲未終兮袂更揚，君流涕兮妾斷腸。","已見謀臣歸惠帝，徒留愛子付周昌。","（《才調集》卷三、伯二五六七卷）（按：伯二五六七卷存此詩之後半篇，今參《才調集》補足之。","《全唐詩》卷一二○收此詩，缺「且矜容色長自持」以下四句，故重錄之。","此則承湯華泉同志見告。","）。"]', '["定陶城中是妾家，妾年二八顏如花。","閨中歌舞未終曲，天下死人如亂麻。","漢王此地因征戰，未出簾櫳人已薦。","风花菡萏落轅门，云雨徘徊入行殿。","日夕悠悠非旧乡，飄颻处处逐君王。","玉閨门裏通归梦，銀燭迎来在戰場。","從来顧恩不顧己，何異浮萍寄深水。","逐戰曾迷隻輪下，隨君幾陷重圍裏。","此时平楚复平齊，咸陽宮闕到关西。","珠簾夕殿闻鐘漏，白日秋天憶鼓鼙。","且矜容色长自持，且遇乘輿恩幸时。","香羅侍寢雙龙殿，玉輦看花百子池。","君王縱恣翻成誤，呂后由来有深妒。","不奈君王容髮衰，相存相顧能幾时。","黄泉白骨不可報，雀釵翠羽從此辞。","君楚歌兮妾楚舞，脉脉相看兩心苦。","曲未終兮袂更揚，君流涕兮妾斷腸。","已见謀臣归惠帝，徒留愛子付周昌。","（《才調集》卷三、伯二五六七卷）（按：伯二五六七卷存此诗之後半篇，今參《才調集》補足之。","《全唐诗》卷一二○收此诗，缺「且矜容色长自持」以下四句，故重錄之。","此則承湯华泉同志见告。","）。"]', '诗', 'shi', '', NULL, '戚夫人楚舞歌 李昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fec52c34-3a2a-48f8-b41b-91d861183b02', '三門賦附歌', '三门賦附歌', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["甲負石兮空自奇，客乘查兮何遠爲。","君不見虛舟之泛泛，浩浩乘流而不羈。","（見《文苑英華》卷三四）。"]', '["甲負石兮空自奇，客乘查兮何远爲。","君不见虛舟之泛泛，浩浩乘流而不羈。","（见《文苑英华》卷三四）。"]', '诗', 'shi', '', NULL, '三門賦附歌 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b097c0-5b05-4498-acc2-30eba4d23165', '白楊篇', '白楊篇', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["欲識前王塔鞍處，正北苗抽一小枝。","（《文苑英華》卷八七六令狐楚《白楊新廟碑》引。","此則承陶敏先生告知。","）。"]', '["欲識前王塔鞍处，正北苗抽一小枝。","（《文苑英华》卷八七六令狐楚《白楊新廟碑》引。","此則承陶敏先生告知。","）。"]', '诗', 'shi', '', NULL, '白楊篇 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2548199-5921-433f-a896-19edec69f4c5', '句', '句', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["分班曉入翔鴛閣，直舍旁連浴鳳池。","（見明刻本《錦繡萬花谷後集》卷十）。"]', '["分班晓入翔鴛閣，直舍旁連浴鳳池。","（见明刻本《錦繡万花谷後集》卷十）。"]', '诗', 'shi', '', NULL, '句 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b04e5a0-d3cc-4fe1-b945-29064b1234b5', '詠三御史（題擬）', '詠三御史（題擬）', '32461806-2c65-490c-988f-f4e1e9e6fbd8', '唐', '["韋子凝而密，任生直且狂。","可憐元福慶，也學坐癡牀。","（見《太平廣記》卷二五○韓琬《御史臺記》引）（《御史臺記》云：「唐元福慶，河南人，拜右臺監察。","與韋虛名、任正名頗事軒昂。","殿中監察朱評之詠曰〖詩略〗。","正名聞之，乃自改爲『俊且強』。","」按：談刻本《太平廣記》錄前段文字，適缺「朱」字。","《全唐詩》卷八七二收入此詩。","其祖本當即談刻本，未察「評之」爲人名，因列入無名氏諧謔詩。","人民文學出版社排印本《太平廣記》，爲汪紹楹先生校本，此處據明抄本補「朱」字，今即據以重錄。","評之時代，係參據任正名事跡而定。","）。"]', '["韋子凝而密，任生直且狂。","可怜元福慶，也学坐癡牀。","（见《太平廣記》卷二五○韓琬《御史台記》引）（《御史台記》云：「唐元福慶，河南人，拜右台監察。","與韋虛名、任正名頗事軒昂。","殿中監察朱評之詠曰〖诗略〗。","正名闻之，乃自改爲『俊且強』。","」按：談刻本《太平廣記》錄前段文字，適缺「朱」字。","《全唐诗》卷八七二收入此诗。","其祖本當即談刻本，未察「評之」爲人名，因列入無名氏諧謔诗。","人民文学出版社排印本《太平廣記》，爲汪紹楹先生校本，此处據明抄本補「朱」字，今即據以重錄。","評之时代，係參據任正名事跡而定。","）。"]', '诗', 'shi', '', NULL, '詠三御史（題擬） 朱評之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd2b048-8b04-4f2b-a7c4-7a44a94f83d9', '玄珠歌 一', '玄珠歌 一', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["解採玄珠萬惡除，盡令得道入清虛。","乾符顯出真金行，備在逍遙三卷書。"]', '["解採玄珠万惡除，尽令得道入清虛。","乾符显出真金行，備在逍遙三卷书。"]', '诗', 'shi', '', NULL, '玄珠歌 一 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1602fcc-fc6c-4279-a8b9-a57788d20f8e', '玄珠歌 二', '玄珠歌 二', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["宮闕樓臺表道軀，不留命本敵洪爐。","元神散走枯庭在，拋盡玄珠一物無。"]', '["宮闕楼台表道軀，不留命本敵洪爐。","元神散走枯庭在，拋尽玄珠一物無。"]', '诗', 'shi', '', NULL, '玄珠歌 二 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb12b91-45fd-4e3f-9009-e417d0521862', '玄珠歌 三', '玄珠歌 三', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["塵心不識體中天，空敬靈儀擬覓仙。","自有玄珠不知處，何年歸命入丹田。"]', '["塵心不識體中天，空敬靈儀擬覓仙。","自有玄珠不知处，何年归命入丹田。"]', '诗', 'shi', '', NULL, '玄珠歌 三 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34244425-e196-45ab-acf9-d4d63ca94a5c', '玄珠歌 四', '玄珠歌 四', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["多恃聰明強是非，縱聞法要亦相違。","若能不出長生寶，結作玄珠透紫微。"]', '["多恃聰明強是非，縱闻法要亦相違。","若能不出长生寶，結作玄珠透紫微。"]', '诗', 'shi', '', NULL, '玄珠歌 四 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c716ae-05f7-430b-b461-09f3fdcdb6c0', '玄珠歌 五', '玄珠歌 五', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["謾求土塑及丹青，空看經文道豈成。","自有玄珠無價寶，幾時覺悟駐神精。"]', '["謾求土塑及丹青，空看經文道豈成。","自有玄珠無價寶，幾时覺悟駐神精。"]', '诗', 'shi', '', NULL, '玄珠歌 五 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b396817-615c-4729-a1e6-b0c7278450ca', '玄珠歌 六', '玄珠歌 六', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["明暗同源人不知，若能曉了自幽奇。","玄珠定是含光主，永住金宮月魄池。"]', '["明暗同源人不知，若能晓了自幽奇。","玄珠定是含光主，永住金宮月魄池。"]', '诗', 'shi', '', NULL, '玄珠歌 六 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51c49b3-a7ce-4fcc-a434-356ca1ec95a4', '玄珠歌 七', '玄珠歌 七', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["落崖溪畔整神機，能把金光閉命扉。","爲得玄珠鎮靈府，一真行處一光輝。"]', '["落崖溪畔整神機，能把金光閉命扉。","爲得玄珠鎮靈府，一真行处一光輝。"]', '诗', 'shi', '', NULL, '玄珠歌 七 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86680d1e-b8aa-48dc-b8c3-50358ca2d28e', '玄珠歌 八', '玄珠歌 八', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["元真散走不能扃，積毒縱橫壞百靈。","豁盡玄珠無上寶，醉中生死幾時醒。"]', '["元真散走不能扃，積毒縱橫壞百靈。","豁尽玄珠無上寶，醉中生死幾时醒。"]', '诗', 'shi', '', NULL, '玄珠歌 八 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc7b2ab-fa8f-4c4b-8697-86bcf32741d7', '玄珠歌 九', '玄珠歌 九', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["冲和海裏育元精，中有玄珠壽命成。","不鍊不凝拋欲盡，何如黑處頓教明。"]', '["冲和海裏育元精，中有玄珠壽命成。","不鍊不凝拋欲尽，何如黑处頓教明。"]', '诗', 'shi', '', NULL, '玄珠歌 九 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef8a5cb1-d007-471c-b530-da6d653da846', '玄珠歌 十', '玄珠歌 十', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["解通神息體藏珍，與道相違便失真。","若遇玄珠結中道，自然成就化金巾。"]', '["解通神息體藏珍，與道相違便失真。","若遇玄珠結中道，自然成就化金巾。"]', '诗', 'shi', '', NULL, '玄珠歌 十 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f571d9-c7ff-4060-9deb-339f80826a55', '玄珠歌 十一', '玄珠歌 十一', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["凡情激濁污天門，豈識玄珠性命根。","生處莫令流浪去，當時清淨不迷昏。"]', '["凡情激濁污天门，豈識玄珠性命根。","生处莫令流浪去，當时清淨不迷昏。"]', '诗', 'shi', '', NULL, '玄珠歌 十一 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9129cb25-5319-45f4-925e-50296edd2975', '玄珠歌 十二', '玄珠歌 十二', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠振動被魔羣，照著生門白黑分。","向裏修持堅固後，道成方識九霄君。"]', '["玄珠振动被魔羣，照著生门白黑分。","向裏修持堅固後，道成方識九霄君。"]', '诗', 'shi', '', NULL, '玄珠歌 十二 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298153c3-353b-4c46-9748-d6bf90d91f83', '玄珠歌 十三', '玄珠歌 十三', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["欲採玄珠日月奔，先須火發制靈根。","朝元萬過金精結，此是登真第一門。","。"]', '["欲採玄珠日月奔，先須火發制靈根。","朝元万過金精結，此是登真第一门。","。"]', '诗', 'shi', '', NULL, '玄珠歌 十三 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe79da35-c629-4e0d-81c4-305af0e1d4f5', '玄珠歌 十四', '玄珠歌 十四', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠常處洞房居，日月融來渾太虛。","真遣瓊環隨液化，光明不絕照神廬。"]', '["玄珠常处洞房居，日月融来渾太虛。","真遣瓊环隨液化，光明不絕照神廬。"]', '诗', 'shi', '', NULL, '玄珠歌 十四 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe7997d-544f-4d57-ad6b-925522b77a57', '玄珠歌 十五', '玄珠歌 十五', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠玉樹有根苗，水際連天永不凋。","真火含虛如赤日，金華結魄六時潮。"]', '["玄珠玉樹有根苗，水際連天永不凋。","真火含虛如赤日，金华結魄六时潮。"]', '诗', 'shi', '', NULL, '玄珠歌 十五 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd199a8-3bd7-47ba-a388-20af922f8350', '玄珠歌 十六', '玄珠歌 十六', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["早須烹取太陽酥，喫著元神永不枯。","若要形超化金骨，玄珠向裏有醍醐。"]', '["早須烹取太陽酥，喫著元神永不枯。","若要形超化金骨，玄珠向裏有醍醐。"]', '诗', 'shi', '', NULL, '玄珠歌 十六 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c410dbbc-bb59-4ffd-88e0-617afbfb8dc8', '玄珠歌 十七', '玄珠歌 十七', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["逍遙常飲月魂津，灌溉靈根道德新。","留寶去塵光不散，玄珠照耀五通身。"]', '["逍遙常饮月魂津，灌溉靈根道德新。","留寶去塵光不散，玄珠照耀五通身。"]', '诗', 'shi', '', NULL, '玄珠歌 十七 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be233e0-3567-4c34-a824-5863c04e5769', '玄珠歌 十八', '玄珠歌 十八', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["往來出入改嬰孩，順逆參差致禍災。","盡有玄珠同一處，因師與指住靈臺。"]', '["往来出入改嬰孩，順逆參差致禍災。","尽有玄珠同一处，因師與指住靈台。"]', '诗', 'shi', '', NULL, '玄珠歌 十八 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb86bf95-6bca-41ad-80f4-70427c2119e3', '玄珠歌 十九', '玄珠歌 十九', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠鼓吹法雷霆，雨滿中池變八瓊。","從此光明徹天上，五雲行駕到蓬瀛。"]', '["玄珠鼓吹法雷霆，雨满中池变八瓊。","從此光明徹天上，五云行駕到蓬瀛。"]', '诗', 'shi', '', NULL, '玄珠歌 十九 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ede85bb-097a-4ab5-84ea-e4dc217d4c06', '玄珠歌 二十', '玄珠歌 二十', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["用心萬種事多端，何以歸元向裏觀。","捉得玄珠令換骨，形超碧落駕金鸞。"]', '["用心万種事多端，何以归元向裏观。","捉得玄珠令換骨，形超碧落駕金鸾。"]', '诗', 'shi', '', NULL, '玄珠歌 二十 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d541352-b2fe-4fca-9520-abb1a29da080', '玄珠歌 二十一', '玄珠歌 二十一', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["安閑日夜不曾奔，裏有玄珠開一門。","蕩盡塵勞分日月，直交至寶入崑崙。"]', '["安闲日夜不曾奔，裏有玄珠开一门。","蕩尽塵勞分日月，直交至寶入崑崙。"]', '诗', 'shi', '', NULL, '玄珠歌 二十一 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44fec688-8ce4-4116-bf5d-1bd480d571c6', '玄珠歌 二十二', '玄珠歌 二十二', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["因師傳秘頓無爭，抽却玄珠一道明。","天樂至今聲不絕，玄珠果滿赤龍迎。"]', '["因師傳秘頓無爭，抽却玄珠一道明。","天乐至今声不絕，玄珠果满赤龙迎。"]', '诗', 'shi', '', NULL, '玄珠歌 二十二 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b364d4c8-d970-4ae2-ab0c-57acf8ab85be', '玄珠歌 二十三', '玄珠歌 二十三', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["點檢光芒八道分，解吞真火體中焚。","玄珠開決三清界，待了齊驅五色雲。"]', '["点檢光芒八道分，解吞真火體中焚。","玄珠开決三清界，待了齊驱五色云。"]', '诗', 'shi', '', NULL, '玄珠歌 二十三 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0dec26-ea0d-4bfe-905c-e45ad69191b9', '玄珠歌 二十四', '玄珠歌 二十四', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["未悟真元恍惚驚，任心貪慾恣三彭。","玄珠到處無能染，寶滿瓊池達上清。"]', '["未悟真元恍惚驚，任心貪慾恣三彭。","玄珠到处無能染，寶满瓊池達上清。"]', '诗', 'shi', '', NULL, '玄珠歌 二十四 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f99eac7-6527-4a32-b840-fc27b69b5e30', '玄珠歌 二十五', '玄珠歌 二十五', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠得了永無爭，不出丹元結實成。","因轉淘澄輪似月，尋常清淨顆中明。"]', '["玄珠得了永無爭，不出丹元結實成。","因轉淘澄輪似月，尋常清淨顆中明。"]', '诗', 'shi', '', NULL, '玄珠歌 二十五 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa1219c-8cf7-4d3f-ad32-630c48201319', '玄珠歌 二十六', '玄珠歌 二十六', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠失却落坵墟，流浪輪迴錯卷舒。","魂魄若凝如日月，體同天地合清虛。"]', '["玄珠失却落坵墟，流浪輪迴錯卷舒。","魂魄若凝如日月，體同天地合清虛。"]', '诗', 'shi', '', NULL, '玄珠歌 二十六 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37645389-2acf-4894-86a5-ac757c58f249', '玄珠歌 二十七', '玄珠歌 二十七', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["玄珠結魄一時冲，送入瓊樓最上宮。","恰似蟾光能出沒，自然輕舉入雲中。"]', '["玄珠結魄一时冲，送入瓊楼最上宮。","恰似蟾光能出沒，自然轻舉入云中。"]', '诗', 'shi', '', NULL, '玄珠歌 二十七 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f91fbdd-5168-4499-9f5b-58cd4dfea51c', '玄珠歌 二十八', '玄珠歌 二十八', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["從前搬運幾多人，只把凡形頓出塵。","千萬天仙行此術，玄珠照耀一元真。"]', '["從前搬運幾多人，只把凡形頓出塵。","千万天仙行此術，玄珠照耀一元真。"]', '诗', 'shi', '', NULL, '玄珠歌 二十八 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24dc1e9f-5cfd-46a1-a897-24e48a904d21', '玄珠歌 二十九', '玄珠歌 二十九', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["因師指動日光隨，解把玄珠化羽衣。","功滿得成天上道，未登雲路沒人知。","。"]', '["因師指动日光隨，解把玄珠化羽衣。","功满得成天上道，未登云路沒人知。","。"]', '诗', 'shi', '', NULL, '玄珠歌 二十九 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('754abb77-7eec-4309-9857-161afe0f231f', '玄珠歌 三十', '玄珠歌 三十', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["逍遙著述顯虛無，不出身田指道軀。","內秘分爲上中下，尋蹤盡道得玄珠。","（按：《崇文總目》卷四著錄《玄珠歌》一卷，不題撰人。","《通志·藝文略》署通玄先生。","）。"]', '["逍遙著述显虛無，不出身田指道軀。","內秘分爲上中下，尋蹤尽道得玄珠。","（按：《崇文總目》卷四著錄《玄珠歌》一卷，不題撰人。","《通志·藝文略》署通玄先生。","）。"]', '诗', 'shi', '', NULL, '玄珠歌 三十 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d095784c-3e83-4641-acea-8749da8ae884', '金虎白龍詩 一', '金虎白龙诗 一', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["鉛汞傳法百萬秋，幾人認得幾人修。","若教世上知靈藥，天上神仙似水流。"]', '["鉛汞傳法百万秋，幾人認得幾人修。","若教世上知靈藥，天上神仙似水流。"]', '诗', 'shi', '', NULL, '金虎白龍詩 一 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51312f1-006c-4db1-b10f-bd4abeeb9121', '金虎白龍詩 二', '金虎白龙诗 二', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["大道分明在目前，時人不會謾求鉛。","黃芽本是乾坤氣，神水根基與汞連。"]', '["大道分明在目前，时人不會謾求鉛。","黄芽本是乾坤氣，神水根基與汞連。"]', '诗', 'shi', '', NULL, '金虎白龍詩 二 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2c649c-2fa2-4803-ae7e-1b263a952dd8', '金虎白龍詩 三', '金虎白龙诗 三', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["姹女初生醉似泥，千朝暗室不東西。","虔心日夜勤調火，莫遣靈丹氣不齊。"]', '["姹女初生醉似泥，千朝暗室不东西。","虔心日夜勤調火，莫遣靈丹氣不齊。"]', '诗', 'shi', '', NULL, '金虎白龍詩 三 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce2f31ee-2687-4a1e-9fb9-514bd6b5bcaa', '金虎白龍詩 四', '金虎白龙诗 四', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["天地初生日月高，狀如雞子狀如桃。","陰陽真氣知時節，直待三年始脫胞。"]', '["天地初生日月高，狀如雞子狀如桃。","陰陽真氣知时節，直待三年始脫胞。"]', '诗', 'shi', '', NULL, '金虎白龍詩 四 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a8f807-6dd6-4173-91a0-ee4bc0397671', '金虎白龍詩 五', '金虎白龙诗 五', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["世人何處覓黃芽，此物鉛中是我家。","鉛汞共成真地氣，脫胞方始見靈砂。"]', '["世人何处覓黄芽，此物鉛中是我家。","鉛汞共成真地氣，脫胞方始见靈砂。"]', '诗', 'shi', '', NULL, '金虎白龍詩 五 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac0f20d-f663-431b-b83e-50801cf2ae46', '金虎白龍詩 六', '金虎白龙诗 六', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["滿世黃芽人不識，識得黃芽家不貧。","黃芽豈使世人識，縱識黃芽不得門。"]', '["满世黄芽人不識，識得黄芽家不貧。","黄芽豈使世人識，縱識黄芽不得门。"]', '诗', 'shi', '', NULL, '金虎白龍詩 六 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ac7b0d-2d08-44ed-8831-f0c54a53106a', '金虎白龍詩 七', '金虎白龙诗 七', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["二氣丹砂不足靈，真成真氣用黃輕。","鉛中有物丹中汞，人自迷津落路行。"]', '["二氣丹砂不足靈，真成真氣用黄轻。","鉛中有物丹中汞，人自迷津落路行。"]', '诗', 'shi', '', NULL, '金虎白龍詩 七 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db75f3e-41af-414a-ad44-80b40a890e01', '金虎白龍詩 八', '金虎白龙诗 八', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["合於天地合於玄，子母相幷不敢言。","先汞後鉛真大道，莫教失伴鶴歸天。"]', '["合於天地合於玄，子母相幷不敢言。","先汞後鉛真大道，莫教失伴鹤归天。"]', '诗', 'shi', '', NULL, '金虎白龍詩 八 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('589b0f54-9d61-4693-a021-fee589d5a92a', '金虎白龍詩 九', '金虎白龙诗 九', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["此物從分二八傳，吉年吉月入爐安。","千朝火候知時節，莫遣芽成汞不乾。"]', '["此物從分二八傳，吉年吉月入爐安。","千朝火候知时節，莫遣芽成汞不乾。"]', '诗', 'shi', '', NULL, '金虎白龍詩 九 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f75d10-50f0-4687-92a6-435cd1e31292', '金虎白龍詩 十', '金虎白龙诗 十', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["汞在中宮芽在南，先須斟酌莫教參。","黃芽不是難求藥，人自無知口不緘。"]', '["汞在中宮芽在南，先須斟酌莫教參。","黄芽不是难求藥，人自無知口不緘。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf66a949-9527-4e4b-bf8c-8937158470d6', '金虎白龍詩 十一', '金虎白龙诗 十一', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["滿市黃芽無不歸，世人輕宴治塵微。","公卿盡識真靈藥，至死貪婪鬬曉暉。"]', '["满市黄芽無不归，世人轻宴治塵微。","公卿尽識真靈藥，至死貪婪鬬晓暉。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十一 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e999eb-3474-46dd-b232-e16f2f78c518', '金虎白龍詩 十二', '金虎白龙诗 十二', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["日月延人人自忙，分明真道不窮陽。","家家盡有鉛和汞，使得迷人人渺茫。"]', '["日月延人人自忙，分明真道不窮陽。","家家尽有鉛和汞，使得迷人人渺茫。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十二 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce71b3de-248d-4e97-96aa-13399606b499', '金虎白龍詩 十三', '金虎白龙诗 十三', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["明明五運自推尋，汞中鉛中理最深。","鉛汞既知人世有，堅須窮道莫沉吟。","。"]', '["明明五運自推尋，汞中鉛中理最深。","鉛汞既知人世有，堅須窮道莫沉吟。","。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十三 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa90b2ca-ab8e-4763-9eb0-7e0fcf190768', '金虎白龍詩 十四', '金虎白龙诗 十四', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["大道遺留一卷經，自然匹配作儀形。","天生鉛汞人間有，何得他州問藥名。"]', '["大道遺留一卷經，自然匹配作儀形。","天生鉛汞人间有，何得他州问藥名。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十四 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d1dbc2c-8272-426d-b02a-62c6b4e92b09', '金虎白龍詩 十五', '金虎白龙诗 十五', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["用鉛須得汞相和，二姓爲親女唱歌。","鍊到紫河車半地，白雲相伴鶴回過。"]', '["用鉛須得汞相和，二姓爲親女唱歌。","鍊到紫河车半地，白云相伴鹤回過。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十五 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f79bc3-6569-49a4-8131-f36337dbf828', '金虎白龍詩 十六', '金虎白龙诗 十六', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["甲乙神驅造化圖，潛龍知是好鉛酥。","分明制出何難會，却道仙家謎語浮。"]', '["甲乙神驱造化圖，潛龙知是好鉛酥。","分明制出何难會，却道仙家謎語浮。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十六 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1681932-69de-4a7d-a29f-5d70ff5bf00b', '金虎白龍詩 十七', '金虎白龙诗 十七', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["青龍白虎合爲胎，十月爐中滿始開。","此是黃芽親口訣，世人何處覓三才。"]', '["青龙白虎合爲胎，十月爐中满始开。","此是黄芽親口訣，世人何处覓三才。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十七 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06cd9e6-d87d-47e0-af8d-5e176164e8f4', '金虎白龍詩 十八', '金虎白龙诗 十八', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["鉛汞居乾不在山，三關晝夜好追攀。","少年縱却疎狂性，漸覺尫羸作鬼顏。"]', '["鉛汞居乾不在山，三关晝夜好追攀。","少年縱却疎狂性，漸覺尫羸作鬼顏。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十八 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01d4f5e-0f91-446a-bdd7-c744744c4799', '金虎白龍詩 十九', '金虎白龙诗 十九', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["道須心向北方窮，黃芽生長在鉛中。","丹砂姹女真靈藥，得伴相將去大蓬。"]', '["道須心向北方窮，黄芽生长在鉛中。","丹砂姹女真靈藥，得伴相將去大蓬。"]', '诗', 'shi', '', NULL, '金虎白龍詩 十九 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a53572-74c1-46de-bfec-708c39f42c27', '金虎白龍詩 二十', '金虎白龙诗 二十', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["大道從來不負人，分明鉛汞棄如塵。","莫言世上無靈藥，二氣丹砂水火真。"]', '["大道從来不負人，分明鉛汞棄如塵。","莫言世上無靈藥，二氣丹砂水火真。"]', '诗', 'shi', '', NULL, '金虎白龍詩 二十 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f73419-56cf-4a14-adc3-99e07cc35a8f', '金虎白龍詩 二十一', '金虎白龙诗 二十一', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["此物天生人不知，陰陽真氣兌爲離。","坎宮五世求名姓，認得黃芽作聖基。","（《正統道藏》本宋佚名《內丹秘訣》引）（按：《通志·藝文略》道類收張果〖通玄先生〗《玄珠歌逍遙歌內指黃芽歌》一卷。","《玄珠歌》已見前錄。","本組詩多述黃芽，疑即《內指黃芽歌》。","）。"]', '["此物天生人不知，陰陽真氣兌爲離。","坎宮五世求名姓，認得黄芽作聖基。","（《正統道藏》本宋佚名《內丹秘訣》引）（按：《通志·藝文略》道類收張果〖通玄先生〗《玄珠歌逍遙歌內指黄芽歌》一卷。","《玄珠歌》已见前錄。","本組诗多述黄芽，疑即《內指黄芽歌》。","）。"]', '诗', 'shi', '', NULL, '金虎白龍詩 二十一 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da38e9c-ef5e-43cd-8732-f13d535aa566', '五子守仙丸歌', '五子守仙丸歌', 'f029bee1-d418-48c0-90e5-795fa49301d2', '唐', '["返老成少是還丹，不得守仙亦大難。","愁見鬢斑令却黑，一日但服三十丸。","松竹本自無艷色，金液因從火制乾。","五子可定千秋旨，百歲如同一萬年。","（《正統道藏》本《懸解錄》。","又《雲笈七籤》卷六四）（按：《懸解錄》卷首有唐大中九年序。","據《新唐書·藝文志》、《通志·藝文略》，並參陳國符先生所考，此序爲紇干臮作。","）。"]', '["返老成少是還丹，不得守仙亦大难。","愁见鬢斑令却黑，一日但服三十丸。","松竹本自無艷色，金液因從火制乾。","五子可定千秋旨，百歲如同一万年。","（《正統道藏》本《懸解錄》。","又《云笈七籤》卷六四）（按：《懸解錄》卷首有唐大中九年序。","據《新唐书·藝文志》、《通志·藝文略》，並參陳国符先生所考，此序爲紇干臮作。","）。"]', '诗', 'shi', '', NULL, '五子守仙丸歌 張果 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079f5388-cbfb-4fa0-9a21-2aa7847ef468', '還丹口訣', '還丹口訣', '0841913a-32d9-4757-be11-79b42325a1ee', '唐', '["水中鉛，火裏鉛，水火二鉛同一原，不知咫尺是神仙。","敬將朱砂酒醋煎，千千萬萬化爲煙。","假如伏火只成頑，欲得人間作地仙。","煉取五行四象全，陰功濟世真上天。","（後蜀無名氏《大還丹照鑑》）。"]', '["水中鉛，火裏鉛，水火二鉛同一原，不知咫尺是神仙。","敬將朱砂酒醋煎，千千万万化爲煙。","假如伏火只成頑，欲得人间作地仙。","煉取五行四象全，陰功濟世真上天。","（後蜀無名氏《大還丹照鑑》）。"]', '诗', 'shi', '', NULL, '還丹口訣 白履忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d14d0f-b466-4d50-b0d7-64a60bb98e7f', '太上昇玄消災護命妙經頌', '太上昇玄消災護命妙經頌', '5897b472-f68f-49c0-b167-aeb689d55cde', '唐', '["太上本來真，虛無中有神。","若能心解悟，身外更無身。","假名元始號，元始虛無老。","心源是元始，更無無上道。","七寶爲林苑，五明宮殿寬。","人身皆備有，不解向心觀。","三世諸天聖，相因一性宗。","一身無萬法，萬法一身同。","放出光明照，無央世界中。","乾坤明表裏，日月覺朦朧。","妙觀無靜苦，自性不能知。","妄想隨緣去，何時有出期。","生滅何時盡，相因浩劫來。","似環螻蟻轉，如轂碾塵埃。","誰言河海闊，深淺尚能知。","愛欲情無底，何年有出時？","水鳥及風林，咸歸一法音。","如何顛倒性，自起萬般心。","虛無含有象，有象復歸無。","心若分明了，知權呼有無。","無空空不空，無色色不色。","若能知色空，色空皆自得。","有有兼無有，無無及有無。","虛心能不動，妙道自來居。","如人入黑暗，目覩又何曾。","若要分明見，須憑浩劫燈。","有相兼無相，迷惑終不知。","未能明覺性，安得決狐疑。","衆生情行劣，迷失道根源。","特謂宣宗旨，教令入妙門。","物向無中有，道從有裏無。","莫生無有見，迷執自消除。","空色互相生，相纏如糾墨。","要知空色理，自莫分空色。","道性本虛無，虛無亦假呼。","若生無有見，終被法來拘。","不空是真空，不色是真色。","空色便爲真，真法何曾得？","是空及是色，究竟總非干。","要認真空色，迴心向己難。","空色宜雙泯，不須舉一隅。","色空無滯礙，本性自如如。","妙音喻虛性，虛心非妙音。","認他毫髮事，難得[自]（目）由心。","一心觀一切，一切法皆同。","若能如斯解，方明智慧通。","了悟性根源，名爲入妙門方便法，是法勿留存。","決破疑惑網，有無都不干。","正心長自在，如[隼]（準）入雲盤。","心靜六根清，六根隨性行。","性能無著物，邪障那邊生。","妙經無礙性，權立妙經名。","故爲衆生說，令教悟此經。","一真度一切，如檝濟橫流。","真性隨身有，勿於身外求。","傳教虛無理，世間散布行。","誦經能萬遍，其義自分明。","真性號神王，飛天無定方。","破邪能自外，堅固喻金剛。","靈童即正性，無染號真人。","威猛喻師子，名殊一法身。","諸天諸聖衆，無一亦無二。","性不遂波流，是名真侍衛。","語默及遊息，無生一念思。","忘形歸恍惚，神鬼不能窺。","正法度邪法，衆生見處偏。","若生無有見，即被染心田。","天尊重說偈，直爲指心源。","汲引迷惑者，令歸解脫門。","道非干視聽，視聽轉生疑。","應物臨機用，虛心即可知。","心疑隨萬境，隨境認心田。","道非有爲有，方名離種邊。","（《正統道藏》鳥字號）。"]', '["太上本来真，虛無中有神。","若能心解悟，身外更無身。","假名元始號，元始虛無老。","心源是元始，更無無上道。","七寶爲林苑，五明宮殿寬。","人身皆備有，不解向心观。","三世諸天聖，相因一性宗。","一身無万法，万法一身同。","放出光明照，無央世界中。","乾坤明表裏，日月覺朦朧。","妙观無静苦，自性不能知。","妄想隨緣去，何时有出期。","生滅何时尽，相因浩劫来。","似环螻蟻轉，如轂碾塵埃。","誰言河海闊，深淺尚能知。","愛欲情無底，何年有出时？","水鸟及风林，咸归一法音。","如何顛倒性，自起万般心。","虛無含有象，有象复归無。","心若分明了，知權呼有無。","無空空不空，無色色不色。","若能知色空，色空皆自得。","有有兼無有，無無及有無。","虛心能不动，妙道自来居。","如人入黑暗，目覩又何曾。","若要分明见，須憑浩劫灯。","有相兼無相，迷惑終不知。","未能明覺性，安得決狐疑。","衆生情行劣，迷失道根源。","特謂宣宗旨，教令入妙门。","物向無中有，道從有裏無。","莫生無有见，迷執自消除。","空色互相生，相纏如糾墨。","要知空色理，自莫分空色。","道性本虛無，虛無亦假呼。","若生無有见，終被法来拘。","不空是真空，不色是真色。","空色便爲真，真法何曾得？","是空及是色，究竟總非干。","要認真空色，迴心向己难。","空色宜雙泯，不須舉一隅。","色空無滯礙，本性自如如。","妙音喻虛性，虛心非妙音。","認他毫髮事，难得[自]（目）由心。","一心观一切，一切法皆同。","若能如斯解，方明智慧通。","了悟性根源，名爲入妙门方便法，是法勿留存。","決破疑惑網，有無都不干。","正心长自在，如[隼]（準）入云盤。","心静六根清，六根隨性行。","性能無著物，邪障那邊生。","妙經無礙性，權立妙經名。","故爲衆生说，令教悟此經。","一真度一切，如檝濟橫流。","真性隨身有，勿於身外求。","傳教虛無理，世间散布行。","誦經能万遍，其義自分明。","真性號神王，飞天無定方。","破邪能自外，堅固喻金剛。","靈童即正性，無染號真人。","威猛喻師子，名殊一法身。","諸天諸聖衆，無一亦無二。","性不遂波流，是名真侍衛。","語默及游息，無生一念思。","忘形归恍惚，神鬼不能窺。","正法度邪法，衆生见处偏。","若生無有见，即被染心田。","天尊重说偈，直爲指心源。","汲引迷惑者，令归解脫门。","道非干視听，視听轉生疑。","應物臨機用，虛心即可知。","心疑隨万境，隨境認心田。","道非有爲有，方名離種邊。","（《正統道藏》鸟字號）。"]', '诗', 'shi', '', NULL, '太上昇玄消災護命妙經頌 司馬承禎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eba1377-e5dc-49fd-8abf-8e89c38671cb', '丹元子步天歌 東方七宿 一', '丹元子步天歌 东方七宿 一', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["角，兩星南北正直著，中有平道上天田，總是黑星兩相連，別有一烏名進賢。","平道右畔獨淵然，最上三星周鼎形，角下天門左平星，雙雙橫於庫樓上，庫樓十星屈曲明。","樓中五柱十五星，三三相著如鼎形。","其中四星別名衡，南門樓外兩星橫。"]', '["角，兩星南北正直著，中有平道上天田，總是黑星兩相連，別有一烏名進賢。","平道右畔独淵然，最上三星周鼎形，角下天门左平星，雙雙橫於庫楼上，庫楼十星屈曲明。","楼中五柱十五星，三三相著如鼎形。","其中四星別名衡，南门楼外兩星橫。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 一 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a983941b-6e9f-4af2-8a64-f78a555b21de', '丹元子步天歌 東方七宿 二', '丹元子步天歌 东方七宿 二', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["亢，四星恰如彎弓狀。","大角一星直上明，折威七子亢下橫。","大角左右攝提星，三三相似如鼎形。","折威下左頓頑星，兩箇斜安黃色精。","頑下二星號陽門，色若頓頑直下𨀛。"]', '["亢，四星恰如彎弓狀。","大角一星直上明，折威七子亢下橫。","大角左右攝提星，三三相似如鼎形。","折威下左頓頑星，兩箇斜安黄色精。","頑下二星號陽门，色若頓頑直下𨀛。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 二 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b353972b-9a0d-461b-a317-df88ace57fa4', '丹元子步天歌 東方七宿 三', '丹元子步天歌 东方七宿 三', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["氐，四星似斗側量米。","天乳氐上黑一星，世人不識稱無名。","一箇招搖梗河上，梗河橫列三星狀。","帝席三黑河之西，亢池六星近攝提。","氐下衆星騎官出，騎官之衆二十七。","三三相連十欠一，陣車氐下騎官次，騎官下三車騎位。","天輻兩星列陣傍，將軍陣裏振威霜。"]', '["氐，四星似斗側量米。","天乳氐上黑一星，世人不識稱無名。","一箇招搖梗河上，梗河橫列三星狀。","帝席三黑河之西，亢池六星近攝提。","氐下衆星騎官出，騎官之衆二十七。","三三相連十欠一，陣车氐下騎官次，騎官下三车騎位。","天輻兩星列陣傍，將軍陣裏振威霜。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 三 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249f849e-464f-43de-9910-63d7dc080725', '丹元子步天歌 東方七宿 四', '丹元子步天歌 东方七宿 四', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["房，四星直下主明堂。","鍵閉一黃斜向上，鉤鈴兩箇近其傍。","罸有三星植鍵上，兩咸夾罸似房狀。","房下一星號爲日，從官兩箇日下出。","。"]', '["房，四星直下主明堂。","鍵閉一黄斜向上，鉤鈴兩箇近其傍。","罸有三星植鍵上，兩咸夾罸似房狀。","房下一星號爲日，從官兩箇日下出。","。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 四 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d3fcf2-a18e-4261-b344-87ff7365d034', '丹元子步天歌 東方七宿 五', '丹元子步天歌 东方七宿 五', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["心，三星中央色最深。","下有種卒共十二，三三相聚心下是。"]', '["心，三星中央色最深。","下有種卒共十二，三三相聚心下是。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 五 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c207ad3-cd17-43bf-8078-f024656e94c2', '丹元子步天歌 東方七宿 六', '丹元子步天歌 东方七宿 六', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["尾，九星如鉤蒼龍尾。","下頭五點號龜星，尾上天江四橫是。","尾東一箇名傅說，傅說東畔一魚子。","龜西一室是神宮，所以列在后妃中。"]', '["尾，九星如鉤蒼龙尾。","下头五点號龟星，尾上天江四橫是。","尾东一箇名傅说，傅说东畔一鱼子。","龟西一室是神宮，所以列在后妃中。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 六 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e65447-ff94-4daf-b501-baf510436e6f', '丹元子步天歌 東方七宿 七', '丹元子步天歌 东方七宿 七', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["箕，四星形狀如簸箕。","箕下三星名木杵，箕前一黑是糠皮。"]', '["箕，四星形狀如簸箕。","箕下三星名木杵，箕前一黑是糠皮。"]', '诗', 'shi', '', NULL, '丹元子步天歌 東方七宿 七 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c169b304-9fec-4d87-974f-bd5eb260102d', '丹元子步天歌 北方七宿 一', '丹元子步天歌 北方七宿 一', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["斗，六星其狀似北斗。","魁上建星三相對，天弁建上三三九。","斗下圓安十四星，雖然名鼈貫索形。","天雞建背雙黑星，天籥柄前八黃精，狗國四方雞下生。","天淵十星鼈東邊，更有兩狗斗魁前，農家丈人狗下眠，天淵十黃狗色玄。"]', '["斗，六星其狀似北斗。","魁上建星三相对，天弁建上三三九。","斗下圓安十四星，雖然名鼈貫索形。","天雞建背雙黑星，天籥柄前八黄精，狗国四方雞下生。","天淵十星鼈东邊，更有兩狗斗魁前，農家丈人狗下眠，天淵十黄狗色玄。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 一 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('782dba3a-0369-42e8-8fb6-5d8fae590aa8', '丹元子步天歌 北方七宿 二', '丹元子步天歌 北方七宿 二', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["牛，六星近在河岸頭。","頭上雖然有兩角，腹下從來欠一脚。","牛下九黑是天田，田下三三九坎連。","牛上直建三河鼓，鼓上三星號織女。","左旗右旗各九星，河鼓兩畔右邊明。","更有四黃名天桴，河鼓直下如連珠，羅堰三烏牛東居。","漸臺四星似口形，輦道漸臺在何許，欲得見時近織女。"]', '["牛，六星近在河岸头。","头上雖然有兩角，腹下從来欠一脚。","牛下九黑是天田，田下三三九坎連。","牛上直建三河鼓，鼓上三星號织女。","左旗右旗各九星，河鼓兩畔右邊明。","更有四黄名天桴，河鼓直下如連珠，羅堰三烏牛东居。","漸台四星似口形，輦道漸台在何許，欲得见时近织女。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 二 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda76f77-ad50-4154-a315-8c5819869ee4', '丹元子步天歌 北方七宿 三', '丹元子步天歌 北方七宿 三', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["女，四星如箕主嫁娶。","十二諸國在下陳，先從越國向東論。","東西兩周次二秦，雍州南下雙鴈門。","代國向西一晉伸，韓魏各一晉北輪。","楚之一國魏西屯，楚城南畔獨燕軍。","燕西一郡是齊鄰，齊北兩邑平原君。","欲知鄭在越下存，十六黃星細區分。","五箇離珠女上星，敗瓜珠上瓠瓜生。","兩箇各五瓠瓜明，天津九箇彈弓形。","兩星入午河中橫，四箇奚仲天津上，七箇仲側扶筐星。"]', '["女，四星如箕主嫁娶。","十二諸国在下陳，先從越国向东論。","东西兩周次二秦，雍州南下雙鴈门。","代国向西一晉伸，韓魏各一晉北輪。","楚之一国魏西屯，楚城南畔独燕軍。","燕西一郡是齊鄰，齊北兩邑平原君。","欲知鄭在越下存，十六黄星細區分。","五箇離珠女上星，敗瓜珠上瓠瓜生。","兩箇各五瓠瓜明，天津九箇彈弓形。","兩星入午河中橫，四箇奚仲天津上，七箇仲側扶筐星。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 三 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c4add7-4f9e-4d44-b19b-8c9a675a28fb', '丹元子步天歌 北方七宿 四', '丹元子步天歌 北方七宿 四', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["虛，上下各一如連珠。","命祿危非虛上呈，虛危之下哭泣星。","哭泣雙雙下壘城，天壘團圓十三星，敗臼四星城下橫，臼西三箇離瑜明。"]', '["虛，上下各一如連珠。","命祿危非虛上呈，虛危之下哭泣星。","哭泣雙雙下壘城，天壘團圓十三星，敗臼四星城下橫，臼西三箇離瑜明。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 四 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a0506b-d02f-4c56-b055-f7b42c07b3d1', '丹元子步天歌 北方七宿 五', '丹元子步天歌 北方七宿 五', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["危，三星不直舊先知。","危上五黑號人星，人畔三五杵臼形。","人上七烏號車府，府上天鉤九黃晶。","鉤上五鵶字造父，危下四星號墳墓。","墓下四星斜虛梁，十箇天錢梁下黃。","墓傍兩星能蓋屋，身著黑衣危下宿。"]', '["危，三星不直旧先知。","危上五黑號人星，人畔三五杵臼形。","人上七烏號车府，府上天鉤九黄晶。","鉤上五鵶字造父，危下四星號墳墓。","墓下四星斜虛梁，十箇天錢梁下黄。","墓傍兩星能蓋屋，身著黑衣危下宿。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 五 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d114a2e-3a4b-45e2-aa3a-b566968bd787', '丹元子步天歌 北方七宿 六', '丹元子步天歌 北方七宿 六', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["室，兩星上有離宮出。","遶室三雙有六星，下頭六箇雷電形。","壘壁陳次十二星，十二兩頭大似升。","陣下分布羽林軍，四十五卒三爲羣。","壁西星多難論，子細歷歷看區分。","三粒黃金名鈇鉞，一顆真珠北落門。","門東八魁九箇子，門西一宿天綱是。","電傍兩星土功吏，騰蛇室上二十二。"]', '["室，兩星上有離宮出。","遶室三雙有六星，下头六箇雷電形。","壘壁陳次十二星，十二兩头大似升。","陣下分布羽林軍，四十五卒三爲羣。","壁西星多难論，子細歷歷看區分。","三粒黄金名鈇鉞，一顆真珠北落门。","门东八魁九箇子，门西一宿天綱是。","電傍兩星土功吏，腾蛇室上二十二。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 六 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5008b98-f4d1-4c33-822c-d61e8fbef4d1', '丹元子步天歌 北方七宿 七', '丹元子步天歌 北方七宿 七', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["壁，兩星下頭是霹靂。","霹靂五星橫著行，雲雨次之口四方。","壁上天廐十圓黃，鈇鑕五星羽林傍。"]', '["壁，兩星下头是霹靂。","霹靂五星橫著行，云雨次之口四方。","壁上天廐十圓黄，鈇鑕五星羽林傍。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北方七宿 七 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fba944-7621-4402-88a2-d5a350ad9e5d', '丹元子步天歌 西方七宿 一', '丹元子步天歌 西方七宿 一', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["奎，腰細頭尖似破鞋。","一十六星遶鞋生，外屏七烏奎下橫。","屏下七星天溷明，司空左畔土之精。","奎上一宿軍南門，河中六箇閣道形。","附路一星傍道明，五箇吐花王良星，良星近上一策名。"]', '["奎，腰細头尖似破鞋。","一十六星遶鞋生，外屏七烏奎下橫。","屏下七星天溷明，司空左畔土之精。","奎上一宿軍南门，河中六箇閣道形。","附路一星傍道明，五箇吐花王良星，良星近上一策名。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 一 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22dc46be-b801-4fce-ba40-d93705b6ed2e', '丹元子步天歌 西方七宿 二', '丹元子步天歌 西方七宿 二', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["婁，三星不勻近一頭。","左更右更烏夾婁，天倉六箇婁下頭。","天庾四星倉東脚，婁上十一將軍侯。"]', '["婁，三星不勻近一头。","左更右更烏夾婁，天倉六箇婁下头。","天庾四星倉东脚，婁上十一將軍侯。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 二 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e349590-cf70-4f0a-b95b-8433ed8501fa', '丹元子步天歌 西方七宿 三', '丹元子步天歌 西方七宿 三', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["胃，三星鼎足河之次。","天廩胃下斜四星，天囷十三如乙形。","河中八星名太陵，陵北九箇天船名。","陵中積屍一箇星，積水船中一黑精。"]', '["胃，三星鼎足河之次。","天廩胃下斜四星，天囷十三如乙形。","河中八星名太陵，陵北九箇天船名。","陵中積屍一箇星，積水船中一黑精。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 三 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df4005fa-4587-40f2-af74-7121c0b92fc5', '丹元子步天歌 西方七宿 四', '丹元子步天歌 西方七宿 四', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["昴，七星一聚實不少。","阿西月東各一星，月下五黃天陰名。","陰下六烏芻藁營，營南十六天苑形。","河裏六星名卷舌，舌中黑點天讒星，礪石舌傍斜四丁。","。"]', '["昴，七星一聚實不少。","阿西月东各一星，月下五黄天陰名。","陰下六烏芻藁營，營南十六天苑形。","河裏六星名卷舌，舌中黑点天讒星，礪石舌傍斜四丁。","。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 四 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07523a08-7031-4bc4-a72e-8e9eb9c68ce0', '丹元子步天歌 西方七宿 五', '丹元子步天歌 西方七宿 五', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["畢，恰似爪叉八星出。","附耳畢股一星光，天街兩星畢背傍。","天節耳下八烏幢，畢下橫列六諸王。","王下四皂天高星，節下團圓九州城。","畢口斜對五車口，車有三柱任縱橫。","車中五箇天潢精，潢畔咸池三黑星。","天關一星車脚邊，參旗九箇參車間，旗下直建九斿連，斿下十三烏天園，九斿天園參脚邊。"]', '["畢，恰似爪叉八星出。","附耳畢股一星光，天街兩星畢背傍。","天節耳下八烏幢，畢下橫列六諸王。","王下四皂天高星，節下團圓九州城。","畢口斜对五车口，车有三柱任縱橫。","车中五箇天潢精，潢畔咸池三黑星。","天关一星车脚邊，參旗九箇參车间，旗下直建九斿連，斿下十三烏天园，九斿天园參脚邊。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 五 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5051224a-504a-42ab-9aff-d0d2885afd34', '丹元子步天歌 西方七宿 六', '丹元子步天歌 西方七宿 六', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["觜，三星相近作參蘂。","觜上坐旗真指天，尊卑之位九相連。","司怪曲立坐旗邊，四鵶大近井鉞前。"]', '["觜，三星相近作參蘂。","觜上坐旗真指天，尊卑之位九相連。","司怪曲立坐旗邊，四鵶大近井鉞前。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 六 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1b0e2b-5a02-45dd-8a8c-ea8369defa07', '丹元子步天歌 西方七宿 七', '丹元子步天歌 西方七宿 七', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["參，總有十星觜相侵。","兩肩䨥足三爲心，伐有三星足裏深。","玉井四星右足陰，屏星兩扇井南襟。","軍井四星屏上吟，左足下四天厠臨，厠下一物天屎沉。"]', '["參，總有十星觜相侵。","兩肩䨥足三爲心，伐有三星足裏深。","玉井四星右足陰，屏星兩扇井南襟。","軍井四星屏上吟，左足下四天厠臨，厠下一物天屎沉。"]', '诗', 'shi', '', NULL, '丹元子步天歌 西方七宿 七 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('845d2af9-ff3d-4dcd-93fb-c449889f7551', '丹元子步天歌 南方七宿 一', '丹元子步天歌 南方七宿 一', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["井，八星橫列河中淨。","一星名鉞井邊安，兩河各三南北正。","天樽三星井上頭，樽上橫列五諸侯。","侯上北河西積水，欲覓積薪東畔是。","鉞下四星名水府，水位東邊四星序。","四瀆橫列南河裏，南河下頭是軍市。","軍市團圓十三星，中有一個野雞精。","孫子丈人市下列，各立兩星從東說。","闕丘二箇南河東，丘下一狼光蒙茸。","左畔九箇彎弧弓，一矢擬射頑狼胸。","有箇老人南極中，春秋出入壽無窮。"]', '["井，八星橫列河中淨。","一星名鉞井邊安，兩河各三南北正。","天樽三星井上头，樽上橫列五諸侯。","侯上北河西積水，欲覓積薪东畔是。","鉞下四星名水府，水位东邊四星序。","四瀆橫列南河裏，南河下头是軍市。","軍市團圓十三星，中有一個野雞精。","孫子丈人市下列，各立兩星從东说。","闕丘二箇南河东，丘下一狼光蒙茸。","左畔九箇彎弧弓，一矢擬射頑狼胸。","有箇老人南極中，春秋出入壽無窮。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 一 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e0491e-036e-40d6-b254-536ac26b932d', '丹元子步天歌 南方七宿 二', '丹元子步天歌 南方七宿 二', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["鬼，四星冊方似木櫃。","中央白者積尸氣，鬼上四星是爟位。","天狗七星鬼下是，外廚六間柳是次。","天社六箇弧東倚，社東一星是天紀。"]', '["鬼，四星冊方似木櫃。","中央白者積尸氣，鬼上四星是爟位。","天狗七星鬼下是，外廚六间柳是次。","天社六箇弧东倚，社东一星是天紀。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 二 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56799022-e80c-47b3-b4ba-5bff85fcc8e3', '丹元子步天歌 南方七宿 三', '丹元子步天歌 南方七宿 三', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["柳，八星曲頭垂似柳。","近上三星號爲酒，享宴大酺五星守。"]', '["柳，八星曲头垂似柳。","近上三星號爲酒，享宴大酺五星守。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 三 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('880f39ad-4280-4e57-879a-35e1781ed744', '丹元子步天歌 南方七宿 四', '丹元子步天歌 南方七宿 四', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["星，七星如鉤柳下生。","星上十七軒轅形，軒轅東頭四內平。","平下三箇名天相，相下稷星橫五靈。"]', '["星，七星如鉤柳下生。","星上十七軒轅形，軒轅东头四內平。","平下三箇名天相，相下稷星橫五靈。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 四 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33e6aeda-39f5-46b0-895d-9caee82a283f', '丹元子步天歌 南方七宿 五', '丹元子步天歌 南方七宿 五', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["張，六星似軫在星傍。","張下只是有天廟，十四之星冊四方。","長垣少微雖向上，星數歌在太微傍，天尊一星直上黃。"]', '["張，六星似軫在星傍。","張下只是有天廟，十四之星冊四方。","长垣少微雖向上，星數歌在太微傍，天尊一星直上黄。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 五 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad0d2993-cd3d-4b5c-8af6-874ead3bf151', '丹元子步天歌 南方七宿 六', '丹元子步天歌 南方七宿 六', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["翼，二十二星大難識。","上五下五橫著行，中心六箇恰如張。","更有六星在何許？三三相連張畔附。","必若不能分處所，更請向前看野取。","五箇黑星翼下頭。","欲知名字是東甌。"]', '["翼，二十二星大难識。","上五下五橫著行，中心六箇恰如張。","更有六星在何許？三三相連張畔附。","必若不能分处所，更請向前看野取。","五箇黑星翼下头。","欲知名字是东甌。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 六 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb0b672-f00c-42bf-ba4a-b8428f5c8544', '丹元子步天歌 南方七宿 七', '丹元子步天歌 南方七宿 七', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["軫，四星似張翼相近，中央一箇長沙子。","左轄附兩星，軍門兩黃近翼是。","門下四箇主司空，門東七烏青丘子。","青丘之下名器府，器府之星三十二。","以上便爲太微宮，黃道向上看取是。","（以上二十八首均錄自鄭樵《通志》卷三八《天文略》第一）。"]', '["軫，四星似張翼相近，中央一箇长沙子。","左轄附兩星，軍门兩黄近翼是。","门下四箇主司空，门东七烏青丘子。","青丘之下名器府，器府之星三十二。","以上便爲太微宮，黄道向上看取是。","（以上二十八首均錄自鄭樵《通志》卷三八《天文略》第一）。"]', '诗', 'shi', '', NULL, '丹元子步天歌 南方七宿 七 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaaa4691-592b-46cf-acfc-cc75101e2ff2', '丹元子步天歌 太微宮', '丹元子步天歌 太微宮', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["上元太微宮，昭昭列象布蒼穹。","端門只是門之中，左右執法門西東。","門左皂衣一謁者，以次即是烏三公。","三黑九卿公背傍，五黑諸侯卿後行。","四箇門西主軒屏，五帝內坐於中正。","幸臣太子幷從官，烏列帝后從東定。","郎將虎賁居左右，常陳郎位居其後。","常陳七星不相誤，郎位陳東一十五。","兩面宮垣十星布，左右執法是其數。","宮外明堂布政宮，三箇靈臺候雲雨。","少微四星西南隅，長垣䨥䨥微西居。","北門西外接三台，與垣相對無兵災。"]', '["上元太微宮，昭昭列象布蒼穹。","端门只是门之中，左右執法门西东。","门左皂衣一謁者，以次即是烏三公。","三黑九卿公背傍，五黑諸侯卿後行。","四箇门西主軒屏，五帝內坐於中正。","幸臣太子幷從官，烏列帝后從东定。","郎將虎賁居左右，常陳郎位居其後。","常陳七星不相誤，郎位陳东一十五。","兩面宮垣十星布，左右執法是其數。","宮外明堂布政宮，三箇靈台候云雨。","少微四星西南隅，长垣䨥䨥微西居。","北门西外接三台，與垣相对無兵災。"]', '诗', 'shi', '', NULL, '丹元子步天歌 太微宮 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67acb0dc-0696-4176-8f49-7fca2c1030bc', '丹元子步天歌 北極紫微宮', '丹元子步天歌 北極紫微宮', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["中元北極紫微宮，北極五星在其中。","大帝之坐第二珠，第三之星庶子居。","第一號曰爲太子，四爲后宮五天樞。","（一云：「第三明者帝之居，第四名曰四庶子，最小第五天之樞。","」）左右四星是四輔，天一太一當門路。","左樞右樞夾南門，兩面營衛一十五。","上宰少尉兩相對，少宰上輔次少輔。","上衛少衛次上丞，後門東邊大贊府。","門西喚作一少丞，以次却向前門數。","陰德門裏兩黃聚，尚書以次其位五。","女史柱史各一戶，御女四星五天柱。","大理兩星陰德邊，勾陳尾指北極顛，勾陳六星六甲前。","天皇獨在勾陳裏，五帝內坐後門是。","華蓋幷杠十六星，杠作柄象蓋傘形。","蓋上連連九箇星，名曰傳舍如連丁。","垣外左右各六珠，右是內階左天廚。","階前八星名八穀，廚下五箇天棓宿。","天牀六星左樞在，內廚相星右樞對。","文昌斗上半月形，希疎分明六箇星。","文昌之下曰三公，太尊只向三公明。","天牢六星太尊邊，太陽之守四勢前。","一箇宰相太陽側，更有三公相西偏，即是玄戈一星圓。","天理四星斗裏暗，輔星近著開陽淡。","（一本云：「文昌之下三師名，天牢六星四勢前。","更有三公相西偏，即是太陽一星圓。","天理四星斗裏暗，輔星近著闓陽淡。","」）北斗之宿七星明，第一主帝名樞精，第二第三璇璣星，第四名權第五衡，闓陽搖光六七名。"]', '["中元北極紫微宮，北極五星在其中。","大帝之坐第二珠，第三之星庶子居。","第一號曰爲太子，四爲后宮五天樞。","（一云：「第三明者帝之居，第四名曰四庶子，最小第五天之樞。","」）左右四星是四輔，天一太一當门路。","左樞右樞夾南门，兩面營衛一十五。","上宰少尉兩相对，少宰上輔次少輔。","上衛少衛次上丞，後门东邊大贊府。","门西喚作一少丞，以次却向前门數。","陰德门裏兩黄聚，尚书以次其位五。","女史柱史各一戶，御女四星五天柱。","大理兩星陰德邊，勾陳尾指北極顛，勾陳六星六甲前。","天皇独在勾陳裏，五帝內坐後门是。","华蓋幷杠十六星，杠作柄象蓋傘形。","蓋上連連九箇星，名曰傳舍如連丁。","垣外左右各六珠，右是內階左天廚。","階前八星名八穀，廚下五箇天棓宿。","天牀六星左樞在，內廚相星右樞对。","文昌斗上半月形，希疎分明六箇星。","文昌之下曰三公，太尊只向三公明。","天牢六星太尊邊，太陽之守四勢前。","一箇宰相太陽側，更有三公相西偏，即是玄戈一星圓。","天理四星斗裏暗，輔星近著开陽淡。","（一本云：「文昌之下三師名，天牢六星四勢前。","更有三公相西偏，即是太陽一星圓。","天理四星斗裏暗，輔星近著闓陽淡。","」）北斗之宿七星明，第一主帝名樞精，第二第三璇璣星，第四名權第五衡，闓陽搖光六七名。"]', '诗', 'shi', '', NULL, '丹元子步天歌 北極紫微宮 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ec2551-0b54-4a21-838e-6b8f070144df', '丹元子步天歌 天市垣', '丹元子步天歌 天市垣', 'f11954c0-8742-40e3-95b2-34e958a73ada', '唐', '["下垣一宮名天市，兩扇垣牆二十二。","當門六角黑市樓，門左兩星是車肆。","兩箇宗正四宗人，宗星一䨥亦依次。","帛度兩星屠肆前，候星還在帝坐邊。","帝坐一星常光明，四箇微茫宦者星。","以次兩星名列肆，斗斛帝前依其次，斗是五星斛是四。","垣北九箇貫索星，索口橫者七公成。","天紀恰似七公形，數著分明多兩星。","紀北三星名女牀，此坐還依織女傍。","三元之象無相侵，二十八宿隨其陰。","水火土木幷與金，以次別有五行分。","（以上三首錄《通志》卷三九《天文略》第二）（按：〖1〗《崇文總目》輯本卷四《天文占書類》有「《丹元子步天歌》一卷，王希明撰」。","〖2〗《新唐書·藝文志》「天文類」云：「王希明《丹元步天歌》一卷。","」）（〖3〗黃伯思《東觀餘論》卷下《校正〈崇文總目〉十七條》云：「《丹元子步天歌》，此但記列星所在，並其象數，使人易識耳，非占說也。","」〖4〗鄭樵《通志·天文略》云：「隋有丹元子者，隱者之流也。","不知名氏，作《步天歌》，見者可以觀象焉。","王希明纂漢晉志以釋之，《唐書》誤以爲王希明也。","……此本只傳靈臺，不傳人間，術家秘之，名曰《鬼料竅》。","世有數本，不勝其訛，今則取之，仰觀以從稽定。","」〖5〗晁公武《郡齋讀書志》〖袁本〗卷三上錄《步天歌》一卷：「右未詳撰人。","二十八宿地歌也。","三垣頌、五星凌犯賦於後。","或云唐王希明，自號丹元子。","」〖6〗王應麟《困學紀聞》卷九《天道》云：「《步天歌》，《唐志》謂王希明丹元子。","今本司天右拾遺內供奉王希明撰，喬令來注。","二十八宿歌、三垣頌，五行吟，總爲一卷。","」次引鄭樵之說，末謂「然則王希明丹元子蓋二人也」。","〖7〗錢大昕《十駕齋養新錄》卷十四云：「《丹元子步天歌》，不著撰人姓名。","相傳以爲唐王希明所撰。","鄭樵獨非之。","以爲丹元子隋之隱者，與希明各是一人。","然歌詞淺陋，不似隋人文字，《隋書·經籍志》亦無此書，其非隋人明矣。","古天文家未有以太微、天市配紫宮爲三垣者。","《太史公書》，太微屬南宮，天市屬東宮。","《晉》、《隋》二志，則分中外宮與二十八宿爲三列、而太微、天市雜敍於中宮之次。","使丹元子果隋人，則唐初李淳風修《隋志》，何不一述三垣之說乎？","漁仲好異而無識，欲取俚鄙之歌，駕乎前志之上，所謂棄周鼎而寶康瓠者也。","」〖8〗沈曾植《海日樓札叢》卷三云：「世或謂《丹元子步天歌》是隋時人作，鄭漁仲《天文略》亦謂丹元子隋人撰歌，王希明唐人撰釋。","然《通志》天文書目：《丹元子步天歌》一卷，注云：『唐右拾遺內供奉王希明撰。","』固無丹元子隋人之說也。","《唐志》五行類，王希明《太一金鏡式經》十卷，注『開元中詔撰』則希明乃術數學家，非天文專家。","」〖9〗羅振玉《雪堂校刊羣書敍錄》卷下云：「鄭氏《通志·天文略》謂撰《步天歌》之丹元子乃隋人，於前藉無徵，恐未可信。","」）。"]', '["下垣一宮名天市，兩扇垣牆二十二。","當门六角黑市楼，门左兩星是车肆。","兩箇宗正四宗人，宗星一䨥亦依次。","帛度兩星屠肆前，候星還在帝坐邊。","帝坐一星常光明，四箇微茫宦者星。","以次兩星名列肆，斗斛帝前依其次，斗是五星斛是四。","垣北九箇貫索星，索口橫者七公成。","天紀恰似七公形，數著分明多兩星。","紀北三星名女牀，此坐還依织女傍。","三元之象無相侵，二十八宿隨其陰。","水火土木幷與金，以次別有五行分。","（以上三首錄《通志》卷三九《天文略》第二）（按：〖1〗《崇文總目》輯本卷四《天文占书類》有「《丹元子步天歌》一卷，王希明撰」。","〖2〗《新唐书·藝文志》「天文類」云：「王希明《丹元步天歌》一卷。","」）（〖3〗黄伯思《东观餘論》卷下《校正〈崇文總目〉十七條》云：「《丹元子步天歌》，此但記列星所在，並其象數，使人易識耳，非占说也。","」〖4〗鄭樵《通志·天文略》云：「隋有丹元子者，隐者之流也。","不知名氏，作《步天歌》，见者可以观象焉。","王希明纂漢晉志以釋之，《唐书》誤以爲王希明也。","……此本只傳靈台，不傳人间，術家秘之，名曰《鬼料竅》。","世有數本，不勝其訛，今則取之，仰观以從稽定。","」〖5〗晁公武《郡斋读书志》〖袁本〗卷三上錄《步天歌》一卷：「右未詳撰人。","二十八宿地歌也。","三垣頌、五星凌犯賦於後。","或云唐王希明，自號丹元子。","」〖6〗王應麟《困学紀闻》卷九《天道》云：「《步天歌》，《唐志》謂王希明丹元子。","今本司天右拾遺內供奉王希明撰，喬令来注。","二十八宿歌、三垣頌，五行吟，總爲一卷。","」次引鄭樵之说，末謂「然則王希明丹元子蓋二人也」。","〖7〗錢大昕《十駕斋養新錄》卷十四云：「《丹元子步天歌》，不著撰人姓名。","相傳以爲唐王希明所撰。","鄭樵独非之。","以爲丹元子隋之隐者，與希明各是一人。","然歌词淺陋，不似隋人文字，《隋书·經籍志》亦無此书，其非隋人明矣。","古天文家未有以太微、天市配紫宮爲三垣者。","《太史公书》，太微屬南宮，天市屬东宮。","《晉》、《隋》二志，則分中外宮與二十八宿爲三列、而太微、天市杂敍於中宮之次。","使丹元子果隋人，則唐初李淳风修《隋志》，何不一述三垣之说乎？","漁仲好異而無識，欲取俚鄙之歌，駕乎前志之上，所謂棄周鼎而寶康瓠者也。","」〖8〗沈曾植《海日楼札叢》卷三云：「世或謂《丹元子步天歌》是隋时人作，鄭漁仲《天文略》亦謂丹元子隋人撰歌，王希明唐人撰釋。","然《通志》天文书目：《丹元子步天歌》一卷，注云：『唐右拾遺內供奉王希明撰。","』固無丹元子隋人之说也。","《唐志》五行類，王希明《太一金镜式經》十卷，注『开元中詔撰』則希明乃術數学家，非天文專家。","」〖9〗羅振玉《雪堂校刊羣书敍錄》卷下云：「鄭氏《通志·天文略》謂撰《步天歌》之丹元子乃隋人，於前藉無徵，恐未可信。","」）。"]', '诗', 'shi', '', NULL, '丹元子步天歌 天市垣 王希明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da8251c5-4e5e-4c3b-bc8d-9fb515f79477', '若耶春意', '若耶春意', 'a85e9e64-21d4-4d54-a3a7-0b20ecee9eae', '唐', '["越水正逶迤，艷陽三月時。","中有嬋娟子，含怨望佳期。","鮮膚潤玉澤，微眄動蛾眉。","解珮遺中浦，折芳懷所思。","彩色豈不重，瓌艷難久滋。","一歌江南曲，再使妾心悲。","（見《會稽掇英總集》卷七）。"]', '["越水正逶迤，艷陽三月时。","中有嬋娟子，含怨望佳期。","鲜膚潤玉澤，微眄动蛾眉。","解珮遺中浦，折芳懷所思。","彩色豈不重，瓌艷难久滋。","一歌江南曲，再使妾心悲。","（见《會稽掇英總集》卷七）。"]', '诗', 'shi', '', NULL, '若耶春意 許景先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3349e0b-6fae-4f3f-91e9-ed4fa3d51f9e', '答客問', '答客问', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["龍躍湯泉雲漸迴，龍飛香殿氣還來。","龍潛龍見雲皆應，天道常然何問哉！（見宋敏求《長安志》卷十五「臨潼」「陰盤城」條）（《長安志》云：「開元八年冬，乘輿自南入，行至半城，黑氣自城東北角起，倐忽滿城，從官皆相失。","上策馬踰城赴官路下，至渭川，雲氣稍解。","侍臣分散尋求乘輿所在，既謁見，悲喜迸涕，上亦悵然。","自是還宮，數日不出。","翰林學士通事舍人王翰作《答客問》上之，詞曰〖略〗。","」）。"]', '["龙躍湯泉云漸迴，龙飞香殿氣還来。","龙潛龙见云皆應，天道常然何问哉！（见宋敏求《长安志》卷十五「臨潼」「陰盤城」條）（《长安志》云：「开元八年冬，乘輿自南入，行至半城，黑氣自城东北角起，倐忽满城，從官皆相失。","上策马踰城赴官路下，至渭川，云氣稍解。","侍臣分散尋求乘輿所在，既謁见，悲喜迸涕，上亦悵然。","自是還宮，數日不出。","翰林学士通事舍人王翰作《答客问》上之，词曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '答客問 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84af0c7-919d-4ad9-8781-95cb2512cc33', '過琴溪（幷序）', '過琴溪（幷序）', '7b66aab3-4c48-4b2c-a914-a6c0746f05a3', '唐', '["州府謫宦居，邑城攝官涖。","悠悠涇川適，佳期此相遲。","靈溪知幾曲，曲曲各殊致。","仙嶺多巉顏，前峰特超類。","穹崇勢旁倒，㟯下無地。","洞穴盤龍蛇，空巖隱魑魅。","蘋開秋水綠，竹動寒山翠。","遠嶂數瀑懸，疎林一猿墜。","依然彈素絃，流我望鄉淚。","席上紅泉飛，樽前白雲至。","中山是隱居，緬想故心醉。","忽覩邢武辭，聆其金石備。","神交十載得，良願三人遂。","（詩見嘉慶十二年刊洪亮吉纂《涇縣志》卷三一，序據附錄蔣之奇文補）（〖1〗清趙紹祖《涇川金石記》「開元摩崖詩碑」條引宋蔣之奇《磨崖詩序》略云：「予遊涇川，過琴溪，浮舟釣臺，道旁見石崖蒼蒼，上摩穹旻，意其下必有瓌觀焉。","既還至水西，涇令陳中裕餞余巖礲寺，尉劉公曼云：向所觀石崖古刻尚在。","唐玄宗開元甲子，河間邢巨、沛國武平一，嘗遊是溪，題絕句其下。","又刻一長篇，尤雅淡有清思。","其序云：『二十二年冬，予自柱史謫掾宣城，明年九月，連率班公〖原注：下闕〗。","』讀其詩，有云：『忽覩邢武辭，聆其金石備。","』以詩序考之，蓋是人也。","後邢、武一紀而來，疑其即杜偉也。","」〖2〗同書「杜偉《周公亭記》」條引同人《琴溪釣臺詩序》略曰：「釣臺旁山臨溪，上有古碑，皆漫滅殘剝，僅有數字可辨。","其上篆四字曰《周公亭頌》，其餘字皆八分，云：『前殿中侍御史宣城郡司戶京兆杜偉纂。","』〖下略〗」）（按：《涇縣志》錄此詩，署「亡名氏」，無序。","末跋云：「疑杜偉作。","偉以開元二十年謫掾宣城，今《全唐詩》但收『忽覩邢武辭』二句，即作杜偉。","」今參蔣之奇熙寧間所作二序，可決知此詩爲杜偉所作。","《全唐詩》卷七九五據蔣文錄二句，歸杜偉，無小傳，今據蔣氏二序補之。","）。"]', '["州府謫宦居，邑城攝官涖。","悠悠涇川適，佳期此相遲。","靈溪知幾曲，曲曲各殊致。","仙嶺多巉顏，前峰特超類。","穹崇勢旁倒，㟯下無地。","洞穴盤龙蛇，空巖隐魑魅。","蘋开秋水綠，竹动寒山翠。","远嶂數瀑懸，疎林一猿墜。","依然彈素絃，流我望乡泪。","席上紅泉飞，樽前白云至。","中山是隐居，緬想故心醉。","忽覩邢武辞，聆其金石備。","神交十載得，良願三人遂。","（诗见嘉慶十二年刊洪亮吉纂《涇縣志》卷三一，序據附錄蔣之奇文補）（〖1〗清趙紹祖《涇川金石記》「开元摩崖诗碑」條引宋蔣之奇《磨崖诗序》略云：「予游涇川，過琴溪，浮舟釣台，道旁见石崖蒼蒼，上摩穹旻，意其下必有瓌观焉。","既還至水西，涇令陳中裕餞余巖礲寺，尉劉公曼云：向所观石崖古刻尚在。","唐玄宗开元甲子，河间邢巨、沛国武平一，嘗游是溪，題絕句其下。","又刻一长篇，尤雅淡有清思。","其序云：『二十二年冬，予自柱史謫掾宣城，明年九月，連率班公〖原注：下闕〗。","』读其诗，有云：『忽覩邢武辞，聆其金石備。","』以诗序考之，蓋是人也。","後邢、武一紀而来，疑其即杜偉也。","」〖2〗同书「杜偉《周公亭記》」條引同人《琴溪釣台诗序》略曰：「釣台旁山臨溪，上有古碑，皆漫滅殘剝，僅有數字可辨。","其上篆四字曰《周公亭頌》，其餘字皆八分，云：『前殿中侍御史宣城郡司戶京兆杜偉纂。","』〖下略〗」）（按：《涇縣志》錄此诗，署「亡名氏」，無序。","末跋云：「疑杜偉作。","偉以开元二十年謫掾宣城，今《全唐诗》但收『忽覩邢武辞』二句，即作杜偉。","」今參蔣之奇熙寧间所作二序，可決知此诗爲杜偉所作。","《全唐诗》卷七九五據蔣文錄二句，归杜偉，無小傳，今據蔣氏二序補之。","）。"]', '诗', 'shi', '', NULL, '過琴溪（幷序） 杜偉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff07ae02-41db-4259-bc7c-951ed6c581a7', '駕幸華清宮賦附歌', '駕幸华清宮賦附歌', '7295782d-8e11-4ef1-909a-fcdc2015fdfa', '唐', '["素秋歸兮玄冬早，王是時兮出西鎬。","幸華清兮順天道，瓊樓架虛兮靈仙保，長生殿前兮樹難老，甘泉流兮聖躬可澡，俾吾皇兮億千壽考。","（見《文苑英華》卷五八）。"]', '["素秋归兮玄冬早，王是时兮出西鎬。","幸华清兮順天道，瓊楼架虛兮靈仙保，长生殿前兮樹难老，甘泉流兮聖躬可澡，俾吾皇兮億千壽考。","（见《文苑英华》卷五八）。"]', '诗', 'shi', '', NULL, '駕幸華清宮賦附歌 韓休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e399f1-85d2-4432-9839-de1a62162cd7', '缺題', '缺題', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["在家嬌小女，卷[幔]（慢）愛花叢。","不畏羅衣濕，折花風雨中。","（見《四部叢刊》本《後邨先生大全集》卷一七七《詩話續集》引李康成《玉臺後集》）。"]', '["在家嬌小女，卷[幔]（慢）愛花叢。","不畏羅衣濕，折花风雨中。","（见《四部叢刊》本《後邨先生大全集》卷一七七《诗話續集》引李康成《玉台後集》）。"]', '诗', 'shi', '', NULL, '缺題 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737d1898-0a66-4ad9-8ee6-826304053e3f', '', '', '4e24066a-a3cc-4306-9787-defaa0550e04', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 徐嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87979f20-5e6c-4b12-9182-27a03c8835d0', '遊石門山', '游石门山', '4e24066a-a3cc-4306-9787-defaa0550e04', '唐', '["維舟清溪泊，徐步石門瞻。","窾屈借巖洞，空□□□纖。","□飛下習□，響（下缺）。","（見光緒元年王棻纂《青田縣志》卷六《金石》）（按：《縣志》云此詩殘刻在青田縣石門洞石壁，題下署：「勅採訪大使、潤州刺史徐嶠。","」徐詩後尚存張愿和詩殘刻，錄如次：「題石門山瀑布八韻敬贈□□□公幷序。","吳郡守兼江東採訪使張愿。","所歷名山觀瀑布者多矣，至於飛流若布，遠近如〖中缺〗。","百步石壁千尋急流成〖後缺〗。","」《縣志》又錄雲舫跋云：「張刻第三行有奉和某某使遊石門山數小字參於其間。","」張詩無殘存，故不另錄，姑附此以備考。","）。"]', '["維舟清溪泊，徐步石门瞻。","窾屈借巖洞，空□□□纖。","□飞下習□，响（下缺）。","（见光緒元年王棻纂《青田縣志》卷六《金石》）（按：《縣志》云此诗殘刻在青田縣石门洞石壁，題下署：「勅採訪大使、潤州刺史徐嶠。","」徐诗後尚存張愿和诗殘刻，錄如次：「題石门山瀑布八韻敬贈□□□公幷序。","吳郡守兼江东採訪使張愿。","所歷名山观瀑布者多矣，至於飞流若布，远近如〖中缺〗。","百步石壁千尋急流成〖後缺〗。","」《縣志》又錄云舫跋云：「張刻第三行有奉和某某使游石门山數小字參於其间。","」張诗無殘存，故不另錄，姑附此以備考。","）。"]', '诗', 'shi', '', NULL, '遊石門山 徐嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('117450df-2926-4ab4-93a2-7cdca7693b88', '草堂吟', '草堂吟', '928d386f-e6b7-4736-a303-978a5fe7b998', '唐', '["草堂棲在靈山谷，勤讀詩書向燈燭。","柴門半掩寂無人，惟有白雲相伴宿。","春日溪頭垂釣歸，花笑鶯啼芳草綠。","猿鶴寥寥愁轉深，携琴獨理仙家曲。","曲中哀怨誰知妙，子期能識宮商調。","魚未成龍劍未飛，家貧耽學人爭笑。","君不見蘇秦與韓信，獨步誰知是英俊。","一朝得遇聖明君，腰間各佩黃金印。","男兒立志需稽古，莫厭燈前讀書苦。","自古公侯未遇時，蕭條長閉山中戶。","（見《高岑三廉薛氏宗譜》，轉錄自《唐代文學論叢》第九期刊施景西《薛令之的〈靈巖寺〉詩及其寫作時代》）（按：《全唐詩》卷二一五僅收此詩之首四句，題作《靈巖寺》。","據施景西考，《靈巖寺》詩題爲咸通元年後的輯錄者所加。","）。"]', '["草堂棲在靈山谷，勤读诗书向灯燭。","柴门半掩寂無人，惟有白云相伴宿。","春日溪头垂釣归，花笑鶯啼芳草綠。","猿鹤寥寥愁轉深，携琴独理仙家曲。","曲中哀怨誰知妙，子期能識宮商調。","鱼未成龙劍未飞，家貧耽学人爭笑。","君不见蘇秦與韓信，独步誰知是英俊。","一朝得遇聖明君，腰间各佩黄金印。","男兒立志需稽古，莫厭灯前读书苦。","自古公侯未遇时，蕭條长閉山中戶。","（见《高岑三廉薛氏宗譜》，轉錄自《唐代文学論叢》第九期刊施景西《薛令之的〈靈巖寺〉诗及其寫作时代》）（按：《全唐诗》卷二一五僅收此诗之首四句，題作《靈巖寺》。","據施景西考，《靈巖寺》诗題爲咸通元年後的輯錄者所加。","）。"]', '诗', 'shi', '', NULL, '草堂吟 薛令之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca47f5a2-eb75-42fe-9755-7ebeca6d73f6', '燕支行營 一', '燕支行營 一', 'd80c26d6-065f-4d94-9dc9-94e057aa2f3e', '唐', '["天平四塞盡黃砂，塞冷三春少物華。","忽見天山飛下雪，疑是前庭有落花。"]', '["天平四塞尽黄砂，塞冷三春少物华。","忽见天山飞下雪，疑是前庭有落花。"]', '诗', 'shi', '', NULL, '燕支行營 一 崔希逸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34403b0f-72e9-4bce-ab0c-5c1d8aa6c4da', '燕支行營 二', '燕支行營 二', 'd80c26d6-065f-4d94-9dc9-94e057aa2f3e', '唐', '["陽烏黯黯暎山平，陰兔微微光漸生。","戍樓往往雲間沒，烽火時時磧裏明。","（見伯三六一九卷）。"]', '["陽烏黯黯暎山平，陰兔微微光漸生。","戍楼往往云间沒，烽火时时磧裏明。","（见伯三六一九卷）。"]', '诗', 'shi', '', NULL, '燕支行營 二 崔希逸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('033df532-e37c-4314-9ca4-15c93b60161a', '歸舊隱', '归旧隐', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["北闕辭天子，南山隱薜蘿。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》引）（按：此二句疑爲浩然《歸故園作》「北闕休上書，南山歸弊廬」之異文。","）。"]', '["北闕辞天子，南山隐薜蘿。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》引）（按：此二句疑爲浩然《归故园作》「北闕休上书，南山归弊廬」之異文。","）。"]', '诗', 'shi', '', NULL, '歸舊隱 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d85daa-3622-4c1e-96f5-aeeb6a3053ed', '句', '句', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["日暮馬行疾，城荒人住稀。","（見宋葛立方《韻語陽秋》卷十四）（《韻語陽秋》云：「余在毗陵，見孫潤夫家有王維畫孟浩然像，絹素敗爛，丹青已渝。","維題其上云：『維嘗見孟公吟曰：「日暮馬行疾，城荒人住稀。","」又吟云：「掛席數千里，名都未逢。","泊舟香爐峰。","」余因美其風調，至所舍圖於素軸。","』」）。"]', '["日暮马行疾，城荒人住稀。","（见宋葛立方《韻語陽秋》卷十四）（《韻語陽秋》云：「余在毗陵，见孫潤夫家有王維畫孟浩然像，絹素敗爛，丹青已渝。","維題其上云：『維嘗见孟公吟曰：「日暮马行疾，城荒人住稀。","」又吟云：「掛席數千里，名都未逢。","泊舟香爐峰。","」余因美其风調，至所舍圖於素軸。","』」）。"]', '诗', 'shi', '', NULL, '句 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1119b1f3-956b-4caf-aded-b08c89bb1740', '贈韓襄客', '贈韓襄客', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["只爲陽臺夢裏狂，降來教作神仙客。","（見《增修詩話總龜前集》卷十三引《詩史》）。"]', '["只爲陽台梦裏狂，降来教作神仙客。","（见《增修诗話總龟前集》卷十三引《诗史》）。"]', '诗', 'shi', '', NULL, '贈韓襄客 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bbe10a6-8408-43df-9b28-cf1336db0e6d', '閨怨詩', '閨怨诗', 'c1330b3a-cf15-4e28-8f25-52c3994ffbd5', '唐', '["連理枝前同設誓，丁香樹下共論心。","（同前）。"]', '["連理枝前同設誓，丁香樹下共論心。","（同前）。"]', '诗', 'shi', '', NULL, '閨怨詩 韓襄客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe14fc6-c94e-41bb-8c22-14208b553c1c', '九度仙樓', '九度仙楼', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["誰斷巨鰲足？連山分一股。","誰跨海上鵬？壓作參差羽。","應是女媧輩，化工揮巧斧。","掀翻煮石雲，大塊將天補。","渣滓至今在，縣瓴分注乳。","磊落擲遐荒，齟齬不合土。","忙惊日月過，晃漾空中舞。","裒益問巨靈，谽谺礙臂武。","塞罅制逆流，努力跡駢拇。","神禹四載僕，九年梗作雨。","紆回殺拗區，澎湃亂飛鼓。","漫下祖龍鞭，六丁擭舟府。","漫發熊繹矢，非石又非虎。","數狹不能制，伊誰可再侮。","曾把蓬萊輪，難將此物賭。","羅浮亦可移，此物不可取。","肋斗出盤山，粗能踞地主。","芝田第九層，最上蕙生圃。","（見同治十三年刊《直隸澧州志》卷二四）（按：嘉慶《石門縣志》卷四九收此詩，署「唐張九淵」。","）。"]', '["誰斷巨鰲足？連山分一股。","誰跨海上鵬？壓作參差羽。","應是女媧輩，化工揮巧斧。","掀翻煮石云，大塊將天補。","渣滓至今在，縣瓴分注乳。","磊落擲遐荒，齟齬不合土。","忙惊日月過，晃漾空中舞。","裒益问巨靈，谽谺礙臂武。","塞罅制逆流，努力跡駢拇。","神禹四載僕，九年梗作雨。","紆回殺拗區，澎湃亂飞鼓。","漫下祖龙鞭，六丁擭舟府。","漫發熊繹矢，非石又非虎。","數狹不能制，伊誰可再侮。","曾把蓬萊輪，难將此物賭。","羅浮亦可移，此物不可取。","肋斗出盤山，粗能踞地主。","芝田第九層，最上蕙生圃。","（见同治十三年刊《直隸澧州志》卷二四）（按：嘉慶《石门縣志》卷四九收此诗，署「唐張九淵」。","）。"]', '诗', 'shi', '', NULL, '九度仙樓 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3f3f5b-3581-450a-b136-0228ccdd1e53', '遊洞門題陳氏丹臺詩', '游洞门題陳氏丹台诗', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["鷄頭西畔洞門開，陳氏丹昇劫仞臺。","𩳛鬼（《體道通鑑》作「鬽」）昔年誠誓否？","至今猶說鬼肩栽。","（見《宛委別藏》本宋陳田夫《南嶽總勝集》卷中「洞門觀」條。","又見《歷世真仙體道通鑑》卷三三）。"]', '["鷄头西畔洞门开，陳氏丹昇劫仞台。","𩳛鬼（《體道通鑑》作「鬽」）昔年誠誓否？","至今猶说鬼肩栽。","（见《宛委別藏》本宋陳田夫《南嶽總勝集》卷中「洞门观」條。","又见《歷世真仙體道通鑑》卷三三）。"]', '诗', 'shi', '', NULL, '遊洞門題陳氏丹臺詩 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d6cf00-110d-498c-8f36-0df2425d09b3', '登終南山得句', '登終南山得句', '8cb1e0bd-7bb8-4669-acc5-55acfb5fd30a', '唐', '["野迥雲根闊，山高樹影長。","（見《增修詩話總龜》卷八引《零陵總記》）。"]', '["野迥云根闊，山高樹影长。","（见《增修诗話總龟》卷八引《零陵總記》）。"]', '诗', 'shi', '', NULL, '登終南山得句 開元儒士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66857def-1ffe-4383-b542-d57b0852fa38', '', '', 'b09e8760-1d25-47b5-81b7-36244bb246d7', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王位之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66be7869-8667-4d6a-9bb3-1ffe7d7e9e1c', '五言晚汎靈溪之作', '五言晚汎靈溪之作', 'b09e8760-1d25-47b5-81b7-36244bb246d7', '唐', '["溪水晚澄鮮，虛無含萬象。","窺臨時見底，勝異如在掌。","魚□□起伏，靈□猶影響。","心悮出人寰，神清資偃仰。","掉舟□□□，聊復愜新賞。","香風襲蕙蘭，秋日浮清朗。","如何得真趣，更此纓時網。","坐嘯人事閑，悠然思獨往。","（見光緒二十二年刊蔣師轍纂《光緒鹿邑縣志》卷十下）（按：此詩見於石刻《唐開元神武皇帝道德經注碑》右側，詩題下署：「□□採訪使下都檢校官滑州匡城主簿王位之」。","詩末有「自書」二字。","詩刻後有題名五行：朝散郎行臨渙縣尉李嵒□義□奉敕修功德□□□□陳忠盛開□□□□歲次庚辰臨渙主簿陳奉璋因題廟內額至此。","另詳後跋。","）。"]', '["溪水晚澄鲜，虛無含万象。","窺臨时见底，勝異如在掌。","鱼□□起伏，靈□猶影响。","心悮出人寰，神清資偃仰。","掉舟□□□，聊复愜新賞。","香风襲蕙蘭，秋日浮清朗。","如何得真趣，更此纓时網。","坐嘯人事闲，悠然思独往。","（见光緒二十二年刊蔣師轍纂《光緒鹿邑縣志》卷十下）（按：此诗见於石刻《唐开元神武皇帝道德經注碑》右側，诗題下署：「□□採訪使下都檢校官滑州匡城主簿王位之」。","诗末有「自书」二字。","诗刻後有題名五行：朝散郎行臨渙縣尉李嵒□義□奉敕修功德□□□□陳忠盛开□□□□歲次庚辰臨渙主簿陳奉璋因題廟內額至此。","另詳後跋。","）。"]', '诗', 'shi', '', NULL, '五言晚汎靈溪之作 王位之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1a9410-b8c5-4c89-a62b-4865d8b268e2', '五言晚遊靈溪汎舟作', '五言晚游靈溪汎舟作', 'dd15cfbe-ff56-42ac-8c6d-4e1a29689d60', '唐', '["晚□照靈溪，溪澄水□綺。","維舟平岸□，□下□□□。","□□□□□，事閒亦念此。","（以下四行闕。","同前）（按：此詩見於石刻《唐開元神武皇帝道德經注碑》左側，署「都知造作□□封丘主簿邢□」。","詩後有題名五行：□古書敕監修功德內使梁令深監內供奉京肅明□□□玄元廟等□功□天寶元年歲在壬午□□敕修功德京同內使判官車□。","〖1〗《鹿邑縣志》附跋云：「右碑二面皆刻字，下半全沒土中，蓋自宋以後，縣境屢有河患，淤填已甚也。","掘地數尺，若陷穽然，龜趺乃見。","碑陽漫漶過半，陰殆全泐，後亡年月，不知何時立。","〖注：唐明皇開元二十三年頒《注道德經》，碑）（內有『廿三祀帝載』云云，情事正合。","〗碑右側刻匡城主簿王位之詩五言八十字，具有左司風格，字亦遒逸，蓋才而淪於下位者。","下列題名凡四人，同時與否，未敢決。","歲次庚辰，當是開元二十八年，是歲敕修宮宇，《唐書》無徵。","左側封丘主簿邢□詩，纔餘十數字，似不逮王作。","下列題名皆內使監修功德者，時在天寶元年，距開元廿八年僅二載，疑是一役久而未竟也。","」）。"]', '["晚□照靈溪，溪澄水□綺。","維舟平岸□，□下□□□。","□□□□□，事閒亦念此。","（以下四行闕。","同前）（按：此诗见於石刻《唐开元神武皇帝道德經注碑》左側，署「都知造作□□封丘主簿邢□」。","诗後有題名五行：□古书敕監修功德內使梁令深監內供奉京肅明□□□玄元廟等□功□天寶元年歲在壬午□□敕修功德京同內使判官车□。","〖1〗《鹿邑縣志》附跋云：「右碑二面皆刻字，下半全沒土中，蓋自宋以後，縣境屢有河患，淤填已甚也。","掘地數尺，若陷穽然，龟趺乃见。","碑陽漫漶過半，陰殆全泐，後亡年月，不知何时立。","〖注：唐明皇开元二十三年頒《注道德經》，碑）（內有『廿三祀帝載』云云，情事正合。","〗碑右側刻匡城主簿王位之诗五言八十字，具有左司风格，字亦遒逸，蓋才而淪於下位者。","下列題名凡四人，同时與否，未敢決。","歲次庚辰，當是开元二十八年，是歲敕修宮宇，《唐书》無徵。","左側封丘主簿邢□诗，纔餘十數字，似不逮王作。","下列題名皆內使監修功德者，时在天寶元年，距开元廿八年僅二載，疑是一役久而未竟也。","」）。"]', '诗', 'shi', '', NULL, '五言晚遊靈溪汎舟作 邢□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efae2569-890e-47bf-b737-b06b074a3cc4', '雜詠', '杂詠', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["既作湖陰客，如何更遠游？章江昨夜雨，送我過揚州。"]', '["既作湖陰客，如何更远游？章江昨夜雨，送我過揚州。"]', '诗', 'shi', '', NULL, '雜詠 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('303c727b-ebc3-47e6-8673-c5ed16856fba', '見遠亭', '见远亭', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["高亭□可望，朝暮對溪山。","野色軒楹外，霞光几席間。"]', '["高亭□可望，朝暮对溪山。","野色軒楹外，霞光几席间。"]', '诗', 'shi', '', NULL, '見遠亭 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469f4413-a429-4c3d-8907-bfae3b1d762e', '晚過水北', '晚過水北', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["寒川消積雪，凍浦漸通流。","日暮人歸盡，沙禽上釣舟。"]', '["寒川消積雪，凍浦漸通流。","日暮人归尽，沙禽上釣舟。"]', '诗', 'shi', '', NULL, '晚過水北 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89fa547f-4ee4-412c-aa5a-6b0ce102e2c2', '三橋', '三橋', '6417afa9-6222-4e9c-aadb-238631feb17b', '唐', '["北臨白雲澗，南望清風閣。","出樹見行人，隔溪有魚躍。","（均見《式古堂書畫彙考》卷七引《張長史四詩帖》。","此帖末有柯九思、高仁卿、陶宗儀等跋。","陶跋云此帖「《宣和書譜》所載，初爲蔡忠惠公〖襄〗家藏，後入御府」。","）。"]', '["北臨白云澗，南望清风閣。","出樹见行人，隔溪有鱼躍。","（均见《式古堂书畫彙考》卷七引《張长史四诗帖》。","此帖末有柯九思、高仁卿、陶宗儀等跋。","陶跋云此帖「《宣和书譜》所載，初爲蔡忠惠公〖襄〗家藏，後入御府」。","）。"]', '诗', 'shi', '', NULL, '三橋 張旭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa67e73b-c2b3-4bf1-ace9-e4af10c0b8ba', '', '', '34bad6a0-3a9c-4ad7-bd39-da7ddd9116df', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 智封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a510bb9e-7619-4217-85d2-fcc308687f5f', '對州牧衛文昇使君問（題擬）', '对州牧衛文昇使君问（題擬）', '34bad6a0-3a9c-4ad7-bd39-da7ddd9116df', '唐', '["日從濛汜出，照樹全無影。","（《宋高僧傳》卷八《唐鄆州安國院巨方傳》附）。"]', '["日從濛汜出，照樹全無影。","（《宋高僧傳》卷八《唐鄆州安国院巨方傳》附）。"]', '诗', 'shi', '', NULL, '對州牧衛文昇使君問（題擬） 智封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f429fe-a991-4e0a-acf2-efd441a5cf60', '偈', '偈', 'd98fde98-f713-447c-88e2-9eaa468048ed', '唐', '["清淨皎潔無塵垢，蓮華化生爲父母。","我修道來經十劫，出示閻浮厭衆苦。","一生苦行超十劫，永離娑婆歸淨土。","（見《宋高僧傳》卷二四）。"]', '["清淨皎潔無塵垢，蓮华化生爲父母。","我修道来經十劫，出示閻浮厭衆苦。","一生苦行超十劫，永離娑婆归淨土。","（见《宋高僧傳》卷二四）。"]', '诗', 'shi', '', NULL, '偈 懷玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1d94cf-92bd-44dc-a5f0-65001429469a', '望石門作', '望石门作', '29b773b2-f9b2-43db-a6a1-bffc96f753db', '唐', '["高峰隔半天，長崖斷千里。","鷄鳴清澗中，猿嘯白雲裏。","瑤波逐空開，霞石觸峰起。","（見《輿地紀勝》卷三十）。"]', '["高峰隔半天，长崖斷千里。","鷄鳴清澗中，猿嘯白云裏。","瑤波逐空开，霞石觸峰起。","（见《輿地紀勝》卷三十）。"]', '诗', 'shi', '', NULL, '望石門作 王喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c76cc2-17a9-40f5-a6a8-76277d50334f', '', '', '2d8e95f0-99ed-49c5-831f-145d4fd64339', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 慈和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e2ba89-4f3a-4afa-bf28-4a5f9f69531e', '曇一師歌（題擬）', '曇一師歌（題擬）', '2d8e95f0-99ed-49c5-831f-145d4fd64339', '唐', '["曇一師，解毗尼。","大聰明，更無疑。","（《宋高僧傳》卷十四《唐會稽開元寺曇一傳》）。"]', '["曇一師，解毗尼。","大聰明，更無疑。","（《宋高僧傳》卷十四《唐會稽开元寺曇一傳》）。"]', '诗', 'shi', '', NULL, '曇一師歌（題擬） 慈和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516fefc2-ebfc-4df2-8b65-5ca42aad0e8e', '句', '句', '91da5c08-d9d6-499d-bc2b-acee8bebe087', '唐', '["雲壑凝寒陰，巖泉激幽響。","（見《吟窗雜錄》卷二六《歷代吟譜》引殷璠語引）（殷璠曰：「彥雄詩但責瀟灑，不尚綺密，至如『雲壑凝寒陰，巖泉激幽響』，亦非凡俗之所能至也。","」今按：此爲璠輯《丹陽集》佚文，詳拙文《殷璠〈丹陽集〉輯考》〖刊《唐代文學論叢》第八輯〗）。"]', '["云壑凝寒陰，巖泉激幽响。","（见《吟窗杂錄》卷二六《歷代吟譜》引殷璠語引）（殷璠曰：「彥雄诗但責瀟灑，不尚綺密，至如『云壑凝寒陰，巖泉激幽响』，亦非凡俗之所能至也。","」今按：此爲璠輯《丹陽集》佚文，詳拙文《殷璠〈丹陽集〉輯考》〖刊《唐代文学論叢》第八輯〗）。"]', '诗', 'shi', '', NULL, '句 張彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6d8594-e088-483f-a10d-a1060c0635f9', '句', '句', 'fa507594-a886-4a2e-a16b-86dd052ee862', '唐', '["草徑不聞金馬詔，松門唯見石人看。","（見《吟窗雜錄》卷二六《歷代吟譜》）。"]', '["草徑不闻金马詔，松门唯见石人看。","（见《吟窗杂錄》卷二六《歷代吟譜》）。"]', '诗', 'shi', '', NULL, '句 蔡隱丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ad1512-b226-4fe0-9fb7-9df02bc3e71d', '', '', 'dc21ce50-6923-4ae8-8c14-d25fc25a8147', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 馮待徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6167176-239f-47d5-926a-20b69a04f70c', '虞美人怨（按：《全唐詩》卷七七三收此詩，題作《虞姬怨》，第二十句缺三字。伯三一九五卷作「帳下娥眉隨李結」。此卷異文較多，錄如次：第四句「年華」作「容華」，第六句「結髮」作「結帶」，第九句「事征戰」作「征戰間」，第十一句「羅衣」作「羅襦」，「沾」作「裛」，第十二句「不辭」作「寧辭」，第十三句「定」作「王」，第十五句「誤」作「悟」，第十八句「智窮計屈」作「致窮勢屈」，第二十一句作「君王死時遺神彩」，第二十二句「貌」作「色」，第二十七句「本來」作「元來」。）', '虞美人怨（按：《全唐诗》卷七七三收此诗，題作《虞姬怨》，第二十句缺三字。伯三一九五卷作「帳下娥眉隨李結」。此卷異文較多，錄如次：第四句「年华」作「容华」，第六句「結髮」作「結带」，第九句「事征戰」作「征戰间」，第十一句「羅衣」作「羅襦」，「沾」作「裛」，第十二句「不辞」作「寧辞」，第十三句「定」作「王」，第十五句「誤」作「悟」，第十八句「智窮計屈」作「致窮勢屈」，第二十一句作「君王死时遺神彩」，第二十二句「貌」作「色」，第二十七句「本来」作「元来」。）', 'dc21ce50-6923-4ae8-8c14-d25fc25a8147', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '虞美人怨（按：《全唐詩》卷七七三收此詩，題作《虞姬怨》，第二十句缺三字。伯三一九五卷作「帳下娥眉隨李結」。此卷異文較多，錄如次：第四句「年華」作「容華」，第六句「結髮」作「結帶」，第九句「事征戰」作「征戰間」，第十一句「羅衣」作「羅襦」，「沾」作「裛」，第十二句「不辭」作「寧辭」，第十三句「定」作「王」，第十五句「誤」作「悟」，第十八句「智窮計屈」作「致窮勢屈」，第二十一句作「君王死時遺神彩」，第二十二句「貌」作「色」，第二十七句「本來」作「元來」。） 馮待徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b0b1b7-0648-45cb-ae8a-06692d7fab06', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'cd623a9d-6648-4aa0-9904-87b180ab052d', '唐', '["送君青門外，遠詣滄海汜。","鳧舄遊帝鄉，羽衣飛故里。","術妙焚金鼎，丹成屑瓊蘂。","追餞會羣僚，屬文降天旨。","秦吳稱異域，少別猶千祀。","黃鶴寓遼陽，應明城郭是。","（見孔延之《會稽掇英總集》卷二）（〖1〗鄭樵《通志》卷七十《藝文略》第八「詩總集類」有「《賀監歸鄉詩集》一卷。","」〖2〗王楙《野客叢書》卷十七云：「僕尋考《會稽集》，得明皇所爲送賀老歸越之序與詩，及朝士自李適[之]以下三十七人餞別之作，是時正天寶三載正月五日也。","」按：王楙所見《會稽集》，當即《會稽掇英總集》。","該集卷二收明皇以下三十七人送賀詩，與楙所云正合。","除明皇、李白、李林甫、姚鵠等四首已收入《全唐詩》外，餘均失收，以下分別輯出。","其中王鐸、嚴都、李慎微三首，係晚唐人擬作，分別收入本書卷三十三、卷三十一、卷三十五。","）。"]', '["送君青门外，远詣滄海汜。","鳧舄游帝乡，羽衣飞故里。","術妙焚金鼎，丹成屑瓊蘂。","追餞會羣僚，屬文降天旨。","秦吳稱異域，少別猶千祀。","黄鹤寓遼陽，應明城郭是。","（见孔延之《會稽掇英總集》卷二）（〖1〗鄭樵《通志》卷七十《藝文略》第八「诗總集類」有「《賀監归乡诗集》一卷。","」〖2〗王楙《野客叢书》卷十七云：「僕尋考《會稽集》，得明皇所爲送賀老归越之序與诗，及朝士自李適[之]以下三十七人餞別之作，是时正天寶三載正月五日也。","」按：王楙所见《會稽集》，當即《會稽掇英總集》。","該集卷二收明皇以下三十七人送賀诗，與楙所云正合。","除明皇、李白、李林甫、姚鵠等四首已收入《全唐诗》外，餘均失收，以下分別輯出。","其中王鐸、嚴都、李慎微三首，係晚唐人擬作，分別收入本书卷三十三、卷三十一、卷三十五。","）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 辛替否 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf18106-8570-4f62-8f8f-23625a53dee1', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '82832cb9-a482-4a9c-8123-cf948bfcbe0f', '唐', '["父子承恩日，遺榮拜職辰。","挂冠辭聖主，佩印奉嚴親。","舉代辭賢智，當朝勸孝仁。","退歸將適越，攀餞乃傾秦。","（同前）。"]', '["父子承恩日，遺榮拜職辰。","挂冠辞聖主，佩印奉嚴親。","舉代辞賢智，當朝勸孝仁。","退归將適越，攀餞乃傾秦。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 王瑀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9f1e07-d1d0-4089-9f9b-2fe05d29dada', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'f832873f-2988-4065-8923-f6b5c44950ff', '唐', '["業盛王公秩，名高絳老年。","遺榮謝珪組，得志學神仙。","去國風爲馭，還鄉海作田。","何當曳鳧舄，萬里更朝天。","（同前）（按：《新唐書》卷七二中《宰相世系表》琅邪王氏房有「濬，南昌丞。","」其祖弘讓，貞觀中爲中書舍人。","若濬長壽，亦可活至開、天之世。","然尚無確證定爲一人，姑附識於此，以俟考詳。","）。"]', '["業盛王公秩，名高絳老年。","遺榮謝珪組，得志学神仙。","去国风爲馭，還乡海作田。","何當曳鳧舄，万里更朝天。","（同前）（按：《新唐书》卷七二中《宰相世系表》琅邪王氏房有「濬，南昌丞。","」其祖弘讓，貞观中爲中书舍人。","若濬长壽，亦可活至开、天之世。","然尚無確證定爲一人，姑附識於此，以俟考詳。","）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 王濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf6cf1df-bb0f-44eb-93f5-505b77904a6c', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '501b635b-f65c-434c-b14c-0e801f7fa5bf', '唐', '["紫氣朝明主，丹丘送老臣。","誰知探穴處，更有散金人。","陌上神仙日，城東梅柳春。","遙知歸隱處，煙浪隔囂塵。","（同前）。"]', '["紫氣朝明主，丹丘送老臣。","誰知探穴处，更有散金人。","陌上神仙日，城东梅柳春。","遙知归隐处，煙浪隔囂塵。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 宋鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4df5671-3b98-4278-a117-e17b23bfb685', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'c2976d94-0d13-4b1a-9eaa-1eb73e6a66eb', '唐', '["遺榮辭上國，解印適稽山。","聖主流深眷，羣公祖別顏。","綵帆收鑑水，紫氣度函關。","應是遼陽鶴，千年始一還。","（同前）。"]', '["遺榮辞上国，解印適稽山。","聖主流深眷，羣公祖別顏。","綵帆收鑑水，紫氣度函关。","應是遼陽鹤，千年始一還。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 李彥和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fcf79c0-d543-41a4-8b8f-98a2de467c57', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '4b82495a-3f9f-451f-8205-987afc463ca5', '唐', '["帝鄉辭寵命，羽服表華年。","地變君臣禮，門榮父子仙。","鳳書開紫觀，鶴駕待青田。","歸舸蓬萊近，宸章日月懸。","跡光三樂美，聲重三疏賢。","即此過函谷，應留《道德篇》。","（同前）（按：《全唐文》卷四○二有胡嘉隱，亦開、天間人，疑爲嘉鄢之昆從輩。","）。"]', '["帝乡辞寵命，羽服表华年。","地变君臣禮，门榮父子仙。","鳳书开紫观，鹤駕待青田。","归舸蓬萊近，宸章日月懸。","跡光三乐美，声重三疏賢。","即此過函谷，應留《道德篇》。","（同前）（按：《全唐文》卷四○二有胡嘉隐，亦开、天间人，疑爲嘉鄢之昆從輩。","）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 胡嘉鄢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72bfd60-d643-4ce0-b8ea-e850bca6a33f', '', '', '56fd489d-a43f-41d7-9297-74a6da493706', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 崔璘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680a660f-7165-4275-9dce-3b24b6ae6afd', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '56fd489d-a43f-41d7-9297-74a6da493706', '唐', '["軒冕朝恩盛，霓裳祖帳榮。","倐然謝時客，高步尚遺名。","魏闕鴛行斷，稽山鶴駕迎。","相期下鳧舄，謁帝會承明。","（同前）。"]', '["軒冕朝恩盛，霓裳祖帳榮。","倐然謝时客，高步尚遺名。","魏闕鴛行斷，稽山鹤駕迎。","相期下鳧舄，謁帝會承明。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 崔璘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a577e767-1cc3-439e-8a5c-d211217dbcdf', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '3b2fb840-5cba-448e-888c-7c5e7913d521', '唐', '["紫綬朝中貴，黃冠物外高。","孰能知止足，君獨避塵勞。","已曉青霞志，方從碧落遨。","軒車儻來物，從此賤吾曹。","（同前）。"]', '["紫綬朝中貴，黄冠物外高。","孰能知止足，君独避塵勞。","已晓青霞志，方從碧落遨。","軒车儻来物，從此賤吾曹。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 張博望 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a228c1c-f49d-41a4-8043-cfdc130d477f', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '8d1159b0-ab95-4e8d-83ec-1de7bbdeade5', '唐', '["北闕皇恩重，東門紫氣飛。","爲看賓客去，何似買臣歸。","迎綬旋江國，題輿入侍闈。","千年舊跡在，七日故人非。","別涕霑霓服，離筵著錦衣。","無因伴仙羽，空此羨光輝。","（同前）（按：《全唐詩》卷八六一收仙人張辭詩四首，《桂苑叢談》、《增修詩話總龜前集》卷四句均作張綽，惟《太平慶記》卷七五引作張辭，疑應作「張綽」爲是。","仙人張綽傳爲咸通初人，與本詩作者時代不合，爲另一人。","）。"]', '["北闕皇恩重，东门紫氣飞。","爲看賓客去，何似買臣归。","迎綬旋江国，題輿入侍闈。","千年旧跡在，七日故人非。","別涕霑霓服，離筵著錦衣。","無因伴仙羽，空此羨光輝。","（同前）（按：《全唐诗》卷八六一收仙人張辞诗四首，《桂苑叢談》、《增修诗話總龟前集》卷四句均作張綽，惟《太平慶記》卷七五引作張辞，疑應作「張綽」爲是。","仙人張綽傳爲咸通初人，與本诗作者时代不合，爲另一人。","）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 張綽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc9dea9c-ec83-4172-8e19-8cddd604d54f', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '9476fcdf-30b3-4ba6-becd-4246c5b662e8', '唐', '["遺老去朝行，登真返舊鄉。","軒車成羽駕，纓綬換霓裳。","明主懷江外，羣公祖道傍。","青門有前事，千載共輝光。","（見《會稽掇英總集》卷二）（〖1〗陶敏云：光緒杜氏浣花宗塾刊本《會稽掇英總集》作朝宗，疑即韓朝宗。","）。"]', '["遺老去朝行，登真返旧乡。","軒车成羽駕，纓綬換霓裳。","明主懷江外，羣公祖道傍。","青门有前事，千載共輝光。","（见《會稽掇英總集》卷二）（〖1〗陶敏云：光緒杜氏浣花宗塾刊本《會稽掇英總集》作朝宗，疑即韓朝宗。","）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 韓宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af4e0f32-5791-4d7f-b649-4d93ba391524', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'd7c2794a-1943-4719-ae86-85e2be1ccb23', '唐', '["子綦南國隱，周氏北山居。","羽客輕簪綬，霓裳下里閭。","仙帆歸海近，雲氣度關虛。","今日辭明主，深恩寵漢疏。","（同前）。"]', '["子綦南国隐，周氏北山居。","羽客轻簪綬，霓裳下里閭。","仙帆归海近，云氣度关虛。","今日辞明主，深恩寵漢疏。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 韓倩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b32e49-5273-4469-86b4-b59b65812c1b', '', '', 'bbf74b90-2beb-4aab-9ee1-efcf8d5577b2', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 魏盈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dacf96fe-4120-4633-a381-4ed9714431f1', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'bbf74b90-2beb-4aab-9ee1-efcf8d5577b2', '唐', '["東門挂冠處，西漢祖筵開。","乃是黃庭老，言辭丹闕來。","方稱四皓德，更仰二疏才。","今日青溪路，何時謁帝回。","（同前）。"]', '["东门挂冠处，西漢祖筵开。","乃是黄庭老，言辞丹闕来。","方稱四皓德，更仰二疏才。","今日青溪路，何时謁帝回。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 魏盈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86135489-6d1c-483b-aa73-1a008c3b8b6e', '古銅雀臺歌（題擬）', '古銅雀台歌（題擬）', '4a94c648-4c3d-43bc-badc-e28b176dc769', '唐', '["銅雀蒼蒼對古馗，清風切切有餘悲。","試憶望陵三五夜，便是西園明月時。","（見《文苑英華》卷五二《古銅雀臺賦》附）。"]', '["銅雀蒼蒼对古馗，清风切切有餘悲。","試憶望陵三五夜，便是西园明月时。","（见《文苑英华》卷五二《古銅雀台賦》附）。"]', '诗', 'shi', '', NULL, '古銅雀臺歌（題擬） 張鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3216459-73df-4af8-8422-7652b5f30442', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'a5711d5b-5ffc-46d5-8757-36cb1e2358e0', '唐', '["承明常謁帝，函谷坐成仙。","少別商山下，長探禹穴前。","雲迎出關馭，花待過江船。","欲識恩華重，宸章七曜懸。","（見《會稽掇英總集》卷二）。"]', '["承明常謁帝，函谷坐成仙。","少別商山下，长探禹穴前。","云迎出关馭，花待過江船。","欲識恩华重，宸章七曜懸。","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 郭慎微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6653a215-d4d8-40dc-8f0b-4c0317322108', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '5755be33-d1c0-4717-a861-a88d8e6f65da', '唐', '["尚道遺朝紱，從天降羽衣。","儲安四皓去，榮足二疏歸。","垂耀珠隨轉，馳軒鶴送飛。","輕舟鏡湖上，宸翰作光輝。","（同前）。"]', '["尚道遺朝紱，從天降羽衣。","儲安四皓去，榮足二疏归。","垂耀珠隨轉，驰軒鹤送飞。","轻舟镜湖上，宸翰作光輝。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 梁涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d909a688-a980-40c0-89ff-53f1bdee8761', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '31bf2bf2-d924-4786-a1d0-29b816e34c36', '唐', '["君家在四明，崇道復遺榮。","霓服辭丹禁，天文詔玉京。","義方延永錫，真籙受長生。","舉手都門外，白雲江上行。","（見《會稽掇英總集》卷二）。"]', '["君家在四明，崇道复遺榮。","霓服辞丹禁，天文詔玉京。","義方延永錫，真籙受长生。","舉手都门外，白云江上行。","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 齊澣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac0d8a3-d489-4ec3-8030-529330118aa0', '', '', '49803eb1-4b5f-441c-aa97-ee8d7ba36d1c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陸善經 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477b4b32-3c61-4d8a-b8ca-7410caf3fba9', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '49803eb1-4b5f-441c-aa97-ee8d7ba36d1c', '唐', '["至貴不忘初，辭榮返舊居。","霓裳因寵錫，鶴駕欲淩虛。","丹禁傾三事，青門祖二疏。","函關遇真隱，應演道家書。","（同前）。"]', '["至貴不忘初，辞榮返旧居。","霓裳因寵錫，鹤駕欲淩虛。","丹禁傾三事，青门祖二疏。","函关遇真隐，應演道家书。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 陸善經 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680158a0-9be9-46a9-98e8-fb6b68808134', '寓汨羅芭蕉寺', '寓汨羅芭蕉寺', '49803eb1-4b5f-441c-aa97-ee8d7ba36d1c', '唐', '["寒泉瀉破青山腹，青山不改寒泉綠。","幽人一派泉石心，倚溪著此數椽屋。","窗外飄噴萬斛珠，枕邊玲瓏一片玉。","山間金龍嘯欲飛，澗底銀蟾清可掬。","敲磬愁驚曉鷺眠，停經坐看昏鴉浴。","香浮茗雪滋肺腑，響入松濤震崖谷。","清淨耳聆絕弦琴，廣長舌相無生曲。","客來坐此亦忘歸，溪南溪北千竿竹。","（同治《平江縣志》卷五四。","此首爲陶敏先生錄示）。"]', '["寒泉瀉破青山腹，青山不改寒泉綠。","幽人一派泉石心，倚溪著此數椽屋。","窗外飄噴万斛珠，枕邊玲瓏一片玉。","山间金龙嘯欲飞，澗底銀蟾清可掬。","敲磬愁驚晓鷺眠，停經坐看昏鴉浴。","香浮茗雪滋肺腑，响入松濤震崖谷。","清淨耳聆絕弦琴，廣长舌相無生曲。","客来坐此亦忘归，溪南溪北千竿竹。","（同治《平江縣志》卷五四。","此首爲陶敏先生錄示）。"]', '诗', 'shi', '', NULL, '寓汨羅芭蕉寺 陸善經 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95f7160-150d-4a4f-8dae-8a845e5a6c4f', '春興', '春兴', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["泉噴（疑）橫琴膝，花黏漉酒巾。","盃中不覺老，林下更逢春。","（日本藏唐抄本《新撰類林抄》卷四，轉引自日本京都大學《中國文學報》一九五九年第十一期刊小川環樹《〈新撰類林抄〉校讀記》）。"]', '["泉噴（疑）橫琴膝，花黏漉酒巾。","盃中不覺老，林下更逢春。","（日本藏唐抄本《新撰類林抄》卷四，轉引自日本京都大学《中国文学報》一九五九年第十一期刊小川环樹《〈新撰類林抄〉校读記》）。"]', '诗', 'shi', '', NULL, '春興 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50c667a-756b-48f2-841e-05800c651b1f', '放達詩', '放達诗', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["落花真好些，一醉一回顛。","（《詩式》卷一）（按：《全唐詩》卷一一二錄句，缺題，今補錄之。","）。"]', '["落花真好些，一醉一回顛。","（《诗式》卷一）（按：《全唐诗》卷一一二錄句，缺題，今補錄之。","）。"]', '诗', 'shi', '', NULL, '放達詩 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53092264-3d37-4ead-8da6-5f9c11e85881', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'f0c8471c-29f8-49d8-b476-e8f4b773979f', '唐', '["解印辭榮祿，遊真奉德音。","贈行天藻下，餞席上台臨。","遠馭仙山鶴，常懷帝里心。","無因同執袂，相望但霑襟。","（《會稽掇英總集》卷二）。"]', '["解印辞榮祿，游真奉德音。","贈行天藻下，餞席上台臨。","远馭仙山鹤，常懷帝里心。","無因同執袂，相望但霑襟。","（《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 韋堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50093d0-64db-4de9-8404-6cd3cce55ea0', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '7d9a3246-dbbb-4c6f-8d99-ea53bf87cd40', '唐', '["聖代全高尚，玄風闡道微。","筵開百僚（《廣卓異記》作「壺」）餞，詔許二疏歸。","仙記題金籙，朝章換（《廣卓異記》作「披」）羽衣。","悄然承睿藻，行路滿光輝。","（同前。","以樂史《廣卓異記》卷三所錄相校。","《廣卓異記》原署「左丞相李適之。","」）。"]', '["聖代全高尚，玄风闡道微。","筵开百僚（《廣卓異記》作「壺」）餞，詔許二疏归。","仙記題金籙，朝章換（《廣卓異記》作「披」）羽衣。","悄然承睿藻，行路满光輝。","（同前。","以乐史《廣卓異記》卷三所錄相校。","《廣卓異記》原署「左丞相李適之。","」）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 李適之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f65059a5-439a-46ab-92b5-ab3794de607f', '遊法華寺', '游法华寺', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["山勢轉深看更好，嶺霞谿霧沒樓臺。","異時花向陰崖發，遠處泉從青壁來。","世界自知千古促，賢愚悉被四時催。","須知此地堪終老，七竅終成一片灰。","（見《會稽掇英總集》卷八）。"]', '["山勢轉深看更好，嶺霞谿霧沒楼台。","異时花向陰崖發，远处泉從青壁来。","世界自知千古促，賢愚悉被四时催。","須知此地堪終老，七竅終成一片灰。","（见《會稽掇英總集》卷八）。"]', '诗', 'shi', '', NULL, '遊法華寺 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84470a6-7fb0-46b1-9fc8-3dd514123018', '日賦附歌', '日賦附歌', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["披雲覩日兮日則明，就日瞻雲兮心若驚。","日爾一日兮何道，時哉幾時兮此生。","（見《文苑英華》卷二）。"]', '["披云覩日兮日則明，就日瞻云兮心若驚。","日爾一日兮何道，时哉幾时兮此生。","（见《文苑英华》卷二）。"]', '诗', 'shi', '', NULL, '日賦附歌 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50d68cca-ace6-4d1a-9491-5566e56f6666', '題滑州公府大廳樑上（題擬）', '題滑州公府大廳樑上（題擬）', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["大廈中構，山屹雲斗。","黃河畎澮，太行培塿。","整庶宣風，緝戎備寇。","鎮寧一方，光輔元后。","（見民國二十一年鉛印本王蒲園等纂《重修滑縣志》卷十二《金石》錄宋趙世長《天禧二年滑州公府大廳記》引）。"]', '["大廈中構，山屹云斗。","黄河畎澮，太行培塿。","整庶宣风，緝戎備寇。","鎮寧一方，光輔元后。","（见民国二十一年鉛印本王蒲园等纂《重修滑縣志》卷十二《金石》錄宋趙世长《天禧二年滑州公府大廳記》引）。"]', '诗', 'shi', '', NULL, '題滑州公府大廳樑上（題擬） 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936eb2bc-af1a-4424-b196-6aa6f3063871', '秋夜泊江[渚]（諸） 一', '秋夜泊江[渚]（諸） 一', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["夜聞木葉落，疑是洞庭秋。","中宵起□望，正見滄江流。","□風□□□，山月隱城樓。","[潯]（尋）陽幾萬里，朝夕泛孤[舟]。"]', '["夜闻木葉落，疑是洞庭秋。","中宵起□望，正见滄江流。","□风□□□，山月隐城楼。","[潯]（尋）陽幾万里，朝夕泛孤[舟]。"]', '诗', 'shi', '', NULL, '秋夜泊江[渚]（諸） 一 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddc401c-fe41-4216-90bf-c3be067e12fd', '秋夜泊江[渚]（諸） 二', '秋夜泊江[渚]（諸） 二', 'f48b5408-126d-4e8d-af9c-3d91a7c24766', '唐', '["我有方寸心，安在六尺軀。","懷山復懷□，□□□□□。","水能澄不渾，劍用持復酬。","珠已含報恩，□□□□□。","□□貧與富，但願一相知。","（以上二首見伯三六一九卷）。"]', '["我有方寸心，安在六尺軀。","懷山复懷□，□□□□□。","水能澄不渾，劍用持复酬。","珠已含報恩，□□□□□。","□□貧與富，但願一相知。","（以上二首见伯三六一九卷）。"]', '诗', 'shi', '', NULL, '秋夜泊江[渚]（諸） 二 李邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b49c6c4-1a99-44e2-af1c-5f549323857b', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'f9026ed0-ed16-4235-88df-474584918cb1', '唐', '["官著朝中貴，才傳海上名。","早年常好道，晚歲更遺榮。","授籙歸三洞，還車謁四明。","東門詔送日，揮涕盡羣英。","（見《會稽掇英總集》卷二。","原署「嗣許王瓘」）。"]', '["官著朝中貴，才傳海上名。","早年常好道，晚歲更遺榮。","授籙归三洞，還车謁四明。","东门詔送日，揮涕尽羣英。","（见《會稽掇英總集》卷二。","原署「嗣許王瓘」）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 李瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b511ca4a-001d-416c-8145-31d954bee562', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'cd9ec1d3-694e-46a8-960a-22b7033c4985', '唐', '["辰象降星精，登朝隱吏幷。","求珠謝軒冕，放舄指蓬瀛。","擲地文章逸，匡儲羽翼成。","江邊丹障起，雲外綠輿迎。","落落神仙意，悽悽離別情。","聖恩殊未已，何獨厭承明？","（同前）。"]', '["辰象降星精，登朝隐吏幷。","求珠謝軒冕，放舄指蓬瀛。","擲地文章逸，匡儲羽翼成。","江邊丹障起，云外綠輿迎。","落落神仙意，悽悽離別情。","聖恩殊未已，何独厭承明？","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 杜昆吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa47497-b27a-44a0-8b24-f95276afafc0', '奉答燕公 一', '奉答燕公 一', 'ed7e0024-7c4e-49c6-b0d8-f8000f36ed31', '唐', '["誰道零陵守，東過此地遊。","友僚同省閣，昆弟接荆州。","我逐江潭雁，君隨海上鷗。","屢傷神氣阻，久別鬢毛秋。","疑嶺春應徧，陽臺兩欲收。","主人情未盡，高駕少淹留。"]', '["誰道零陵守，东過此地游。","友僚同省閣，昆弟接荆州。","我逐江潭雁，君隨海上鷗。","屢傷神氣阻，久別鬢毛秋。","疑嶺春應徧，陽台兩欲收。","主人情未尽，高駕少淹留。"]', '诗', 'shi', '', NULL, '奉答燕公 一 王琚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb26ad54-4731-480b-b35f-bb63e57cb3c3', '奉答燕公 二', '奉答燕公 二', 'ed7e0024-7c4e-49c6-b0d8-f8000f36ed31', '唐', '["語別意淒淒，零陵湘水西。","佳人金谷返，愛（一作「遊」）子洞庭迷。","舊館逢花發，他山值鳥啼。","江天千里望，誰見綠蘋齊？","（均見《結一廬叢書》本《張說之文集》卷七）（按：結一廬本此二詩下署「王琚」。","《四部叢刊》影印龍池草堂刊本《張說之集》收張說《贈趙公》後，無署名。","《全唐詩》卷九八均收趙冬曦名下，實誤。","趙公爲王琚之封爵，岑仲勉先生《唐集質疑·趙公》已有考證，可參看。","友人陳祖言撰《張說年譜》云：「前一首第三句『友寮同省閣』，琚先天元年八月擢拜中書侍郎，說二年七月爲中書令，即爲『同省閣』。","……而冬曦無此經歷。","兩首詩俱言及零陵守，冬曦亦無此經歷。","又前首五、六句『我逐江潭雁，君隨海上鷗』，冬曦爲從六品下之侍御史，階卑辭謙，在其地唱酬詩中均無此等平起平坐之語。","且說離岳赴荆，冬曦送之，說則未嘗送冬曦也，故知必非冬曦詩。","」）。"]', '["語別意淒淒，零陵湘水西。","佳人金谷返，愛（一作「游」）子洞庭迷。","旧館逢花發，他山值鸟啼。","江天千里望，誰见綠蘋齊？","（均见《結一廬叢书》本《張说之文集》卷七）（按：結一廬本此二诗下署「王琚」。","《四部叢刊》影印龙池草堂刊本《張说之集》收張说《贈趙公》後，無署名。","《全唐诗》卷九八均收趙冬曦名下，實誤。","趙公爲王琚之封爵，岑仲勉先生《唐集質疑·趙公》已有考證，可參看。","友人陳祖言撰《張说年譜》云：「前一首第三句『友寮同省閣』，琚先天元年八月擢拜中书侍郎，说二年七月爲中书令，即爲『同省閣』。","……而冬曦無此經歷。","兩首诗俱言及零陵守，冬曦亦無此經歷。","又前首五、六句『我逐江潭雁，君隨海上鷗』，冬曦爲從六品下之侍御史，階卑辞謙，在其地唱酬诗中均無此等平起平坐之語。","且说離岳赴荆，冬曦送之，说則未嘗送冬曦也，故知必非冬曦诗。","」）。"]', '诗', 'shi', '', NULL, '奉答燕公 二 王琚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e863cef2-760e-474f-8d62-13a5b83a58ae', '蒲津迎駕', '蒲津迎駕', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["回鸞下蒲坂，飛旆指秦京。","雕上黃雲送，關中紫氣迎。","霞朝看馬色，月曉聽雞鳴。","防拒連山險，長橋壓水平。","省方知化洽，察俗覺時清。","天下長無事，空餘襟帶名。","（見唐芮挺章編《國秀集》卷上）（按：《全唐詩》卷六四誤作宋鼎作，今移正。","）。"]', '["回鸾下蒲坂，飞旆指秦京。","雕上黄云送，关中紫氣迎。","霞朝看马色，月晓听雞鳴。","防拒連山險，长橋壓水平。","省方知化洽，察俗覺时清。","天下长無事，空餘襟带名。","（见唐芮挺章編《国秀集》卷上）（按：《全唐诗》卷六四誤作宋鼎作，今移正。","）。"]', '诗', 'shi', '', NULL, '蒲津迎駕 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9f8558-6d33-4e3a-bd8a-9a416a4e0db8', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["南山四皓德，東海二疏名。","功遂知身退，心微覺道成。","霓裳明主賜，鶴駕列仙迎。","詔餞出中野，朋歡留上京。","灞橋春水溢，稽嶺白雲生。","此去三千里，那堪長別情。","（見宋孔延之編《會稽掇英總集》卷二）。"]', '["南山四皓德，东海二疏名。","功遂知身退，心微覺道成。","霓裳明主賜，鹤駕列仙迎。","詔餞出中野，朋歡留上京。","灞橋春水溢，稽嶺白云生。","此去三千里，那堪长別情。","（见宋孔延之編《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb61a8ff-aa1a-44fa-9e95-a07641acf268', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '4e6d0f30-c915-43d3-99a7-7a2a3edbbd9e', '唐', '["錫鼎昇天幾萬春，裔孫今復出囂塵。","姓名當繫上清籙，齒髮不知何代人？","暫應客星過世主，旋歸吳市作遺民。","遼東鶴駕忽飛去，揮手無言辭紫宸。","（同前）。"]', '["錫鼎昇天幾万春，裔孫今复出囂塵。","姓名當繫上清籙，齒髮不知何代人？","暫應客星過世主，旋归吳市作遺民。","遼东鹤駕忽飞去，揮手無言辞紫宸。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 何千里 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea8cafaa-5482-4511-8aea-5a836c77905d', '擬採桑曲', '擬採桑曲', '926a2fe7-1e85-40e1-b32b-f3057f172fce', '唐', '["羅敷十五六，採桑城南道。","（見宋陳元龍《片玉集注》卷十《早梅芳》之二注引）。"]', '["羅敷十五六，採桑城南道。","（见宋陳元龙《片玉集注》卷十《早梅芳》之二注引）。"]', '诗', 'shi', '', NULL, '擬採桑曲 吳兢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d4722a6-9d57-4e5d-b14b-4ea13dea81c4', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'feab2d32-0277-46a6-8451-4bf8004c6260', '唐', '["遠節忘榮趣，全真悟道微。","登朝四皓客，辭老二疏歸。","聖主欽玄德，台臣餞羽衣。","丹丘不可接，鳧舄幾時飛。","（見《會稽掇英總集》卷二）。"]', '["远節忘榮趣，全真悟道微。","登朝四皓客，辞老二疏归。","聖主欽玄德，台臣餞羽衣。","丹丘不可接，鳧舄幾时飞。","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 李巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74bb4527-a0da-4b1a-b3d9-d901c2fd492d', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '7050693d-9da5-42cc-bd99-5305cdeceb0f', '唐', '["白首輕軒冕，黃冠重隱淪。","嚴陵垂釣日，疏廣散金辰。","北闕辭明主，東門別故人。","以茲敦雅俗，玄化盡歸真。","（同前）。"]', '["白首轻軒冕，黄冠重隐淪。","嚴陵垂釣日，疏廣散金辰。","北闕辞明主，东门別故人。","以茲敦雅俗，玄化尽归真。","（同前）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 郭虛己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27eaef9d-9e2d-4790-8855-b0b833af5667', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '02281ac1-bab1-4774-95fa-c22603e5a0a6', '唐', '["止足人高尚，遺榮子獨前。","詣臺飛舄日，辭闕挂冠年。","象服歸丹扆，霓裳降紫天。","仙舟望不及，朝野共推賢。","（同前。","原署「褒信郡王璆」）。"]', '["止足人高尚，遺榮子独前。","詣台飞舄日，辞闕挂冠年。","象服归丹扆，霓裳降紫天。","仙舟望不及，朝野共推賢。","（同前。","原署「褒信郡王璆」）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 李璆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169b327f-bfe4-4e19-a882-1feb7e652e4e', '中書壁畫山水', '中书壁畫山水', 'd2e5befd-2ea1-44f9-a9b1-2953a4503f5e', '唐', '["八載忝司存。","（見《全唐詩》卷一一八孫逖《奉和李右相中書壁畫山水》注引）。"]', '["八載忝司存。","（见《全唐诗》卷一一八孫逖《奉和李右相中书壁畫山水》注引）。"]', '诗', 'shi', '', NULL, '中書壁畫山水 李林甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bac1e5b-823d-48d5-9537-3e2d4881a836', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '27f6430a-1123-4885-86f7-1bfd9a64f2b5', '唐', '["解綬申知足，歸元道益真。","離章垂睿作，祖帳別羣臣。","紫禁辭明主，青溪訪羽人。","賞延忠孝著，榮耀故鄉春。","（見宋孔延之《會稽掇英總集》卷二）（按：《會稽掇英總集》此詩作者作「康璡」。","今檢《御史臺精舍題名》及《金石錄》卷七錄《唐康珽告》、《寶刻叢編》錄《復齋碑錄》收《大理少卿康公夫人河間郡君許氏墓志》諸石刻，皆作「康珽」，故從之。","）。"]', '["解綬申知足，归元道益真。","離章垂睿作，祖帳別羣臣。","紫禁辞明主，青溪訪羽人。","賞延忠孝著，榮耀故乡春。","（见宋孔延之《會稽掇英總集》卷二）（按：《會稽掇英總集》此诗作者作「康璡」。","今檢《御史台精舍題名》及《金石錄》卷七錄《唐康珽告》、《寶刻叢編》錄《复斋碑錄》收《大理少卿康公夫人河间郡君許氏墓志》諸石刻，皆作「康珽」，故從之。","）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 康珽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea031ad2-ef23-484e-a974-0b26db7927cb', '和黃三安仁山莊五首 一', '和黄三安仁山莊五首 一', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["春到郭園靜，冰開水木清。","俄聞北山客，虛淡遲聲榮。","不獨閑爲貴，兼將山自名。","古人情亦爾，君識古人情。"]', '["春到郭园静，冰开水木清。","俄闻北山客，虛淡遲声榮。","不独闲爲貴，兼將山自名。","古人情亦爾，君識古人情。"]', '诗', 'shi', '', NULL, '和黃三安仁山莊五首 一 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e6f409-5e93-42b8-8df1-3a9e2256d0e5', '和黃三安仁山莊五首 二', '和黄三安仁山莊五首 二', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["結宇因青嶂，開門對綠疇。","樹交花相色，谿合水同流。","竹逕春來掃，蘭罇暝不收。","無心亦無事，鼓腹醉中遊。"]', '["結宇因青嶂，开门对綠疇。","樹交花相色，谿合水同流。","竹逕春来掃，蘭罇暝不收。","無心亦無事，鼓腹醉中游。"]', '诗', 'shi', '', NULL, '和黃三安仁山莊五首 二 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b5b997-464f-4fb7-b286-c8effd3ce2df', '和黃三安仁山莊五首 三', '和黄三安仁山莊五首 三', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["車馬東城路，尋君至北山。","爲從人境出，彌覺世情閑。","月在清潭上，風歸暗篠間。","此時心最得，長嘯不能還。"]', '["车马东城路，尋君至北山。","爲從人境出，彌覺世情闲。","月在清潭上，风归暗篠间。","此时心最得，长嘯不能還。"]', '诗', 'shi', '', NULL, '和黃三安仁山莊五首 三 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a4015fd-6761-457a-837d-f7582a11030f', '和黃三安仁山莊五首 四', '和黄三安仁山莊五首 四', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["耕種春須了，幽人晚到家。","琴中來遠吹，竹裏映殘霞。","谷鳥牽垂葉，池魚洩（疑）水花。","朝留半樽酒，細酌倚山槎。"]', '["耕種春須了，幽人晚到家。","琴中来远吹，竹裏映殘霞。","谷鸟牽垂葉，池鱼洩（疑）水花。","朝留半樽酒，細酌倚山槎。"]', '诗', 'shi', '', NULL, '和黃三安仁山莊五首 四 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bae716-6de5-446c-ac70-5645ec90d8c8', '和黃三安仁山莊五首 五', '和黄三安仁山莊五首 五', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["幽客嵒（疑）中坐，農人野外居。","報來禾近種，城去麥堪鋤。","夏色歸舟壑，春光逐碧虛。","君開山海記，共我摘園蔬。","（日本藏唐抄本《新撰類林抄》卷四）（按：《國秀集》卷中、《文苑英華》卷三一八、《全唐詩》卷二五八收第二首爲蔣洌詩，《全唐詩》卷二○○又誤作岑參詩，均題作《南溪別業》，文字稍異。","今仍重收，俟考詳。","）。"]', '["幽客嵒（疑）中坐，農人野外居。","報来禾近種，城去麦堪鋤。","夏色归舟壑，春光逐碧虛。","君开山海記，共我摘园蔬。","（日本藏唐抄本《新撰類林抄》卷四）（按：《国秀集》卷中、《文苑英华》卷三一八、《全唐诗》卷二五八收第二首爲蔣洌诗，《全唐诗》卷二○○又誤作岑參诗，均題作《南溪別業》，文字稍異。","今仍重收，俟考詳。","）。"]', '诗', 'shi', '', NULL, '和黃三安仁山莊五首 五 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227de91e-5481-4e38-b89e-ba9912ebc553', '西亭即事', '西亭即事', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["桃李皆開盡，芳菲漸覺闌。","鳥聲愁暮雨，花色寂（疑）春寒。","倚石攀藤蔓，窺林數竹竿。","葛巾常半著，何處似當閒。"]', '["桃李皆开尽，芳菲漸覺闌。","鸟声愁暮雨，花色寂（疑）春寒。","倚石攀藤蔓，窺林數竹竿。","葛巾常半著，何处似當閒。"]', '诗', 'shi', '', NULL, '西亭即事 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2227a83e-3477-43ab-afb2-81b93bf34eea', '陳十六東亭', '陳十六东亭', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["餘春伴蝴蝶，把酒聽黃鸝。","最是淹留處，殘花三兩枝。","（同前。","以上二首據日本大阪市立美術館編《唐抄本》影印本校）。"]', '["餘春伴蝴蝶，把酒听黄鸝。","最是淹留处，殘花三兩枝。","（同前。","以上二首據日本大阪市立美術館編《唐抄本》影印本校）。"]', '诗', 'shi', '', NULL, '陳十六東亭 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c62c87-4447-4361-86af-35def3a0977b', '送李大貶南陽', '送李大貶南陽', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["鴻聲斷續暮天遠，柳影蕭疎秋日寒。","（《千載佳句》卷上《四時部·暮秋》）。"]', '["鴻声斷續暮天远，柳影蕭疎秋日寒。","（《千載佳句》卷上《四时部·暮秋》）。"]', '诗', 'shi', '', NULL, '送李大貶南陽 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4310d61-fdea-4c34-ad3f-06579a2088d4', '裴將軍劍舞賦附歌', '裴將軍劍舞賦附歌', 'd59e4e67-c96f-4bff-b4e9-29e162112b87', '唐', '["洸洸武臣，耀雄劍兮清邊塵。","威戎夷兮率土來賓（一作「威遠夷兮率來賓」），焉用輕裙之妓女，長袖之才人。","（見《文苑英華》卷八二）。"]', '["洸洸武臣，耀雄劍兮清邊塵。","威戎夷兮率土来賓（一作「威远夷兮率来賓」），焉用轻裙之妓女，长袖之才人。","（见《文苑英华》卷八二）。"]', '诗', 'shi', '', NULL, '裴將軍劍舞賦附歌 喬潭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d82ae4f-6b54-481d-bb56-ae07e7393581', '羣玉山賦附歌', '羣玉山賦附歌', 'd59e4e67-c96f-4bff-b4e9-29e162112b87', '唐', '["彼天子兮塵外鑣，登靈臺兮意飄飄。","吾君得道兮異於是，不自求兮自逍遙。","（同前書卷二十九）。"]', '["彼天子兮塵外鑣，登靈台兮意飄飄。","吾君得道兮異於是，不自求兮自逍遙。","（同前书卷二十九）。"]', '诗', 'shi', '', NULL, '羣玉山賦附歌 喬潭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92cb2dfb-967d-4c7c-90ce-b8c4f33d8365', '秋晴曲江望太一納歸雲賦附歌', '秋晴曲江望太一納归云賦附歌', 'd59e4e67-c96f-4bff-b4e9-29e162112b87', '唐', '["節彼南山兮人所瞻，施此雲雨兮濟君欲。"]', '["節彼南山兮人所瞻，施此云雨兮濟君欲。"]', '诗', 'shi', '', NULL, '秋晴曲江望太一納歸雲賦附歌 喬潭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c69448fb-a767-492e-bc65-222dd521375d', '同前賦附歸雲之曲', '同前賦附归云之曲', 'd59e4e67-c96f-4bff-b4e9-29e162112b87', '唐', '["歸雲之狀兮不一，歸雲之趣兮難儔。","雲不以朝脯而異賞，士不以前後而異求。","誠在位之如是，知夫鴻漸之高秋。","（均見《文苑英華》卷十一）。"]', '["归云之狀兮不一，归云之趣兮难儔。","云不以朝脯而異賞，士不以前後而異求。","誠在位之如是，知夫鴻漸之高秋。","（均见《文苑英华》卷十一）。"]', '诗', 'shi', '', NULL, '同前賦附歸雲之曲 喬潭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c926ec1-eb1b-43fd-be15-9941585e1061', '河陽店家女（僅存六句）', '河陽店家女（僅存六句）', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["因緣苟合會（《適園叢書》本及《文獻通考·經籍考》皆作「會合」），萬里猶同鄉。","運命倘不諧，隔壁無津梁。","傳語王家子，何爲不自量？","（見宋劉克莊《後邨先生大全集》卷一七七《詩話續集》引康成輯《玉臺後集》）（〖1〗劉克莊云：《玉臺後集》「中間自載其詩八首，……如《河陽店家女》長篇一首，押五十二韻，若欲與《木蘭》及『孔雀東南飛』之作方駕者。","末云：『因緣……津梁。","』亦佳。","但木蘭始代父征伐，終潔身來歸；仲卿妻死不事二夫，二篇庶幾發乎情性，止乎禮義。","店家女則異是。","王嫗兒雖蓬頭歷齒，母許婿之矣，女慕鄭家郎裘馬之盛，背母而奔之，康成卒章都無譏貶，反云：『傳語王家子，何爲不自量？","』豈詩人之義哉！」按：《文獻通考·經籍考》摘錄後村語，僅至「亦佳」止，《全唐詩》卷二百三據以收入，缺末二句，本事亦未詳。","今具錄之，以供治盛唐詩者參詳。","）。"]', '["因緣苟合會（《適园叢书》本及《文獻通考·經籍考》皆作「會合」），万里猶同乡。","運命倘不諧，隔壁無津梁。","傳語王家子，何爲不自量？","（见宋劉克莊《後邨先生大全集》卷一七七《诗話續集》引康成輯《玉台後集》）（〖1〗劉克莊云：《玉台後集》「中间自載其诗八首，……如《河陽店家女》长篇一首，押五十二韻，若欲與《木蘭》及『孔雀东南飞』之作方駕者。","末云：『因緣……津梁。","』亦佳。","但木蘭始代父征伐，終潔身来归；仲卿妻死不事二夫，二篇庶幾發乎情性，止乎禮義。","店家女則異是。","王嫗兒雖蓬头歷齒，母許婿之矣，女慕鄭家郎裘马之盛，背母而奔之，康成卒章都無譏貶，反云：『傳語王家子，何爲不自量？","』豈诗人之義哉！」按：《文獻通考·經籍考》摘錄後村語，僅至「亦佳」止，《全唐诗》卷二百三據以收入，缺末二句，本事亦未詳。","今具錄之，以供治盛唐诗者參詳。","）。"]', '诗', 'shi', '', NULL, '河陽店家女（僅存六句） 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5bd444-56eb-40e0-81cb-a9cfe7d270ee', '自詠', '自詠', '5fb8964a-793f-41f9-88a2-c3a5e6c91e77', '唐', '["長吟太息問皇天，神通由來也已偏。","一名國士皆貧病，但是裨兵總有錢。","（見唐封演《封氏聞見記》卷十）（《封氏聞見記》云：「范液有口才，薄命，所向不偶。","曾爲詩曰：『舉意三江竭，興心四海枯。","南遊李邕死，北望守珪殂。","』液欲投謁二公，皆會其淪歿，故云。","然宗叔范純家富于財，液每有所求，純常給與之非一。","純曾謂液曰：『君有才而困于貧，今可試自詠。","』液命紙筆立操而竟。","其詩曰〖詩略〗。","純大笑曰：『教君自詠，何駡我乎？","』不以爲過。","」按：前一詩《全唐詩》已收入，「守珪」誤作「宋珪」，守珪指張守珪，與李邕皆天寶間卒，因知液爲天寶間人。","）。"]', '["长吟太息问皇天，神通由来也已偏。","一名国士皆貧病，但是裨兵總有錢。","（见唐封演《封氏闻见記》卷十）（《封氏闻见記》云：「范液有口才，薄命，所向不偶。","曾爲诗曰：『舉意三江竭，兴心四海枯。","南游李邕死，北望守珪殂。","』液欲投謁二公，皆會其淪歿，故云。","然宗叔范純家富于財，液每有所求，純常給與之非一。","純曾謂液曰：『君有才而困于貧，今可試自詠。","』液命紙笔立操而竟。","其诗曰〖诗略〗。","純大笑曰：『教君自詠，何駡我乎？","』不以爲過。","」按：前一诗《全唐诗》已收入，「守珪」誤作「宋珪」，守珪指張守珪，與李邕皆天寶间卒，因知液爲天寶间人。","）。"]', '诗', 'shi', '', NULL, '自詠 范液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a062dc0-c36c-4580-9bd9-83cdedd11e2b', '鳳凰之歌', '鳳凰之歌', 'a7b8838e-38da-4b92-bb47-b8b3bd300ac7', '唐', '["處分明兮繫舒慘，一人慶兮萬物感。","羽族猶得以效珍，微生何久於習坎。","（見《文苑英華》卷八四《鳳凰儀賦》附）。"]', '["处分明兮繫舒慘，一人慶兮万物感。","羽族猶得以效珍，微生何久於習坎。","（见《文苑英华》卷八四《鳳凰儀賦》附）。"]', '诗', 'shi', '', NULL, '鳳凰之歌 李解 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b7a780-5349-4c95-946b-6d0c9ff62ec4', '古意', '古意', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["昨夜巫山中，失却陽臺女。","今朝粧閣裏，獨伴楚王語。","（見《文苑英華》卷二百五）（按：《才調集》卷十收此詩爲蔣藴作，《全唐詩》卷七九九收入。","未詳孰是，今兩存之。","）。"]', '["昨夜巫山中，失却陽台女。","今朝粧閣裏，独伴楚王語。","（见《文苑英华》卷二百五）（按：《才調集》卷十收此诗爲蔣藴作，《全唐诗》卷七九九收入。","未詳孰是，今兩存之。","）。"]', '诗', 'shi', '', NULL, '古意 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30b1d604-38b9-48e6-831c-5de093e84f10', '觀會稽圖', '观會稽圖', 'f9f5bfd9-5750-4203-aa5e-7bb136b7a38b', '唐', '["良使求圖籍，工人巧思饒。","全移會稽郡，不散浙江潮。","夏禹猶卑室，秦皇尚斷橋。","宛然山水趣，誰道故鄉遙。","（見孔延之《會稽掇英總集》卷十五）。"]', '["良使求圖籍，工人巧思饒。","全移會稽郡，不散浙江潮。","夏禹猶卑室，秦皇尚斷橋。","宛然山水趣，誰道故乡遙。","（见孔延之《會稽掇英總集》卷十五）。"]', '诗', 'shi', '', NULL, '觀會稽圖 褚朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a9fb47-2b59-4cc4-8067-0fd433e79b87', '渡浙江問舟中人（存目）（按：以上三首，《四部叢刊》影印本殷璠《河嶽英靈集》卷中作崔國輔詩。同書附孫毓修校記引毛斧季、何義門校本。爲二卷本，較近殷氏原本，卷下亦以諸詩屬崔。然《全唐詩》卷一六○均收作孟浩然詩。孟詩初由王士源輯集，宋以後流傳漸紊。另《國秀集》卷中收《渡浙江》爲孟作。此三詩究爲誰作，尚俟考詳。因其出處甚早，姑存目。）', '渡浙江问舟中人（存目）（按：以上三首，《四部叢刊》影印本殷璠《河嶽英靈集》卷中作崔国輔诗。同书附孫毓修校記引毛斧季、何義门校本。爲二卷本，較近殷氏原本，卷下亦以諸诗屬崔。然《全唐诗》卷一六○均收作孟浩然诗。孟诗初由王士源輯集，宋以後流傳漸紊。另《国秀集》卷中收《渡浙江》爲孟作。此三诗究爲誰作，尚俟考詳。因其出处甚早，姑存目。）', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '渡浙江問舟中人（存目）（按：以上三首，《四部叢刊》影印本殷璠《河嶽英靈集》卷中作崔國輔詩。同書附孫毓修校記引毛斧季、何義門校本。爲二卷本，較近殷氏原本，卷下亦以諸詩屬崔。然《全唐詩》卷一六○均收作孟浩然詩。孟詩初由王士源輯集，宋以後流傳漸紊。另《國秀集》卷中收《渡浙江》爲孟作。此三詩究爲誰作，尚俟考詳。因其出處甚早，姑存目。） 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e3d60e4-f83a-4f3e-b765-2f3632d94bd0', '', '', 'c41ad5b5-270e-4eff-b88b-5a0e3ad920ef', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 齊光乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e872a020-4b6a-44d5-8bc4-2a58f3726cb2', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'c41ad5b5-270e-4eff-b88b-5a0e3ad920ef', '唐', '["晚歲朝真隱，皇情諒不違。","辭家五十載，今日復東歸。","祖帳臨青道，天章降紫微。","顧嗟軒冕者，誰與比光輝？","（見《會稽掇英總集》卷二）。"]', '["晚歲朝真隐，皇情諒不違。","辞家五十載，今日复东归。","祖帳臨青道，天章降紫微。","顧嗟軒冕者，誰與比光輝？","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 齊光乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7cbbc0-0925-4a45-9c83-1c44e24059a7', '讖句', '讖句', '3fb0213e-efec-47fe-9ed8-c6a95f466947', '唐', '["木易若逢山下鬼，定知此處喪金環。","（見《新編分門古今類事》卷十四引《青瑣高議》佚文）。"]', '["木易若逢山下鬼，定知此处喪金环。","（见《新編分门古今類事》卷十四引《青瑣高議》佚文）。"]', '诗', 'shi', '', NULL, '讖句 李遐周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cff9176-9a38-40b7-8e3e-02420a3402b9', '句', '句', '181c8f3f-39df-4f86-8488-91810ee13064', '唐', '["象筵列虛白，幽偈清心胸。","（見《吟窗雜錄》卷二六《歷代吟譜》，又見吳琯《盛唐詩紀》卷三）。"]', '["象筵列虛白，幽偈清心胸。","（见《吟窗杂錄》卷二六《歷代吟譜》，又见吳琯《盛唐诗紀》卷三）。"]', '诗', 'shi', '', NULL, '句 蔡希寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01a4fb9-9fef-473e-b104-8142f91b9d24', '句', '句', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["搘頤笑來客，頭上有朝簪。","（《詩式》卷四）。"]', '["搘頤笑来客，头上有朝簪。","（《诗式》卷四）。"]', '诗', 'shi', '', NULL, '句 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a22351-21d4-4dc4-9d33-1f07d21fd9b5', '句', '句', '02ab63b8-2a8c-4205-aa8b-df59281a4a34', '唐', '["迎娘歌喉玉䆗窱，蠻兒舞帶金葳蕤。","（《斷腸詩集前集》卷六《會魏夫人席上……》鄭元佐注引《羣玉雜俎》引《楊妃外傳》引。","今本《楊妃外傳》無此二句。","詩當出依託。","）。"]', '["迎娘歌喉玉䆗窱，蠻兒舞带金葳蕤。","（《斷腸诗集前集》卷六《會魏夫人席上……》鄭元佐注引《羣玉杂俎》引《楊妃外傳》引。","今本《楊妃外傳》無此二句。","诗當出依託。","）。"]', '诗', 'shi', '', NULL, '句 楊貴妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6979ac9c-0a26-4aeb-aa2c-39375e234a0f', '泰階六符賦附歌', '泰階六符賦附歌', '3ba50fb2-6148-4b07-8ada-63e2a10b19a7', '唐', '["君臣穆兮純化清，玉衡正兮泰階平。","嘉曆數兮無極，配乾坤兮永貞。","（見《文苑英華》卷九）。"]', '["君臣穆兮純化清，玉衡正兮泰階平。","嘉曆數兮無極，配乾坤兮永貞。","（见《文苑英华》卷九）。"]', '诗', 'shi', '', NULL, '泰階六符賦附歌 婁玄穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76812e8b-fd7f-4bea-a6fb-71ba20f1e24b', '掌上蓮峰賦附歌', '掌上蓮峰賦附歌', 'ddd18faf-1ff3-4404-8ba8-d57904cd61ad', '唐', '["苔至滑兮石無蹤，道不可得，仙不可逢。","儻賜一丸生羽翼，願輕舉於三峰。","（見《文苑英華》卷二八）。"]', '["苔至滑兮石無蹤，道不可得，仙不可逢。","儻賜一丸生羽翼，願轻舉於三峰。","（见《文苑英华》卷二八）。"]', '诗', 'shi', '', NULL, '掌上蓮峰賦附歌 呂令問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2056ef6-45e2-4fe3-929f-c4057c45f922', '駕幸天安宮賦附邑老田父歌', '駕幸天安宮賦附邑老田父歌', 'ddd18faf-1ff3-4404-8ba8-d57904cd61ad', '唐', '["歲既稔而時清，我后來兮應天行。","東都士庶扶輪送，西土諸侯掃地迎。","君之德兮德無有，路旁勞賚皆牛酒。","乘輿一至長安城，千秋萬歲南山壽。","（見前書卷五八）。"]', '["歲既稔而时清，我后来兮應天行。","东都士庶扶輪送，西土諸侯掃地迎。","君之德兮德無有，路旁勞賚皆牛酒。","乘輿一至长安城，千秋万歲南山壽。","（见前书卷五八）。"]', '诗', 'shi', '', NULL, '駕幸天安宮賦附邑老田父歌 呂令問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b474a1-be11-434a-b662-7ef8fdd366ef', '新安江林（存目）（按：見《才調集》卷七。《全唐詩》卷二八一收作章八元詩。）', '新安江林（存目）（按：见《才調集》卷七。《全唐诗》卷二八一收作章八元诗。）', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '新安江林（存目）（按：見《才調集》卷七。《全唐詩》卷二八一收作章八元詩。） 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63f6891-3915-42a7-bb29-601934063956', '弔軹道賦附邵平歌', '弔軹道賦附邵平歌', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["道不虛行兮，史鰌沒位，吾寧范伯之徒歟，感夷齊而多愧。","麟鳳遠去，龍則死之，河水洋洋兮，先師莫歸。","往者不可諫，來者吾誰欺？","始退身以進道，曷颺言而受非，彼蕭相國知予乎布衣。","（見《文苑英華》卷一三○）。"]', '["道不虛行兮，史鰌沒位，吾寧范伯之徒歟，感夷齊而多愧。","麟鳳远去，龙則死之，河水洋洋兮，先師莫归。","往者不可諫，来者吾誰欺？","始退身以進道，曷颺言而受非，彼蕭相国知予乎布衣。","（见《文苑英华》卷一三○）。"]', '诗', 'shi', '', NULL, '弔軹道賦附邵平歌 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf5203f-6507-4e43-a049-c98d17a2948e', '雲山清曉', '云山清晓', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["蒼深翠淺瀑崢潺，豈謂譏秦始愛山。","一炬咸陽機冢赤，紫霄巍立曉雲間。","（見《古今圖書集成·山川典》卷一七三。","此首當出後人依託。","）。"]', '["蒼深翠淺瀑崢潺，豈謂譏秦始愛山。","一炬咸陽機冢赤，紫霄巍立晓云间。","（见《古今圖书集成·山川典》卷一七三。","此首當出後人依託。","）。"]', '诗', 'shi', '', NULL, '雲山清曉 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('796a2ab8-be28-4d0b-b74c-d349300b179e', '四時調玉燭', '四时調玉燭', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["祥光長赫矣，佳號得溫其。","（見宋葛立方《韻語陽秋》卷三）。"]', '["祥光长赫矣，佳號得溫其。","（见宋葛立方《韻語陽秋》卷三）。"]', '诗', 'shi', '', NULL, '四時調玉燭 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99f944a-aa0c-43f1-9244-c5ee79ae88d1', '梅詩', '梅诗', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["落落寞寞路不分，夢中喚作梨花雲。","（見《苕溪漁隱叢話前集》卷四、《野客叢書》卷六引曾慥《高齋詩話》、龍榆生《東坡樂府箋》卷二《西江月》注引南宋傅藻注引。","）（按：《墨莊漫錄》卷六載此詩全篇，以爲王建作，詳本書卷十八。","然曾慥時代較早，當有所據。","蘇軾《西江月》詞末句云：「不與梨花同夢。","」自跋云：「詩人王昌齡夢中作梅花詩。","」傅注因引此二句。","其時代較曾慥更早。","今互收。","）。"]', '["落落寞寞路不分，梦中喚作梨花云。","（见《苕溪漁隐叢話前集》卷四、《野客叢书》卷六引曾慥《高斋诗話》、龙榆生《东坡乐府箋》卷二《西江月》注引南宋傅藻注引。","）（按：《墨莊漫錄》卷六載此诗全篇，以爲王建作，詳本书卷十八。","然曾慥时代較早，當有所據。","蘇軾《西江月》词末句云：「不與梨花同梦。","」自跋云：「诗人王昌齡梦中作梅花诗。","」傅注因引此二句。","其时代較曾慥更早。","今互收。","）。"]', '诗', 'shi', '', NULL, '梅詩 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b7cd64c-505e-4196-b98c-403d25e8928e', '送別', '送別', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["河口餞南客，進帆清江水。"]', '["河口餞南客，進帆清江水。"]', '诗', 'shi', '', NULL, '送別 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21792ec1-f78b-47ef-8b64-90f606512c2b', '送友人之安南', '送友人之安南', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["還舟望炎海，楚葉下秋水。","（均見《文鏡秘府論》地卷《十七勢》引王昌齡《詩格》。","市河世寧《全唐詩逸》卷上收四句，缺題，今重錄。","）。"]', '["還舟望炎海，楚葉下秋水。","（均见《文镜秘府論》地卷《十七勢》引王昌齡《诗格》。","市河世寧《全唐诗逸》卷上收四句，缺題，今重錄。","）。"]', '诗', 'shi', '', NULL, '送友人之安南 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff945796-4ca6-410d-8458-243c9d483b07', '句（附存）', '句（附存）', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["王維詩天子，杜甫詩宰相。","（見宋葉廷珪《海錄碎事》卷十九引《王昌齡集》。","似出後人依托。","）（按：《全唐詩》卷一四一收昌齡《小敷谷龍潭祠作》，第十九句缺一字。","汲克閣本《唐詩紀事》卷二四引此詩不缺，此句作「奔飛振串梁」。","）。"]', '["王維诗天子，杜甫诗宰相。","（见宋葉廷珪《海錄碎事》卷十九引《王昌齡集》。","似出後人依托。","）（按：《全唐诗》卷一四一收昌齡《小敷谷龙潭祠作》，第十九句缺一字。","汲克閣本《唐诗紀事》卷二四引此诗不缺，此句作「奔飞振串梁」。","）。"]', '诗', 'shi', '', NULL, '句（附存） 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884eaf68-4d11-47f6-a5fb-dc6a0ff07cee', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '23c917a5-0d8f-4da5-8a72-4b096478ceb8', '唐', '["抗情遺黼冕，高步出氛埃。","橫海鴻飛遠，登仙鶴語催。","希微餘第宅，怳惚視嬰孩。","桃實三千歲，何當獻壽來？","（見孔延之《會稽掇英總集》卷二）。"]', '["抗情遺黼冕，高步出氛埃。","橫海鴻飞远，登仙鹤語催。","希微餘第宅，怳惚視嬰孩。","桃實三千歲，何當獻壽来？","（见孔延之《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 韋斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f59e92d-a11b-4d5f-9a27-002e3e5d09f0', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'b8a5479a-4ee8-4d5d-bcb8-ebe86adb295f', '唐', '["二疏方告老，四皓盡歸山。","藹藹都門別，仍看衣錦還。","霓裳標逸氣，丹竈理童顏。","一遇真仙侶，羣心難可攀。","（見孔延之《會稽掇英總集》卷二）。"]', '["二疏方告老，四皓尽归山。","藹藹都门別，仍看衣錦還。","霓裳標逸氣，丹竈理童顏。","一遇真仙侶，羣心难可攀。","（见孔延之《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 韋述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1190fc51-31ee-4dca-864f-1d9843ba0d39', '破陣樂', '破陣乐', '26eea48f-c079-4d07-8684-634f8374bbcc', '唐', '["西戎最沐恩深，犬羊違背生心。","神將驅兵出塞，橫行海畔生擒。","石堡巖高萬丈，雕窠霞外千尋。","一喝盡屬唐國，將知應合天心。","（見伯三六一九卷。","轉錄自任半塘先生《唐聲詩》下編第十附錄。","）。"]', '["西戎最沐恩深，犬羊違背生心。","神將驱兵出塞，橫行海畔生擒。","石堡巖高万丈，雕窠霞外千尋。","一喝尽屬唐国，將知應合天心。","（见伯三六一九卷。","轉錄自任半塘先生《唐声诗》下編第十附錄。","）。"]', '诗', 'shi', '', NULL, '破陣樂 哥舒翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c455f600-bb79-4b35-a67a-c27c24b08767', '題鳳凰山', '題鳳凰山', '26eea48f-c079-4d07-8684-634f8374bbcc', '唐', '["彩鳳雙飛翼，宛然半巖間。","（《記纂淵海》卷二十五）。"]', '["彩鳳雙飞翼，宛然半巖间。","（《記纂淵海》卷二十五）。"]', '诗', 'shi', '', NULL, '題鳳凰山 哥舒翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e732ba32-8920-44ea-aa75-ca62ea79d4d5', '白金小還丹歌 一', '白金小還丹歌 一', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["法藥變化，無非水精。","六芝潤色，黃芽自生。","陽光不起，陰流無聲。","道方秘易，學者難成。"]', '["法藥变化，無非水精。","六芝潤色，黄芽自生。","陽光不起，陰流無声。","道方秘易，学者难成。"]', '诗', 'shi', '', NULL, '白金小還丹歌 一 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c3ed62-21a8-4355-b505-9a2dd3a39122', '白金小還丹歌 二', '白金小還丹歌 二', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["既養黃男，先禁家鬼。","盡死扶金，餘生制水。","世人能明，並窮斯理。","親奉聖言，事難自揣。"]', '["既養黄男，先禁家鬼。","尽死扶金，餘生制水。","世人能明，並窮斯理。","親奉聖言，事难自揣。"]', '诗', 'shi', '', NULL, '白金小還丹歌 二 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e8e298-83a9-4ed0-8215-dde83f7c8638', '白金小還丹歌 三', '白金小還丹歌 三', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["籠虛其底，免被炎馳。","知白守黑，清黃一支。","能忌陰穢，不逾百時。","延生大道，易解難知。"]', '["籠虛其底，免被炎驰。","知白守黑，清黄一支。","能忌陰穢，不逾百时。","延生大道，易解难知。"]', '诗', 'shi', '', NULL, '白金小還丹歌 三 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3052c46b-6d0c-43ec-990b-81ba76f683ba', '白金小還丹歌 四', '白金小還丹歌 四', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["黃子淳淑，自娶玄妃。","金成力厚，藥就身肥。","土宅三分，火房二儀。","至德消陰，純陽幽微。"]', '["黄子淳淑，自娶玄妃。","金成力厚，藥就身肥。","土宅三分，火房二儀。","至德消陰，純陽幽微。"]', '诗', 'shi', '', NULL, '白金小還丹歌 四 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a676f35d-7fc4-470b-9286-3fc4ee83b305', '白金小還丹歌 五', '白金小還丹歌 五', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["一味白金，固人衰朽。","雜性難防，同心易守。","服食千粒，百日無咎。","萬痾漸除，天地同壽。"]', '["一味白金，固人衰朽。","杂性难防，同心易守。","服食千粒，百日無咎。","万痾漸除，天地同壽。"]', '诗', 'shi', '', NULL, '白金小還丹歌 五 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f01130f-4f3c-40b2-a885-256c556b0d68', '白金小還丹歌 六', '白金小還丹歌 六', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["言依口訣，親貴手傳。","七日自伏，萬刻牢堅。","千鍊萬煑，託在五賢。","好藴金器，不絕玄關。"]', '["言依口訣，親貴手傳。","七日自伏，万刻牢堅。","千鍊万煑，託在五賢。","好藴金器，不絕玄关。"]', '诗', 'shi', '', NULL, '白金小還丹歌 六 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03939ef9-c2cb-446f-8154-93e7a73a6cdf', '白金小還丹歌 七', '白金小還丹歌 七', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["赭塗四壁，丹守圓扉。","一居火匱，二處灰池。","五蟾可保，三烏無疑。","道情未速，益日加奇。"]', '["赭塗四壁，丹守圓扉。","一居火匱，二处灰池。","五蟾可保，三烏無疑。","道情未速，益日加奇。"]', '诗', 'shi', '', NULL, '白金小還丹歌 七 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88cac6b4-a759-4076-a629-31138a51be1d', '白金小還丹歌 八', '白金小還丹歌 八', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["一黃二白，三銖兩作。","養至滿蟾，生其高鶴。","事忌他非，道身自樂。","傳受非人，天殃地虐。"]', '["一黄二白，三銖兩作。","養至满蟾，生其高鹤。","事忌他非，道身自乐。","傳受非人，天殃地虐。"]', '诗', 'shi', '', NULL, '白金小還丹歌 八 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b2cecd-5acd-4b59-9e21-3244f46a1892', '白金小還丹歌 九', '白金小還丹歌 九', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["芽屬黃男，藥屬玄女。","外助無非，玉芝清醑。","俗士多聞，道君少語。","用物參差，虛受辛苦。"]', '["芽屬黄男，藥屬玄女。","外助無非，玉芝清醑。","俗士多闻，道君少語。","用物參差，虛受辛苦。"]', '诗', 'shi', '', NULL, '白金小還丹歌 九 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb851a3-5b5e-447a-b79c-62ca25423cb0', '白金小還丹歌 十', '白金小還丹歌 十', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["銅鐵壞形，丹灰損力。","欲驗其神，須存本色。","一陰一陽，事易候則。","異族同羣，自種荆棘。"]', '["銅鐵壞形，丹灰損力。","欲驗其神，須存本色。","一陰一陽，事易候則。","異族同羣，自種荆棘。"]', '诗', 'shi', '', NULL, '白金小還丹歌 十 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0699bf0-8c81-45de-9d38-65d66e49f11f', '白金小還丹歌 十一', '白金小還丹歌 十一', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["殺青龍，須白虎，自然感化無風雨。","雪花飛，雪花飛，魂歸魄亦歸。","聚散既由壬癸水，玉神華蓋體無爲。","湧泉水，湧泉水，春夏秋冬深無底。","要行天下時，厚暖自然制。","（見《正統道藏》本元陽子輯《還丹歌訣》卷上。","此書爲北宋前之著。","）（按：此組詩原題作「青城羅真人上明皇《白金小還丹歌》」，詩前有小引云：「帝問真人曰：『道本無二，同歸乎一。","藥有多功，身寧濟惠。","願垂憫念，速救餘生。","』真人曰：『身在和炁，藥同元滋，二道符機，衰朽自差，莫希大藥，日月難期。","一味白金，延年益壽，仙人保秘，不妄虛傳，但能秘之，無輕泄爾。","』凡一十二首。","」似爲後人所加。","《太平廣記》卷二二云公遠「因以《三峯歌》八首以進焉，其大旨乃玄素黃赤之使、還纓泝流之事」。","今不存。","）。"]', '["殺青龙，須白虎，自然感化無风雨。","雪花飞，雪花飞，魂归魄亦归。","聚散既由壬癸水，玉神华蓋體無爲。","湧泉水，湧泉水，春夏秋冬深無底。","要行天下时，厚暖自然制。","（见《正統道藏》本元陽子輯《還丹歌訣》卷上。","此书爲北宋前之著。","）（按：此組诗原題作「青城羅真人上明皇《白金小還丹歌》」，诗前有小引云：「帝问真人曰：『道本無二，同归乎一。","藥有多功，身寧濟惠。","願垂憫念，速救餘生。","』真人曰：『身在和炁，藥同元滋，二道符機，衰朽自差，莫希大藥，日月难期。","一味白金，延年益壽，仙人保秘，不妄虛傳，但能秘之，無轻泄爾。","』凡一十二首。","」似爲後人所加。","《太平廣記》卷二二云公远「因以《三峯歌》八首以進焉，其大旨乃玄素黄赤之使、還纓泝流之事」。","今不存。","）。"]', '诗', 'shi', '', NULL, '白金小還丹歌 十一 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6b37b3d-774b-4e5b-b401-8e751db11bd2', '大還丹口訣', '大還丹口訣', '633b4b5e-fb54-41e2-9b0f-9b8bc997a449', '唐', '["世人不知丹有神，試喫狼毒必害人。","將知世上有善惡，何不將身近善鄰。","女媧鍊得五常氣，變化成形補天地。","三十六筭世間知，七十二石列具位。","天得一而能長，地得一而方久。","金得火而轉精，木成炭而不朽。","故知唯鍊唯精，大還如何不有？","凝我神，定我心，志精可以成黃金。","河車本向鉛中取，姹女還須汞裏尋。","傍思之物謾周彰，太一出水入公量。","淮南調鼎彭祖嘗，得道同歸不死鄉。","固濟精研須緘密，一文一武莫踈失。","釜下唯鋪淥海鹽，鑪中少用槫桑日。","紫煙碧焰噴人香，赫奕魚鱗透日光。","須同魏伯雲中去，莫學姮娥月裏藏。","酆都落名天府記，地下陰官大怖畏。","兵刃水火不能忤，何但蟲蛇兼虎兕。","亭亭金骨皆堅牢，鬱鬱綠身徧綠毛。","曾觀東海幾廻變，數度曾偷王母桃。","乘龍駕鶴傾城市，驅策雷公使神鬼。","七日應歸緱氏山，千年少別遼東水。","道是易，亦大難，青龍白虎自相盤。","陰車濕，陽車乾，夫妻相對卦中安。","四方未住霑顏色，五箇王侯盡罷官。","（《正統道藏》本後蜀佚名著《大還丹照鑒》）。"]', '["世人不知丹有神，試喫狼毒必害人。","將知世上有善惡，何不將身近善鄰。","女媧鍊得五常氣，变化成形補天地。","三十六筭世间知，七十二石列具位。","天得一而能长，地得一而方久。","金得火而轉精，木成炭而不朽。","故知唯鍊唯精，大還如何不有？","凝我神，定我心，志精可以成黄金。","河车本向鉛中取，姹女還須汞裏尋。","傍思之物謾周彰，太一出水入公量。","淮南調鼎彭祖嘗，得道同归不死乡。","固濟精研須緘密，一文一武莫踈失。","釜下唯鋪淥海鹽，鑪中少用槫桑日。","紫煙碧焰噴人香，赫奕鱼鱗透日光。","須同魏伯云中去，莫学姮娥月裏藏。","酆都落名天府記，地下陰官大怖畏。","兵刃水火不能忤，何但蟲蛇兼虎兕。","亭亭金骨皆堅牢，鬱鬱綠身徧綠毛。","曾观东海幾廻变，數度曾偷王母桃。","乘龙駕鹤傾城市，驱策雷公使神鬼。","七日應归緱氏山，千年少別遼东水。","道是易，亦大难，青龙白虎自相盤。","陰车濕，陽车乾，夫妻相对卦中安。","四方未住霑顏色，五箇王侯尽罷官。","（《正統道藏》本後蜀佚名著《大還丹照鑒》）。"]', '诗', 'shi', '', NULL, '大還丹口訣 羅公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72706db0-7f84-4fcc-a027-e8baa6e418f7', '', '', '61574eee-0e89-45a8-bc72-0a0650eb2642', '唐', '["張司馬，名不詳，乾元中任劍州司馬。","著有《玄晉蘇元明太清石壁記》三卷。","詩二首。","（傳據《新唐書·藝文志》）。"]', '["張司马，名不詳，乾元中任劍州司马。","著有《玄晉蘇元明太清石壁記》三卷。","诗二首。","（傳據《新唐书·藝文志》）。"]', '诗', 'shi', '', NULL, ' 張司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('504efa15-7435-40ed-bd99-2615012cc6af', '還丹口訣', '還丹口訣', '61574eee-0e89-45a8-bc72-0a0650eb2642', '唐', '["九九之中乾體開，華池金液自徘徊。","陰陽鼎上先光彩，鉛花鑪裏考三才。","即知造化由人手，術正藥真神自來。","到此修時應出世，四時不用苦相催。","（五代後蜀人著《大還丹照鑒》）。"]', '["九九之中乾體开，华池金液自徘徊。","陰陽鼎上先光彩，鉛花鑪裏考三才。","即知造化由人手，術正藥真神自来。","到此修时應出世，四时不用苦相催。","（五代後蜀人著《大還丹照鑒》）。"]', '诗', 'shi', '', NULL, '還丹口訣 張司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febe19dd-40ce-4a97-9bfb-7b3875b53258', '歌', '歌', '61574eee-0e89-45a8-bc72-0a0650eb2642', '唐', '["其色光輝耀日月，無窮改變不思議。","但住鉛砂成寶後，歇頭一任丙丁吹。","（同前）。"]', '["其色光輝耀日月，無窮改变不思議。","但住鉛砂成寶後，歇头一任丙丁吹。","（同前）。"]', '诗', 'shi', '', NULL, '歌 張司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e162cf19-9693-44ea-bc6c-85278022b6cb', '大還丹口訣', '大還丹口訣', '297103e8-13c2-458a-a719-49e2670d8a81', '唐', '["岷山寶室九仙居，日月縈迴洞底虛。","爲有真人常鎮此，玉留盤結氣長舒。","曾遊海嶠崑丘客，遠控龍駢亦探賾。","鍊得精華九轉成，中有白銀相韞積。","月中玉兔坎中陽，外柔形容內有剛。","二象雄雌同一體，還如金向水中藏。","金水相合是魂魄，三才變異誠難測。","倐然龍虎兩交幷，化得龍兒在杳冥。","狀似凝酥黃芽雪，亦如玄圃玉華結。","本非世上起機心，元是真人留祕訣。","留祕訣，不參差，晃山石室有丹砂。","至道之人依此法，飛取青龍作一家。","季魂周天成氣質，重與水銀相固密。","似子還婚小女兒，蘇張下說情難失。","相傳此物是黃芽，重重金鼎貯金華，制成雄黃偃藥砂。","六一緘封須祕密，莫教神室有纖瑕。","火候初從一陽起，乾坤兩卦成終始。","文經武緯啓靈機，一法先王傳祕旨。","蟾蜍天上盡還生，丹鼎開時見道情。","每度恢奇別起象，璘㻞紅紫狀難名。","却取金合雄作匱，世光流盡赤龍飛。","燒金學道岷山子，親得真人受玄旨。","玄旨唯論汞與鉛，修得黃芽身不死。","鍊丹鍊志兼鍊神，不營名利顯清芬。","逃名遠去塵埃外，棲託空閑契上真。","莫學人寰囂薄士，役役終身愛名利。","雖然有意慕椿年，未免將身在朝市。","（後蜀無名氏著《大還丹照鑒》）。"]', '["岷山寶室九仙居，日月縈迴洞底虛。","爲有真人常鎮此，玉留盤結氣长舒。","曾游海嶠崑丘客，远控龙駢亦探賾。","鍊得精华九轉成，中有白銀相韞積。","月中玉兔坎中陽，外柔形容內有剛。","二象雄雌同一體，還如金向水中藏。","金水相合是魂魄，三才变異誠难測。","倐然龙虎兩交幷，化得龙兒在杳冥。","狀似凝酥黄芽雪，亦如玄圃玉华結。","本非世上起機心，元是真人留祕訣。","留祕訣，不參差，晃山石室有丹砂。","至道之人依此法，飞取青龙作一家。","季魂周天成氣質，重與水銀相固密。","似子還婚小女兒，蘇張下说情难失。","相傳此物是黄芽，重重金鼎貯金华，制成雄黄偃藥砂。","六一緘封須祕密，莫教神室有纖瑕。","火候初從一陽起，乾坤兩卦成終始。","文經武緯啓靈機，一法先王傳祕旨。","蟾蜍天上尽還生，丹鼎开时见道情。","每度恢奇別起象，璘㻞紅紫狀难名。","却取金合雄作匱，世光流尽赤龙飞。","燒金学道岷山子，親得真人受玄旨。","玄旨唯論汞與鉛，修得黄芽身不死。","鍊丹鍊志兼鍊神，不營名利显清芬。","逃名远去塵埃外，棲託空闲契上真。","莫学人寰囂薄士，役役終身愛名利。","雖然有意慕椿年，未免將身在朝市。","（後蜀無名氏著《大還丹照鑒》）。"]', '诗', 'shi', '', NULL, '大還丹口訣 崔玄真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('742b9fb7-d569-4f1e-83fd-8580177773f7', '題泗水亭', '題泗水亭', '73209059-4a9e-4c87-9fc7-272cbc847160', '唐', '["春風落東林，綠葉翳重陰。","流鶯坐花塢，宛傳來清音。","和光沛天地，樂意同人心。","卷簾出庭戶，獨立蒼苔深。","（《海昌勝跡志》卷二。","此首承陶敏先生錄示。","）。"]', '["春风落东林，綠葉翳重陰。","流鶯坐花塢，宛傳来清音。","和光沛天地，乐意同人心。","卷簾出庭戶，独立蒼苔深。","（《海昌勝跡志》卷二。","此首承陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '題泗水亭 許遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e79a93-ce66-4083-a0d3-bd5b060ecc7b', '同房侍御竹園新亭與邢大判官同遊', '同房侍御竹园新亭與邢大判官同游', '81d65a2b-62c5-4bfe-8715-f10754403f3b', '唐', '["隱隱春城東，朦朧陳近深。","君子顧榛莽，興言傷古今。","決河道新流，疎逕蹤舊林。","開亭俯川陸，時景宜招尋。","肅穆逢使軒，寅猶事登臨。","忝遊芝蘭下，還對桃李陰。","峯遠白波來，氣喧黃鳥吟。","因覩歌頌作，始知經濟心。","灌（疑）壇（疑）縣（小川環樹疑此字涉下文而衍）有遺風，單父多鳴琴。","誰得久州縣，蒼生懷德音。","（日本藏唐抄本《新撰類林抄》卷四）。"]', '["隐隐春城东，朦朧陳近深。","君子顧榛莽，兴言傷古今。","決河道新流，疎逕蹤旧林。","开亭俯川陸，时景宜招尋。","肅穆逢使軒，寅猶事登臨。","忝游芝蘭下，還对桃李陰。","峯远白波来，氣喧黄鸟吟。","因覩歌頌作，始知經濟心。","灌（疑）壇（疑）縣（小川环樹疑此字涉下文而衍）有遺风，單父多鳴琴。","誰得久州縣，蒼生懷德音。","（日本藏唐抄本《新撰類林抄》卷四）。"]', '诗', 'shi', '', NULL, '同房侍御竹園新亭與邢大判官同遊 張垍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ef8f72-40ba-4c79-b6b1-f04472080005', '謁聖容', '謁聖容', 'bcb37ce8-0ffa-4790-a43f-0002fb9a596d', '唐', '["法雨震天雷，祁山一半頹。","鱗鱗碧玉色，寂寂現如來。","縲髻從烟合，圓光滿月開。","從茲一頂謁，永劫去塵埃。"]', '["法雨震天雷，祁山一半頹。","鱗鱗碧玉色，寂寂現如来。","縲髻從烟合，圓光满月开。","從茲一頂謁，永劫去塵埃。"]', '诗', 'shi', '', NULL, '謁聖容 渾惟明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed56c0d7-8ec6-4748-9345-dd7dbe06e0d5', '吐蕃党舍人臨刑', '吐蕃党舍人臨刑', 'bcb37ce8-0ffa-4790-a43f-0002fb9a596d', '唐', '["生死誰能免，嗟君最可憐。","幼男猶在抱，老母未終年。","爲復冥徒任，爲當命合然。","設將泉下事，時向夢中傳。","（均見伯三六一九卷，原署「渾維明」）。"]', '["生死誰能免，嗟君最可怜。","幼男猶在抱，老母未終年。","爲复冥徒任，爲當命合然。","設將泉下事，时向梦中傳。","（均见伯三六一九卷，原署「渾維明」）。"]', '诗', 'shi', '', NULL, '吐蕃党舍人臨刑 渾惟明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887edca6-4dd2-468f-95cc-005e9624e8f6', '述懷', '述懷', '45ea89a4-30fa-4997-91a2-5f33328df75b', '唐', '["昔在{亠/樂，木=水}（疑應作「灤」）河外，征馬倦風塵。","今來洛陽道，人事復艱辛。","有策懷明主，無媒託近臣。","君門不可見，歸去淥山春。"]', '["昔在{亠/乐，木=水}（疑應作「灤」）河外，征马倦风塵。","今来洛陽道，人事复艱辛。","有策懷明主，無媒託近臣。","君门不可见，归去淥山春。"]', '诗', 'shi', '', NULL, '述懷 史昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e3ea1a-7f9c-4d72-9648-25a617908cee', '野外遙[占]渾將軍', '野外遙[占]渾將軍', '45ea89a4-30fa-4997-91a2-5f33328df75b', '唐', '["山頭一隊欲陵（當作「凌」）雲，白馬紅旗纓（此處衍一字）出衆羣。","諸人氣色不如此，祇應者箇是將軍。","（見伯三六一九卷、伯三八八五卷）。"]', '["山头一隊欲陵（當作「凌」）云，白马紅旗纓（此处衍一字）出衆羣。","諸人氣色不如此，祇應者箇是將軍。","（见伯三六一九卷、伯三八八五卷）。"]', '诗', 'shi', '', NULL, '野外遙[占]渾將軍 史昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c71ea2-4d8c-4635-af5d-e0b1c572186a', '書訣', '书訣', 'b97ab22b-211c-48ce-9ad9-98513f7a2102', '唐', '["剡紙易墨，心圓管直。","漿深色濃，萬毫齊力。","先臨告誓，次寫《黃庭》。","骨豐肉潤，入妙通靈。","努如直槊，勒若橫釘。","虛專妥帖，毆鬬崢嶸。","開張鳳翼，聳擢芝英。","粗不爲重，細不爲輕。","纖微向背，毫髮死生。","工之未盡，已擅時名。"]', '["剡紙易墨，心圓管直。","漿深色濃，万毫齊力。","先臨告誓，次寫《黄庭》。","骨豐肉潤，入妙通靈。","努如直槊，勒若橫釘。","虛專妥帖，毆鬬崢嶸。","开張鳳翼，聳擢芝英。","粗不爲重，細不爲轻。","纖微向背，毫髮死生。","工之未尽，已擅时名。"]', '诗', 'shi', '', NULL, '書訣 張懷瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4da27f3-2e8f-49fa-b4f5-ef9a4de6452b', '詩', '诗', 'b97ab22b-211c-48ce-9ad9-98513f7a2102', '唐', '["向展右背，長伸左足。","峻角一支，潛虛半腹。","已放則留，無垂不縮。","分若抵背，合還口並目。","似側暎斜，似斜附曲。","覃精一字，工歸自得。","盈虛統視聯行，妙在相承起伏。","（均見宋朱長文《墨池編》卷二引張懷瓘《玉堂禁經》）。"]', '["向展右背，长伸左足。","峻角一支，潛虛半腹。","已放則留，無垂不縮。","分若抵背，合還口並目。","似側暎斜，似斜附曲。","覃精一字，工归自得。","盈虛統視聯行，妙在相承起伏。","（均见宋朱长文《墨池編》卷二引張懷瓘《玉堂禁經》）。"]', '诗', 'shi', '', NULL, '詩 張懷瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e940c7-1b10-4ea2-a1d5-42a0a36dd9ba', '石榴詩', '石榴诗', '2efa768f-df91-4108-96f9-9a2a21c3e48c', '唐', '["三月四月紅花裏，五月六月瓶子裏。","作刀割破黃胞衣，六七千箇赤男女。","（見唐姚汝能《安祿山事跡》卷下）。"]', '["三月四月紅花裏，五月六月瓶子裏。","作刀割破黄胞衣，六七千箇赤男女。","（见唐姚汝能《安祿山事跡》卷下）。"]', '诗', 'shi', '', NULL, '石榴詩 史思明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f38cce9-28d8-421d-a7eb-333d9e9ed438', '以櫻桃賜子朝義及周贄（題擬）', '以櫻桃賜子朝義及周贄（題擬）', '2efa768f-df91-4108-96f9-9a2a21c3e48c', '唐', '["櫻桃一籠子，半赤一半黃（《太平廣記》卷四九五引《芝田錄》此句作「半已赤，半已黃」）。","一半與懷王，一半與周贄。","（同前）（按：《全唐詩》卷八六九收此詩，首句缺二字，今重錄。","）。"]', '["櫻桃一籠子，半赤一半黄（《太平廣記》卷四九五引《芝田錄》此句作「半已赤，半已黄」）。","一半與懷王，一半與周贄。","（同前）（按：《全唐诗》卷八六九收此诗，首句缺二字，今重錄。","）。"]', '诗', 'shi', '', NULL, '以櫻桃賜子朝義及周贄（題擬） 史思明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6df88c9-6051-4f7f-9871-1d5d561ab414', '長生草', '长生草', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["老根那復占春晴，能住虛根自發生。","（見《剡錄》卷十。","疑僞）。"]', '["老根那复占春晴，能住虛根自發生。","（见《剡錄》卷十。","疑僞）。"]', '诗', 'shi', '', NULL, '長生草 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67872764-9baa-4113-a600-5f95ac63c635', '四大無主偈', '四大無主偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["四大無[主]（心）（從《景德傳燈錄》改）復如水，遇曲逢直無彼此。","淨穢兩處不生心，壅決何曾有二意。","境觸（《景德傳燈錄》作「觸境」）但似水無心，在世縱橫有何事。"]', '["四大無[主]（心）（從《景德傳灯錄》改）复如水，遇曲逢直無彼此。","淨穢兩处不生心，壅決何曾有二意。","境觸（《景德傳灯錄》作「觸境」）但似水無心，在世縱橫有何事。"]', '诗', 'shi', '', NULL, '四大無主偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c72645-37f1-4d52-b054-4302bba51df0', '見聞覺知偈', '见闻覺知偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["見聞覺知無障礙，聲香味觸常三昧。","如鳥空中只沒（《景德傳燈錄》作「麽」）飛，無取無捨無憎愛。","若會應處本無心，方（《景德傳燈錄》作「始」）得名爲觀自在。","。"]', '["见闻覺知無障礙，声香味觸常三昧。","如鸟空中只沒（《景德傳灯錄》作「麽」）飞，無取無捨無憎愛。","若會應处本無心，方（《景德傳灯錄》作「始」）得名爲观自在。","。"]', '诗', 'shi', '', NULL, '見聞覺知偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9944e828-bff8-4914-b20c-94741b25d9d7', '無修偈', '無修偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["見道方修道，不見復何修。","道性如虛空，虛空何處（《景德傳燈錄》作「所」）修。","遍觀修道者，撥火覓浮漚。","但看弄傀儡，線斷一時休。"]', '["见道方修道，不见复何修。","道性如虛空，虛空何处（《景德傳灯錄》作「所」）修。","遍观修道者，撥火覓浮漚。","但看弄傀儡，線斷一时休。"]', '诗', 'shi', '', NULL, '無修偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fc263c-dd14-492f-9c3f-1bd8171684b9', '背道逐教偈', '背道逐教偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["道體本無修，不修自合道。","若起修道心，此人未（《景德傳燈錄》作「不」）會道。","棄却一真性，却入鬧浩浩。","忽逢修道人，第一莫向道。"]', '["道體本無修，不修自合道。","若起修道心，此人未（《景德傳灯錄》作「不」）會道。","棄却一真性，却入鬧浩浩。","忽逢修道人，第一莫向道。"]', '诗', 'shi', '', NULL, '背道逐教偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e48be0-1fe9-4c4f-a41d-144a94186435', '真妄偈', '真妄偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["窮（《景德傳燈錄》作「推」）真真無相，窮妄妄無形。","返觀推窮心，知心亦假名。","會道既（《景德傳燈錄》作「亦」）如此，到頭亦只寧。"]', '["窮（《景德傳灯錄》作「推」）真真無相，窮妄妄無形。","返观推窮心，知心亦假名。","會道既（《景德傳灯錄》作「亦」）如此，到头亦只寧。"]', '诗', 'shi', '', NULL, '真妄偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715f5059-1f8d-4f26-90f6-c81efac839a0', '善惡二根不實偈', '善惡二根不實偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["善既從心生，惡豈離心有。","善惡是外緣，於心實不有。","捨惡送何處，取善令誰守？","傷嗟二見人，攀緣兩頭走。","忽悟無生本（《景德傳燈錄》作「若悟本無心」），始會（《景德傳燈錄》作「悔」）從前咎。"]', '["善既從心生，惡豈離心有。","善惡是外緣，於心實不有。","捨惡送何处，取善令誰守？","傷嗟二见人，攀緣兩头走。","忽悟無生本（《景德傳灯錄》作「若悟本無心」），始會（《景德傳灯錄》作「悔」）從前咎。"]', '诗', 'shi', '', NULL, '善惡二根不實偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052cd1eb-c406-430c-ad15-1c13a1999d89', '來往如夢偈', '来往如梦偈', 'efbd732f-5595-4984-9349-31dc55449d98', '唐', '["亦知（《景德傳燈錄》作「視生」）如在夢，睡（《景德傳燈錄》作「夢」）裏實是鬧。","忽覺萬事休，還同睡時覺（《景德傳燈錄》作「悟」）。","智者會悟夢，迷人信夢鬧。","會夢無（《景德傳燈錄》作「如」）兩般，一悟無別悟。","富貴與貧賤，更亦無別道（《景德傳燈錄》作「更無分別路」。","《祖堂集》卷三、《景德傳燈錄》卷五、《五燈會元》卷二）。"]', '["亦知（《景德傳灯錄》作「視生」）如在梦，睡（《景德傳灯錄》作「梦」）裏實是鬧。","忽覺万事休，還同睡时覺（《景德傳灯錄》作「悟」）。","智者會悟梦，迷人信梦鬧。","會梦無（《景德傳灯錄》作「如」）兩般，一悟無別悟。","富貴與貧賤，更亦無別道（《景德傳灯錄》作「更無分別路」。","《祖堂集》卷三、《景德傳灯錄》卷五、《五灯會元》卷二）。"]', '诗', 'shi', '', NULL, '來往如夢偈 本淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a16385-1ebb-4923-a397-23253e7a0498', '紫陽真人歌（幷序）', '紫陽真人歌（幷序）', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["君不見先生耳鼻有仙骨，自號狂生中有物。","金華侍講三十年，兒戲公卿與簪笏。","青門抗行謝客兒，健筆連羈王獻之。","長安素絹書欲徧，主人愛惜常保持。","每歎二疏不足道，復言四皓常枯槁。","去年寢疾彌數旬，神鬼盈庭謀一老。","長男泣血求司命，少女[顰]（頻）眉誦《靈寶》。","還如簡子復歸來，更與洪崖同壽考。","上書北闕言授籙。","稅駕東州願修道。","初聞行路猶未信，果達吾君謂之好。","山陰舊宅作仙壇，湖上閑田種芝草。","鏡湖之水含杳冥，會稽仙洞多精靈。","須乘赤鯉遊滄海，當以羣鵝寫道經。","皇恩贈詩四十字，明主賜金三十鎰。","供帳傾朝一送歸，雙童駟馬從茲出。","迴看紫綬若輕塵，遠別青門嗟故人。","鴛鷺差池攀羽蓋，虹霓夭矯翊車輪。","田田列侍浮丘伯，曾子榮過朱買臣。","余高若是有先覺，滅蹟歸根從大樸。","千載悠悠等令威，十洲漫漫思方朔。","歸去來，青牛頓足少遲迴。","忽然雲霧不相見，唯有飄飄香氣來。","（見宋孔延之編《會稽掇英總集》卷二）。"]', '["君不见先生耳鼻有仙骨，自號狂生中有物。","金华侍講三十年，兒戲公卿與簪笏。","青门抗行謝客兒，健笔連羈王獻之。","长安素絹书欲徧，主人愛惜常保持。","每歎二疏不足道，复言四皓常枯槁。","去年寢疾彌數旬，神鬼盈庭謀一老。","长男泣血求司命，少女[顰]（頻）眉誦《靈寶》。","還如簡子复归来，更與洪崖同壽考。","上书北闕言授籙。","稅駕东州願修道。","初闻行路猶未信，果達吾君謂之好。","山陰旧宅作仙壇，湖上闲田種芝草。","镜湖之水含杳冥，會稽仙洞多精靈。","須乘赤鯉游滄海，當以羣鵝寫道經。","皇恩贈诗四十字，明主賜金三十鎰。","供帳傾朝一送归，雙童駟马從茲出。","迴看紫綬若轻塵，远別青门嗟故人。","鴛鷺差池攀羽蓋，虹霓夭矯翊车輪。","田田列侍浮丘伯，曾子榮過朱買臣。","余高若是有先覺，滅蹟归根從大樸。","千載悠悠等令威，十洲漫漫思方朔。","归去来，青牛頓足少遲迴。","忽然云霧不相见，唯有飄飄香氣来。","（见宋孔延之編《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '紫陽真人歌（幷序） 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1dedce-bc04-4a9d-ac50-66c8616a31cf', '寄雲門亮師', '寄云门亮師', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["玄度常稱支道林，南山隱處白雲深。","一去人間長不見，千峰萬壑樹森森。","（同前書卷七）。"]', '["玄度常稱支道林，南山隐处白云深。","一去人间长不见，千峰万壑樹森森。","（同前书卷七）。"]', '诗', 'shi', '', NULL, '寄雲門亮師 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3cc1ff-4c2d-4ec4-b47e-9ea9d31b392e', '詩送玄靜先生赴金壇（題擬）', '诗送玄静先生赴金壇（題擬）', '145ef57a-612d-494f-8347-b96417298558', '唐', '["紫府煙霞士，玄宗道德師。","心將萬籟合，志與九仙期。","絕俗遺塵境，同人喜濟時。","訪經遊玉洞，敷教入瑤墀。","茅嶺追餘跡，金壇赴遠思。","陰宮春舊記，陽觀飭新祠。","緬想埋雙璧，長懷採五芝。","真靈若可遇，鸞鶴佇來茲。","（詳後。","此首又見《嘉定鎮江志》卷二十）（按：《茅山志》卷二收玄宗賜李玄靜先生勑書二十四通，此詩見第三道勑內。","此勑書全文錄如次：「勑。","廣陵李鍊師，上清品人也。","抗志雲霞，和光代俗。","爲予修福靈跡，將赴金壇，故賦詩寵行，以美其志。","〖詩略〗尊師抱一守中，探微昭遠，能回貞潔，發揮道門。","遂與太和先生啓是仙宗，起予虔奉，崇飭靈跡，廣求真經。","則詩以寵行，物將厚意，永慰歧路，以彰禮賢也。","所謝知。","」又按，據同書同卷所附玄靜先生等表奏，知此詩爲天寶六載九月二十五日作，由高力士宣賜。","）。"]', '["紫府煙霞士，玄宗道德師。","心將万籟合，志與九仙期。","絕俗遺塵境，同人喜濟时。","訪經游玉洞，敷教入瑤墀。","茅嶺追餘跡，金壇赴远思。","陰宮春旧記，陽观飭新祠。","緬想埋雙璧，长懷採五芝。","真靈若可遇，鸾鹤佇来茲。","（詳後。","此首又见《嘉定鎮江志》卷二十）（按：《茅山志》卷二收玄宗賜李玄静先生勑书二十四通，此诗见第三道勑內。","此勑书全文錄如次：「勑。","廣陵李鍊師，上清品人也。","抗志云霞，和光代俗。","爲予修福靈跡，將赴金壇，故賦诗寵行，以美其志。","〖诗略〗尊師抱一守中，探微昭远，能回貞潔，發揮道门。","遂與太和先生啓是仙宗，起予虔奉，崇飭靈跡，廣求真經。","則诗以寵行，物將厚意，永慰歧路，以彰禮賢也。","所謝知。","」又按，據同书同卷所附玄静先生等表奏，知此诗爲天寶六載九月二十五日作，由高力士宣賜。","）。"]', '诗', 'shi', '', NULL, '詩送玄靜先生赴金壇（題擬） 玄宗皇帝李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a13d73-4835-44af-9217-73ba21b8f797', '詩送玄靜先生暫還廣陵（幷序）', '诗送玄静先生暫還廣陵（幷序）', '145ef57a-612d-494f-8347-b96417298558', '唐', '["楊許開真籙，夫君密契傳。","九星連紫蓋，雙景合丹田，玉簡龜臺職，金壇洞府仙。","猶期禦風便，朝夕候泠然。"]', '["楊許开真籙，夫君密契傳。","九星連紫蓋，雙景合丹田，玉簡龟台職，金壇洞府仙。","猶期禦风便，朝夕候泠然。"]', '诗', 'shi', '', NULL, '詩送玄靜先生暫還廣陵（幷序） 玄宗皇帝李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7465bea0-1be0-45d6-823e-a5b5f5ed84d2', '詩送玄靜先生歸廣陵（幷序）', '诗送玄静先生归廣陵（幷序）', '145ef57a-612d-494f-8347-b96417298558', '唐', '["默受王倪道，逾深尹喜師。","欣同八景會，更叶九丹時。","鸞鶴遙煙境，江山渺別思。","當遷洞庭日，留念上京期。","（以上三首幷見《正統道藏》本元劉大彬撰《茅山志》卷二）（按：據同書同卷附玄靜先生等表奏，前二詩中之一首爲天寶十載九月十四日由內侍袁思藝宣勑。","又玄靜先生即李含光，爲茅山宗第十三代宗師，事跡詳《顏魯公文集》卷七《有唐茅山玄靖先生廣陵李君碑銘》。","〖1〗《輿地紀勝》卷十七《建康府》「碑記」云：「《賜李煉師詩詔》，唐道士任良友書。","玄宗所賜詩，凡三首，貞元十四年刻石。","在茅山。","」）。"]', '["默受王倪道，逾深尹喜師。","欣同八景會，更叶九丹时。","鸾鹤遙煙境，江山渺別思。","當遷洞庭日，留念上京期。","（以上三首幷见《正統道藏》本元劉大彬撰《茅山志》卷二）（按：據同书同卷附玄静先生等表奏，前二诗中之一首爲天寶十載九月十四日由內侍袁思藝宣勑。","又玄静先生即李含光，爲茅山宗第十三代宗師，事跡詳《顏魯公文集》卷七《有唐茅山玄靖先生廣陵李君碑銘》。","〖1〗《輿地紀勝》卷十七《建康府》「碑記」云：「《賜李煉師诗詔》，唐道士任良友书。","玄宗所賜诗，凡三首，貞元十四年刻石。","在茅山。","」）。"]', '诗', 'shi', '', NULL, '詩送玄靜先生歸廣陵（幷序） 玄宗皇帝李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982ce316-0746-45c2-bb37-a69b8873c4ed', '送道士薛季昌還山（補序）', '送道士薛季昌還山（補序）', '145ef57a-612d-494f-8347-b96417298558', '唐', '["空（按：此詩《全唐詩》卷三已收入。","茲據唐李沖昭《南嶽小錄》補序。","《大正新修大藏經》第五十一冊收宋陳田夫《南嶽總勝集》卷下，載此序異文較多，另錄如次以備攷：「煉師志慕玄門，棲心南嶽。","及登道籙，忽然來辭，願歸舊山，以守虛白。","不違雅志，且重精修，若遇真人靈藥，時來城闕也。","」）。"]', '["空（按：此诗《全唐诗》卷三已收入。","茲據唐李沖昭《南嶽小錄》補序。","《大正新修大藏經》第五十一冊收宋陳田夫《南嶽總勝集》卷下，載此序異文較多，另錄如次以備攷：「煉師志慕玄门，棲心南嶽。","及登道籙，忽然来辞，願归旧山，以守虛白。","不違雅志，且重精修，若遇真人靈藥，时来城闕也。","」）。"]', '诗', 'shi', '', NULL, '送道士薛季昌還山（補序） 玄宗皇帝李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea70707-00ea-4090-ae55-4339ba6b70c6', '批答安祿山賀雪兼賜口號（題擬）', '批答安祿山賀雪兼賜口號（題擬）', '145ef57a-612d-494f-8347-b96417298558', '唐', '["臘月忻三[白]（日），嘉平安四鄰。","預知天下稔，先爲物華春。","（見上海古籍出版社排印本《安祿山事迹》卷上）（〖1〗《安祿山事迹》：「其〖天寶九載〗冬，久無雪，至十二月十四日乃雪，祿山表賀焉。","玄宗批答兼口號以賜之曰〖詩略〗。","其見重如此。","」）。"]', '["臘月忻三[白]（日），嘉平安四鄰。","預知天下稔，先爲物华春。","（见上海古籍出版社排印本《安祿山事迹》卷上）（〖1〗《安祿山事迹》：「其〖天寶九載〗冬，久無雪，至十二月十四日乃雪，祿山表賀焉。","玄宗批答兼口號以賜之曰〖诗略〗。","其见重如此。","」）。"]', '诗', 'shi', '', NULL, '批答安祿山賀雪兼賜口號（題擬） 玄宗皇帝李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be7a2594-116c-4f8f-8358-2e5e8bda4826', '攻玉賦附卞生追怨之歌', '攻玉賦附卞生追怨之歌', 'a8ec69c2-478e-447c-835c-6aae873fc4a8', '唐', '["昔之玉在石，石在山，山有玉兮隱其間。","今則石爲錯，玉爲環，環亦獻兮君解顏。","遂與生芻爲比，與郄桂同攀。","豈辛勤於道路，徒抱泣於荆蠻。","（見《文苑英華》卷一一五）。"]', '["昔之玉在石，石在山，山有玉兮隐其间。","今則石爲錯，玉爲环，环亦獻兮君解顏。","遂與生芻爲比，與郄桂同攀。","豈辛勤於道路，徒抱泣於荆蠻。","（见《文苑英华》卷一一五）。"]', '诗', 'shi', '', NULL, '攻玉賦附卞生追怨之歌 趙昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec63b9e-8969-4cfa-897a-b1312d660019', '江夏送倩公歸漢東（幷序）', '江夏送倩公归漢东（幷序）', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["彼美漢東國，川藏明月輝。","寧知喪亂後，更有一珠歸。","（錄自影宋蜀刻本《李太白文集》卷二十七）。"]', '["彼美漢东国，川藏明月輝。","寧知喪亂後，更有一珠归。","（錄自影宋蜀刻本《李太白文集》卷二十七）。"]', '诗', 'shi', '', NULL, '江夏送倩公歸漢東（幷序） 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246a6cf2-c8db-443e-b581-64f6d35c3df5', '別匡山', '別匡山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["曉峰如畫碧參差（碑作「參差碧」），藤影風搖拂檻垂。","野徑來多將犬伴，人間歸晚帶（碑作「待」）樵隨。","看雲客倚啼猿樹，洗鉢僧臨失鶴（一作「鷺」，或作「鶩」）池。","莫怪無心戀清境，已將書劍許明時。","（見光緒《重修江油縣志》卷二十四）（陳廣福《李白的〈別匡山〉詩考》謂江油縣匡山書院存宋熙寧元年《勅賜中和大明寺住持碑》，碑文云：「玄宗朝翰林學士李白字太白，少爲當縣小吏，後於此山讀書，於喬松滴翠之平有十載。","」文中錄此詩。","）。"]', '["晓峰如畫碧參差（碑作「參差碧」），藤影风搖拂檻垂。","野徑来多將犬伴，人间归晚带（碑作「待」）樵隨。","看云客倚啼猿樹，洗鉢僧臨失鹤（一作「鷺」，或作「鶩」）池。","莫怪無心戀清境，已將书劍許明时。","（见光緒《重修江油縣志》卷二十四）（陳廣福《李白的〈別匡山〉诗考》謂江油縣匡山书院存宋熙寧元年《勅賜中和大明寺住持碑》，碑文云：「玄宗朝翰林学士李白字太白，少爲當縣小吏，後於此山读书，於喬松滴翠之平有十載。","」文中錄此诗。","）。"]', '诗', 'shi', '', NULL, '別匡山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('864837b3-b784-45cd-bc64-0821886709fe', '太華觀', '太华观', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["厄磴層層上太華，白雲深處有人家。","道童對月閒吹笛，仙子乘雲遠駕車。","恠石堆山如坐虎，老藤纏樹似騰蛇。","曾聞玉井金河在，會見蓬萊十丈花。","（同前）。"]', '["厄磴層層上太华，白云深处有人家。","道童对月閒吹笛，仙子乘云远駕车。","恠石堆山如坐虎，老藤纏樹似腾蛇。","曾闻玉井金河在，會见蓬萊十丈花。","（同前）。"]', '诗', 'shi', '', NULL, '太華觀 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a6c7a9-7b78-4cae-8bdf-157f70e256e4', '觀佽飛斬蛟龍圖讚', '观佽飞斬蛟龙圖讚', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["佽飛斬長蛟，遺圖畫中見。","登舟既虎嘯，激水方龍戰。","驚波動連山，拔劍曳雷電。","鱗摧白刃下，血染滄江變。","感此壯古人，千秋（一作「載」）若對面。","（見《李太白文集》卷二十八）。"]', '["佽飞斬长蛟，遺圖畫中见。","登舟既虎嘯，激水方龙戰。","驚波动連山，拔劍曳雷電。","鱗摧白刃下，血染滄江变。","感此壯古人，千秋（一作「載」）若对面。","（见《李太白文集》卷二十八）。"]', '诗', 'shi', '', NULL, '觀佽飛斬蛟龍圖讚 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60a15ad-8775-467a-84d3-051280507e11', '地藏菩薩讚', '地藏菩薩讚', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["本心若虛空，清淨無一物。","焚蕩淫怒癡，圓寂了見佛。","五綵圖聖像，悟真非妄傳。","掃雪萬病盡，爽然清凉天。","讚此功德海，永爲曠代宣。","（同前）。"]', '["本心若虛空，清淨無一物。","焚蕩淫怒癡，圓寂了见佛。","五綵圖聖像，悟真非妄傳。","掃雪万病尽，爽然清凉天。","讚此功德海，永爲曠代宣。","（同前）。"]', '诗', 'shi', '', NULL, '地藏菩薩讚 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d3d21cd-e805-43c1-9509-d72d83994064', '獨坐敬亭山（其二）', '独坐敬亭山（其二）', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["合沓牽數峰，奔地鎮平楚。","中間最高頂，髣髴接天語。","（見《宛陵郡志備要》。","又見嘉慶廿年刊洪亮吉纂《寧國府志》卷二四）。"]', '["合沓牽數峰，奔地鎮平楚。","中间最高頂，髣髴接天語。","（见《宛陵郡志備要》。","又见嘉慶廿年刊洪亮吉纂《寧国府志》卷二四）。"]', '诗', 'shi', '', NULL, '獨坐敬亭山（其二） 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47617aaf-9f47-4c4a-bc2e-e423d4e1c6fd', '秀華亭', '秀华亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遙望九華峰，誠然是九華。","蒼顏耐風雪，奇態燦雲霞。","曜日凝成錦，凌霄增壁崖。","何當餘蔭照，天造洞仙家。","（見《青陽縣志·藝文志》及《九華山志》卷八）（〖1〗《李白在安徽》云：秀華亭在九華山麓，五溪橋側，延壽寺前。","亭已圮，遺址猶存。","）。"]', '["遙望九华峰，誠然是九华。","蒼顏耐风雪，奇態燦云霞。","曜日凝成錦，凌霄增壁崖。","何當餘蔭照，天造洞仙家。","（见《青陽縣志·藝文志》及《九华山志》卷八）（〖1〗《李白在安徽》云：秀华亭在九华山麓，五溪橋側，延壽寺前。","亭已圮，遺址猶存。","）。"]', '诗', 'shi', '', NULL, '秀華亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18d8740-167c-4fe8-9673-7bcd4d8e5ef3', '煉丹井', '煉丹井', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聞說神仙晉葛洪，煉丹曾此占雲峰。","庭前廢井今猶在，不見長松見短松。","（見《宛陵郡志備要》卷一。","又見嘉慶《寧國府志》卷二四）（〖1〗《李白在安徽》云：井在九華山臥雲庵北面。","）。"]', '["闻说神仙晉葛洪，煉丹曾此占云峰。","庭前廢井今猶在，不见长松见短松。","（见《宛陵郡志備要》卷一。","又见嘉慶《寧国府志》卷二四）（〖1〗《李白在安徽》云：井在九华山臥云庵北面。","）。"]', '诗', 'shi', '', NULL, '煉丹井 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc5c752-5c9f-43be-9bb6-89963f0e8683', '宿無相寺', '宿無相寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["頭陀懸萬仞，遠眺望華峰。","聊借金沙水，洗開九芙蓉。","煙嵐隨遍覽，踏屐走雙龍。","明日登高去，山僧孰與從？","禪床今暫歇，枕月臥青松。","更盡聞呼鳥，恍來報曉鐘。","（詳後，以上四首，皆轉錄自常秀峰等著《李白在安徽》。","）（〖1〗《李白在安徽》云：此詩刻於清道光十年《重建無相寺碑記》。","無相寺在九華山頭陀嶺下，旁有一泉，名金沙，李白在九華時曾遊此。","無相寺建於唐初，治平元年賜額，道光間重修。","此詩保存有兩種可能：一，無相寺舊時碑文刻有此詩；二，爲康熙時禮部尚書吳襄收藏，吳姓修寺捐資最多。","）。"]', '["头陀懸万仞，远眺望华峰。","聊借金沙水，洗开九芙蓉。","煙嵐隨遍覽，踏屐走雙龙。","明日登高去，山僧孰與從？","禪床今暫歇，枕月臥青松。","更尽闻呼鸟，恍来報晓鐘。","（詳後，以上四首，皆轉錄自常秀峰等著《李白在安徽》。","）（〖1〗《李白在安徽》云：此诗刻於清道光十年《重建無相寺碑記》。","無相寺在九华山头陀嶺下，旁有一泉，名金沙，李白在九华时曾游此。","無相寺建於唐初，治平元年賜額，道光间重修。","此诗保存有兩種可能：一，無相寺旧时碑文刻有此诗；二，爲康熙时禮部尚书吳襄收藏，吳姓修寺捐資最多。","）。"]', '诗', 'shi', '', NULL, '宿無相寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f75c5aea-e9f3-45b7-b71d-95b712721330', '詠方廣詩', '詠方廣诗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聖寺閑棲睡眼醒，此時何處最幽清？","滿窗明月天風靜，玉磬時聞一兩聲。","（見宋陳田夫《南嶽總勝集》卷中）。"]', '["聖寺闲棲睡眼醒，此时何处最幽清？","满窗明月天风静，玉磬时闻一兩声。","（见宋陳田夫《南嶽總勝集》卷中）。"]', '诗', 'shi', '', NULL, '詠方廣詩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c494cf3-95cc-4f93-b6f7-4e5c9ce843ad', '上清寶鼎詩二首（附存） 一', '上清寶鼎诗二首（附存） 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝披夢澤雲（甲、乙、戊本作「雲夢澤」），笠釣青茫茫。","尋絲（甲作「流」、乙作「綠」）得雙鯉，中有三（乙作「二」）元章。","篆字若丹蛇，逸（乙作「遶」）勢如飛翔。","歸來問天老（甲、戊作「姥」）奧（甲、戊作「妙」）義不可量。","金刀（甲作「刃」）割青素（甲作「紫」），靈文爛煌煌。","嚥（甲、戊作「燕」）服十二環（戊作「鐶」），奄（甲、戊作「想」）見仙人房。","暮跨（丙作「騎」）紫鱗（丙作「麟」）去，海氣侵肌凉。","龍子善（戊作「喜」）變化，化作梅花妝。","贈（甲、戊作「遺」）我纍纍（乙作「疊疊」）珠，靡靡（甲作「非」）明月光。","勸我穿絳（乙作「絡」）縷（甲、戊作「樓」），繫作裙（戊、丁作「裾」）間襠（甲作「當」，戊作「璫」）。","挹（甲、戊作「揖」）子（甲作「予」，丁戊作「余」）以攜（甲作「疾」，乙作「詞」，丁、戊作「辭」）去，談笑聞遺（甲、乙、戊作「餘」）香。","（按：《全唐詩》卷一八五據《王直方詩話》錄「房」、「涼」、「光」三韻，《全唐詩續補遺》卷四錄「茫」、「涼」二韻。","）。"]', '["朝披梦澤云（甲、乙、戊本作「云梦澤」），笠釣青茫茫。","尋絲（甲作「流」、乙作「綠」）得雙鯉，中有三（乙作「二」）元章。","篆字若丹蛇，逸（乙作「遶」）勢如飞翔。","归来问天老（甲、戊作「姥」）奧（甲、戊作「妙」）義不可量。","金刀（甲作「刃」）割青素（甲作「紫」），靈文爛煌煌。","嚥（甲、戊作「燕」）服十二环（戊作「鐶」），奄（甲、戊作「想」）见仙人房。","暮跨（丙作「騎」）紫鱗（丙作「麟」）去，海氣侵肌凉。","龙子善（戊作「喜」）变化，化作梅花妝。","贈（甲、戊作「遺」）我纍纍（乙作「叠叠」）珠，靡靡（甲作「非」）明月光。","勸我穿絳（乙作「絡」）縷（甲、戊作「楼」），繫作裙（戊、丁作「裾」）间襠（甲作「當」，戊作「璫」）。","挹（甲、戊作「揖」）子（甲作「予」，丁戊作「余」）以携（甲作「疾」，乙作「词」，丁、戊作「辞」）去，談笑闻遺（甲、乙、戊作「餘」）香。","（按：《全唐诗》卷一八五據《王直方诗話》錄「房」、「涼」、「光」三韻，《全唐诗續補遺》卷四錄「茫」、「涼」二韻。","）。"]', '诗', 'shi', '', NULL, '上清寶鼎詩二首（附存） 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4407e6ca-9d88-4b1f-ba7f-f101d7e0f133', '上清寶鼎詩二首（附存） 二', '上清寶鼎诗二首（附存） 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["人生燭上花，光（乙作「火」）滅巧妍盡。","春風繞樹頭，日與化（戊作「花」）工（丁作「花工」）進。","只（戊作「惟」）知雨露貪，不聞（丁、戊作「念」）零落盡（甲無以上二句）。","我昔（乙、戊作「昔我」）飛骨時，慘見當塗墳。","青松靄朝（丁、戊作「明」）霞，縹緲山（戊作「上」）丁村。","既死明月魄，無復（丁、戊作「彼」）玻璃（乙、戊作「瓈」）魂。","念此一脫灑（戊作「酒」），長嘯祭（甲、乙、戊作「登」）崑崙。","醉著鸞皇（甲、丁、戊作「鳳」）衣，星斗俯可捫。","（見瞿蛻園、朱金城《李白集校注》卷三十《詩文補遺》錄蘇軾書李白詩墨跡。","出校各本，甲本爲趙令畤《侯鯖錄》卷二，乙本指《增修詩話總龜》卷十一引《王直方詩話》，丙本指《全唐詩》卷一八五引《王直方詩話》，丁本指《李白詩校注》據《唐宋詩醇》所錄校語，戊本指《津逮秘書》本《東坡題跋》卷二）（〖1〗《東坡題跋》卷二：「余頃在京師，有道人相訪，風骨甚異，語論不凡，自云常與物外諸公往還，口誦此二篇，云東華上清監清逸真人李太白作也。","」〖2〗《侯鯖錄》卷二：「東坡先生在嶺南，言元祐中有見李白酒肆中誦其近詩云：『朝披夢澤雲，笠釣青茫茫。","』此非世人語也。","少游嘗手錄其全篇，少游敍云：『觀頃在京師，有道人相訪，風骨甚異，語論不凡，自云嘗與物外諸公往還，口誦二篇，云東華上清監清逸真人李白作也。","』」）（〖3〗《王直方詩話》：「元祐八年，東坡帥定武，李方叔、王仲弓別於惠濟，出示南嶽典寶東華李真人像，又出此二詩，曰此李真人作也。","近有人於江上遇之得此，云即李太白也。","」〖4〗《苕溪漁隱叢話前集》卷五引東坡云：「予都下見有人携一紙文書，字則顏魯公也，墨跡如未乾，紙亦新健，其詩曰：『朝披夢澤雲，笠釣青茫茫。","』此語非太白不能道也。","」今按：此詩第二首云：「我昔飛骨時，慘見當塗墳。","」顯然非李白所作。","就前所錄北宋諸家有關獲得此詩的記錄而言，其作者約有以下幾種可能：其一，北宋道士托名李白作；其二，李真人作，後傳成李白作；其三，北宋道士錄唐時遺詩而獻於東坡；其四，東坡自作而僞稱得之於他人，亦如解《八陣圖》而稱少陵託夢之類。","今莫詳孰是。","因此二詩出處甚早，《全唐詩》及今賢補遺已錄存其片斷，故爲補足而附存之。","）。"]', '["人生燭上花，光（乙作「火」）滅巧妍尽。","春风繞樹头，日與化（戊作「花」）工（丁作「花工」）進。","只（戊作「惟」）知雨露貪，不闻（丁、戊作「念」）零落尽（甲無以上二句）。","我昔（乙、戊作「昔我」）飞骨时，慘见當塗墳。","青松靄朝（丁、戊作「明」）霞，縹緲山（戊作「上」）丁村。","既死明月魄，無复（丁、戊作「彼」）玻璃（乙、戊作「瓈」）魂。","念此一脫灑（戊作「酒」），长嘯祭（甲、乙、戊作「登」）崑崙。","醉著鸾皇（甲、丁、戊作「鳳」）衣，星斗俯可捫。","（见瞿蛻园、朱金城《李白集校注》卷三十《诗文補遺》錄蘇軾书李白诗墨跡。","出校各本，甲本爲趙令畤《侯鯖錄》卷二，乙本指《增修诗話總龟》卷十一引《王直方诗話》，丙本指《全唐诗》卷一八五引《王直方诗話》，丁本指《李白诗校注》據《唐宋诗醇》所錄校語，戊本指《津逮秘书》本《东坡題跋》卷二）（〖1〗《东坡題跋》卷二：「余頃在京師，有道人相訪，风骨甚異，語論不凡，自云常與物外諸公往還，口誦此二篇，云东华上清監清逸真人李太白作也。","」〖2〗《侯鯖錄》卷二：「东坡先生在嶺南，言元祐中有见李白酒肆中誦其近诗云：『朝披梦澤云，笠釣青茫茫。","』此非世人語也。","少游嘗手錄其全篇，少游敍云：『观頃在京師，有道人相訪，风骨甚異，語論不凡，自云嘗與物外諸公往還，口誦二篇，云东华上清監清逸真人李白作也。","』」）（〖3〗《王直方诗話》：「元祐八年，东坡帥定武，李方叔、王仲弓別於惠濟，出示南嶽典寶东华李真人像，又出此二诗，曰此李真人作也。","近有人於江上遇之得此，云即李太白也。","」〖4〗《苕溪漁隐叢話前集》卷五引东坡云：「予都下见有人携一紙文书，字則顏魯公也，墨跡如未乾，紙亦新健，其诗曰：『朝披梦澤云，笠釣青茫茫。","』此語非太白不能道也。","」今按：此诗第二首云：「我昔飞骨时，慘见當塗墳。","」显然非李白所作。","就前所錄北宋諸家有关獲得此诗的記錄而言，其作者約有以下幾種可能：其一，北宋道士托名李白作；其二，李真人作，後傳成李白作；其三，北宋道士錄唐时遺诗而獻於东坡；其四，东坡自作而僞稱得之於他人，亦如解《八陣圖》而稱少陵託梦之類。","今莫詳孰是。","因此二诗出处甚早，《全唐诗》及今賢補遺已錄存其片斷，故爲補足而附存之。","）。"]', '诗', 'shi', '', NULL, '上清寶鼎詩二首（附存） 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383492e2-2ecc-4aa5-88ca-f9fead3bc4f1', '句', '句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["眼前有景道不得，崔顥題詩在上頭。","（見《苕溪漁隱叢話前集》卷五引李畋《該聞錄》、《後村詩話前集》卷一。","）。"]', '["眼前有景道不得，崔顥題诗在上头。","（见《苕溪漁隐叢話前集》卷五引李畋《該闻錄》、《後村诗話前集》卷一。","）。"]', '诗', 'shi', '', NULL, '句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1cc096-f2f8-4f3f-8c08-7e2d9b3dcb8a', '', '', '5f26199b-7911-4acf-a812-d2460ae7e113', '唐', '["嚴光，自稱釣鰲客。","安史亂後任棣州司戶。","詩二句。","（《全唐詩》無王嚴光詩）。"]', '["嚴光，自稱釣鰲客。","安史亂後任棣州司戶。","诗二句。","（《全唐诗》無王嚴光诗）。"]', '诗', 'shi', '', NULL, ' 王嚴光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b16eb35c-8df1-43c8-8b3d-113f482ffa36', '詩', '诗', '5f26199b-7911-4acf-a812-d2460ae7e113', '唐', '["郡將雖乘馬，羣官總是驢。","（見唐封演《封氏聞見記》卷十）（按：《封氏聞見記》云：「王嚴光頗有文才，而性卓詭。","既無所達，自稱釣鰲客。","……兵亂之後，嚴光年鬚已衰，任棣州司戶。","時刺史有馬，州佐已下多乘驢，嚴光作詩曰〖略〗。","對衆吟誦，以爲笑樂。","」按：封演爲大曆間人，因知兵亂即指安史之亂。","）。"]', '["郡將雖乘马，羣官總是驢。","（见唐封演《封氏闻见記》卷十）（按：《封氏闻见記》云：「王嚴光頗有文才，而性卓詭。","既無所達，自稱釣鰲客。","……兵亂之後，嚴光年鬚已衰，任棣州司戶。","时刺史有马，州佐已下多乘驢，嚴光作诗曰〖略〗。","对衆吟誦，以爲笑乐。","」按：封演爲大曆间人，因知兵亂即指安史之亂。","）。"]', '诗', 'shi', '', NULL, '詩 王嚴光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1707725f-7f84-4574-a478-c54e8055bf1d', '刺當塗者', '刺當塗者', '082ac388-821b-424d-8955-ba557a2e820b', '唐', '["末刼蘭香科下人，衣冠禮樂與君臣。","如來若向閻浮出，莫現從來丈六身。","（同前）（按：《封氏聞見記》云：「補闕王志安晚不得志，久遊恒、趙之間，人畏其口，莫敢引用。","志安作詩以刺當塗者云〖略〗。","見者彌增怨忌。","」）。"]', '["末刼蘭香科下人，衣冠禮乐與君臣。","如来若向閻浮出，莫現從来丈六身。","（同前）（按：《封氏闻见記》云：「補闕王志安晚不得志，久游恒、趙之间，人畏其口，莫敢引用。","志安作诗以刺當塗者云〖略〗。","见者彌增怨忌。","」）。"]', '诗', 'shi', '', NULL, '刺當塗者 王志安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397e5f69-615f-4a65-acf2-e0c23eb1c69a', '懷歐陽山人嚴秀才', '懷歐陽山人嚴秀才', '6be03a45-f607-4c5b-bb8b-17063c7bd70b', '唐', '["鴉鳴東牖曙，草秀南湖春。","（《十萬卷樓叢書》本皎然《詩式》卷四）（按：《詩式》誤作「祖迥」，今據《吟窗雜錄》卷三十二、《四友齋叢說》卷二十四、《全唐詩》卷八五一定爲神迥作。","《吟窗雜錄》題作《懷歐陽山人》。","《全唐詩》收此二句，缺題。","又其小傳云：「臨晉人。","姓田。","貞觀間流化岷峨，爲道俗宗仰。","」殆據《續高僧傳》卷十五。","按唐有二神迥，另一爲寶應間越州僧，見《宋高僧傳》卷二九。","檢《詩式》錄其詩於嚴維、皇甫冉等詩後，知應爲肅代間人。","詩中提到之南湖，亦在越中。","詩題中之嚴秀才，疑即長期居於越中之嚴）（維。","因知此詩應爲越州僧神迥作，《全唐詩》誤，今爲移正補題重錄。","）。"]', '["鴉鳴东牖曙，草秀南湖春。","（《十万卷楼叢书》本皎然《诗式》卷四）（按：《诗式》誤作「祖迥」，今據《吟窗杂錄》卷三十二、《四友斋叢说》卷二十四、《全唐诗》卷八五一定爲神迥作。","《吟窗杂錄》題作《懷歐陽山人》。","《全唐诗》收此二句，缺題。","又其小傳云：「臨晉人。","姓田。","貞观间流化岷峨，爲道俗宗仰。","」殆據《續高僧傳》卷十五。","按唐有二神迥，另一爲寶應间越州僧，见《宋高僧傳》卷二九。","檢《诗式》錄其诗於嚴維、皇甫冉等诗後，知應爲肅代间人。","诗中提到之南湖，亦在越中。","诗題中之嚴秀才，疑即长期居於越中之嚴）（維。","因知此诗應爲越州僧神迥作，《全唐诗》誤，今爲移正補題重錄。","）。"]', '诗', 'shi', '', NULL, '懷歐陽山人嚴秀才 神迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0435bff-97b7-4f01-8b31-1b1e25db6581', '詩 一', '诗 一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["梵志死去來，魂識（《天聖廣燈錄》作「魄」）見閻老。","讀盡百王書，未免（《天聖廣燈錄》作「不兌」）受捶拷。","一稱南無佛，皆以成佛道。","（見《續藏經》本五代風穴延沼禪師《風穴語錄》、《天聖廣燈錄》卷十五、《古尊宿語錄》卷七《風穴禪師語錄》、《五燈會元》卷十一引）。"]', '["梵志死去来，魂識（《天聖廣灯錄》作「魄」）见閻老。","读尽百王书，未免（《天聖廣灯錄》作「不兌」）受捶拷。","一稱南無佛，皆以成佛道。","（见《續藏經》本五代风穴延沼禪師《风穴語錄》、《天聖廣灯錄》卷十五、《古尊宿語錄》卷七《风穴禪師語錄》、《五灯會元》卷十一引）。"]', '诗', 'shi', '', NULL, '詩 一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938861c3-e515-4aa0-9ea0-1e80efea32c6', '詩 二', '诗 二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["井底生紅塵，高峰起波（《五燈會元》作「白」）浪。","石女生石兒，龜毛寸寸長。","若要學菩提，但看此牓（《五燈會元》作「模」）樣。","（《天聖廣燈錄》卷二十三、《五燈會元》卷十五）。"]', '["井底生紅塵，高峰起波（《五灯會元》作「白」）浪。","石女生石兒，龟毛寸寸长。","若要学菩提，但看此牓（《五灯會元》作「模」）樣。","（《天聖廣灯錄》卷二十三、《五灯會元》卷十五）。"]', '诗', 'shi', '', NULL, '詩 二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dff215-8255-4f1f-b47e-f38acd896e3a', '頌 一', '頌 一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["無瞋是持（《五燈會元》作「嗔即是」）戒，心淨是（《五燈會元》作「即」）出家。","我性與汝（《五燈會元》作「你」）合，一切法無差。","（見吳越釋延壽《宗鏡錄》卷二十四、宋普濟《五燈會元》卷二。","）（按：《全唐詩續補遺》卷二誤收此首爲寒山詩。","）。"]', '["無瞋是持（《五灯會元》作「嗔即是」）戒，心淨是（《五灯會元》作「即」）出家。","我性與汝（《五灯會元》作「你」）合，一切法無差。","（见吳越釋延壽《宗镜錄》卷二十四、宋普濟《五灯會元》卷二。","）（按：《全唐诗續補遺》卷二誤收此首爲寒山诗。","）。"]', '诗', 'shi', '', NULL, '頌 一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083b302d-9719-4df5-965b-15225e6bd344', '頌 二', '頌 二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["東陽海水清，水清復見底。","靈源流法泉，斫水刀而痕。","我見頑愚士，燈心拄須彌。","寸樵煮大海，足抹大地石，蒸沙成飯無，磨甎將爲鏡。","說食終不飽，直須著力行。","恢恢大丈夫，堂堂六尺土。","枉死埋塚下，可惜孤標物。","（同前書卷三十三。","此條承陳允吉師告知）。"]', '["东陽海水清，水清复见底。","靈源流法泉，斫水刀而痕。","我见頑愚士，灯心拄須彌。","寸樵煮大海，足抹大地石，蒸沙成飯無，磨甎將爲镜。","说食終不飽，直須著力行。","恢恢大丈夫，堂堂六尺土。","枉死埋塚下，可惜孤標物。","（同前书卷三十三。","此條承陳允吉師告知）。"]', '诗', 'shi', '', NULL, '頌 二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de24fa99-d92f-4174-ae58-c1e2c956d96a', '喜陸侍御破石埭草寇東峰亭賦詩', '喜陸侍御破石埭草寇东峰亭賦诗', 'df1e5321-18c9-495d-8d32-ee465afe8948', '唐', '["獨坐理戎行，安邊策最長。","霜臺雷電振，雲漢翼箕張。","決策威千里，除妖靜一方。","林巒開罨畫，泉石韻宮商。","戍罷涇川外，烽閑句水陽。","肅清淮海後，誰不詠時康。","（見嘉慶十一年刊洪亮吉纂《涇縣志》卷三十）（按：趙紹祖《涇川金石記》載北宋熙寧二年蔣之奇跋此詩文，知之奇當時曾重刻此碑。","清代碑已不存，而諸詩則載於縣志中。","同唱五人，惟㝢詩《全唐詩》失收。","）。"]', '["独坐理戎行，安邊策最长。","霜台雷電振，云漢翼箕張。","決策威千里，除妖静一方。","林巒开罨畫，泉石韻宮商。","戍罷涇川外，烽闲句水陽。","肅清淮海後，誰不詠时康。","（见嘉慶十一年刊洪亮吉纂《涇縣志》卷三十）（按：趙紹祖《涇川金石記》載北宋熙寧二年蔣之奇跋此诗文，知之奇當时曾重刻此碑。","清代碑已不存，而諸诗則載於縣志中。","同唱五人，惟㝢诗《全唐诗》失收。","）。"]', '诗', 'shi', '', NULL, '喜陸侍御破石埭草寇東峰亭賦詩 蘇㝢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa705ac8-3281-4b0c-8039-c423fefd8f2b', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', '343fd956-817b-4553-9b1b-bf50eb603d34', '唐', '["孤雲去住本無機，却指蒼梧下翠微。","錫鼎爲傳仙族在，泛槎還入海煙歸。","客星一夜淩光武，華表千年送令威。","聞道葛洪丹竈畔，至今霜果有金衣。","（見《會稽掇英總集》卷二）。"]', '["孤云去住本無機，却指蒼梧下翠微。","錫鼎爲傳仙族在，泛槎還入海煙归。","客星一夜淩光武，华表千年送令威。","闻道葛洪丹竈畔，至今霜果有金衣。","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 嚴向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb98b5b8-7eb2-483f-a0b1-b4c9febdd4f2', '與林元籍郊行舉對（題擬）', '與林元籍郊行舉对（題擬）', '9bea10f1-a9d3-4033-ac3b-e48fd1163eba', '唐', '["石壓筍斜出。","（虔）谷陰花後開。","（元籍）（見《全浙詩話》卷五引《三台詩話》）（〖1〗《三台詩話》云：「鄭司戶虔初至台，見風俗樸野，選民間子弟教之。","一日與弟子林元籍輩郊行，舉一對曰〖略〗。","元籍應聲云〖略〗。","司戶大驚異曰：何教化神速如是。","」）。"]', '["石壓筍斜出。","（虔）谷陰花後开。","（元籍）（见《全浙诗話》卷五引《三台诗話》）（〖1〗《三台诗話》云：「鄭司戶虔初至台，见风俗樸野，選民间子弟教之。","一日與弟子林元籍輩郊行，舉一对曰〖略〗。","元籍應声云〖略〗。","司戶大驚異曰：何教化神速如是。","」）。"]', '诗', 'shi', '', NULL, '與林元籍郊行舉對（題擬） 鄭虔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d889a4-7740-426f-841f-8bbe0f17e7bd', '奉和聖製雨中春望詩', '奉和聖製雨中春望诗', '9554339e-918d-4b20-8d13-d3dfe7440fb6', '唐', '["雨後山川光正發，雲端花柳意無窮。"]', '["雨後山川光正發，云端花柳意無窮。"]', '诗', 'shi', '', NULL, '奉和聖製雨中春望詩 苗晉卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('719949bf-69cc-44f7-8677-d3f6ab647bee', '奉和行幸詩', '奉和行幸诗', '9554339e-918d-4b20-8d13-d3dfe7440fb6', '唐', '["接仗風雲動，迎軍鳥獸舞。","（均見清趙殿成《王右丞集箋注》卷二十二《魏郡太守河北採訪處置使上黨苗八德政碑》、《吟窗雜錄》卷二六《歷代吟譜》）。"]', '["接仗风云动，迎軍鸟獸舞。","（均见清趙殿成《王右丞集箋注》卷二十二《魏郡太守河北採訪处置使上黨苗八德政碑》、《吟窗杂錄》卷二六《歷代吟譜》）。"]', '诗', 'shi', '', NULL, '奉和行幸詩 苗晉卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e248d48c-5c7c-4a45-8e97-fe2d9f62fe2e', '餞故人', '餞故人', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["祈君辭丹豁（孫疑爲「丹墀」之誤），負仗（孫疑爲「杖」字之誤）歸海隅。","離庭自蕭索，別心何鬱紆。","天高白雲斷，野曠青山孤。","欲知腸斷處，明月照江湖。","（〖1〗孫欽善云：「此詩原集缺佚，據敦煌殘卷伯三六一九補。","當作於天寶十一載秋，時在長安。","」）。"]', '["祈君辞丹豁（孫疑爲「丹墀」之誤），負仗（孫疑爲「杖」字之誤）归海隅。","離庭自蕭索，別心何鬱紆。","天高白云斷，野曠青山孤。","欲知腸斷处，明月照江湖。","（〖1〗孫欽善云：「此诗原集缺佚，據敦煌殘卷伯三六一九補。","當作於天寶十一載秋，时在长安。","」）。"]', '诗', 'shi', '', NULL, '餞故人 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02b7e7f-533c-4461-befb-6c0423de7e67', '送蕭判官賦得黃花戍', '送蕭判官賦得黄花戍', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君不見黃花曲裏黃，戍日蕭蕭帶寒樹。","（孫云：「以上二句疑有缺字，姑作此斷。","」）樓上篇（孫云「借作偏」）臨北斗星，門前宜（孫云「當作直，與上句偏成對文」）至西州路。","每到爪時（孫云：「爪，《集韻》：『本又作叉，或作蚤、騷。","』爪時，即早時。","」今按：「爪時」應爲「瓜時」之誤，用《左傳》典。","作早時解亦不可通）更卒來，祇對黃花□□□。","（孫云：「外句末字模糊不清。","」今按：此句疑缺末三字）樓中幾度哭明月，笛裏何人吹《落梅》？","多君莫不推才傑（孫云：「原作𭪪傑俗字」），欲奏平戎赴天闕。","轅門杯酒別交親，去去雲霄羽翼新。","知君馬上貂裘暖，須念黃花久戍人。","（以上三首均錄自孫欽善《高適集校注》）（〖1〗孫欽善云：「此詩作於任職哥舒翰幕府期間。","原集缺佚，據敦煌殘集伯三一九五補。","」）。"]', '["君不见黄花曲裏黄，戍日蕭蕭带寒樹。","（孫云：「以上二句疑有缺字，姑作此斷。","」）楼上篇（孫云「借作偏」）臨北斗星，门前宜（孫云「當作直，與上句偏成对文」）至西州路。","每到爪时（孫云：「爪，《集韻》：『本又作叉，或作蚤、騷。","』爪时，即早时。","」今按：「爪时」應爲「瓜时」之誤，用《左傳》典。","作早时解亦不可通）更卒来，祇对黄花□□□。","（孫云：「外句末字模糊不清。","」今按：此句疑缺末三字）楼中幾度哭明月，笛裏何人吹《落梅》？","多君莫不推才傑（孫云：「原作𭪪傑俗字」），欲奏平戎赴天闕。","轅门杯酒別交親，去去云霄羽翼新。","知君马上貂裘暖，須念黄花久戍人。","（以上三首均錄自孫欽善《高適集校注》）（〖1〗孫欽善云：「此诗作於任職哥舒翰幕府期间。","原集缺佚，據敦煌殘集伯三一九五補。","」）。"]', '诗', 'shi', '', NULL, '送蕭判官賦得黃花戍 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eae263b-c784-4836-af0b-de4254b2cf83', '奉贈賀郎詩一首', '奉贈賀郎诗一首', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["報[賀]（駕）郎，莫潛藏。","障門終不免，何用漫思量。","清酒濃如雞，臛㹠與白羊。","不論空蒜酢，兼要好椒薑。","姑娣能無語，多言有侍娘。","不知何日辦，急共婦平章。","如其意不決，請問阿耶孃。","（見伯二九七六卷）（按：原卷連錄四首詩，不署作者。","前三首爲《自薊北歸》、《宴別郭尚書》、《題李別駕壁》〖原卷缺題〗皆高適作，疑此詩亦爲其所作。","）。"]', '["報[賀]（駕）郎，莫潛藏。","障门終不免，何用漫思量。","清酒濃如雞，臛㹠與白羊。","不論空蒜酢，兼要好椒薑。","姑娣能無語，多言有侍娘。","不知何日辦，急共婦平章。","如其意不決，請问阿耶孃。","（见伯二九七六卷）（按：原卷連錄四首诗，不署作者。","前三首爲《自薊北归》、《宴別郭尚书》、《題李別駕壁》〖原卷缺題〗皆高適作，疑此诗亦爲其所作。","）。"]', '诗', 'shi', '', NULL, '奉贈賀郎詩一首 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af597c8a-fe6f-4cb9-b97d-0175fba37407', '題石門', '題石门', '86f5e07a-b8e4-4977-8748-76070a1af131', '唐', '["雙扉啓（《咸淳臨安志》作「起」）巖石，塵客過應稀。","千古掩不得，從教雲夜歸。","（見清釋廣賓《西天目祖山志》卷五）（按：此詩最早見收於南宋潛說友《咸淳臨安志》卷二十六，謂「世傳唐玄宗有詩」云云。","明皇平行跡未及東南，詩顯非其所作。","）。"]', '["雙扉啓（《咸淳臨安志》作「起」）巖石，塵客過應稀。","千古掩不得，從教云夜归。","（见清釋廣賓《西天目祖山志》卷五）（按：此诗最早见收於南宋潛说友《咸淳臨安志》卷二十六，謂「世傳唐玄宗有诗」云云。","明皇平行跡未及东南，诗显非其所作。","）。"]', '诗', 'shi', '', NULL, '題石門 釋玄宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9a3cac-33ca-4533-909f-f4524e422df4', '題石門洞', '題石门洞', '86f5e07a-b8e4-4977-8748-76070a1af131', '唐', '["密竹流泉不居熱，洞門深沉風雨歇。","洗出清風快活天，醉弄江南謝家月。","（見《康熙青田縣志》卷十二《藝文》下「七言絕」。","以上二首，皆承張靖龍同志錄示。","）。"]', '["密竹流泉不居熱，洞门深沉风雨歇。","洗出清风快活天，醉弄江南謝家月。","（见《康熙青田縣志》卷十二《藝文》下「七言絕」。","以上二首，皆承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '題石門洞 釋玄宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9079a429-bafc-4e2e-9c39-9503c6b8089b', '沙門崇惠登刀梯歌（幷序○題擬）', '沙门崇惠登刀梯歌（幷序○題擬）', 'c3b02f9d-4a0c-411c-bc69-fe95c27d6c94', '唐', '["百尺凌空倚劍梯，千峰迴（疑應作「迥」）拔（一作「枝」）接天霓。","鏖鑪霜明鳥道（一作「邊」）齋，龍泉金鐶生虹蜺。","刀爲樹，劍作山，應真飛錫遊其間。","一步一登，揮手攀毛，七星燦爛光斑斑。","干將劍刃兩離披（一作「柀」），碧光焰，上人履之不爲嶮；鏌鎁刀，銛鋒鋭鍔可吹毛，如今蹈之不足勞。","白若雪，青如冰，龜甲魚鱗幾百層，四部覩之，戰戰兢兢，萬仞峰頭見一僧。","賓鐵文，青蛇色，蒨𮑕崢嶸寒岌嶷。","不傷不損難可測，方是大悲解脫力。","自古武臣矜劍術，舞之杸（疑爲「投」字）之皆不失。","視之膽攝（一作「欇」）身慄慄，誰道揮戈移白日？李廣舊傳百戰功，何如今日見神通？紫衣襜襜飛入空，出沒縱橫[蹈]白刃（一本多「中」字）兮，[蹈白刃兮]光翡翠，黯黯精光和能利。","（見《大正新脩大藏經》第五十二冊釋圓照集《代宗朝贈司空大辨正廣智三藏和上〖即不空〗表制集》卷六。","其後尚收《崇惠登刀梯頌》及崇惠《謝賜紫衣幷賀表》）。"]', '["百尺凌空倚劍梯，千峰迴（疑應作「迥」）拔（一作「枝」）接天霓。","鏖鑪霜明鸟道（一作「邊」）斋，龙泉金鐶生虹蜺。","刀爲樹，劍作山，應真飞錫游其间。","一步一登，揮手攀毛，七星燦爛光斑斑。","干將劍刃兩離披（一作「柀」），碧光焰，上人履之不爲嶮；鏌鎁刀，銛鋒鋭鍔可吹毛，如今蹈之不足勞。","白若雪，青如冰，龟甲鱼鱗幾百層，四部覩之，戰戰兢兢，万仞峰头见一僧。","賓鐵文，青蛇色，蒨𮑕崢嶸寒岌嶷。","不傷不損难可測，方是大悲解脫力。","自古武臣矜劍術，舞之杸（疑爲「投」字）之皆不失。","視之膽攝（一作「欇」）身慄慄，誰道揮戈移白日？李廣旧傳百戰功，何如今日见神通？紫衣襜襜飞入空，出沒縱橫[蹈]白刃（一本多「中」字）兮，[蹈白刃兮]光翡翠，黯黯精光和能利。","（见《大正新脩大藏經》第五十二冊釋圓照集《代宗朝贈司空大辨正廣智三藏和上〖即不空〗表制集》卷六。","其後尚收《崇惠登刀梯頌》及崇惠《謝賜紫衣幷賀表》）。"]', '诗', 'shi', '', NULL, '沙門崇惠登刀梯歌（幷序○題擬） □釗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('536f946b-7bb2-4f9c-b091-d955d2943210', '', '', '004ecbe9-fa05-4827-a617-b3a0718ebe12', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 張誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f1da0ea-4617-48de-a351-6598d5d8985b', '詠懷', '詠懷', '004ecbe9-fa05-4827-a617-b3a0718ebe12', '唐', '["論成方辯命，賦罷即歸田。","（見《白氏長慶集》卷四十一《唐贈尚書工部侍郎吳郡張公神道碑銘》）。"]', '["論成方辯命，賦罷即归田。","（见《白氏长慶集》卷四十一《唐贈尚书工部侍郎吳郡張公神道碑銘》）。"]', '诗', 'shi', '', NULL, '詠懷 張誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf93d9e-3273-48c4-8aeb-73319ac220f4', '湘夫人祠', '湘夫人祠', '5e62a0fb-2541-4af2-8061-a06132b0dc43', '唐', '["靈祠古木合，波颺大江濆。","未作湘南雨，知爲何處雲。","苔痕澀珠履，草色妬羅裙。","妙鼓彤雲瑟，羈臣不可聞。","（見明刻本《唐僧弘秀集》卷八、《古今禪藻集》卷四）（按：《全唐詩》卷八一○收此詩，有闕文，今重錄。","）。"]', '["靈祠古木合，波颺大江濆。","未作湘南雨，知爲何处云。","苔痕澀珠履，草色妬羅裙。","妙鼓彤云瑟，羈臣不可闻。","（见明刻本《唐僧弘秀集》卷八、《古今禪藻集》卷四）（按：《全唐诗》卷八一○收此诗，有闕文，今重錄。","）。"]', '诗', 'shi', '', NULL, '湘夫人祠 太易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba3e591-1f24-4680-bf26-68a7b594d084', '答智威偈（題擬） 一', '答智威偈（題擬） 一', '13bc0178-da74-4743-ad1c-4ab6ca7eb438', '唐', '["念想由來幻，性自無終始。","若得此中意，長波當自止。","。"]', '["念想由来幻，性自無終始。","若得此中意，长波當自止。","。"]', '诗', 'shi', '', NULL, '答智威偈（題擬） 一 慧忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5568739b-d258-47a4-94c1-e76a1e864bb4', '答智威偈（題擬） 二', '答智威偈（題擬） 二', '13bc0178-da74-4743-ad1c-4ab6ca7eb438', '唐', '["虛無是實體，人我何所存。","妄情不須息，即汎般若船。","（見《五燈會元》卷二）。"]', '["虛無是實體，人我何所存。","妄情不須息，即汎般若船。","（见《五灯會元》卷二）。"]', '诗', 'shi', '', NULL, '答智威偈（題擬） 二 慧忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f178267-ce7e-4b0e-8efb-231f2ff34806', '感舊賦附歌', '感旧賦附歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["東海之水化爲田，北溟之魚飛上天。","城有時而復，陵有時而遷，理固常矣，人亦其然。","觀夫陌上豪貴，當年高位，歌鐘拂天，鞍馬照地，積黃金以自滿，矜青雲之坐致，高館招其賓朋，重門疊其車騎。","及其高堂傾，曲池平，雀羅空悲其處所，門客肯念其生平？已矣夫！世路崎嶇，孰爲後圖？豈無疇日之光榮，何今人之棄予。","彼乘軒而不恤爾後，曾不愛我之覉孤。","歎君門兮何深，顧盛時而向隅。","攬蕙草以惆悵，步衡門而踟躕。","強學以待，知音不無。","思達人之惠顧，庶有望於亨衢。","（見《文苑英華》卷九一）。"]', '["东海之水化爲田，北溟之鱼飞上天。","城有时而复，陵有时而遷，理固常矣，人亦其然。","观夫陌上豪貴，當年高位，歌鐘拂天，鞍马照地，積黄金以自满，矜青云之坐致，高館招其賓朋，重门叠其车騎。","及其高堂傾，曲池平，雀羅空悲其处所，门客肯念其生平？已矣夫！世路崎嶇，孰爲後圖？豈無疇日之光榮，何今人之棄予。","彼乘軒而不恤爾後，曾不愛我之覉孤。","歎君门兮何深，顧盛时而向隅。","攬蕙草以惆悵，步衡门而踟躕。","強学以待，知音不無。","思達人之惠顧，庶有望於亨衢。","（见《文苑英华》卷九一）。"]', '诗', 'shi', '', NULL, '感舊賦附歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1a3b91-19f8-45bf-9602-02f48f59cb51', '江行遇梅花之作', '江行遇梅花之作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["江畔梅花白如雪，使我思鄉膓欲斷。","摘得一枝在手中，無人遠向金閨說。","願得青鳥啣此花，西飛直送到我家。","胡姬正在臨窗下，獨織留黃淺碧紗。","此鳥啣花胡姬前，胡姬見花知我憐。","千說萬說由不得，一夜抱花空館眠。","（見伯二五五五卷，轉錄自《文獻》十三輯廖立《敦煌殘卷岑詩辨》）（〖1〗李嘉言《岑詩繫年》云：「案岑參江陵人，而足跡不及江陵以東。","此曰：『西飛直送到吾家』，其非岑作明矣。","」〖2〗廖立云：「今覈對膠片，此詩題下署名爲岑參〖原字作𠫭〗，不知何故《繫年》未提此點。","」「詩中所言胡姬，恐怕也是寄託之辭，勿須考證岑參家中是否真有一個胡姬。","這是寫詩，不是寫史，香草美人，均非實指。","《江行》爲岑參之作，似勿須多辨。","」）。"]', '["江畔梅花白如雪，使我思乡膓欲斷。","摘得一枝在手中，無人远向金閨说。","願得青鸟啣此花，西飞直送到我家。","胡姬正在臨窗下，独织留黄淺碧紗。","此鸟啣花胡姬前，胡姬见花知我怜。","千说万说由不得，一夜抱花空館眠。","（见伯二五五五卷，轉錄自《文獻》十三輯廖立《敦煌殘卷岑诗辨》）（〖1〗李嘉言《岑诗繫年》云：「案岑參江陵人，而足跡不及江陵以东。","此曰：『西飞直送到吾家』，其非岑作明矣。","」〖2〗廖立云：「今覈对膠片，此诗題下署名爲岑參〖原字作𠫭〗，不知何故《繫年》未提此点。","」「诗中所言胡姬，恐怕也是寄託之辞，勿須考證岑參家中是否真有一個胡姬。","這是寫诗，不是寫史，香草美人，均非實指。","《江行》爲岑參之作，似勿須多辨。","」）。"]', '诗', 'shi', '', NULL, '江行遇梅花之作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('912b38fa-92f5-4a54-87a4-87f5f7957368', '寒食夜蘇二宅', '寒食夜蘇二宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒食明堪坐，春參夕已垂。","好風經柳葉，清風照花枝。","客淚聞歌掩，歸心畏酒知。","佳辰邀賞遍，忽忽更何爲？","（見宋蒲積中《古今歲時雜詠》卷十一）（按：《古今歲時雜詠》各類詩均分爲古詩、今詩二部分，古詩爲宋綬《歲時雜詠》原編，今詩始爲蒲積中所輯。","宋綬爲宋敏求之父，卒於慶曆初。","其時王洙本《杜工部集》雖已編成，尚未刊布。","宋綬所據材料，有爲王洙未及見者。","《古今歲時雜詠》在宋明二代流布未廣，故治杜詩者多未見之。","此詩各本《杜集》皆失收，今亟錄出，以供治杜者研究。","）。"]', '["寒食明堪坐，春參夕已垂。","好风經柳葉，清风照花枝。","客泪闻歌掩，归心畏酒知。","佳辰邀賞遍，忽忽更何爲？","（见宋蒲積中《古今歲时杂詠》卷十一）（按：《古今歲时杂詠》各類诗均分爲古诗、今诗二部分，古诗爲宋綬《歲时杂詠》原編，今诗始爲蒲積中所輯。","宋綬爲宋敏求之父，卒於慶曆初。","其时王洙本《杜工部集》雖已編成，尚未刊布。","宋綬所據材料，有爲王洙未及见者。","《古今歲时杂詠》在宋明二代流布未廣，故治杜诗者多未见之。","此诗各本《杜集》皆失收，今亟錄出，以供治杜者研究。","）。"]', '诗', 'shi', '', NULL, '寒食夜蘇二宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffca4612-5d51-42a7-bfd9-4d3045e05dbc', '閬中行', '閬中行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["豺狼當路，無地遊從。","（《雲溪友議》卷上《嚴黃門》）（按：此二句疑即杜甫《發閬中》首句「前有毒蛇後猛虎」之異傳。","）。"]', '["豺狼當路，無地游從。","（《云溪友議》卷上《嚴黄门》）（按：此二句疑即杜甫《發閬中》首句「前有毒蛇後猛虎」之異傳。","）。"]', '诗', 'shi', '', NULL, '閬中行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a50b03d-2611-4c8b-8778-8422710acd15', '石文詩（附存）', '石文诗（附存）', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["詩王本在陳芳國，九夜捫之麟篆熟，聲振扶桑享天福。","（見馮贄《雲仙雜記》卷一引《文覽》）（按：此詩可斷定非杜甫作。","《雲仙雜記》一書，傳爲唐末人馮贄作，後人雖有疑其爲宋人僞託者，然所舉諸證尚不足以定讞。","今仍從舊說視作唐人之作姑附存杜甫名下。","）。"]', '["诗王本在陳芳国，九夜捫之麟篆熟，声振扶桑享天福。","（见馮贄《云仙杂記》卷一引《文覽》）（按：此诗可斷定非杜甫作。","《云仙杂記》一书，傳爲唐末人馮贄作，後人雖有疑其爲宋人僞託者，然所舉諸證尚不足以定讞。","今仍從旧说視作唐人之作姑附存杜甫名下。","）。"]', '诗', 'shi', '', NULL, '石文詩（附存） 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5dd484-77bd-458b-b489-d5af23bebf90', '句', '句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["狨擲寒條馬見驚。","（見《增修詩話總龜前集》卷二引《楊文公談苑》）（按：《詩話總龜》卷十六引《零陵總記》錄杜陵《朝陽巖歌》一首，《全唐詩》卷二四一收作元結詩。","）。"]', '["狨擲寒條马见驚。","（见《增修诗話總龟前集》卷二引《楊文公談苑》）（按：《诗話總龟》卷十六引《零陵總記》錄杜陵《朝陽巖歌》一首，《全唐诗》卷二四一收作元結诗。","）。"]', '诗', 'shi', '', NULL, '句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('993bb291-4506-4bd8-81c3-d3884d267fa4', '順心上人山池', '順心上人山池', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["南榮對廬{馮/廾}，宴坐日於斯。","細草汀洲色，輕風楊柳枝。","磬聲催暮鳥，泉影入春池。","則異人間世，唯當幽客知。"]', '["南榮对廬{馮/廾}，宴坐日於斯。","細草汀洲色，轻风楊柳枝。","磬声催暮鸟，泉影入春池。","則異人间世，唯當幽客知。"]', '诗', 'shi', '', NULL, '順心上人山池 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5239363b-2cde-4562-83bc-afbd6dbf1b2d', '題陳勝林園', '題陳勝林园', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["閉門不肯偶時人，荒竹閑園莫厭貧。","臘後春風能幾日？家中芳草自相親。","（均見日本藏唐抄本《新撰類林抄》卷四）。"]', '["閉门不肯偶时人，荒竹闲园莫厭貧。","臘後春风能幾日？家中芳草自相親。","（均见日本藏唐抄本《新撰類林抄》卷四）。"]', '诗', 'shi', '', NULL, '題陳勝林園 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b65386-11e4-41cc-94d9-ce3aec4e0c58', '醉歌 一', '醉歌 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["元子樂矣。","（元子）何樂亦然，何樂亦然？","（和者）我雲我山，我林我泉（元子）。"]', '["元子乐矣。","（元子）何乐亦然，何乐亦然？","（和者）我云我山，我林我泉（元子）。"]', '诗', 'shi', '', NULL, '醉歌 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec1fc6d5-ac3d-45a0-8efa-9f5c7cb3dd8d', '醉歌 二', '醉歌 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["元子樂矣。","（元子）何樂然爾，何樂然爾？","（和者）我鼻我目，我口我耳。","（元子）（見《唐文粹》卷四三元結《心規》）。"]', '["元子乐矣。","（元子）何乐然爾，何乐然爾？","（和者）我鼻我目，我口我耳。","（元子）（见《唐文粹》卷四三元結《心規》）。"]', '诗', 'shi', '', NULL, '醉歌 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f83e61a1-7a69-4c78-8fd5-bec2eab8eb29', '惡圓之士歌', '惡圓之士歌', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["寧方爲皁，不圓爲卿。","寧方爲汙辱，不圓爲顯榮。","（見《唐文粹》卷四三元結《惡圓》）。"]', '["寧方爲皁，不圓爲卿。","寧方爲汙辱，不圓爲显榮。","（见《唐文粹》卷四三元結《惡圓》）。"]', '诗', 'shi', '', NULL, '惡圓之士歌 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae1c5cb-e3cc-4217-a393-39590417da00', '桃花（題擬）', '桃花（題擬）', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["桃源自有長生路，却是秦皇不得知。","（見《全芳備祖前集》卷八「桃花」門）（按：《淳熙三山志》卷三十六收元結《贈靈石俱胝詩》云：「萬計千謀總不真，虛將文字役心神。","俱胝祇念三行咒，自得名超一世人。","」元結平生未至閩中。","《淳熙三山志》云：「靈石俱胝院，……唐武宗時僧元修始庵於此，誦七俱胝咒治疾祟。","」事亦在元結身後。","疑此詩爲北宋官閩之元絳作。","）。"]', '["桃源自有长生路，却是秦皇不得知。","（见《全芳備祖前集》卷八「桃花」门）（按：《淳熙三山志》卷三十六收元結《贈靈石俱胝诗》云：「万計千謀總不真，虛將文字役心神。","俱胝祇念三行咒，自得名超一世人。","」元結平生未至閩中。","《淳熙三山志》云：「靈石俱胝院，……唐武宗时僧元修始庵於此，誦七俱胝咒治疾祟。","」事亦在元結身後。","疑此诗爲北宋官閩之元絳作。","）。"]', '诗', 'shi', '', NULL, '桃花（題擬） 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7610f47f-6378-4f25-a94f-4b058ea5175b', '送賀秘監歸會稽詩', '送賀秘監归會稽诗', 'de158645-626e-43d4-8f24-849e9824600d', '唐', '["飛名紫府內，抗手白雲鄉。","道與松喬匹，榮辭園綺行。","夫君既鶴駕，幼子復霓裳。","少別留宸藻，東南歸路光。","（見《會稽掇英總集》卷二）。"]', '["飞名紫府內，抗手白云乡。","道與松喬匹，榮辞园綺行。","夫君既鹤駕，幼子复霓裳。","少別留宸藻，东南归路光。","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '送賀秘監歸會稽詩 于休烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e2339b-da5a-4711-8c4b-332bd5c3d6e6', '授衣賦附歌', '授衣賦附歌', 'd31bd057-0ca2-43ec-b600-6a74788fb022', '唐', '["愁霜落兮歲已終，秋雁吟兮悲遠空。","短褐不完兮憂思充，庭蕭蕭兮冷暮風。","（見《文苑英華》卷一一三）。"]', '["愁霜落兮歲已終，秋雁吟兮悲远空。","短褐不完兮憂思充，庭蕭蕭兮冷暮风。","（见《文苑英华》卷一一三）。"]', '诗', 'shi', '', NULL, '授衣賦附歌 周存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0dd13e4-cbe3-463f-972b-60e9c7363daa', '逢鄉友', '逢乡友', '2579d660-ad82-4d94-9573-498d9e4a12f8', '唐', '["苦吟吟不足，爭忍話離羣。","（見《吟窗雜錄》卷十三梅堯臣《續金針詩格》）。"]', '["苦吟吟不足，爭忍話離羣。","（见《吟窗杂錄》卷十三梅堯臣《續金針诗格》）。"]', '诗', 'shi', '', NULL, '逢鄉友 杜寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c39bad-3720-4833-aa6b-fa1e15df8afb', '江州臥疾送李侍御歌（題擬）', '江州臥疾送李侍御歌（題擬）', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["江沉沉兮雨淒淒，洲渚沒兮玄雲低，傷別心兮聞鼓鼙。","（見《文苑英華》卷七二○李華《江州臥疾送李侍御序》）。"]', '["江沉沉兮雨淒淒，洲渚沒兮玄云低，傷別心兮闻鼓鼙。","（见《文苑英华》卷七二○李华《江州臥疾送李侍御序》）。"]', '诗', 'shi', '', NULL, '江州臥疾送李侍御歌（題擬） 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e79ec3-3a80-406f-8cd0-baedd2e428aa', '詠雙澗', '詠雙澗', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["千峰排碧落，雙澗合清漣。","（《記纂淵海》卷九）。"]', '["千峰排碧落，雙澗合清漣。","（《記纂淵海》卷九）。"]', '诗', 'shi', '', NULL, '詠雙澗 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281bc805-818c-4844-84a4-d1eed2933d8b', '題像', '題像', 'ecc8ed41-4dc4-48b1-bc6f-f77605deefdd', '唐', '["攜筇小步踏蒼苔，遙指青山雲正開。","澗水松風聽不絕，又教童子抱琴來。"]', '["携筇小步踏蒼苔，遙指青山云正开。","澗水松风听不絕，又教童子抱琴来。"]', '诗', 'shi', '', NULL, '題像 明瓚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a921a1-d4b7-4c6f-9dc1-32768f2246d8', '辭名', '辞名', 'ecc8ed41-4dc4-48b1-bc6f-f77605deefdd', '唐', '["三十年來獨掩關，使符那得到青山？","休將瑣末人間事，換我一生林下閒。","（以上二首均見《沅湘耆舊集》卷十）。"]', '["三十年来独掩关，使符那得到青山？","休將瑣末人间事，換我一生林下閒。","（以上二首均见《沅湘耆旧集》卷十）。"]', '诗', 'shi', '', NULL, '辭名 明瓚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08808d35-8bbe-44f6-91ee-3ad20cdbb574', '樂道歌', '乐道歌', 'ecc8ed41-4dc4-48b1-bc6f-f77605deefdd', '唐', '["兀然無事無改換，無事何須論一段。","直心無散亂，他事不須斷，過去已過去，未來更（《燈錄》作「猶」）莫（黃庭堅書本作「何用」）算。","兀然無事坐（黃作「事」），何曾有人喚？","向外覓功（黃作「工」）夫，總是癡頑漢。","糧不畜一粒，逢飯但知{埶/食}（黃作「知{口馵}」，《燈錄》同黃，注：「陟立切」）。","世間多少（黃作「事」）人，相趁渾不及。","我不樂生（黃作「昇」）天，亦不愛福田。","饑來喫飯（黃作「饑來一鉢飯」），困來即臥（黃作「展脚」《燈錄》無「臥」字）眠。","愚人笑我，智乃知賢（《燈錄》作「焉」，黃作「愚人以爲笑，智者謂之然」）。","不是癡鈍，本體如然。","（此下黃多「非愚亦非智，不是空中去」二句）要去即去，要住即住（二「即」字，黃皆作「如是」）。","身被（《燈錄》作「披」）一破[衲]（納）（從《燈錄》改），脚著孃生袴。","多言復多語，由來反相悮（黃作「誤」）。","若欲度衆生，無過且自度。","莫謾求真佛，真佛不可見。","妙性及靈臺，何曾受[薰]（勳）（從《燈錄》改）煉（黃作「鍊」）。","心是無事心，面是孃生面。","劫石可移動（黃作「動搖」），箇中難（《燈錄》作「無」）改變。","無事本無事（黃無以上三字），何須讀文字？","削除人我本，冥合箇中意。","種種勞筋骨，不如林間（《燈錄》作「下」）睡兀兀。","舉頭見日高（黃作「出」），乞飯從頭餧（《燈錄》、黃作「𢫫」）。","將功用功，展轉冥朦。","取則（《燈錄》作「即」）不得，不取自通。","吾有一言，絕慮[忘]（志）（從黃書本改，《燈錄》作「亡」）緣。","巧說不得，只用心傳。","更有一語，無過直與。","細如（黃作「極」）毫（《燈錄》作「豪」）末，[大]（本）（從《燈錄》改）無方所，本自圓成，不勞機杼。","世事悠悠，不如山丘。","青松蔽日，碧澗長（黃作「常秋」）。","臥藤蘿下，塊石枕頭。","山雲當幕（《總勝》作「賞慕」），夜月爲鉤（《燈錄》、《總勝》、《沅湘》二句均在「臥藤」二句前）。","不朝天子，豈羨王侯。","生死（《總勝》二字至乙）無慮，更須（《燈錄》等均作「復」）何憂？","水月無形，我常只（《總勝》作「自」）寧。","萬法皆爾，本自無生（《總勝》作「不死不生」）。","兀然無事坐（《總勝》作「箇事」），春來草自青。","（見《祖堂集》卷三，以《四部叢刊三編》影宋本《景德傳燈錄》卷三十、《宛委別藏》本《南嶽總勝集》卷下、《沅湘耆舊集》卷十引《林間錄》及《王梵志詩輯校》卷六據石刻拓本錄黃庭堅書此詩對校。","）（按：《全唐詩續補遺》卷二據清高士奇《江村消夏錄》卷二《黃庭堅書梵志詩卷》收此詩歸王梵志，分作十一首，實誤。","《江村消夏錄》收該卷後有庭堅自跋，並未以爲梵志詩。","以此詩歸梵志，始於卷末董其昌跋。","今唐宋多種典籍皆作懶殘作，其昌逞臆之說，應予否定。","）。"]', '["兀然無事無改換，無事何須論一段。","直心無散亂，他事不須斷，過去已過去，未来更（《灯錄》作「猶」）莫（黄庭堅书本作「何用」）算。","兀然無事坐（黄作「事」），何曾有人喚？","向外覓功（黄作「工」）夫，總是癡頑漢。","糧不畜一粒，逢飯但知{埶/食}（黄作「知{口馵}」，《灯錄》同黄，注：「陟立切」）。","世间多少（黄作「事」）人，相趁渾不及。","我不乐生（黄作「昇」）天，亦不愛福田。","饑来喫飯（黄作「饑来一鉢飯」），困来即臥（黄作「展脚」《灯錄》無「臥」字）眠。","愚人笑我，智乃知賢（《灯錄》作「焉」，黄作「愚人以爲笑，智者謂之然」）。","不是癡鈍，本體如然。","（此下黄多「非愚亦非智，不是空中去」二句）要去即去，要住即住（二「即」字，黄皆作「如是」）。","身被（《灯錄》作「披」）一破[衲]（納）（從《灯錄》改），脚著孃生袴。","多言复多語，由来反相悮（黄作「誤」）。","若欲度衆生，無過且自度。","莫謾求真佛，真佛不可见。","妙性及靈台，何曾受[薰]（勳）（從《灯錄》改）煉（黄作「鍊」）。","心是無事心，面是孃生面。","劫石可移动（黄作「动搖」），箇中难（《灯錄》作「無」）改变。","無事本無事（黄無以上三字），何須读文字？","削除人我本，冥合箇中意。","種種勞筋骨，不如林间（《灯錄》作「下」）睡兀兀。","舉头见日高（黄作「出」），乞飯從头餧（《灯錄》、黄作「𢫫」）。","將功用功，展轉冥朦。","取則（《灯錄》作「即」）不得，不取自通。","吾有一言，絕慮[忘]（志）（從黄书本改，《灯錄》作「亡」）緣。","巧说不得，只用心傳。","更有一語，無過直與。","細如（黄作「極」）毫（《灯錄》作「豪」）末，[大]（本）（從《灯錄》改）無方所，本自圓成，不勞機杼。","世事悠悠，不如山丘。","青松蔽日，碧澗长（黄作「常秋」）。","臥藤蘿下，塊石枕头。","山云當幕（《總勝》作「賞慕」），夜月爲鉤（《灯錄》、《總勝》、《沅湘》二句均在「臥藤」二句前）。","不朝天子，豈羨王侯。","生死（《總勝》二字至乙）無慮，更須（《灯錄》等均作「复」）何憂？","水月無形，我常只（《總勝》作「自」）寧。","万法皆爾，本自無生（《總勝》作「不死不生」）。","兀然無事坐（《總勝》作「箇事」），春来草自青。","（见《祖堂集》卷三，以《四部叢刊三編》影宋本《景德傳灯錄》卷三十、《宛委別藏》本《南嶽總勝集》卷下、《沅湘耆旧集》卷十引《林间錄》及《王梵志诗輯校》卷六據石刻拓本錄黄庭堅书此诗对校。","）（按：《全唐诗續補遺》卷二據清高士奇《江村消夏錄》卷二《黄庭堅书梵志诗卷》收此诗归王梵志，分作十一首，實誤。","《江村消夏錄》收該卷後有庭堅自跋，並未以爲梵志诗。","以此诗归梵志，始於卷末董其昌跋。","今唐宋多種典籍皆作懶殘作，其昌逞臆之说，應予否定。","）。"]', '诗', 'shi', '', NULL, '樂道歌 明瓚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7eaeae5-0fee-49e7-aeae-715c03e6749e', '', '', 'dc950776-05e5-4c02-af7d-0125aade071d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 鄭轅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('747d1cf2-9d84-47a8-a2b1-d39d93539d9a', '遊枋口（幷序） 蒙泉', '游枋口（幷序） 蒙泉', 'dc950776-05e5-4c02-af7d-0125aade071d', '唐', '["丹洞吐細泉，宛轉蒼苔里。","凝碧時含光，流洩復如此。","誰知山下泉，來洗幽人耳。"]', '["丹洞吐細泉，宛轉蒼苔里。","凝碧时含光，流洩复如此。","誰知山下泉，来洗幽人耳。"]', '诗', 'shi', '', NULL, '遊枋口（幷序） 蒙泉 鄭轅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a6a1a4f-8cc1-4d8a-a2fa-bd9a3e2bda17', '遊枋口（幷序） 薜荔壁', '游枋口（幷序） 薜荔壁', 'dc950776-05e5-4c02-af7d-0125aade071d', '唐', '["薜荔生空山，幽姿媚苔壁。","根封石燕泥，花似乳竇滴。","靈均沒已久，榮落誰人惜。"]', '["薜荔生空山，幽姿媚苔壁。","根封石燕泥，花似乳竇滴。","靈均沒已久，榮落誰人惜。"]', '诗', 'shi', '', NULL, '遊枋口（幷序） 薜荔壁 鄭轅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d05337-74e6-48a3-815a-ac190bc2b198', '遊枋口（幷序） 石筍高', '游枋口（幷序） 石筍高', 'dc950776-05e5-4c02-af7d-0125aade071d', '唐', '["竦榦青山下，卓立白雲際。","濯似春筠莖，奇如夏峰勢。","賞者空往來，亭亭幾千里。","（見乾隆二十四年刊蕭應植纂《濟源縣志》卷十六）（〖1〗《縣志》跋云：「鄭轅以下三人，《舊志》列於明時，今改正。","《全唐詩》旁搜博採，有鄭轅，餘無考。","」〖2〗清孫星衍《寰宇訪碑錄》卷四著錄河南濟源唐代石刻有「監察御史鄭轅詩，正書，無年月。","」）。"]', '["竦榦青山下，卓立白云際。","濯似春筠莖，奇如夏峰勢。","賞者空往来，亭亭幾千里。","（见乾隆二十四年刊蕭應植纂《濟源縣志》卷十六）（〖1〗《縣志》跋云：「鄭轅以下三人，《旧志》列於明时，今改正。","《全唐诗》旁搜博採，有鄭轅，餘無考。","」〖2〗清孫星衍《寰宇訪碑錄》卷四著錄河南濟源唐代石刻有「監察御史鄭轅诗，正书，無年月。","」）。"]', '诗', 'shi', '', NULL, '遊枋口（幷序） 石筍高 鄭轅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b58857-5692-4c21-99df-956a779aae0f', '', '', '9a1634b3-e602-4ea6-9b67-614fb08dd0f0', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 崔全素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f2368d-9919-4da9-b5fe-472e443e2e9a', '與鄭轅薛晏遊枋口同賦三韻詩（題擬） 蒙泉', '與鄭轅薛晏游枋口同賦三韻诗（題擬） 蒙泉', '9a1634b3-e602-4ea6-9b67-614fb08dd0f0', '唐', '["溪轉聞鳴泉，林疎渲蒼蘚。","䔩潔來潺湲，凝光散清淺。","未知適所從，空山漫流衍。"]', '["溪轉闻鳴泉，林疎渲蒼蘚。","䔩潔来潺湲，凝光散清淺。","未知適所從，空山漫流衍。"]', '诗', 'shi', '', NULL, '與鄭轅薛晏遊枋口同賦三韻詩（題擬） 蒙泉 崔全素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59089ba6-2a14-46ba-8865-b719744b4e7a', '與鄭轅薛晏遊枋口同賦三韻詩（題擬） 薜荔壁', '與鄭轅薛晏游枋口同賦三韻诗（題擬） 薜荔壁', '9a1634b3-e602-4ea6-9b67-614fb08dd0f0', '唐', '["芳姿抱青巒，根蔓殊衆品。","水淨隱簾珠，雲開露屏錦。","瀝瀝巖風來，幽香洩清澟。"]', '["芳姿抱青巒，根蔓殊衆品。","水淨隐簾珠，云开露屏錦。","瀝瀝巖风来，幽香洩清澟。"]', '诗', 'shi', '', NULL, '與鄭轅薛晏遊枋口同賦三韻詩（題擬） 薜荔壁 崔全素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb1ba4d-aabf-42ea-bdf7-e90e4a1388f2', '與鄭轅薛晏遊枋口同賦三韻詩（題擬） 石筍高', '與鄭轅薛晏游枋口同賦三韻诗（題擬） 石筍高', '9a1634b3-e602-4ea6-9b67-614fb08dd0f0', '唐', '["石筍生孤標，屹立青冥直。","根橫曉浪痕，籜卷春雲色。","稜稜長鈞鋒，應使山魅惕。","（同前）（按：三詩原收鄭轅詩後，題作「同賦」，今重爲擬題。","）。"]', '["石筍生孤標，屹立青冥直。","根橫晓浪痕，籜卷春云色。","稜稜长鈞鋒，應使山魅惕。","（同前）（按：三诗原收鄭轅诗後，題作「同賦」，今重爲擬題。","）。"]', '诗', 'shi', '', NULL, '與鄭轅薛晏遊枋口同賦三韻詩（題擬） 石筍高 崔全素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a654690-18d3-4083-85b7-84858d27e576', '與鄭轅崔全素遊枋口同賦三韻詩（題擬） 蒙泉', '與鄭轅崔全素游枋口同賦三韻诗（題擬） 蒙泉', 'e6572f4b-dd8b-4028-b11d-823366245e93', '唐', '["嘖蘇出深竇，欣然傍欹壁。","清潄疎林澄，光淨寒石白。","一勞意渴甚，挽翫此水碧。"]', '["嘖蘇出深竇，欣然傍欹壁。","清潄疎林澄，光淨寒石白。","一勞意渴甚，挽翫此水碧。"]', '诗', 'shi', '', NULL, '與鄭轅崔全素遊枋口同賦三韻詩（題擬） 蒙泉 薛晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad34e693-70ab-4dbf-a35c-2b2459937c20', '與鄭轅崔全素遊枋口同賦三韻詩（題擬） 薜荔壁', '與鄭轅崔全素游枋口同賦三韻诗（題擬） 薜荔壁', 'e6572f4b-dd8b-4028-b11d-823366245e93', '唐', '["誰種薜荔花？盤根上幽石。","玲瓏珠綴曉，香靄岑嵐夕。","却誤貪寢人，遺衣挂苔壁。"]', '["誰種薜荔花？盤根上幽石。","玲瓏珠綴晓，香靄岑嵐夕。","却誤貪寢人，遺衣挂苔壁。"]', '诗', 'shi', '', NULL, '與鄭轅崔全素遊枋口同賦三韻詩（題擬） 薜荔壁 薛晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea01b8c5-d10b-4064-9c3f-8af9c8c80090', '與鄭轅崔全素遊枋口同賦三韻詩（題擬） 石筍高', '與鄭轅崔全素游枋口同賦三韻诗（題擬） 石筍高', 'e6572f4b-dd8b-4028-b11d-823366245e93', '唐', '["峭筍倚溪壖，雄標屹霞境。","雲披看卷籜，波靜見垂影。","頓翼已棲林，殘陽方在頂。","（同前）（按：三詩原收鄭轅、崔全素詩後，題作「同賦」，今重爲擬題。","）。"]', '["峭筍倚溪壖，雄標屹霞境。","云披看卷籜，波静见垂影。","頓翼已棲林，殘陽方在頂。","（同前）（按：三诗原收鄭轅、崔全素诗後，題作「同賦」，今重爲擬題。","）。"]', '诗', 'shi', '', NULL, '與鄭轅崔全素遊枋口同賦三韻詩（題擬） 石筍高 薛晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8076267f-1af6-4e11-9ed5-41d1116bcdce', '偈', '偈', '29aa2457-8b11-4045-9db1-8783d351ac46', '唐', '["湘之南，潭之北，中有黃金充一國。","無影樹下合同船，琉璃殿上無知識。","（見《景德傳燈錄》卷六，、《五燈會元》卷二、《佛祖歷代通載》卷十四、《釋氏稽古略》卷三、《江西詩徵》卷八七、日本《大燈國師語錄》卷下）。"]', '["湘之南，潭之北，中有黄金充一国。","無影樹下合同船，琉璃殿上無知識。","（见《景德傳灯錄》卷六，、《五灯會元》卷二、《佛祖歷代通載》卷十四、《釋氏稽古略》卷三、《江西诗徵》卷八七、日本《大灯国師語錄》卷下）。"]', '诗', 'shi', '', NULL, '偈 應真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd67a6d-84e8-406b-80ac-d6af8b7f5f7e', '題琅琊山寺道標道揖二上人東峰禪室時助成此□□築斯地', '題琅琊山寺道標道揖二上人东峰禪室时助成此□□築斯地', 'f190d050-07ab-46e7-944a-c6dd87b9d678', '唐', '["佛寺秋山裏，僧堂絕頂邊。","同依妙樂土，別占淨居天。","轉壁千林合，歸房一逕穿。","豁心羣壑盡，駭目半空懸。","錫杖棲雲濕，繩床挂月圓。","經行躡霞雨，跬步隔嵐煙。","地勝情非繫，言忘意可傳。","憑虛堪喻道，封境自安禪。","每貯歸休巔，多慙愛深偏。","助君成此地，一到一留連。","（安徽人民出版社出版《瑯琊山石刻選》載拓片。","此詩承周勳初先生錄示。","）。"]', '["佛寺秋山裏，僧堂絕頂邊。","同依妙乐土，別占淨居天。","轉壁千林合，归房一逕穿。","豁心羣壑尽，駭目半空懸。","錫杖棲云濕，繩床挂月圓。","經行躡霞雨，跬步隔嵐煙。","地勝情非繫，言忘意可傳。","憑虛堪喻道，封境自安禪。","每貯归休巔，多慙愛深偏。","助君成此地，一到一留連。","（安徽人民出版社出版《瑯琊山石刻選》載拓片。","此诗承周勳初先生錄示。","）。"]', '诗', 'shi', '', NULL, '題琅琊山寺道標道揖二上人東峰禪室時助成此□□築斯地 李幼卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d737b4e8-f999-4220-a1a5-f4b32722530d', '偈', '偈', '57774cd3-6ad5-485e-9109-f050455d08e4', '唐', '["婦是沒耳伽，男女蘭單杻。","爾是沒價奴，至老不得走。","（《歷代法寶記》）。"]', '["婦是沒耳伽，男女蘭單杻。","爾是沒價奴，至老不得走。","（《歷代法寶記》）。"]', '诗', 'shi', '', NULL, '偈 無住 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da062bc-1481-411a-ace5-d81fc32f52b1', '茶偈', '茶偈', '57774cd3-6ad5-485e-9109-f050455d08e4', '唐', '["幽谷生靈草，堪爲入道媒。","樵人採其葉，美味入流杯。","靜虛澄虛識，明心照會臺。","不勞人氣力，直聳法門開。","（同前）。"]', '["幽谷生靈草，堪爲入道媒。","樵人採其葉，美味入流杯。","静虛澄虛識，明心照會台。","不勞人氣力，直聳法门开。","（同前）。"]', '诗', 'shi', '', NULL, '茶偈 無住 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c8af96c-4e31-483f-901c-1ec981045449', '故功德使涼國公李將軍挽歌詞二首 一', '故功德使涼国公李將軍挽歌词二首 一', 'c7ae208e-b074-466b-b388-16f5b7195fb9', '唐', '["業盛唐堯際，功成文子軍。","累承三帝寵，六比五臣勳。","畫角悲寒吹，愁笳咽曉雲。","聖朝忠義骨，今日委荒墳。"]', '["業盛唐堯際，功成文子軍。","累承三帝寵，六比五臣勳。","畫角悲寒吹，愁笳咽晓云。","聖朝忠義骨，今日委荒墳。"]', '诗', 'shi', '', NULL, '故功德使涼國公李將軍挽歌詞二首 一 趙遷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2844a8-01ef-425e-a99b-92005348b64a', '故功德使涼國公李將軍挽歌詞二首 二', '故功德使涼国公李將軍挽歌词二首 二', 'c7ae208e-b074-466b-b388-16f5b7195fb9', '唐', '["大樹悲風起，將軍去不迴。","撫棺心益痛，臨穴淚難裁。","曉月繁霜草，幽泉掩夜臺。","更聞歌伴哭，觸物盡成哀。","（見《大正新修大藏經》第五十二冊釋圓照集《代宗朝贈司空大辨正廣智三藏和上〖即不空〗表制集》卷五）（按：二詩題下署「前左領軍衛兵曹參軍翰林待詔趙遷」。","同書卷六有同人大曆十一年《賀平李靈曜表》。","同人撰《不空行狀》見《大正新修大藏經》卷四十九冊。","）。"]', '["大樹悲风起，將軍去不迴。","撫棺心益痛，臨穴泪难裁。","晓月繁霜草，幽泉掩夜台。","更闻歌伴哭，觸物尽成哀。","（见《大正新修大藏經》第五十二冊釋圓照集《代宗朝贈司空大辨正廣智三藏和上〖即不空〗表制集》卷五）（按：二诗題下署「前左領軍衛兵曹參軍翰林待詔趙遷」。","同书卷六有同人大曆十一年《賀平李靈曜表》。","同人撰《不空行狀》见《大正新修大藏經》卷四十九冊。","）。"]', '诗', 'shi', '', NULL, '故功德使涼國公李將軍挽歌詞二首 二 趙遷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a1fc436-c486-444d-8e2e-4abf68ffa44a', '揚州崔行軍水亭泛舟望月醼集賦詩（幷序）', '揚州崔行軍水亭泛舟望月醼集賦诗（幷序）', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["明月借秋興，流光在此池。","山公顧我厚，酩酊稱未疲。","勿謂嘉會易，但憂離別隨。","飽君醉中德，敢使松心移。","（見《四部叢刊初編》影清趙懷玉刊本《毘陵集》卷十六）。"]', '["明月借秋兴，流光在此池。","山公顧我厚，酩酊稱未疲。","勿謂嘉會易，但憂離別隨。","飽君醉中德，敢使松心移。","（见《四部叢刊初編》影清趙懷玉刊本《毘陵集》卷十六）。"]', '诗', 'shi', '', NULL, '揚州崔行軍水亭泛舟望月醼集賦詩（幷序） 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb9e2a3-0a0a-4b10-a721-d84a87f61eab', '登姑蘇臺賦附歌', '登姑蘇台賦附歌', '021b3068-262b-43c1-be34-49e3377dd9a8', '唐', '["中心不必兮子胥何爲？","懷直道而驟諫，遭重昏之見危。","將漁父以抗迹，且垂釣於江湄。","（見《文苑英華》卷五二《登姑蘇臺賦》附）。"]', '["中心不必兮子胥何爲？","懷直道而驟諫，遭重昏之见危。","將漁父以抗迹，且垂釣於江湄。","（见《文苑英华》卷五二《登姑蘇台賦》附）。"]', '诗', 'shi', '', NULL, '登姑蘇臺賦附歌 任公叔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ef58b4-40ff-4e25-95b9-e38f305365e8', '句', '句', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["家無阿堵物，門有寧馨兒。","（見宋莊季裕《雞肋編》卷下、高似孫《緯略》卷一）。"]', '["家無阿堵物，门有寧馨兒。","（见宋莊季裕《雞肋編》卷下、高似孫《緯略》卷一）。"]', '诗', 'shi', '', NULL, '句 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d23269-c6b5-4b8c-a653-ba618e4ecf28', '句', '句', 'f6ac4c35-0d24-4863-a84e-f7af49e9aac9', '唐', '["石梯青嶂下，茅屋白雲間。","（見明刻本《錦繡萬花谷》卷二十五「隱逸」門）。"]', '["石梯青嶂下，茅屋白云间。","（见明刻本《錦繡万花谷》卷二十五「隐逸」门）。"]', '诗', 'shi', '', NULL, '句 崔峒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf2a16e-c9e4-4807-a2d5-4d9b9965ced1', '句 一', '句 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["家住青山下，時向青山上。","（見宋談鑰《嘉泰吳興志》卷四「青山」條）。"]', '["家住青山下，时向青山上。","（见宋談鑰《嘉泰吳兴志》卷四「青山」條）。"]', '诗', 'shi', '', NULL, '句 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31ce9d65-6cb1-4b03-8e60-700a5c494150', '句 二', '句 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["垂花臨碧澗，清翠依丹巘。","（《全芳備祖後集》卷七《棗》）。"]', '["垂花臨碧澗，清翠依丹巘。","（《全芳備祖後集》卷七《棗》）。"]', '诗', 'shi', '', NULL, '句 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c8d457-ff2f-437e-9fe9-bee08c71a3de', '消暑樓詩', '消暑楼诗', 'ff595da9-7fb8-4d94-86d2-536c72864706', '唐', '["卷簾對斜橋。","（見《嘉泰吳興志》卷十九「霅溪支港」條）。"]', '["卷簾对斜橋。","（见《嘉泰吳兴志》卷十九「霅溪支港」條）。"]', '诗', 'shi', '', NULL, '消暑樓詩 崔載華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ff157f-46c5-491a-8b80-ef0e991bad04', '望歸舟', '望归舟', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["暮春（《適園叢書》本《後村詩話》作「莫莫」）望歸客，依依江上船。","潮落猶有信，去楫未知旋。","（見《後邨先生大全集》卷一七七《詩話續集》引李康成《玉臺後集》）。"]', '["暮春（《適园叢书》本《後村诗話》作「莫莫」）望归客，依依江上船。","潮落猶有信，去楫未知旋。","（见《後邨先生大全集》卷一七七《诗話續集》引李康成《玉台後集》）。"]', '诗', 'shi', '', NULL, '望歸舟 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6287fc36-a7b0-4be5-8865-ad3214b18972', '代書索鏡', '代书索镜', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["情親留故鏡，賤子感遺簪。","漢月經時掩，胡[塵與]歲深。","珠還仍向浦，鵲遶會歸林。","早晚清光至，窺予白髮親。","（影印本《詩淵》第二冊第一五三二頁，所缺二字據《詩式》卷四補）。"]', '["情親留故镜，賤子感遺簪。","漢月經时掩，胡[塵與]歲深。","珠還仍向浦，鵲遶會归林。","早晚清光至，窺予白髮親。","（影印本《诗淵》第二冊第一五三二頁，所缺二字據《诗式》卷四補）。"]', '诗', 'shi', '', NULL, '代書索鏡 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('074373eb-91ac-4db6-b4fc-1c862b42e919', '剡縣法臺寺灌頂壇詩', '剡縣法台寺灌頂壇诗', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["九燈傳像法，七夜會龍華。","月靜金田廣，幡搖銀漢斜。","香壇分地位，寶印辨根牙。","試問因緣者，清溪無數沙。","（《剡錄》卷八）。"]', '["九灯傳像法，七夜會龙华。","月静金田廣，幡搖銀漢斜。","香壇分地位，寶印辨根牙。","試问因緣者，清溪無數沙。","（《剡錄》卷八）。"]', '诗', 'shi', '', NULL, '剡縣法臺寺灌頂壇詩 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832e82e2-fc4a-48cc-a14a-6a5fed6cb505', '送客', '送客', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["頻年獨對鴛鴦綺，計日雙飛鸚鵡洲。","（見宋王象之《輿地紀勝》卷六七《鄂州》）。"]', '["頻年独对鴛鴦綺，計日雙飞鸚鵡洲。","（见宋王象之《輿地紀勝》卷六七《鄂州》）。"]', '诗', 'shi', '', NULL, '送客 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918b289d-ac15-4b0f-a28f-d1fa352cf7d8', '酬李端得山中道友書見寄之作（題擬）', '酬李端得山中道友书见寄之作（題擬）', 'a78b0949-fd21-461b-9c9a-f9af0f3e35b6', '唐', '["馬融方直校，閱檢復持鉛。","素業高風繼，青春壯思全。","論文多在夜，宿寺不虛年。","自署區中職，同荒郭外田。","山鄰三徑絕，野意八行傳。","煮玉矜新法，留符識舊仙。","涵苔溪溜淺，搖浪竹橋懸。","複洞潛棲燕，疏楊半翳蟬。","詠歌雖有和，雲錦獨成妍。","應以馮唐老，相譏示此篇。","（見江標影宋書棚本《李端詩集》卷三）（按：《全唐詩》卷二八六以此詩爲李端詩，題作「酬前駕部員外郎苗發」，實誤。","檢影宋書棚本此詩附於李端《得山中道友書寄苗錢二員外》後，題作「酬前」，下署「駕部員外郎苗發」，殆爲苗發酬答李端見寄之作而附入李端集者。","後代輾轉刻印，誤將苗發職銜與詩題相連，遂誤成端詩。","類似情況，在唐人原集中甚常見，如竇叔向詩誤歸已經繼之類，岑仲勉、李嘉言二先生已指出。","苗發與張芬詩誤歸李端，亦屬同類型錯誤。","）。"]', '["马融方直校，閱檢复持鉛。","素業高风繼，青春壯思全。","論文多在夜，宿寺不虛年。","自署區中職，同荒郭外田。","山鄰三徑絕，野意八行傳。","煮玉矜新法，留符識旧仙。","涵苔溪溜淺，搖浪竹橋懸。","複洞潛棲燕，疏楊半翳蟬。","詠歌雖有和，云錦独成妍。","應以馮唐老，相譏示此篇。","（见江標影宋书棚本《李端诗集》卷三）（按：《全唐诗》卷二八六以此诗爲李端诗，題作「酬前駕部員外郎苗發」，實誤。","檢影宋书棚本此诗附於李端《得山中道友书寄苗錢二員外》後，題作「酬前」，下署「駕部員外郎苗發」，殆爲苗發酬答李端见寄之作而附入李端集者。","後代輾轉刻印，誤將苗發職銜與诗題相連，遂誤成端诗。","類似情況，在唐人原集中甚常见，如竇叔向诗誤归已經繼之類，岑仲勉、李嘉言二先生已指出。","苗發與張芬诗誤归李端，亦屬同類型錯誤。","）。"]', '诗', 'shi', '', NULL, '酬李端得山中道友書見寄之作（題擬） 苗發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1bbfc0-f4f0-450b-8051-f9da918ecc7a', '垂白之老擊壤歌（題擬）', '垂白之老擊壤歌（題擬）', '25484cc8-36b6-4dad-913a-6e06e6084511', '唐', '["功成作樂兮帝力則那，樂正崇德兮雅頌則多，雲門之典兮大呂之歌，金石節奏兮絲竹駢羅，天地已正兮神人以和，兩堦舞羽兮三邊止戈，擊壤鼓腹兮不識其他。","客有獻成功之頌，九重深兮其若何！（見《文苑英華》卷七四《功成作樂賦》附）。"]', '["功成作乐兮帝力則那，乐正崇德兮雅頌則多，云门之典兮大呂之歌，金石節奏兮絲竹駢羅，天地已正兮神人以和，兩堦舞羽兮三邊止戈，擊壤鼓腹兮不識其他。","客有獻成功之頌，九重深兮其若何！（见《文苑英华》卷七四《功成作乐賦》附）。"]', '诗', 'shi', '', NULL, '垂白之老擊壤歌（題擬） 李子卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253963e5-b435-4d32-b807-52559fa9ba5c', '授衣歌（題擬）', '授衣歌（題擬）', '25484cc8-36b6-4dad-913a-6e06e6084511', '唐', '["天之高兮無不覆，君之大兮無不祐。","生人殖物，既庶且富。","爾在（原注：「疑」）于時，爾茅于晝。","霜始降兮女工就，歲時窮兮寒衣授。","（見同書卷一一三《府試授衣賦》附）。"]', '["天之高兮無不覆，君之大兮無不祐。","生人殖物，既庶且富。","爾在（原注：「疑」）于时，爾茅于晝。","霜始降兮女工就，歲时窮兮寒衣授。","（见同书卷一一三《府試授衣賦》附）。"]', '诗', 'shi', '', NULL, '授衣歌（題擬） 李子卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb130508-dbb5-4e51-b54d-78603a7e98a1', '投龍洞', '投龙洞', '21cb05c2-b06b-4352-9494-f23d9d7eeb1c', '唐', '["水溜空沿石，雲扃不見人。","川源世上異，日月洞中春。","（見《輿地紀勝》卷二《臨安府·名勝》）。"]', '["水溜空沿石，云扃不见人。","川源世上異，日月洞中春。","（见《輿地紀勝》卷二《臨安府·名勝》）。"]', '诗', 'shi', '', NULL, '投龍洞 玄覽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dddbcd8-cc6d-4bd6-8bb4-6661e757a7b8', '題戴徵君幽居', '題戴徵君幽居', '3d36c06b-e184-4b0f-ade4-118b7402c0a3', '唐', '["高臥雲煙外，幽居靜者心。","門庭新種竹，桃李舊成林。","窗戶泉聲入，池塘柳色深。","松花多醴酒，終日會知音。","（日本藏唐抄本《新撰類林抄》卷四）（按：《李端詩集》卷中有《送戴徵士還山》，戴徵士、戴徵君當爲同一人，因知王綬與李端同時。","《新撰類林抄》收詩以開元、大曆間作者爲主。","）。"]', '["高臥云煙外，幽居静者心。","门庭新種竹，桃李旧成林。","窗戶泉声入，池塘柳色深。","松花多醴酒，終日會知音。","（日本藏唐抄本《新撰類林抄》卷四）（按：《李端诗集》卷中有《送戴徵士還山》，戴徵士、戴徵君當爲同一人，因知王綬與李端同时。","《新撰類林抄》收诗以开元、大曆间作者爲主。","）。"]', '诗', 'shi', '', NULL, '題戴徵君幽居 王綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51adf32-5061-401b-bc7e-bd3a9375773b', '五言登郡北佛龕一首', '五言登郡北佛龕一首', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["石壁江城後，籃輿晚蹔登。","古龕千塔佛，秋樹一山僧。","清磬和虛籟，香泉吐暗藤。","願將身灑掃，求官復作能。"]', '["石壁江城後，籃輿晚蹔登。","古龕千塔佛，秋樹一山僧。","清磬和虛籟，香泉吐暗藤。","願將身灑掃，求官复作能。"]', '诗', 'shi', '', NULL, '五言登郡北佛龕一首 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3162926e-b85e-4d1d-83a3-6630a17a40d4', '七言謁倍城縣南香積寺老師一首', '七言謁倍城縣南香積寺老師一首', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["竹林青青山寺幽，老僧禪坐對江流。","長眉（塵）亷襜寂不語，能令過客小低頭。","黃昏鐘竟香煙起，行舟去去心何已。","回看石壁蓮花宮，紗燈一點蒙籠裏。"]', '["竹林青青山寺幽，老僧禪坐对江流。","长眉（塵）亷襜寂不語，能令過客小低头。","黄昏鐘竟香煙起，行舟去去心何已。","回看石壁蓮花宮，紗灯一点蒙籠裏。"]', '诗', 'shi', '', NULL, '七言謁倍城縣南香積寺老師一首 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adae3c85-305a-46b9-9050-6c83342db983', '七言登北山寺西閣樓馮禪師茶酌贈崔少府一首', '七言登北山寺西閣楼馮禪師茶酌贈崔少府一首', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["開[士]（土）相逢暮飲茶，高樓並坐望三巴。","碧嶂不知何劫石，清江流盡幾恒沙。","鑪煙處處香慈竹，溪雨朝朝潤覺花。","道勝自然長法喜，應令遷客小溈華。","（均見日本藏唐抄本《唐詩卷》）（按：《咸淳毘陵志》卷二十二收嘉祐《寄毘陵徹公》詩，《全唐詩》卷五七三收作賈島詩，孰作尚難確定，姑附識於此，以俟考詳。","）。"]', '["开[士]（土）相逢暮饮茶，高楼並坐望三巴。","碧嶂不知何劫石，清江流尽幾恒沙。","鑪煙处处香慈竹，溪雨朝朝潤覺花。","道勝自然长法喜，應令遷客小溈华。","（均见日本藏唐抄本《唐诗卷》）（按：《咸淳毘陵志》卷二十二收嘉祐《寄毘陵徹公》诗，《全唐诗》卷五七三收作賈島诗，孰作尚难確定，姑附識於此，以俟考詳。","）。"]', '诗', 'shi', '', NULL, '七言登北山寺西閣樓馮禪師茶酌贈崔少府一首 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfecdba6-72c7-48b3-9868-47ecbc9bf09f', '題杜舍人林亭', '題杜舍人林亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["來訪龍樓客，時逢酒甕新。","花齊雲入幕，苔徑竹迎人。","鵲喜嬌遲日，鶯啼惜暮春。","不須耽小隱，南院在平津。","（見元駱天驤《類編長安志》卷九勝遊類樊川范公五居條引，據《中國古都研究》收黃永年先生《述〈類編長安志〉》一文轉引。","）。"]', '["来訪龙楼客，时逢酒甕新。","花齊云入幕，苔徑竹迎人。","鵲喜嬌遲日，鶯啼惜暮春。","不須耽小隐，南院在平津。","（见元駱天驤《類編长安志》卷九勝游類樊川范公五居條引，據《中国古都研究》收黄永年先生《述〈類編长安志〉》一文轉引。","）。"]', '诗', 'shi', '', NULL, '題杜舍人林亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e601bc5a-6acf-49f4-8af5-6bea6a024459', '宿雲門寺', '宿云门寺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["山寺宜靜夜，禪房開竹扉。","支公方晤語，孤月復清暉。","一磬響丹壑，千燈明翠微。","平生厭浮世，茲夕更忘歸。","（見《會稽掇英總集》卷六）。"]', '["山寺宜静夜，禪房开竹扉。","支公方晤語，孤月复清暉。","一磬响丹壑，千灯明翠微。","平生厭浮世，茲夕更忘归。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '宿雲門寺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0738e46b-851f-4ef8-b506-fa6edf97856d', '芝草（題擬）', '芝草（題擬）', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["豈如玉殿生三秀，詎有銅池出五雲。","陌上堯樽傾北斗，樓前舜樂動南薰。","（《全芳備祖後集》卷十一《芝草》。","此四句爲「七言律詩散聯」）。"]', '["豈如玉殿生三秀，詎有銅池出五云。","陌上堯樽傾北斗，楼前舜乐动南薰。","（《全芳備祖後集》卷十一《芝草》。","此四句爲「七言律诗散聯」）。"]', '诗', 'shi', '', NULL, '芝草（題擬） 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a05d92-10f6-4ba3-957c-aa80ed13f000', '芭蕉（題擬）', '芭蕉（題擬）', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幸有青絲用，寧將衆草同。","心虛含夕露，葉大怯秋風。","細響安禪後，濃陰坐夏中。","由來何所喻，持以問支公。","（見前書卷十三《芭蕉》）。"]', '["幸有青絲用，寧將衆草同。","心虛含夕露，葉大怯秋风。","細响安禪後，濃陰坐夏中。","由来何所喻，持以问支公。","（见前书卷十三《芭蕉》）。"]', '诗', 'shi', '', NULL, '芭蕉（題擬） 錢起 shi');
